begin;
    with j as (select * from jsonb_to_recordset($law7v028$[{"code_id":"NK_RF_2","article_number":"342.15","version_date":"2000-07-31","article_text":"1. Если иное не предусмотрено настоящей статьей, коэффициент КФР определяется по следующей формуле:\n\nКФР = ЦФР x 0,04 x (СФР / 0,315) x Р + ЦФРДОП,\n\nгде ЦФР - средняя за налоговый период цена на фосфоритовую руду в соответствии с индексом Phosphate rock 68 - 70% BPL bulk FOB Morocco, выраженная в долларах США за 1 тонну. Показатель ЦФР определяется в порядке, установленном федеральным органом исполнительной власти, осуществляющим функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, рассчитывается указанным федеральным органом исполнительной власти и подлежит размещению на его официальном сайте в информационно-телекоммуникационной сети \"Интернет\" до 10-го числа календарного месяца, следующего за налоговым периодом. В случае, если показатель ЦФР для соответствующего налогового периода не размещен (своевременно не размещен) на указанном официальном сайте, показатель ЦФР рассчитывается налогоплательщиком самостоятельно в порядке, установленном указанным федеральным органом исполнительной власти;\n\nСФР - содержание (в долях) оксида фосфора в 1 тонне добытого полезного ископаемого, определяемое налогоплательщиком самостоятельно в соответствии с данными государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году налогового периода, как частное от деления величины изменения запасов оксида фосфора всех категорий в результате его добычи на участке недр (в тоннах) на соответствующий совокупный объем добытой на участке недр руды (в тоннах). Значение показателя СФР округляется до пятого знака после запятой в соответствии с действующим порядком округления;\n\nР - среднее значение за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, определяемое налогоплательщиком самостоятельно как среднеарифметическое значение курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, за все дни в календарном месяце;\n\nЦФРДОП - показатель, характеризующий дополнительную доходность добычи апатит-нефелиновых, апатитовых, фосфоритовых руд, который рассчитывается по следующей формуле:\n\nЦФРДОП = (ЦФР - 200) x 0,12 x (СФР / 0,315) x Р,\n\nгде ЦФР, СФР, Р - показатели, определяемые в соответствии с настоящим пунктом.\n\nВ случае, если значение показателя ЦФР, определенное для налогового периода, оказалось меньше 200 долларов США за 1 тонну, значение показателя ЦФРДОП в таком налоговом периоде принимается равным нулю.\n\n2. При добыче полезных ископаемых, указанных в подпункте 19 пункта 2 статьи 342 настоящего Кодекса, на участках недр, степень выработанности запасов которых по состоянию на 1 января 2021 года составляет менее 1 процента, и при условии, что деятельность по добыче указанных полезных ископаемых на таких участках недр является частью нового инвестиционного проекта, в отношении которого налогоплательщиком заключено и действует соглашение о защите и поощрении капиталовложений либо исполнено такое соглашение, или осуществляется налогоплательщиком в связи с выполнением им специального инвестиционного контракта, заключенного до 31 декабря 2020 года в соответствии с Федеральным законом от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\", коэффициент КФР рассчитывается в течение сроков, установленных настоящим пунктом, по следующей формуле:\n\nКФР = 0,04 x (СОФ / ООФ),\n\nгде СОФ - стоимость добытого полезного ископаемого за налоговый период, определяемая в соответствии со статьей 340 настоящего Кодекса;\n\nООФ - количество добытого за налоговый период полезного ископаемого, определяемое в соответствии со статьей 339 настоящего Кодекса.\n\nКоэффициент КФР определяется в порядке, установленном настоящим пунктом, в течение пятнадцати следующих подряд календарных лет, начинающихся с года начала промышленной добычи полезного ископаемого на участке недр, или срока действия соглашения о защите и поощрении капиталовложений, или срока действия специального инвестиционного контракта в зависимости от того, какой срок истекает позднее.\n\nВ целях настоящего пункта степень выработанности запасов полезного ископаемого, год начала промышленной добычи полезного ископаемого на участке недр определяются в порядке, установленном пунктом 11 статьи 3428 настоящего Кодекса.\n\n3. Коэффициент КФР, рассчитанный в порядке, определенном настоящей статьей, округляется до первого знака после запятой в соответствии с действующим порядком округления.\n\n(Дополнение статьей - Федеральный закон от 12.07.2024 № 176-ФЗ)","article_title":"Статья 342.15. Порядок определения и применения коэффициента КФР","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3896a85a93a345950dbe90e2b42ebc44a444910e3ab7d9b394da221bd8f7ba36"},{"code_id":"NK_RF_2","article_number":"342.2","version_date":"2000-07-31","article_text":"1. При соблюдении условий, установленных настоящей статьей, коэффициент, характеризующий степень сложности добычи нефти (Кд), принимается:\n\n1) (Подпункт утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n2) равным 0,2 - при добыче нефти из конкретной залежи углеводородного сырья с утвержденным показателем проницаемости не более 2 x 10-3 мкм2 и эффективной нефтенасыщенной толщиной пласта по указанной залежи не более 10 метров;\n\n3) равным 0,4 - при добыче нефти из конкретной залежи углеводородного сырья с утвержденным показателем проницаемости не более 2 x 10-3 мкм2 и эффективной нефтенасыщенной толщиной пласта по указанной залежи более 10 метров;\n\n4) равным 0,8 - при добыче нефти из конкретной залежи углеводородного сырья, отнесенной к продуктивным отложениям тюменской свиты в соответствии с данными государственного баланса запасов полезных ископаемых;\n\n5) равным 1 - при добыче нефти из прочих залежей углеводородного сырья, характеристики которых не соответствуют характеристикам, указанным в подпунктах 2 - 4 настоящего пункта. (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nКоэффициент Кд в размере, установленном подпунктами 2 - 4 пункта 1 настоящей статьи, применяется до истечения 180 налоговых периодов, начинающихся с 1 января года, в котором степень выработанности запасов конкретной залежи углеводородного сырья превысила 1 процент, если иное не установлено настоящим пунктом. По истечении указанного срока значение коэффициента принимается равным 1. (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\nКоэффициент Кд в размере, установленном подпунктами 2 - 4 пункта 1 настоящей статьи, применяется до истечения срока, установленного абзацем вторым настоящего пункта, начинающегося с 1 января 2014 года, для залежей углеводородного сырья, степень выработанности запасов которых в соответствии с данными государственного баланса запасов полезных ископаемых на 1 января 2013 года составляет более 1 процента, если иное не установлено настоящим пунктом. По истечении указанного срока значение коэффициента Кд принимается равным 1. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 187-ФЗ) (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nКоэффициент Кд в размере, установленном подпунктом 4 пункта 1 настоящей статьи, применяется до истечения срока, установленного абзацем вторым настоящего пункта, начинающегося с 1 января 2015 года, для залежей углеводородного сырья, указанных в подпункте 4 пункта 1 настоящей статьи, степень выработанности запасов которых в соответствии с данными государственного баланса запасов полезных ископаемых на 1 января 2012 года составляет более 3 процентов. По истечении указанного срока значение коэффициента Кд принимается равным 1. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 187-ФЗ)\n\nСтепень выработанности запасов конкретной залежи углеводородного сырья для целей расчета коэффициентов Кд и Кдв рассчитывается налогоплательщиком в соответствии с данными государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году налогового периода.\n\n1) в случае, если значение коэффициента Кд для залежи углеводородного сырья составляет менее 1 и степень выработанности запасов указанной залежи углеводородного сырья менее 0,8, коэффициент Кдв принимается равным 1;\n\n2) в случае, если значение коэффициента Кд для залежи углеводородного сырья составляет менее 1 и степень выработанности запасов указанной залежи углеводородного сырья больше или равна 0,8 и меньше или равна 1, коэффициент Кдв рассчитывается по формуле:\n\nгде Nдв - сумма накопленной добычи нефти по конкретной залежи углеводородного сырья (включая потери при добыче) в соответствии с данными государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году налогового периода;\n\nVдв - начальные извлекаемые запасы нефти, утвержденные в установленном порядке с учетом прироста и списания запасов нефти и определяемые как сумма извлекаемых запасов всех категорий на 1 января года, предшествующего году налогового периода, и накопленной добычи с начала разработки конкретной залежи углеводородного сырья в соответствии с данными государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году налогового периода; (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\n3) в случае, если значение коэффициента Кд для залежи углеводородного сырья составляет менее 1 и степень выработанности запасов указанной залежи углеводородного сырья более 1, коэффициент Кдв принимается равным 0,3;\n\n4) (Подпункт утратил силу - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\n5) в случае, если участок недр не содержит залежей углеводородного сырья, для которых значение коэффициента Кд составляет менее 1, коэффициент Кдв при добыче нефти из залежей углеводородного сырья, расположенных в пределах указанного участка недр, принимается равным 1.\n\nнефть добывается из скважин, работающих в соответствии с проектной документацией, согласованной в установленном порядке, исключительно на залежах углеводородного сырья, указанных в подпунктах 2 - 4 пункта 1 настоящей статьи; (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nучет нефти, добываемой из залежей углеводородного сырья, указанных в подпунктах 2 - 4 пункта 1 настоящей статьи, осуществляется с учетом требований, установленных пунктом 9 статьи 339 настоящего Кодекса; (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nнефть добывается из залежей углеводородного сырья, запасы нефти по которым поставлены на государственный баланс запасов полезных ископаемых после 1 января 2012 года либо запасы нефти которых учтены в государственном балансе запасов полезных ископаемых на 1 января 2012 года и степень выработанности запасов которых в соответствии с данными государственного баланса запасов полезных ископаемых на 1 января 2012 года составляет: (В редакции Федерального закона от 28.06.2014 № 187-ФЗ)\n\nпри добыче нефти из залежей углеводородного сырья, указанных в подпункте 4 пункта 1 настоящей статьи, - менее 13 процентов; (Дополнение абзацем - Федеральный закон от 28.06.2014 № 187-ФЗ)\n\nпри добыче нефти из залежей углеводородного сырья, указанных в подпунктах 2 и 3 пункта 1 настоящей статьи, - менее 3 процентов. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 187-ФЗ)\n\nПри несоблюдении условий, установленных настоящим пунктом, коэффициент Кд принимается равным 1.\n\nПри этом, если по данным указанного заключения показатели проницаемости и (или) эффективной нефтенасыщенной толщины пласта по залежи углеводородного сырья представляют собой интервал значений, для целей настоящей статьи используется среднее арифметическое минимального и максимального значений этого интервала.\n\nВ случае, если на основании показателей проницаемости и (или) эффективной нефтенасыщенной толщины пласта по соответствующей залежи углеводородного сырья, указанных в государственном балансе запасов полезных ископаемых по состоянию на 1 января года, следующего за годом утверждения заключения, указанного в абзаце первом настоящего пункта, в отношении нефти, добываемой из этой залежи, подлежат применению более высокие значения коэффициента Кд, чем применяемые налогоплательщиком по указанной залежи в соответствии с абзацем первым настоящего пункта, сумма налога, исчисленная по этой нефти, подлежит перерасчету с учетом коэффициента Кд, определенного в соответствии с данными государственного баланса запасов полезных ископаемых по состоянию на 1 января года, следующего за годом утверждения заключения, указанного в абзаце первом настоящего пункта, начиная с налогового периода, в котором впервые был применен коэффициент Кд в соответствии с данными заключения, указанного в абзаце первом настоящего пункта. Исчисленная в результате пересчета сумма налога подлежит уплате в бюджеты бюджетной системы Российской Федерации. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.06.2014 № 187-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 23.07.2013 № 213-ФЗ)","article_title":"Статья 342.2. Порядок определения и применения коэффициента, характеризующего степень сложности добычи нефти (Кд), и коэффициента, характеризующего степень выработанности конкретной залежи углеводородного сырья (Кдв)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a44d1c616d2fe0d6ed48a7c5ca317ac39ba5522c3560c8e4082b36b8272a634f"},{"code_id":"NK_RF_2","article_number":"342.3","version_date":"2000-07-31","article_text":"1) 0 - в течение первых двадцати четырех налоговых периодов;\n\n2) 0,2 - с двадцать пятого по сорок восьмой включительно налоговый период;\n\n3) 0,4 - с сорок девятого по семьдесят второй включительно налоговый период;\n\n4) 0,6 - с семьдесят третьего по девяносто шестой включительно налоговый период;\n\n5) 0,8 - с девяносто седьмого по сто двадцатый включительно налоговый период;\n\n6) 1 - в последующие налоговые периоды.\n\nВеличина TB_МАКС_Р определяется как общая сумма значений величин TB_НДПИ_Р и TB_ПРИБЫЛЬ_Р.\n\nВеличина TB_НДПИ_Р рассчитывается как разница между суммой налога, исчисленного без применения коэффициента КТД, и суммой налога, исчисленного с применением коэффициента КТД менее 1, определенных нарастающим итогом начиная с налогового периода, указанного в пункте 1 настоящей статьи.\n\nВеличина TB_ПРИБЫЛЬ_Р определяется в соответствии с абзацем первым пункта 31 статьи 2843 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nПоложения данного пункта не применяются в случае выполнения участником регионального инвестиционного проекта обязательств, предусмотренных инвестиционной декларацией, в том числе в части сумм финансирования капитальных вложений регионального инвестиционного проекта.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 267-ФЗ)","article_title":"Статья 342.3. Порядок определения и применения коэффициента, характеризующего территорию добычи полезного ископаемого","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8e2aef70fc4f59b182014bf172c08a24194c7c9892505d045da7584c9bdb804f"},{"code_id":"NK_RF_2","article_number":"342.3-1","version_date":"2000-07-31","article_text":"1. Коэффициент, характеризующий территорию добычи полезного ископаемого (Ктд), применяется участником регионального инвестици\n\nонного проекта, указанным в подпункте 2 пункта 1 статьи 259 настоящего Кодекса, начиная с налогового периода, в котором впервые одновременно соблюдены следующие условия:\n\n1) появились основания для определения налоговой базы по налогу на добычу полезных ископаемых в отношении таких полезных ископаемых;\n\n2) налогоплательщиком - участником регионального инвестиционного проекта выполнено требование к минимальному объему капитальных вложений, установленное подпунктом 41 пункта 1 статьи 258 настоящего Кодекса;\n\n3) налогоплательщик - участник регионального инвестиционного проекта обратился в налоговый орган с заявлением о применении налоговой льготы, указанным в пункте 1 статьи 2512-1 настоящего Кодекса.\n\n2. В течение ста двадцати налоговых периодов считая с налогового периода, указанного в пункте 1 настоящей статьи, коэффициент Ктд принимается равным:\n\n1) 0 - в течение первых двадцати четырех налоговых периодов;\n\n2) 0,2 - с двадцать пятого по сорок восьмой включительно налоговый период;\n\n3) 0,4 - с сорок девятого по семьдесят второй включительно налоговый период;\n\n4) 0,6 - с семьдесят третьего по девяносто шестой включительно налоговый период;\n\n5) 0,8 - с девяносто седьмого по сто двадцатый включительно налоговый период;\n\n6) 1 - в последующие налоговые периоды.\n\n3. В случае, если налоговый период, указанный в пункте 1 настоящей статьи, приходится на период после 1 января 2031 года, коэффициент Ктд принимается равным 1.\n\n4. Коэффициент КТД принимается равным 1 начиная с налогового периода, следующего за налоговым периодом, в котором величина TB_МАКС_З, определяемая в порядке, установленном настоящим пунктом, превысила величину, равную объему осуществленных капитальных вложений, указанных в заявлении, предусмотренном пунктом 1 статьи 2512-1 настоящего Кодекса.\n\nВеличина TB_МАКС_З определяется как общая сумма значений величин TB_НДПИ_З и TB_ПРИБЫЛЬ_З.\n\nВеличина TB_НДПИ_З рассчитывается как разница между суммой налога, исчисленного без применения коэффициента КТД, и суммой налога, исчисленного с применением коэффициента КТД менее 1, определенных нарастающим итогом начиная с налогового периода, указанного в пункте 1 настоящей статьи.\n\nВеличина TB_ПРИБЫЛЬ_З определяется в соответствии с абзацем первым пункта 21 статьи 2843-1 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 301-ФЗ) (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 23.05.2016 № 144-ФЗ)","article_title":"Статья 342.3-1. Порядок определения и применения коэффициента, характеризующего территорию добычи полезного ископаемого, для участников региональных инвестиционных проектов, для которых не требуется включение в реестр участников региональных инвестиционных проектов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdca3f0a7be06e65fa28475107f7c527bb8046f0395fe8077b99d9624dd0caee"},{"code_id":"NK_RF_2","article_number":"342.4","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.11.2023 № 539-ФЗ)\n\n1. Базовое значение единицы условного топлива (Еут) рассчитывается налогоплательщиком самостоятельно при добыче газа горючего природного (за исключением попутного газа) и (или) газового конденсата для участка недр, содержащего залежь углеводородного сырья, по следующей формуле:\n\n(В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nгде Цг - цена газа горючего природного, определяемая в целях настоящей статьи в соответствии с пунктом 4 настоящей статьи;\n\nДг - коэффициент, характеризующий долю добытого газа горючего природного (за исключением попутного газа) в общем количестве газа горючего природного (за исключением попутного газа) и газового конденсата, добытых в истекшем налоговом периоде на участке недр, содержащем залежь углеводородного сырья, определяемый в соответствии с пунктом 3 настоящей статьи;\n\nЦк - цена газового конденсата, определяемая в целях настоящей статьи в соответствии с пунктом 2 настоящей статьи;\n\nКгп - коэффициент, характеризующий экспортную доходность единицы условного топлива, определяемый в соответствии с пунктом 18 настоящей статьи. (Дополнение абзацем - Федеральный закон от 28.11.2015 № 325-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nРассчитанное в порядке, определенном настоящим пунктом, базовое значение единицы условного топлива (Еут) округляется до четвертого знака в соответствии с действующим порядком округления. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 242-ФЗ)\n\n2. Цена газового конденсата (Цк) рассчитывается в целях настоящей статьи по следующей формуле:\n\nЦк = (Ц х 8 - Пн) х Р,\n\nгде Ц - средняя за истекший налоговый период цена нефти сорта \"Юралс\" за баррель, выраженная в долларах США, определяемая в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса;\n\nПн - условная ставка вывозной таможенной пошлины на газовый конденсат, определяемая в порядке, установленном пунктом 16 настоящей статьи;\n\nР - среднее за истекший налоговый период значение курса доллара США к рублю Российской Федерации, определяемое в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса.\n\nРассчитанная в порядке, определенном настоящим пунктом, средняя за истекший налоговый период цена газового конденсата (Цк) округляется до 4-го знака в соответствии с действующим порядком округления.\n\n(Пункт в редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\n3. Коэффициент, характеризующий долю добытого газа горючего природного (за исключением попутного газа) в общем количестве газа горючего природного (за исключением попутного газа) и газового конденсата, добытых в истекшем налоговом периоде на участке недр, содержащем залежь углеводородного сырья (Дг), рассчитывается по следующей формуле:\n\nгде Го - количество добытого за истекший налоговый период на участке недр газа горючего природного (за исключением попутного газа), выраженное в тысячах кубических метров;\n\nКо - количество добытого за истекший налоговый период на участке недр газового конденсата, выраженное в тоннах.\n\nРассчитанный в порядке, определенном настоящим пунктом, коэффициент Дг округляется до 4-го знака в соответствии с действующим порядком округления.\n\n4. Цена газа горючего природного (Цг) рассчитывается в целях настоящей статьи по следующей формуле:\n\nЦг = Цв х Ов + Цэ х (1 - Ов),\n\nгде ЦВ - до 31 декабря 2023 года включительно - средняя по Единой системе газоснабжения расчетная цена на газ, поставляемый потребителям Российской Федерации (кроме населения), рассчитываемая федеральным органом исполнительной власти в области регулирования тарифов в порядке, установленном Правительством Российской Федерации. Указанная расчетная цена подлежит применению с 1-го числа первого месяца периода, на который регулируемые оптовые цены на газ утверждаются в установленном порядке. Средняя по Единой системе газоснабжения расчетная цена на газ, поставляемый потребителям Российской Федерации (кроме населения), не позднее чем за пять дней до 1-го числа первого месяца указанного периода размещается на официальном сайте федерального органа исполнительной власти в области регулирования тарифов в информационно-телекоммуникационной сети \"Интернет\". При отсутствии указанной информации на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\" средняя по Единой системе газоснабжения расчетная цена на газ, поставляемый потребителям Российской Федерации (кроме населения), определяется налогоплательщиком самостоятельно в порядке, установленном Правительством Российской Федерации. Значение показателя ЦВ рассчитывается при каждом изменении регулируемых оптовых цен на газ в Российской Федерации, полученное значение применяется для целей налогообложения до следующего изменения регулируемых оптовых цен на газ в Российской Федерации. С 1 января 2024 года - средняя по Единой системе газоснабжения расчетная цена на газ, определенная в соответствии с настоящим абзацем для налогового периода, дата начала которого приходится на период с 1 по 30 ноября 2023 года включительно. Указанная расчетная цена подлежит индексации начиная с 1 июля 2024 года на коэффициент индексации, определяемый федеральным органом исполнительной власти в области регулирования тарифов и размещаемый на его официальном сайте в информационно-телекоммуникационной сети \"Интернет\" в порядке, установленном Правительством Российской Федерации; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nОв - коэффициент, характеризующий долю реализации газа потребителям Российской Федерации в общем объеме реализованного организацией газа, определяемый в порядке, установленном пунктом 5 настоящей статьи;\n\nЦэ - расчетная цена газа горючего природного при поставках за пределы территорий государств - участников Содружества Независимых Государств, рассчитываемая по следующей формуле:\n\nгде Цдз - расчетная цена реализации газа за пределы территорий государств - участников Содружества Независимых Государств. Указанная расчетная цена ежемесячно рассчитывается федеральным органом исполнительной власти в области регулирования тарифов в порядке, установленном Правительством Российской Федерации, размещается на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\" не позднее 15-го числа налогового периода и подлежит применению в налоговом периоде ее размещения. При отсутствии указанной информации на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\" расчетная цена реализации газа за пределы территорий государств - участников Содружества Независимых Государств определяется налогоплательщиком самостоятельно в порядке, установленном Правительством Российской Федерации;\n\nСтп - ставка вывозной таможенной пошлины на газ горючий природный, выраженная в процентах, которая была установлена для истекшего налогового периода;\n\nРдз - расходы на транспортировку и хранение газа за пределами территорий государств - членов Таможенного союза при его реализации за пределы территорий государств - участников Содружества Независимых Государств, выраженные в рублях за 1 000 кубических метров газа. Величина Рдз рассчитывается федеральным органом исполнительной власти в области регулирования тарифов в порядке, установленном Правительством Российской Федерации, размещается на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\" не позднее 1 марта календарного года и подлежит применению в течение двенадцати следующих подряд налоговых периодов начиная с 1 марта указанного календарного года. При отсутствии указанной информации на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\" величина Рдз определяется налогоплательщиком самостоятельно в порядке, установленном Правительством Российской Федерации.\n\nРассчитанная в порядке, определенном настоящим пунктом, цена газа горючего природного (Цг) округляется до 4-го знака в соответствии с действующим порядком округления.\n\nРассчитанная в порядке, определенном настоящим пунктом, расчетная цена газа горючего природного при поставках за пределы территорий государств - участников Содружества Независимых Государств (Цэ) округляется до четвертого знака в соответствии с действующим порядком округления. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 242-ФЗ)\n\n(Пункт в редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\n5. Коэффициент, характеризующий долю реализации газа потребителям Российской Федерации в общем объеме реализованного организацией газа (Ов), устанавливается равным:\n\n1) 0,64 - для налогоплательщиков, являющихся в течение всего налогового периода организациями - собственниками объектов Единой системы газоснабжения и (или) организациями, в которых непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет более 50 процентов, за исключением следующих налогоплательщиков:\n\nналогоплательщиков - организаций, в которых одним из участников с долей не менее 50 процентов является российская организация, в которой непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет менее 15 процентов; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nналогоплательщиков, для которых рассчитываемый по итогам налогового периода коэффициент, характеризующий долю добытого газа горючего природного (за исключением попутного газа) в суммарном объеме добытого углеводородного сырья (Кгпн), составляет менее 0,35. Значение коэффициента Кгпн определяется в соответствии с пунктом 6 настоящей статьи;\n\n2) 1 - для налогоплательщиков, не указанных в подпункте 1 настоящего пункта.\n\n6. Значение коэффициента Кгпн, указанного в пункте 5 настоящей статьи, определяется налогоплательщиком самостоятельно по следующей формуле:\n\nгде Гсо - количество добытого газа горючего природного (за исключением попутного газа), выраженное в тысячах кубических метров;\n\nГп - количество добытого попутного газа, выраженное в тысячах кубических метров;\n\nНо - количество добытой нефти обезвоженной, обессоленной и стабилизированной, выраженное в тоннах;\n\nКсо - количество добытого газового конденсата, выраженное в тоннах.\n\nПоказатели Гсо, Гп, Но, Ксо определяются за истекший налоговый период применительно к добыче на всех участках недр, находящихся в пользовании налогоплательщика.\n\n7. Коэффициент, характеризующий степень сложности добычи газа горючего природного и (или) газового конденсата из залежи углеводородного сырья (Кс), принимается равным минимальному значению из значений коэффициентов Квг, Кр, Кгз, Кас, Корз, рассчитываемых для указанной залежи углеводородного сырья в порядке, установленном пунктами 8 - 12 настоящей статьи.\n\nРассчитанный в порядке, определенном настоящим пунктом, коэффициент Кс округляется до 4-го знака в соответствии с действующим порядком округления.\n\n8. Коэффициент, характеризующий степень выработанности запасов газа конкретного участка недр, содержащего залежь углеводородного сырья (Квг), определяется налогоплательщиком в порядке, установленном настоящим пунктом.\n\nВ случае, если степень выработанности запасов газа горючего природного конкретного участка недр (Свг) больше 0,7 и меньше или равна 0,9, коэффициент Квг рассчитывается по следующей формуле:\n\nКвг = 2,75 - 2,5 х Свг.\n\nВ случае, если степень выработанности запасов газа горючего природного конкретного участка недр (Свг) больше 0,9, коэффициент Квг принимается равным 0,5.\n\nВ случае, если степень выработанности запасов газа горючего природного конкретного участка недр (Свг) меньше или равна 0,7, коэффициент Квг принимается равным 1.\n\n9. Коэффициент, характеризующий географическое расположение участка недр, содержащего залежь углеводородного сырья (Кр), определяется налогоплательщиком в следующем порядке:\n\n1) в случае, если участок недр, содержащий залежь углеводородного сырья, расположен полностью или частично на полуострове Ямал и (или) Гыданском полуострове в Ямало-Ненецком автономном округе, на период с 1 января 2014 года и до истечения ста сорока четырех налоговых периодов, начинающихся с 1 января года, в котором степень выработанности запасов газа горючего природного конкретного участка недр (Свг) впервые превысила 1 процент (но не ранее 1 января 2014 года), коэффициент Кр рассчитывается по следующей формуле:\n\nКр = 0,066 х n + 0,144,\n\nгде n - порядковый номер календарного года, определяемый в целях настоящего подпункта как разность между годом налогового периода и годом, в котором степень выработанности запасов газа горючего природного конкретного участка недр (Свг) впервые превысила 1 процент (но не ранее 1 января 2014 года), увеличенная на 1.\n\nВ случае, если в налоговом периоде степень выработанности запасов газа горючего природного конкретного участка недр (Свг) составляет менее 1 процента, порядковый номер года (n) принимается равным 1.\n\nПо истечении ста сорока четырех налоговых периодов, начинающихся с 1 января года, в котором степень выработанности запасов газа горючего природного конкретного участка недр (Свг) впервые превысила 1 процент (но не ранее 1 января 2014 года), коэффициент Кр принимается равным 1;\n\n2) в случае, если участок недр, содержащий залежь углеводородного сырья, расположен полностью или частично на территории Астраханской области, коэффициент Кр принимается равным 0,73;\n\n3) если иное не установлено подпунктом 4 настоящего пункта, в случае, если участок недр, содержащий залежь углеводородного сырья, расположен полностью или частично на территории Иркутской области, Красноярского края или Дальневосточного федерального округа либо в Охотском море, на период с 1 июля 2014 года по 31 декабря 2033 года коэффициент Кр принимается равным 0,1, начиная с 1 января 2034 года для указанных участков недр коэффициент Кр принимается равным 1;\n\n4) для налогоплательщиков, указанных в подпункте 1 пункта 5 настоящей статьи, в случае, если участок недр, содержащий залежь углеводородного сырья, расположен полностью или частично в границах Иркутской области и (или) Республики Саха (Якутия) и дата начала промышленной добычи газа горючего природного на таком участке недр приходится на период начиная с 1 января 2018 года, коэффициент Кр:\n\nпринимается равным 0 начиная с налогового периода, следующего за налоговым периодом, в котором впервые выдана лицензия на пользование участком недр, и до истечения пятнадцати календарных лет, отсчитываемых последовательно с 1 января года, на который приходится дата начала промышленной добычи газа горючего природного на этом участке недр;\n\nначиная с шестнадцатого календарного года, отсчитываемого последовательно с 1 января года, на который приходится дата начала промышленной добычи газа горючего природного на участке недр, рассчитывается по следующей формуле:\n\nКр = 0,1 х (n - 15),\n\nгде n в целях настоящего подпункта определяется как порядковый номер календарного года с шестнадцатого по двадцать четвертый годы, отсчитываемые последовательно с 1 января года, на который приходится дата начала промышленной добычи газа горючего природного на участке недр;\n\nпринимается равным 1 начиная с первого налогового периода двадцать пятого календарного года, отсчитываемого последовательно с 1 января года, на который приходится дата начала промышленной добычи газа горючего природного на участке недр.\n\nДля целей настоящего подпункта датой начала промышленной добычи газа горючего природного на участке недр признается дата, на которую составлен государственный баланс запасов полезных ископаемых, согласно которому степень выработанности запасов газа горючего природного участка недр впервые превысила 1 процент;\n\n5) при добыче газа горючего природного на участке недр, содержащем залежь углеводородного сырья, расположенном на территориях, не указанных в подпунктах 1 - 4 настоящего пункта, коэффициент Кр принимается равным 1.\n\n(Пункт в редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\n10. Коэффициент, характеризующий глубину залегания залежи углеводородного сырья (Кгз), принимается равным одному из следующих значений:\n\nв случае, если минимальная глубина залегания залежи углеводородного сырья меньше или равна 1 700 метрам, коэффициент Кгз принимается равным 1;\n\nв случае, если минимальная глубина залегания залежи углеводородного сырья больше 1 700 метров и меньше или равна 3 300 метрам, коэффициент Кгз принимается равным 0,64;\n\nв случае, если минимальная глубина залегания залежи углеводородного сырья больше 3 300 метров, коэффициент Кгз принимается равным 0,5 при добыче газового конденса\n\nта и равным результату деления числа 0,5 на значение коэффициента Кгп, определяемого в соответствии с пунктом 18 настоящей статьи, при добыче газа горючего природного. (В редакции федеральных законов от 27.11.2017 № 335-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nМинимальная глубина залегания залежи углеводородного сырья определяется налогоплательщиком самостоятельно по данным государственного баланса запасов полезных ископаемых по состоянию на 1 января года, предшествующего году налогового периода.\n\nПри этом для залежей углеводородного сырья участков недр, расположенных на территориях, перечисленных в абзацах втором - восьмом пункта 9 настоящей статьи, коэффициент, характеризующий глубину залегания залежи углеводородного сырья (Кгз), принимается равным 1.\n\n11. Коэффициент, характеризующий принадлежность участка недр, содержащего залежь углеводородного сырья, к региональной системе газоснабжения (Кас), определяется налогоплательщиком в порядке, установленном настоящим пунктом.\n\nВ случае, если участок недр, содержащий залежь углеводородного сырья, является ресурсной базой исключительно для региональной системы газоснабжения, коэффициент Кас принимается равным 0,1.\n\nВ случаях, не указанных в абзаце втором настоящего пункта, коэффициент Кас принимается равным 1.\n\n12. Коэффициент, характеризующий особенности разработки отдельных залежей участка недр (Корз), определяется налогоплательщиком в порядке, установленном настоящим пунктом.\n\nВ случае, если добыча газа горючего природного осуществляется из залежи углеводородного сырья, отнесенной к туронским продуктивным отложениям или продуктивным отложениям березовской свиты по данным государственного баланса запасов полезных ископаемых, на период с 1 января 2014 года и до истечения ста восьмидесяти налоговых периодов, начинающихся с 1 января года, в котором степень выработанности запасов газа горючего природного залежи углеводородного сырья впервые превысила 1 процент, коэффициент Корз рассчитывается по следующей формуле: (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nКорз = 0,053 х n + 0,157,\n\nгде n - порядковый номер года, определяемый в целях настоящего пункта как разность между годом налогового периода и годом, в котором степень выработанности запасов газа горючего природного залежи углеводородного сырья впервые превысила 1 процент, увеличенная на 1.\n\nВ случае, если в налоговом периоде степень выработанности запасов газа горючего природного залежи углеводородного сырья составляет менее 1 процента, порядковый номер года (n) принимается равным 1.\n\nПо истечении ста восьмидесяти налоговых периодов, начинающихся с 1 января года, в котором степень выработанности запасов газа горючего природного залежи углеводородного сырья впервые превысила 1 процент, коэффициент Корз принимается равным 1.\n\nДля целей настоящего пункта степень выработанности запасов газа горючего природного залежи углеводородного сырья рассчитывается налогоплательщиком самостоятельно по данным государственного баланса запасов полезных ископаемых по состоянию на 1 января года, предшествующего году налогового периода, как частное от деления суммы накопленной добычи газа горючего природного (за исключением попутного газа) из залежи углеводородного сырья (включая потери при добыче) на начальные запасы газа горючего природного (за исключением попутного газа), определяемые как сумма начальных запасов газа горючего природного (за исключением попутного газа) всех категорий и накопленной добычи с начала разработки залежи углеводородного сырья. (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\nПоказатель Тг рассчитывается по следующей формуле:\n\nгде Тр - разница между средним фактическим значением тарифа на услуги по транспортировке газа горючего природного по магистральным газопроводам, являющимся частью Единой системы газоснабжения, в пределах территории Российской Федерации в году, предшествующем году налогового периода, определяемым как среднее арифметическое фактических значений тарифов на услуги по транспортировке газа горючего природного по магистральным газопроводам, являющимся частью Единой системы газоснабжения, в пределах территории Российской Федерации, действовавших в каждом месяце года, предшествующего году налогового периода, и расчетным значением тарифа на услуги по транспортировке газа горючего природного для года, предшествующего году налогового периода, определяемым как произведение среднего фактического значения тарифа на услуги по транспортировке газа горючего природного по магистральным газопроводам, являющимся частью Единой системы газоснабжения, в пределах территории Российской Федерации в 2013 году и коэффициента, учитывающего изменение потребительских цен на товары (работы, услуги) в Российской Федерации начиная с 2013 года.\n\nКоэффициент, учитывающий изменение потребительских цен на товары (работы, услуги) в Российской Федерации начиная с 2013 года, определяется как отношение коэффициента-дефлятора, установленного для года, предшествующего году налогового периода, к коэффициенту-дефлятору, установленному для 2013 года.\n\nПоказатель Тр доводится через официальные источники информации уполномоченным федеральным органом исполнительной власти в области регулирования тарифов.\n\nПри отсутствии указанной информации в официальных источниках показатель Тр рассчитывается налогоплательщиком самостоятельно.\n\nЕсли значение показателя Тр, определенное в соответствии с настоящим пунктом, составляет менее 0, то показатель Тр принимается равным 0;\n\nРг - среднее расстояние транспортировки газа горючего природного по магистральным газопроводам, являющимся частью Единой системы газоснабжения, выраженное в километрах, в пределах территории Российской Федерации организациями, не являющимися собственниками объектов Единой системы газоснабжения и (или) организациями, в которых непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет более 50 процентов за 12 месяцев, предшествующих 1 октября года, предшествующего году налогового периода.\n\nПоказатель Рг рассчитывается федеральным органом исполнительной власти в области регулирования тарифов и размещается на его официальном сайте в информационно-телекоммуникационной сети \"Интернет\" в случае, если показатель Тр не равен нулю.\n\nПри отсутствии указанной информации на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\" и величине показателя Тр, не равной нулю, показатель Рг принимается равным 2000;\n\nОг - коэффициент, определяемый как отношение количества газа горючего природного (за исключением попутного газа), добытого организациями, являющимися собственниками объектов Единой системы газоснабжения, и (или) организациями, в которых непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет более 50 процентов (за исключением организаций, в которых одним из участников с долей не менее 50 процентов является российская организация, в которой непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет менее 15 процентов), за 12 месяцев, предшествующих 1 октября года, предшествующего году налогового периода, к количеству газа горючего природного (за исключением попутного газа), добытого иными налогоплательщиками за 12 месяцев, предшествующих 1 октября года, предшествующего году налогового периода. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nКоэффициент Ог определяется и доводится через официальные источники информации в порядке, устанавливаемом федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\nПри отсутствии указанной информации в официальных источниках коэффициент Ог принимается равным 4.\n\nДля налогоплательщиков, не являющихся в течение всего налогового периода организациями - собственниками объектов Единой системы газоснабжения и (или) организациями, в которых непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет более 50 процентов (за исключением организаций, в которых одним из участников с долей не менее 50 процентов является российская организация, в которой непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет менее 15 процентов), коэффициент Ог принимается равным минус 1. (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nДля участков недр, являющихся ресурсной базой исключительно для региональных систем газоснабжения, а также для участков недр, указанных в подпункте 4 пункта 9 настоящей статьи, для которых значение коэффициента Кр равно 0, показатель, характеризующий расходы на транспортировку газа горючего природного (Тг), принимается равным 0.\n\n(Пункт в редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nпри сложившейся за период мониторинга средней цене на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) до 109,5 доллара США за 1 тонну (включительно) - в размере 0 процентов;\n\nпри превышении сложившейся за период мониторинга средней цены на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) уровня 109,5 доллара США за 1 тонну, но не более 146 долларов США за 1 тонну (включительно) - в размере, не превышающем 35 процентов разницы между сложившейся за период мониторинга средней ценой указанной нефти в долларах США за 1 тонну и 109,5 доллара США;\n\nпри превышении сложившейся за период мониторинга средней цены на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) уровня 146 долларов США за 1 тонну, но не более 182,5 доллара США за 1 тонну (включительно) - в размере, не превышающем суммы 12,78 доллара США за 1 тонну и 45 процентов разницы между сложившейся за период мониторинга средней ценой указанной нефти в долларах США за 1 тонну и 146 долларами США;\n\nпри превышении сложившейся за период мониторинга средней цены на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) уровня 182,5 доллара США за 1 тонну - в размере, не превышающем суммы 29,2 доллара США за 1 тонну и 59 процентов разницы между сложившейся за период мониторинга средней ценой указанной нефти в долларах США за 1 тонну и 182,5 доллара США.\n\nПри этом средняя цена на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) за период мониторинга определяется в порядке, установленном пунктом 3 статьи 31 Закона Российской Федерации \"О таможенном тарифе\".\n\nРассчитанная в порядке, определенном настоящим пунктом, условная ставка вывозной таможенной пошлины на газовый конденсат (Пн) округляется до четвертого знака в соответствии с действующим порядком округления. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 242-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 366-ФЗ)\n\n1) 1,4441 - с 1 января 2019 года - для налогоплательщиков, являющихся в течение всего налогового периода организациями - собственниками объектов Единой системы газоснабжения и (или) организациями, в которых непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет более 50 процентов, за исключением следующих налогоплательщиков: (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nналогоплательщиков - организаций, в которых одним из участников с долей не менее 50 процентов является российская организация, в которой непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет менее 15 процентов;\n\nналогоплательщиков, для которых рассчитываемый по итогам налогового периода коэффициент, характеризующий долю добытого газа горючего природного (за исключением попутного газа) в суммарном объеме добытого углеводородного сырья (Кгпн), составляет менее 0,35. Значение коэффициента Кгпн определяется в соответствии с пунктом 6 настоящей статьи;\n\n2) 1 - для налогоплательщиков, не указанных в подпункте 1 настоящего пункта.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2015 № 325-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nЗначение показателя КГК принимается равным нулю:\n\nдля налогоплательщиков, не указанных в абзаце первом настоящего пункта;\n\nдля налогоплательщиков, в отношении которых рассчитываемый по итогам налогового периода в соответствии с пунктом 6 настоящей статьи коэффициент, характеризующий долю добытого газа горючего природного (за исключением попутного газа) в суммарном объеме добытого углеводородного сырья (Кгпн), составляет менее 0,35.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 30.09.2013 № 263-ФЗ)","article_title":"Статья 342.4. Порядок расчета базового значения единицы условного топлива (Еут), коэффициента, характеризующего степень сложности добычи газа горючего природного и (или) газового конденсата из залежи углеводородного сырья (Кс), показателя, характеризующего расходы на транспортировку газа горючего природного (ТГ), и показателя КГК","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a38a0064dff3ab3ccfbbaa7ae644cf4a43559a83730db947f1d1a3181f62259"},{"code_id":"NK_RF_2","article_number":"342.5","version_date":"2000-07-31","article_text":"1. Показатель, характеризующий особенности добычи нефти (Дм), рассчитывается по следующей формуле:\n\nДМ = КНДПИ x КЦ x (1 - КЗ x КД x КДВ x ККАН) - КК - КАБДТ - КМАН,\n\n(В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\nгде Кндпи равно 530 - с 1 января по 31 декабря 2015 года включительно, 559 - на период с 1 января 2016 года;\n\nКц - коэффициент, который определяется в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса;\n\nКд и Кдв - коэффициенты, которые определяются в соответствии со статьей 3422 настоящего Кодекса;\n\nКЗ и ККАН - коэффициенты, которые определяются в порядке, установленном соответственно пунктами 3 и 4 настоящей статьи; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\nЕсли иное не указано в настоящем пункте, КК устанавливается равным 428 с 1 января 2019 года. При этом Кк устанавливается равным 0 при добыче нефти, указанной в абзаце одиннадцатом пункта 3 статьи 342 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 30.11.2016 № 401-ФЗ) (В редакции  федеральных законов от 03.08.2018 № 301-ФЗ,  от 29.09.2019 № 325-ФЗ, от 15.10.2020 № 342-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nКабдт - коэффициент, который определяется в порядке, установленном пунктом 11 настоящей статьи; (Дополнение абзацем - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\nКман - коэффициент, который определяется в порядке, установленном пунктом 7 настоящей статьи; (Дополнение абзацем - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 03.08.2018 № 301-ФЗ) (Утратил силу - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\nВ случае, если величина начальных извлекаемых запасов нефти (Vз) по конкретному участку недр меньше 5 млн. тонн и степень выработанности запасов (Свз) конкретного участка недр, определяемая в порядке, установленном настоящим пунктом, меньше или равна 0,05, коэффициент Кз рассчитывается по следующей формуле:\n\nКз = 0,125 х Vз + 0,375,\n\nгде Vз - начальные извлекаемые запасы нефти (в млн. тонн) с точностью до 3-го знака после запятой, утвержденные в установленном порядке с учетом прироста и списания запасов нефти и определяемые как сумма извлекаемых запасов всех категорий на 1 января года, предшествующего году налогового периода, и накопленной добычи с начала разработки конкретного участка недр в соответствии с данными государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году налогового периода. (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\nСтепень выработанности запасов конкретного участка недр (Свз), лицензия на право пользования которым предоставлена до 1 января 2012 года, определяется по состоянию на 1 января 2012 года на основании данных государственного баланса запасов полезных ископаемых, утвержденного в 2011 году, как частное от деления суммы накопленной добычи нефти на конкретном участке недр (N) на начальные извлекаемые запасы нефти (Vз) конкретного участка недр.\n\nСтепень выработанности запасов конкретного участка недр (Свз), лицензия на право пользования которым предоставлена начиная с 1 января 2012 года, определяется по состоянию на 1 января года, в котором предоставлена лицензия на право пользования недрами, на основании данных государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году получения лицензии на право пользования недрами, как частное от деления суммы накопленной добычи нефти на конкретном участке недр (N) на начальные извлекаемые запасы нефти (Vз) конкретного участка недр.\n\nВ случае, если запасы нефти поставлены на государственный баланс запасов полезных ископаемых в году, предшествующем году налогового периода, или в году налогового периода, сумма накопленной добычи нефти на конкретном участке недр (N) и начальные извлекаемые запасы нефти (Vз) для применения коэффициента Кз определяются налогоплательщиком самостоятельно на основании заключения государственной экспертизы запасов нефти, утвержденного федеральным органом исполнительной власти, осуществляющим в установленном порядке ведение государствен\n\nного баланса запасов полезных ископаемых, и после утверждения государственного баланса запасов полезных ископаемых уточняются в порядке, установленном настоящим пунктом.\n\nВ случае, если в соответствии с настоящим пунктом величина начальных извлекаемых запасов (Vз) конкретного участка недр превышает или равна 5 млн. тонн и (или) степень выработанности запасов (Свз) конкретного участка недр превышает 0,05, коэффициент Кз принимается равным 1.\n\nВ случае, если сумма накопленной добычи нефти на конкретном участке недр (N) превышает начальные извлекаемые запасы нефти (Vз), использованные при расчете коэффициента Кз по формуле, приведенной в настоящем пункте, к сумме превышения применяется коэффициент Кз, равный 1.\n\nРассчитанный в порядке, определенном настоящим пунктом, коэффициент Кз округляется до 4-го знака в соответствии с действующим порядком округления.\n\nПорядок определения коэффициента Кз по формуле, приведенной в настоящем пункте, не применяется в отношении нефти, облагаемой по ставке 0 рублей, установленной пунктом 1 статьи 342 настоящего Кодекса. При этом коэффициент Кз принимается равным 1.\n\n1) (Подпункт утратил силу - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\n2) нефти на участках недр, расположенных полностью или частично в границах Республики Саха (Якутия), Иркутской области, Красноярского края, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 25 млн. тонн на участке недр;\n\nнаступление 31 декабря 2016 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2007 года и степень выработанности запасов (Св) которых на 1 января 2007 года меньше или равна 0,05, если иное не установлено абзацем четвертым настоящего подпункта;\n\nнаступление 31 декабря 2021 года для участков недр, степень выработанности запасов (Св) которых на 1 января 2015 года меньше или равна 0,05 и в отношении которых дата государственной регистрации лицензии на право пользования недрами приходится на период до 31 декабря 2011 года - для лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или на период до 31 декабря 2006 года - для лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых;\n\nистечение десяти лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение пятнадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзацах третьем и четвертом настоящего подпункта;\n\n3) нефти на участках недр, расположенных севернее Северного полярного круга полностью или частично в границах внутренних морских вод и территориального моря, на континентальном шельфе Российской Федерации, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 35 млн. тонн на участке недр;\n\nнаступление 31 декабря 2018 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2009 года и степень выработанности запасов (Св) которых на 1 января 2009 года меньше или равна 0,05, если иное не установлено абзацем четвертым настоящего подпункта;\n\nнаступление 31 декабря 2021 года для участков недр, степень выработанности запасов (Св) которых на 1 января 2015 года меньше или равна 0,05 и в отношении которых дата государственной регистрации лицензии на право пользования недрами приходится на период до 31 декабря 2011 года - для лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или на период до 31 декабря 2006 года - для лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых;\n\nистечение десяти лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение пятнадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзацах третьем и четвертом настоящего подпункта;\n\n4) нефти на участках недр, расположенных полностью или частично в Азовском море, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств: (В редакции Федерального закона от 28.11.2015 № 325-ФЗ)\n\nдостижение накопленного объема добычи нефти 10 млн. тонн на участке недр;\n\nнаступление 31 декабря 2015 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2009 года и степень выработанности запасов (Св) которых на 1 января 2009 года меньше или равна 0,05;\n\nистечение семи лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение двенадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзаце третьем настоящего подпункта;\n\n5) нефти на участках недр, расположенных полностью или частично на территории Ненецкого автономного округа, полуострове Ямал в Ямало-Ненецком автономном округе, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 15 млн. тонн на участке недр;\n\nнаступление 31 декабря 2015 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2009 года и степень выработанности запасов (Св) которых на 1 января 2009 года меньше или равна 0,05, если иное не установлено абзацем четвертым настоящего подпункта;\n\nнаступление 31 декабря 2021 года для участков недр, степень выработанности запасов (Св) которых на 1 января 2015 года меньше или равна 0,05 и в отношении которых дата государственной регистрации лицензии на право пользования недрами приходится на период до 31 декабря 2014 года - для лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или на период до 31 декабря 2009 года - для лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых;\n\nистечение семи лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение двенадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзацах третьем и четвертом настоящего подпункта;\n\n6) нефти на участках недр, расположенных полностью или частично в Черном море, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 20 млн. тонн на участке недр;\n\nнаступление 31 декабря 2021 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2012 года и степень выработанности запасов (Св) которых на 1 января 2012 года меньше или равна 0,05;\n\nистечение десяти лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение пятнадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзаце третьем настоящего подпункта;\n\n7) нефти на участках недр, расположенных полностью или частично в Охотском море, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 30 млн. тонн на участке недр;\n\nнаступление 31 декабря 2021 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2012 года и степень выработанности запасов (Св) которых на 1 января 2012 года меньше или равна 0,05;\n\nистечение десяти лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение пятнадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзаце третьем настоящего подпункта;\n\n8) нефти на участках недр, расположенных полностью или частично севернее 65 градуса северной широты полностью или частично в границах Ямало-Ненецкого автономного округа, за исключением участков недр, расположенных полностью или частично на территории полуострова Ямал в границах Ямало-Ненецкого автономного округа, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 25 млн. тонн на участке недр;\n\nнаступление 31 декабря 2021 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2012 года и степень выработанности запасов (Св) которых на 1 января 2012 года меньше или равна 0,05;\n\nистечение десяти лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение пятнадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзаце третьем настоящего подпункта;\n\n9) нефти на участках недр, расположенных полностью или частично в Каспийском море, до 1-го числа месяца, следующего за месяцем наступления хотя бы одного из следующих обстоятельств:\n\nдостижение накопленного объема добычи нефти 15 млн. тонн на участке недр, за исключением накопленного объема добычи нефти на новых морских месторождениях углеводородного сырья на данном участке недр;\n\nнаступление 31 декабря 2021 года для участков недр, лицензия на право пользования которыми выдана до 1 января 2009 года и степень выработанности запасов (Св) которых, определенная без учета начальных извлекаемых запасов нефти и накопленной добычи нефти, утвержденных в установленном порядке для новых морских месторождений углеводородного сырья на данном участке недр, на 1 января 2009 года меньше или равна 0,05;\n\nистечение семи лет с даты государственной регистрации лицензии на право пользования недрами для целей разведки и добычи полезных ископаемых или истечение двенадцати лет с даты государственной регистрации лицензии на право пользования недрами одновременно для геологического изучения (поиска, разведки) и добычи полезных ископаемых для участков недр, не указанных в абзаце третьем настоящего подпункта.\n\n(Дополнение подпунктом - Федеральный закон от 28.11.2015 № 325-ФЗ)\n\nНачальные извлекаемые запасы нефти на участке недр, лицензия на право пользования которым выдана до 1 января 2007 года, определяются как сумма извлекаемых запасов всех категорий и накопленной добычи с начала разработки конкретного участка недр в соответствии с данными государственного баланса запасов полезных ископаемых по состоянию на 1 января 2006 года, если иное не установлено абзацами пятым - седьмым настоящего пункта. (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\nНачальные извлекаемые запасы нефти на участке недр, лицензия на право пользования которым выдана до 1 января 2009 года, определяются как сумма извлекаемых запасов всех категорий и накопленной добычи с начала разработки конкретного участка недр в соответствии с данными государственного баланса запасов полезных ископаемых по состоянию на 1 января 2008 года, если иное не установлено абзацами вторым или пятым - седьмым настоящего пункта. (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\nНачальные извлекаемые запасы нефти на участке недр, лицензия на право пользования которым выдана до 1 января 2012 года, определяются как сумма извлекаемых запасов всех категорий и накопленной добычи с начала разработки конкретного участка недр в соответствии с данными государственного баланса запасов полезных ископаемых по состоянию на 1 января 2011 года, если иное не установлено абзацами вторым, третьим или пятым - седьмым настоящего пункта. (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\nПри определении степени выработанности запасов (Св) конкретного участка недр на 1 января 2015 года начальные извлекаемые запасы нефти на участке недр определяются как сумма извлекаемых запасов всех категорий и накопленной добычи с начала разработки конкретного участка недр в соответствии с данными государственного баланса запасов полезных ископаемых: (В редакции Федерального закона от 05.04.2016 № 102-ФЗ)\n\nна 1 января 2013 года - для участков недр, лицензия на право пользования которыми впервые выдана до 1 января 2013 года;\n\nна 1 января 2015 года - для участков недр, лицензия на право пользования которыми впервые выдана после 1 января 2013 года.\n\nКМАН = ЭП x Р - ФМ,\n\n(В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nгде ЭП - коэффициент, рассчитываемый в порядке, установленном пунктом 8 настоящей статьи;\n\nР - среднее значение за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, рассчитываемое в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса;\n\nАбзац; (Утратил силу - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nФМ - коэффициент, рассчитываемый в порядке, установленном пунктом 9 настоящей статьи.\n\nПри добыче углеводородного сырья на новых морских месторождениях, по которым истек срок, установленный подпунктами 1 - 4 пункта 6 статьи 338 настоящего Кодекса, в течение которого налоговая база по углеводородному сырью, добытому на указанных месторождениях (за исключением газа природного горючего), определяется как стоимость добытых полезных ископаемых, и применяются налоговые ставки, установленные пунктом 21 статьи 342 настоящего Кодекса, начиная с налогового периода, в котором в отношении указанных месторождений начато применение налоговых ставок, установленных подпунктами 9 и 10 пункта 2 статьи 342 настоящего Кодекса, значение коэффициента Кман принимается равным нулю:\n\nдо 31 марта 2032 года (включительно) - для месторождений, указанных в подпунктах 1, 2 и абзаце втором подпункта 3 пункта 6 статьи 338 настоящего Кодекса; (В редакции Федерального закона от 28.05.2022 № 142-ФЗ)\n\nдо 31 марта 2042 года (включительно) - для месторождений, указанных в абзаце первом подпункта 3 пункта 6 статьи 338 настоящего Кодекса; (В редакции Федерального закона от 28.05.2022 № 142-ФЗ)\n\nбез ограничения срока - для месторождений, указанных в подпункте 4 пункта 6 статьи 338 настоящего Кодекса.\n\nЗначение коэффициента Кман также принимается равным нулю при добыче газового конденсата на месторождениях, указанных в примечании 9 к единой Товарной номенклатуре внешнеэкономической деятельности Евразийского экономического союза, по состоянию на 1 января 2018 года.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\nпри сложившейся за период мониторинга средней цене на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) до 109,5 доллара США за 1 тонну (включительно) - в размере 0;\n\nпри превышении сложившейся за период мониторинга средней цены на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) уровня 109,5 доллара США за 1 тонну, но не более 146 долларов США за 1 тонну (включительно) - в размере, равном 35 процентам разницы между сложившейся за период мониторинга средней ценой указанной нефти в долларах США за 1 тонну и 109,5 доллара США;\n\nпри превышении сложившейся за период мониторинга средней цены на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) уровня 146 долларов США за 1 тонну, но не более 182,5 доллара США за 1 тонну (включительно) - в размере, равном сумме 12,78 доллара США за 1 тонну и 45 процентов разницы между сложившейся за период мониторинга средней ценой указанной нефти в долларах США за 1 тонну и 146 долларами США;\n\nпри превышении сложившейся за период мониторинга средней цены на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) уровня 182,5 доллара США за 1 тонну - в размере, равном сумме 29,2 доллара США за 1 тонну и 30 процентов разницы между сложившейся за период мониторинга средней ценой указанной нефти в долларах США за 1 тонну и 182,5 доллара США.\n\nПри этом средняя цена на нефть сырую марки \"Юралс\" на мировых рынках нефтяного сырья (средиземноморском и роттердамском) за период мониторинга определяется в порядке, установленном пунктом 3 статьи 31 Закона Российской Федерации \"О таможенном тарифе\".\n\nРассчитанный в порядке, определенном настоящим пунктом, коэффициент ЭП округляется до первого десятичного знака в меньшую сторону.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\nЕсли иное не установлено настоящим пунктом, в течение налоговых периодов, в которых действует решение Правительства Российской Федерации, принятое в соответствии с пунктом 62 статьи 31 Закона Российской Федерации \"О таможенном тарифе\", коэффициент ФМ рассчитывается по следующей формуле:\n\nФМ = П x Р,\n\n(В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nгде П - ставка вывозной таможенной пошлины на нефть сырую, действовавшая в налоговом периоде и выраженная в долларах США за 1 тонну;\n\nР - коэффициент, определяемый в порядке, установленном настоящей статьей. (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nРассчитанный в порядке, определенном настоящим пунктом, коэффициент ФМ округляется до первого десятичного знака в меньшую сторону в соответствии с действующим порядком округления.\n\nАбзац. (Утратил силу - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\n11. Коэффициент КАБДТ\n\nопределяется по следующей формуле:\n\nКАБДТ = 105 x ИАБ + 92 x ИДТ + НБУГ + НДФО,\n\nгде ИАБ - бинарный коэффициент для автомобильного бензина, принимает значение, равное нулю для налоговых периодов, в которых коэффициент ДАБ_С, рассчитываемый налогоплательщиком самостоятельно в порядке, установленном настоящим пунктом, принимает значение менее нуля или равное нулю, при иных значениях коэффициента ДАБ_С принимает значение, равное 1;\n\nИДТ - бинарный коэффициент для дизельного топлива, принимает значение, равное нулю для налоговых периодов, в которых коэффициент ДДТ_С, рассчитываемый налогоплательщиком самостоятельно в порядке, установленном настоящим пунктом, принимает значение менее нуля или равное нулю, при иных значениях коэффициента ДДТ_С принимает значение, равное 1.\n\nКоэффициент НБУГ, характеризующий надбавку за изменение механизма демпфера с 2020 года, определяется по следующей формуле:\n\nНБУГ = (НК_ДЕМП - СК_ДЕМП - 0,5 x КК2021) x (37,5 / 484) - 124,\n\nгде НК_ДЕМП - коэффициент, характеризующий демпфер после 2020 года, определяется по формуле:\n\nНК_ДЕМП = (ДАБ x КАБ_КОМП + ДДТ х КДТ_КОМП)  x КНВ, (В редакции  Федерального закона от 21.11.2022 № 443-ФЗ)\n\nгде ДАБ, КАБ_КОМП, ДДТ, КДТ_КОМП определяются в порядке, установленном пунктом 27 статьи 200 настоящего Кодекса;\n\nКНВ - коэффициент, принимаемый равным 1,3 для налоговых периодов, дата начала которых приходится на период с 1 января 2023 года по 31 декабря 2026 года включительно, и равным 1 для налоговых периодов, дата начала которых приходится на период с 1 января 2027 года; (Дополнение абзацем - Федеральный закон от 21.11.2022 № 443-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nСК_ДЕМП - коэффициент, характеризующий демпфер до 2020 года, определяется по формуле:\n\nСК_ДЕМП = (ДАБ_С + ФАБ + ДДТ_С + ФДТ) x (1 / 2),\n\nгде ДАБ_С = ЦАБэксп - ЦАБвр_С;\n\nДДТ_С = ЦДТэксп - ЦДТвр_С;\n\nФАБ - фиксированная компонента по бензину равна 5 600, если ДАБ_С больше нуля, и равна нулю при любом ином значении ДАБ_С;\n\nФДТ - фиксированная компонента по дизельному топливу равна 5 000, если ДДТ_С больше нуля, и равна нулю при любом ином значении ДДТ_С;\n\nЦАБэксп, ЦДТэксп - коэффициенты, определяемые в порядке, установленном пунктом 27 статьи 200 настоящего Кодекса;\n\nЦАБвр_С - условное значение средней оптовой цены реализации автомобильного бензина АИ-92 класса 5 на территории Российской Федерации, принимаемое равным 58 800 на период с 1 января по 31 декабря 2020 года включительно, 61 740 на период с 1 января по 31 декабря 2021 года включительно, 64 827 на период с 1 января по 31 декабря 2022 года включительно, 68 068 на период с 1 января по 31 декабря 2023 года включительно, 71 472 на период с 1 января по 31 декабря 2024 года включительно, 75 046 на период с 1 января по 31 декабря 2025 года включительно, 78 798 на период с 1 января по 31 декабря 2026 года включительно, 82 738 на период с 1 января по 31 декабря 2027 года включительно; (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 31.07.2023 № 389-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nЦДТвр_С - условное значение средней оптовой цены реализации дизельного топлива класса 5 на территории Российской Федерации, принимаемое равным 52 500 на период с 1 января по 31 декабря 2020 года включительно, 55 125 на период с 1 января по 31 декабря 2021 года включительно, 57 881 на период с 1 января по 31 декабря 2022 года включительно, 60 775 на период с 1 января по 31 декабря 2023 года включительно, 63 814 на период с 1 января по 31 декабря 2024 года включительно, 67 005 на период с 1 января по 31 декабря 2025 года включительно, 70 355 на период с 1 января по 31 декабря 2026 года включительно, 73 873 на период с 1 января по 31 декабря 2027 года включительно; (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 31.07.2023 № 389-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nКК2021 - коэффициент, характеризующий корректировку демпфера в 2021 году, определяется по формуле:\n\nКК2021 = (ЦАБвр_2021 - ЦАБвр) x КАБ_КОМП + (ЦДТвр_2021 - ЦДТвр) x КДТ_КОМП,\n\nгде ЦАБвр и ЦДТвр - коэффициенты, определяемые в порядке, установленном пунктом 27 статьи 200 настоящего Кодекса;\n\nЦАБвр_2021 - условное значение средней оптовой цены реализации автомобильного бензина АИ-92 класса 5 на территории Российской Федерации до корректировки демпфера 2021 года, принимаемое равным 56 300 на период с 1 мая по 31 декабря 2021 года включительно, 59 000 на период с 1 января по 31 декабря 2022 года включительно, 62 000 на период с 1 января по 31 декабря 2023 года включительно, 65 000 на период с 1 января по 31 декабря 2024 года включительно, 68 300 на период с 1 января по 31 декабря 2025 года включительно, 71 700 на период с 1 января по 31 декабря 2026 года включительно, 75 300 на период с 1 января по 31 декабря 2027 года включительно; (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 31.07.2023 № 389-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nЦДТвр_2021 - условное значение средней оптовой цены реализации дизельного топлива класса 5 на территории Российской Федерации до корректировки демпфера 2021 года, принимаемое равным 50 700 на период с 1 мая по 31 декабря 2021 года включительно, 53 250 на период с 1 января по 31 декабря 2022 года включительно, 56 000 на период с 1 января по 31 декабря 2023 года включительно, 58 700 на период с 1 января по 31 декабря 2024 года включительно, 61 700 на период с 1 января по 31 декабря 2025 года включительно, 64 800 на период с 1 января по 31 декабря 2026 года включительно, 68 050 на период с 1 января по 31 декабря 2027 года включительно. (В редакции  федеральных законов от 14.07.2022 № 323-ФЗ, от 31.07.2023 № 389-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nКоэффициент НДФО, характеризующий дальневосточную надбавку, определяется по следующей формуле:\n\nНДФО = ДДВ_АБ x (2/484) + ДДВ_ДТ x (3,7/484),\n\nгде ДДВ_АБ и ДДВ_ДТ - величины, определяемые в рублях за 1 тонну, рассчитываются налогоплательщиком самостоятельно как сумма величин 2 000 и ДАБ или ДДТ соответственно. Величины ДАБ и ДДТ определяются в порядке, установленном пунктом 27 статьи 200 настоящего Кодекса. При этом, если величина ДДВ_АБ или ДДВ_ДТ оказалась более 2 000 или менее 0, для целей настоящего пункта ДДВ_АБ или ДДВ_ДТ принимается равной 2 000 или 0 соответственно.\n\nПоказатели НБУГ, НК_ДЕМП, СК_ДЕМП и НДФО, рассчитанные в порядке, установленном настоящим пунктом, округляются до четвертого знака после запятой в соответствии с действующим порядком округления.\n\nЕсли значение НБУГ, определенное для налогового периода по формуле, установленной настоящим пунктом, принимает значение менее нуля, то в таком налоговом периоде значение НБУГ принимается равным нулю.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 301-ФЗ) (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 366-ФЗ)","article_title":"Статья 342.5. Порядок определения показателя, характеризующего особенности добычи нефти (Дм)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e82c5a4362198f75e060bc5f98691856ee32c62453d507795084913ad79261e9"},{"code_id":"NK_RF_2","article_number":"342.6","version_date":"2000-07-31","article_text":"1. Коэффициент, характеризующий уровень налогообложения нефти, добываемой на участках недр, в отношении которой исчисляется налог на дополнительный доход от добычи углеводородного сырья (Кндд), определяется по следующей формуле:\n\n(В редакции Федерального закона от 27.04.2023 № 136-ФЗ)\n\nгде Цнефть - средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США за баррель, определяемый в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса;\n\nР - среднее за налоговый период значение курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, определяемое в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса;\n\nКг - коэффициент, характеризующий период времени, прошедший с даты начала промышленной добычи нефти на участке недр, определяемый в соответствии с пунктом 2 настоящей статьи;\n\nЭП - ставка вывозной таможенной пошлины на нефть, выраженная в долларах США за тонну нефти обезвоженной, обессоленной и стабилизированной, установленная на календарный месяц, соответствующий налоговому периоду, в отношении нефти, добытой на участке недр, в порядке, определенном Законом Российской Федерации \"О таможенном тарифе\";\n\nКАБДТ - коэффициент, определяемый в порядке, установленном пунктом 11 статьи 3425 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nИТ-Р - коэффициент, характеризующий регион добычи нефти, принимаемый равным нулю в отношении нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпункте 5 пункта 1 статьи 33345 настоящего Кодекса, и принимаемый равным 1 в других случаях; (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nКЮ - коэффициент, определяемый для налогового периода по следующей формуле, если иное не установлено настоящим пунктом: (Дополнение абзацем - Федеральный закон от 27.04.2023 № 136-ФЗ)\n\nКЮ = (Цнефть - Цюралс) х Р х 7,3, (Дополнение абзацем - Федеральный закон от 27.04.2023 № 136-ФЗ)\n\nгде Цюралс - средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США за баррель, определяемый в порядке, установленном абзацем вторым пункта 3 статьи 342 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 27.04.2023 № 136-ФЗ)\n\nВ случае, если рассчитанное в соответствии с абзацем десятым настоящего пункта значение коэффициента КЮ составляет менее 0, коэффициент КЮ принимается равным 0. (Дополнение абзацем - Федеральный закон от 27.04.2023 № 136-ФЗ)\n\nКоэффициент КЮ принимается равным 0 для налоговых периодов, для которых коэффициент КГ принимает значение меньше 1, и для налоговых периодов, дата начала которых приходится на период начиная с 1 января 2024 года. (Дополнение абзацем - Федеральный закон от 27.04.2023 № 136-ФЗ)\n\nВ случае, если значение коэффициента Кг меньше единицы, для целей определения Кндд значение ЭП принимается равным 0. Положения настоящего абзаца не применяются в отношении нефти, добытой на участках недр, указанных в подпункте 4 пункта 1 статьи 33345 настоящего Кодекса.\n\n2. Коэффициент, характеризующий период времени, прошедший с даты начала промышленной добычи нефти на участке недр (Кг), определяется в следующих размерах:\n\n1) 1 - для нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпункте 2 (в части участков недр, для которых коэффициент ККАН, определенный на 1 января 2021 года в порядке, установленном пунктом 4 статьи 3425 настоящего Кодекса, принимается равным 1) и подпункте 3 пункта 1 статьи 33345 настоящего Кодекса, если иное не предусмотрено настоящим подпунктом;\n\n1,2 - для нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпункте 2 пункта 1 статьи 33345 настоящего Кодекса, одновременно расположенных в границах Нефтеюганского, Сургутского и Ханты-Мансийского районов Ханты-Мансийского автономного округа - Югры, на период с 1 января 2021 года по 31 декабря 2023 года (включительно);\n\n1,95 - для нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпункте 2 пункта 1 статьи 33345 настоящего Кодекса, расположенных полностью в границах Ямальского района Ямало-Ненецкого автономного округа, на период с 1 января 2021 года по 31 декабря 2023 года (включительно).\n\nВ отношении нефти, добытой на участках недр, указанных в абзацах втором и третьем настоящего подпункта, коэффициент КГ принимается равным 1 начиная с 1 января 2024 года;\n\n(Подпункт в редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n2) для нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпунктах 1 и 2 (в части участков недр, не указанных в подпункте 1 настоящего пункта) пункта 1 статьи 33345 настоящего Кодекса: (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n0,4 - с 1-го числа календарного месяца, начиная с которого в отношении соответствующего участка недр исчисляется налог на дополнительный доход от добычи углеводородного сырья, по 31 декабря (включительно) года, в котором истекает пять последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на этом участке недр. Положения настоящего абзаца не применяются в отношении участков недр, для которых по состоянию на 1 января календарного года, начиная с которого в отношении соответствующего участка недр исчисляется налог на дополнительный доход от добычи углеводородного сырья, истекло пять последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на этом участке недр; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n0,6 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает пять последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр;\n\n0,8 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает шесть последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр;\n\n1 - с 1 января года, следующего за годом, в котором истекает семь последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр;\n\n3) для нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпункте 4 пункта 1 статьи 33345 настоящего Кодекса:\n\n0,5 - с 1-го числа календарного месяца, начиная с которого в отношении соответствующего участка недр исчисляется налог на дополнительный доход от добычи углеводородного сырья, по 31 декабря (включительно) года, в котором истекает один календарный год, непосредственно следующий за календарным годом начала промышленной добычи нефти на этом участке недр;\n\n0,75 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает один календарный год, непосредственно следующий за календарным годом начала промышленной добычи нефти на соответствующем участке недр;\n\n1 - с 1 января года, следующего за календарным годом, в котором истекает два календарных года, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр. (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\nКоэффициенты, предусмотренные настоящим подпунктом, в размере менее 1 не применяются в отношении участков недр, для которых по состоянию на 1 января календарного года, начиная с которого в отношении соответствующего участка недр исчисляется налог на дополнительный доход от добычи углеводородного сырья, истек один календарный год, непосредственно следующий за календарным годом начала промышленной добычи нефти на этом участке недр; (Дополнение абзацем - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\n4) для нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в подпункте 5 пункта 1 статьи 33345 настоящего Кодекса:\n\n0 - с 1-го числа календарного месяца, начиная с которого в отношении соответствующего участка недр исчисляется налог на дополнительный доход от добычи углеводородного сырья, по 31 декабря (включительно) года, в котором истекает пятнадцать последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на этом участке недр; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n0,2 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает пятнадцать последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n0,4 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает шестнадцать последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n0,6 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает семнадцать последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n0,8 - с 1 января по 31 декабря (включительно) года, следующего за годом, в котором истекает восемнадцать последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр; (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n1 - с 1 января года, следующего за годом, в котором истекает девятнадцать последовательных календарных лет, непосредственно следующих за годом начала промышленной добычи нефти на соответствующем участке недр. (В редакции Федерального закона от 15.10.2020 № 342-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 18.03.2020 № 65-ФЗ)\n\n3. В целях настоящей статьи годом начала промышленной добычи нефти на участке недр признается календарный год, на 1 января которого в соответствии с данными государственного баланса запасов полезных ископаемых степень выработанности запасов нефти такого участка недр впервые превысила 1 процент.\n\nПри этом степень выработанности запасов нефти конкретного участка недр определяется в порядке, установленном подпунктом 1 пункта 5 статьи 33343 настоящего Кодекса.\n\n4. Рассчитанный в порядке, определенном настоящей статьей, коэффициент КНДД округляется до 4-го знака в соответствии с действующим порядком округления.\n\nЕсли значение коэффициента КНДД, определенное в соответствии с настоящей статьей, составляет менее 0, то коэффициент КНДД принимается равным 0.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2018 № 424-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 19.07.2018 № 199-ФЗ)","article_title":"Статья 342.6. Порядок определения коэффициента, характеризующего уровень налогообложения нефти, добываемой на участках недр, в отношении которой исчисляется налог на дополнительный доход от добычи углеводородного сырья (Кндд)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e110120efada537d4d3a4b1267cde108fdb90193010edf174fc700d707ba184a"},{"code_id":"NK_RF_2","article_number":"342.7","version_date":"2000-07-31","article_text":"1. При соблюдении условий, установленных настоящей статьей, коэффициент, характеризующий особенности добычи редких металлов (Крм), принимается равным:\n\n1) 0,1 при добыче руд редких металлов (литий, бериллий, скандий, иттрий, лантан, церий, празеодим, неодим, самарий, европий, гадолиний, тербий, диспрозий, гольмий, эрбий, тулий, иттербий, лютеций, германий, ниобий, тантал, рений), образующих собственные месторождения, редких металлов, указанных в настоящем подпункте, являющихся попутными компонентами в рудах других редких металлов, образующих собственные месторождения, рудах других полезных ископаемых, многокомпонентных комплексных рудах;\n\n2) 1 при добыче руд редких металлов и редких металлов, не указанных в подпункте 1 настоящего пункта.\n\n2. Коэффициент Крм применяется до истечения 120 налоговых периодов начиная с налогового периода, в котором впервые появились основания для определения налоговой базы по налогу на добычу полезных ископаемых при добыче руд редких металлов, указанных в подпункте 1 пункта 1 настоящей статьи, образующих собственные месторождения, редких металлов, указанных в подпункте 1 пункта 1 настоящей статьи, являющихся попутными компонентами в рудах других редких металлов, образующих собственные месторождения, рудах других полезных ископаемых, м\n\nногокомпонентных комплексных рудах.\n\nПо истечении указанного в настоящем пункте срока значение коэффициента Крм принимается равным 1.\n\n(Дополнение статьей - Федеральный закон от 02.08.2019 № 284-ФЗ)","article_title":"Статья 342.7. Порядок определения и применения коэффициента, характеризующего особенности добычи редких металлов (Крм)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dfb91839a5838cd92af8250ee4c41ae7ada5c130a53c9839dc9d03926a0d733a"},{"code_id":"NK_RF_2","article_number":"342.8","version_date":"2000-07-31","article_text":"1. Если иное не предусмотрено настоящей статьей, в отношении налоговых ставок, установленных пунктом 2 статьи 342 настоящего Кодекса, рентный коэффициент КРЕНТА принимается равным 3,5.\n\n2. Рентный коэффициент КРЕНТА принимается равным 0,2 в отношении налоговой ставки, установленной подпунктом 16 пункта 2 статьи 342 настоящего Кодекса, до истечения десяти следующих подряд календарных лет, начинающихся с года начала промышленной добычи соответствующих полезных ископаемых на участке недр, при одновременном выполнении следующих требований:\n\n1) в добываемой на участках недр, расположенных полностью или частично на территории Красноярского края, многокомпонентной комплексной руде, содержащей медь, и (или) никель, и (или) металлы платиновой группы, содержание никеля составляет не более 0,5 процента и металлов платиновой группы не более 1 грамма на 1 тонну руды;\n\n2) степень выработанности запасов участков недр, указанных в подпункте 1 настоящего пункта, по состоянию на 1 января 2021 года составляет менее 1 процента;\n\n3) деятельность по добыче указанных в подпункте 1 настоящего пункта полезных ископаемых является частью нового инвестиционного проекта, в отношении которого налогоплательщиком заключено и действует соглашение о защите и поощрении капиталовложений.\n\n3. Рентный коэффициент КРЕНТА принимается равным 1 в отношении:\n\n1) налоговых ставок, установленных подпунктами 1, 31, 7, 9 - 15, 16 (если иное не предусмотрено пунктом 2 настоящей статьи), подпунктами 18 и 19 пункта 2 статьи 342 настоящего Кодекса; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n2) налоговых ставок, установленных пунктом 2 статьи 342 настоящего Кодекса для следующих видов добытых полезных ископаемых: торфа, горючих сланцев, сырья радиоактивных металлов, неметаллического сырья, используемого в основном в строительной индустрии, подземных промышленных и термальных вод, битуминозных пород, концентратов и других полупродуктов, содержащих драгоценные металлы, общераспространенных полезных ископаемых, природных алмазов и других драгоценных и полудрагоценных камней; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n3) налоговых ставок, установленных подпунктами 2 и 3, 4 - 6, 8 и 17 пункта 2 статьи 342 настоящего Кодекса, при добыче полезных ископаемых на участках недр, степень выработанности запасов которых по состоянию на 1 января 2021 года составляет менее 1 процента, при выполнении одного из следующих условий: (В редакции  федеральных законов от 29.11.2021 № 382-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nдеятельность по добыче соответствующих полезных ископаемых на таких участках недр является частью нового инвестиционного проекта, в отношении которого налогоплательщиком заключено и действует соглашение о защите и поощрении капиталовложений либо исполнено соглашение о защите и поощрении капиталовложений;\n\nдеятельность по добыче соответствующих полезных ископаемых осуществляется налогоплательщиком в связи с выполнением им специального инвестиционного контракта, заключенного до 31 декабря 2020 года, в соответствии с Федеральным законом от 31 декабря 2014 года № 488-ФЗ \"О промышленной политике в Российской Федерации\".\n\nРентный коэффициент КРЕНТА, равный 1, применяется по основаниям, указанным в настоящем подпункте, в течение или пятнадцати следующих подряд календарных лет, начинающихся с года начала промышленной добычи полезных ископаемых на участке недр, или срока действия соглашения о защите и поощрении капиталовложений, или срока действия специального инвестиционного контракта в зависимости от того, какой срок истекает позднее;\n\n4) налоговых ставок, установленных пунктом 2 статьи 342 настоящего Кодекса для отдельных видов полезных ископаемых, добытых на участках недр, указанных в настоящем подпункте, при условии заключения организацией, владеющей лицензиями на пользование такими участками недр и не являющейся участником регионального инвестиционного проекта, соглашения о добыче и сохранении занятости (далее в настоящей статье - соглашение о сохранении занятости) в соответствии с пунктами 4 - 10 настоящей статьи.\n\nВ целях применения рентного коэффициента КРЕНТА в соответствии с настоящим подпунктом к отдельным видам полезных ископаемых относятся:\n\nтоварные руды цветных металлов, содержащие вольфрам в качестве основного компонента, добытые на участках недр, расположенных полностью или частично на территории Забайкальского края, Приморского края или Республики Бурятия;\n\nборные руды, многокомпонентные комплексные руды, содержащие свинец и цинк, и полезные компоненты многокомпонентных комплексных руд, содержащих свинец и цинк (за исключением драгоценных металлов, являющихся полезными компонентами указанных многокомпонентных комплексных руд), добытые на участках недр, расположенных полностью или частично на территории Приморского края;\n\nтоварные руды редких металлов, содержащие одновременно титан, ниобий, тантал, редкоземельные металлы, добытые на участках недр, расположенных полностью или частично на территории Мурманской области.\n\nРентный коэффициент КРЕНТА, равный 1, применяется с даты, указанной в соглашении о сохранении занятости, но не ранее 1 января календарного года, в котором заключено такое соглашение, и до последнего числа месяца (включительно), предшествующего месяцу, в котором прекращено действие соглашения о сохранении занятости в соответствии с пунктом 10 настоящей статьи.\n\n4. Соглашение о сохранении занятости заключается организацией, указанной в подпункте 4 пункта 3 настоящей статьи, с Министерством финансов Российской Федерации и федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере изучения, использования, воспроизводства и охраны природных ресурсов.\n\nДанная организация вправе заключить соглашение о сохранении занятости до 31 декабря 2021 года (включительно). С 1 января 2022 года заключение соглашений о сохранении занятости не допускается (за исключением случаев, предусмотренных пунктом 5 настоящей статьи).\n\nФорма соглашения о сохранении занятости, форма уведомления о прекращении действия соглашения о сохранении занятости, порядок заключения (прекращения действия) соглашения о сохранении занятости, внесения в него изменений и осуществления контроля за его исполнением утверждаются Министерством финансов Российской Федерации по согласованию с федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере изучения, использования, воспроизводства и охраны природных ресурсов.\n\n5. В случае реорганизации организации, заключившей соглашение о сохранении занятости (далее в настоящем пункте - первоначальное соглашение о сохранении занятости), и (или) перехода в соответствии с законодательством Российской Федерации о недрах права пользования участком недр (участками недр), указанным (указанными) в первоначальном соглашении о сохранении занятости, и при условии, что на момент совершения данных действий действие первоначального соглашения о сохранении занятости не прекращено по основаниям, предусмотренным подпунктами 3 - 7 пункта 9 настоящей статьи, организация (организации), к которой (к которым) перешли права пользования участком недр (участками недр), и (или) организация, заключившая первоначальное соглашение о сохранении занятости, вправе заключить новое соглашение (новые соглашения) о сохранении занятости при условии, что объем обязательств, возникших из такого нового соглашения (соглашений в совокупности), равен объему обязательств, возникших при заключении первоначального соглашения о сохранении занятости.\n\nПри этом существенные условия соглашения (соглашений) о сохранении занятости, предусмотренные подпунктами 4 и 5 пункта 6 настоящей статьи, должны быть выполнены в отношении всего объема соответствующих обязательств, возникших из таких соглашений о сохранении занятости.\n\n6. Соглашение о сохранении занятости должно содержать следующие существенные условия:\n\n1) предмет соглашения о сохранении занятости - предоставление организации, заключившей соглашение о сохранении занятости, права на применение рентного коэффициента КРЕНТА, равного 1, при добыче отдельных видов полезных ископаемых, предусмотренных подпунктом 4 пункта 3 настоящей статьи, на участках недр, указанных в соглашении о сохранении занятости, на период действия такого соглашения при условии принятия данной организацией на себя обязательств по сохранению численности работников организации на уровне не ниже указанного в соглашении о сохранении занятости и по обеспечению добычи полезных ископаемых, в отношении которых применяется рентный коэффициент КРЕНТА, равный 1, в объемах и в сроки, предусмотренные соглашением о сохранении занятости;\n\n2) номера лицензий на пользование участками недр, при добыче отдельных видов полезных ископаемых на которых может применяться рентный коэффициент КРЕНТА, равный 1, и их географические координаты;\n\n3) идентификационный номер налогоплательщика, полное и сокращенное наименование организации (при наличии), владеющей лицензиями на пользование участками недр, указанными в соглашении о сохранении занятости;\n\n4) планируемый объем добычи отдельных видов полезных ископаемых, предусмотренных подпунктом 4 пункта 3 настоящей статьи, при добыче которых может применяться рентный коэффициент КРЕНТА, равный 1, по каждому году на период с 1 января 2021 года или с 1-го числа календарного года, на который приходится дата заключения соглашения о сохранении занятости, по 31 декабря 2030 года (включительно) отдельно по участкам недр, указанным в соглашении о сохранении занятости, и видам добытых полезных ископаемых (далее в настоящей статье - планируемый объем добычи). При этом планируемый объем добычи определяется в соответствии с техническим проектом разработки месторождения полезных ископаемых;\n\n5) минимальная предельная численность работников, в отношении которых должно быть обеспечено выполнение условия о сохранении их занятости, определяемая как величина, которая не может быть менее среднесписочной численности работников организации, владеющей лицензиями на пользование участками недр, указанными в соглашении о сохранении занятости, за декабрь 2020 года (далее в настоящей статье - минимальная предельная численность работников).\n\n7. Основанием для отказа в заключении соглашения о сохранении занятости является наличие одного из следующих обстоятельств:\n\n1) в соглашении о сохранении занятости указана недостоверная информация;\n\n2) организация, участки недр и (или) виды добытых полезных ископаемых, указанные в соглашении о сохранении занятости, не соответствуют условиям, установленным настоящей статьей;\n\n3) соглашение о сохранении занятости не соответствует требованиям, предусмотренным пунктами 4 - 6 настоящей статьи;\n\n4) в случае заключения соглашения (соглашений) о сохранении занятости по основаниям, предусмотренным пунктом 5 настоящей статьи, если не выполнено условие в отношении объема обязательств, определенное указанным пунктом.\n\nВ иных случаях внесение изменений в соглашение о сохранении занятости не допускается.\n\n1) по истечении срока действия соглашения о сохранении занятости с 1 января 2031 года;\n\n2) в случае ликвидации или реорганизации организации, заключившей соглашение о сохранении занятости;\n\n3) в случае, если в период действия соглашения о сохранении занятости среднесписочная численность работников организации, заключившей соглашение о сохранении занятости, за один календарный месяц оказалась менее минимальной предельной численности работников, указанной в соглашении о сохранении занятости;\n\n4) в случае, если в период действия соглашения о сохранении занятости количество добытого полезного ископаемого за все налоговые периоды календарного года по участку недр, указанному в соглашении о сохранении занятости, оказалось менее планируемого объема добычи такого полезного ископаемого за соответствующий календарный год, указанного в соглашении о сохранении занятости;\n\n5) в случае несоблюдения организацией, заключившей соглашение о сохранении занятости, требования, предусмотренного пунктом 8 настоящей статьи;\n\n6) в случае прекращения права пользования одним из участков недр, указанных в соглашении о сохранении занятости, в соответствии с законодательством Российской Федерации о недрах;\n\n7) по соглашению сторон.\n\nПри наступлении обстоятельств, указанных в подпунктах 3 - 6 пункта 9 настоящей статьи, действие соглашения о сохранении занятости прекращается с 1 января календарного года, для которого установлено наступление таких обстоятельств. При этом суммы налога, исчисленные в отношении добытых полезных ископаемых с применением рентного коэффициента КРЕНТА, равного 1, за налоговые периоды, заканчивающиеся после 1 января года, для которого установлено наступление таких обстоятельств, подлежат перерасчету с применением рентного коэффициента КРЕНТА, равного 3,5, и уплате в бюджет в части, превышающей фактически уплаченные суммы налога для соответствующих налоговых периодов, с уплатой сумм пеней, начисляемых на указанную величину превышения со дня, следующего за днем уплаты налога для соответствующего налогового периода.\n\nПри наступлении обстоятельства, указанного в подпункте 7 пункта 9 настоящей статьи, действие соглашения о сохранении занятости прекращается с даты заключения соглашения о прекращении действия такого соглашения.\n\n1) степень выработанности запасов полезного ископаемого на участке недр рассчитывается налогоплательщиком самостоятельно на основании данных государственного баланса запасов полезных ископаемых по состоянию на соответствующую дату как частное от деления суммы накопленной добычи полезного ископаемого (включая потери при добыче) на участке недр на начальные извлекаемые запасы полезного ископаемого на участке недр. Рассчитанное в порядке, установленном настоящим пунктом, значение степени выработанности запасов полезного ископаемого округляется до второго знака после запятой в соответствии с действующим порядком округления;\n\n2) под годом начала промышленной добычи полезного ископаемого на участке недр понимается год, по состоянию на 1-е число которого степень выработанности запасов полезного ископаемого на таком участке недр впервые превысила 1 процент.\n\n(Дополнение статьей - Федеральный закон от 02.07.2021 № 309-ФЗ)","article_title":"Статья 342.8. Порядок определения и применения рентного коэффициента КРЕНТА","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"496ee9c9319b1733cc13c672ec14b59e5243b806cecfeb1b3f9ca19b7175c39c"},{"code_id":"NK_RF_2","article_number":"342.9","version_date":"2000-07-31","article_text":"1. Если иное не установлено настоящей статьей, коэффициент КЖР определяется по следующей формуле:\n\nКЖР = ЦЖР x 0,067 x (СЖР/62%) x Р, (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nгде ЦЖР - средняя за налоговый период мировая цена на железную руду (с содержанием железа 62 процента) в соответствии с индексом SGX TSI Iron Ore CFR China (62% Fe Fines) Index Futures / Options, определяемая в порядке, установленном федеральным органом исполнительной власти, осуществляющим функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, в долларах США за 1 тонну. Показатель ЦЖР рассчитывается федеральным органом исполнительной власти, осуществляющим функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, и подлежит размещению на официальном сайте указанного федерального органа исполнительной власти в сети \"Интернет\" до 10-го числа календарного месяца, следующего за налоговым периодом. В случае, если показатель ЦЖР не размещен (своевременно не размещен) на официальном сайте федерального органа исполнительной власти, осуществляющего функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, данный показатель рассчитывается налогоплательщиком самостоятельно в порядке, установленном указанным федеральным органом исполнительной власти;\n\nСЖР - содержание (в процентах) железа в руде на соответствующем участке недр в соответствии с данными государственного баланса запасов полезных ископаемых, утвержденного в году, предшествующем году налогового периода;\n\nP - среднее значение за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, определяемое налогоплательщиком самостоятельно как среднеарифметическое значение курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, за все дни в календарном месяце.\n\nРассчитанный в порядке, определенном настоящей статьей, коэффициент КЖР округляется до первого знака после запятой в соответствии с действующим порядком округления.\n\n2. В случае, если значение показателя ЦЖР, определенное для налогового периода, оказалось меньше 60 долларов США за 1 тонну, значение коэффициента КЖР для налогового периода принимается равным произведению 0,63 доллара США и среднего значения за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации (P).\n\n3. Коэффициент КЖР определяется как произведение 0,18 доллара США и среднего значения за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации\n\n(P), в течение сроков, предусмотренных настоящим пунктом, в случае, если деятельность по добыче железных руд на участках недр, степень выработанности запасов которых по состоянию на 1 января 2021 года составляет менее 1 процента, является частью нового инвестиционного проекта, в отношении которого налогоплательщиком заключено и действует соглашение о защите и поощрении капиталовложений либо исполнено такое соглашение.\n\nКоэффициент КЖР определяется в порядке, установленном настоящим пунктом, до истечения пятнадцати следующих подряд календарных лет, начинающихся с года начала промышленной добычи полезных ископаемых на участке недр, или до истечения срока действия соглашения о защите и поощрении капиталовложений в зависимости от того, какой срок истекает позднее.\n\nВ целях настоящего пункта степень выработанности запасов полезного ископаемого, год начала промышленной добычи полезных ископаемых на участке недр определяются в порядке, установленном пунктом 11 статьи 3428 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 29.11.2021 № 382-ФЗ)","article_title":"Статья 342.9. Порядок определения и применения коэффициента КЖР","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d47fa158bfdd273f50f4f68e2229d27fa6965df31972ab96f754c71a2d416051"},{"code_id":"NK_RF_2","article_number":"343","version_date":"2000-07-31","article_text":"Сумма налога по добытым полезным ископаемым, налоговая база при добыче которых в соответствии с подпунктом 3 пункта 2 статьи 338 настоящего Кодекса определяется как их количество, исчисляется к\n\nак произведение соответствующей налоговой ставки и величины налоговой базы. (В редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\nСумма налога, исчисленная в соответствии с настоящим пунктом, подлежит уплате в бюджет по месту нахождения каждого участка недр и по каждому виду угля, предусмотренному подпунктом 11 пункта 2 статьи 337 настоящего Кодекса, в соответствующей доле. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nУказанная доля определяется как отношение суммы налога, исчисленной по каждому виду угля, добытого на участке недр, в условиях отсутствия налогового вычета, к общей сумме налога, исчисленной при добыче угля на этом же участке недр в условиях отсутствия налогового вычета. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 28.12.2010 № 425-ФЗ)\n\nгде НВЭТАН_ОСТАТОК - величина непогашенного налогового вычета, которая рассчитывается налогоплательщиком (правопреемником налогоплательщика) в миллионах рублей по следующей формуле:\n\nгде n - количество налоговых периодов, начало которых приходится на период с 1 января 2025 года по последнее число текущего налогового периода включительно;\n\nНВЭТАН_ИТОГО - показатель, рассчитываемый по формуле:\n\nгде НВЭТАН_Т - сумма налоговых вычетов НВЭТАН, примененных налогоплательщиком (правопреемником налогоплательщика) в соответствии с пунктом 37 статьи 3432 настоящего Кодекса в налоговых периодах, начало которых приходится на период с 1 июля 2022 года по 31 декабря 2024 года включительно, выраженная в миллионах рублей.\n\nНалогоплательщик (правопреемник налогоплательщика) вправе в любом налоговом периоде, начало которого приходится на период с 1 января 2025 года, увеличить сумму налога на величину НДПИДОП_ЭТАН, равную произведению величины НВЭТАН_ОСТАТОК и коэффициента 1,0075, выраженную в миллионах рублей.\n\nЕсли в налоговом периоде налогоплательщик (правопреемник налогоплательщика) воспользовался правом увеличения суммы налога на величину НДПИДОП_ЭТАН, равную произведению величины НВЭТАН_ОСТАТОК и коэффициента 1,0075, то начиная со следующего налогового периода величина НДПИДОП_ЭТАН не рассчитывается.\n\nЗначения показателей НДПИДОП_ЭТАН, НВЭТАН_ОСТАТОК, НВЭТАН_ИТОГО, рассчитанные в определенном настоящим пунктом порядке, округляются до целого значения в соответствии с действующим порядком округления.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 323-ФЗ)\n\n10. Сумма налога, исчисленная налогоплательщиком за налоговый период при добыче железной руды по налоговой ставке, установленной подпунктом 31 пункта 2 статьи 342 настоящего Кодекса, уменьшается на сумму исчисленного налогоплательщиком за этот же налоговый период налога при добыче окисленных железистых кварцитов, если иное не предусмотрено настоящим пунктом.\n\nВ случае, если рассчитанная в соответствии с абзацем первым настоящего пункта разность принимает отрицательное значение, такая разность принимается равной нулю.\n\nУказанное в настоящем пункте уменьшение не производится в случае, если значение показателя ЦЖР, определенное для налогового периода в соответствии со статьей 3429 настоящего Кодекса, оказалось меньше 60 долларов США за 1 тонну.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n13. Сумма налога, исчисленная налогоплательщиком за налоговый период в отношении щебня, не может превышать величину НБК, рассчитываемую в рублях как произведение количества добытого полезного ископаемого за налоговый период, приведенного в единицах массы (тоннах), и числа 16,5.\n\nВеличина НБК, определенная в соответствии с настоящим пунктом, округляется до целого значения в соответствии с действующим порядком округления.\n\nВ случае превышения исчисленной за налоговый период суммы налога над значением величины НБК, рассчитанной за этот же налоговый период, сумма налога принимается равной величине НБК.\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ)\n\n14. Сумма налога, исчисленная налогоплательщиками, являющимися в течение всего налогового периода организациями - собственниками объектов Единой системы газоснабжения, при добыче газа горючего природного по совокупности всех участков недр, лицензия на пользование которыми выдана таким организациям в соответствии с законодательством Российской Федерации о недрах, увеличивается:\n\n1) за налоговый период, начало которого приходится на период с 1 сентября по 30 ноября 2022 года включительно, на величину 416 000, выраженную в миллионах рублей;\n\n2) за налоговый период, начало которого приходится на период с 1 января 2023 года по 31 декабря 2024 года включительно, на величину 50 000, выраженную в миллионах рублей. (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 14.07.2022 № 323-ФЗ) (В редакции  Федерального закона от 21.11.2022 № 443-ФЗ)\n\n17. При применении налогоплательщиком налогового вычета, установленного пунктом 39 статьи 3432 настоящего Кодекса, сумма налога, исчисленная налогоплательщиком (правопреемником налогоплательщика) в соответствии с настоящей статьей по итогам налогового периода, начало которого приходится на период с 1 апреля 2029 года по 31 марта 2035 года включительно, в отношении нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, расположенных полностью в границах Ямальского района Ямало-Ненецкого автономного округа и включающих запасы углеводородного сырья месторождения, указанного в примечании 8 к единой Товарной номенклатуре внешнеэкономической деятельности Евразийского экономического союза по состоянию на 1 января 2018 года, увеличивается на величину НДПИТИ_ДОП, выраженную в миллионах рублей, которая, если иное не установлено настоящим пунктом, рассчитывается для каждого налогового периода в совокупности по всем таким участкам недр по следующей формуле:\n\nНДПИТИ_ДОП = НВТИ_ИТОГО + ПР - НДПИТИ_ДОП_ИТОГО,\n\nгде НВТИ_ИТОГО - сумма налоговых вычетов, заявленных налогоплательщиком (правопреемником налогоплательщика) в соответствии с пунктом 39 статьи 3432 настоящего Кодекса в налоговых периодах, дата начала которых приходится на период с 1 апреля 2023 года по 31 марта 2029 года включительно;\n\nНДПИТИ_ДОП_ИТОГО - сумма величин НДПИТИ_ДОП, уплаченных налогоплательщиком (правопреемником налогоплательщика) за налоговые периоды, дата начала которых приходится на период с 1 апреля 2029 года включительно;\n\nПР - сумма величин ПРi, выраженных в миллионах рублей и определяемых для каждого налогового периода, дата начала которого приходится на период с 1 апреля 2023 года по 31 марта 2035 года включительно.\n\nПоказатель ПРi, если иное не установлено настоящим пунктом, для каждого налогового периода определяется по следующей формуле:\n\nПРi = (НВТИi-1 - НДПИТИ_ДОПi-1 + ПРi-1) х 0,0075,\n\nгде НВТИi-1 - сумма налоговых вычетов, заявленных налогоплательщиком (правопреемником налогоплательщика) в соответствии с пунктом 39 статьи 3432 настоящего Кодекса, определенная нарастающим итогом за налоговые периоды, дата начала которых приходится на период с 1 апреля 2023 года до последнего числа месяца, предшествующего текущему налоговому периоду;\n\nНДПИТИ_ДОПi-1 - сумма значений НДПИТИ_ДОП, определенная нарастающим итогом за налоговые периоды, дата начала которых приходится на период с 1 апреля 2029 года до последнего числа месяца, предшествующего текущему налоговому периоду. Для налоговых периодов, дата начала которых приходится на период с 1 апреля 2023 года по 31 марта 2029 года включительно, значение величины НДПИТИ_ДОПi-1 принимается равным нулю;\n\nПРi-1 - сумма значений ПРi, определенная нарастающим итогом за налоговые периоды, дата начала которых приходится на период с 1 апреля 2023 года до последнего числа месяца, предшествующего текущему налоговому периоду.\n\nДля налоговых периодов, дата начала которых приходится на период с 1 апреля по 31 мая 2023 года включительно, значение ПРi принимается равным нулю.\n\nЕсли значение величины НДПИТИ_ДОП, определенное для каждого из налоговых периодов, дата начала которых приходится на период с 1 апреля 2029 года по 28 февраля 2035 года включительно, оказалось больше 1 111 миллионов рублей, величина НДПИТИ_ДОП для такого налогового периода принимается равной 1 111 миллионам рублей.\n\nНалогоплательщик (правопреемник налогоплательщика) вправе увеличить сумму налога, исчисленную по итогам налогового периода в отношении нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, указанных в настоящем пункте, в любом налоговом периоде, дата начала которого приходится на период с 1 апреля 2029 года по 31 марта 2035 года включительно, на величину НДПИТИ_ДОП_Р, которая рассчитывается в совокупности по всем таким участкам недр по следующей формуле:\n\nНДПИТИ_ДОП_Р = НВТИi-1 + ПРР - НДПИТИ_ДОПi-1,\n\nгде ПРР - сумма величин ПРi, определяемых для каждого налогового периода, дата начала которого приходится на период с 1 апреля 2023 года по последнее число текущего налогового периода включительно.\n\nЕсли в налоговом периоде налогоплательщик (правопреемник налогоплательщика) воспользовался правом увеличения суммы налога на величину НДПИТИ_ДОП_Р, начиная со следующего налогового периода величина НДПИТИ_ДОП не рассчитывается.\n\n(Дополнение пунктом - Федеральный закон от 23.02.2023 № 36-ФЗ)\n\n18. Сумма налога, исчисленная налогоплательщиком, указанным в абзаце одиннадцатом настоящего пункта, за налоговые периоды, дата начала которых приходится на период начиная с 1 января 2024 года, при добыче газа горючего природного по совокупности всех участков недр, лицензия на пользование которыми выдана такому налогоплательщику в соответствии с законодательством Российской Федерации о недрах, увеличивается на величину значения показателя ККГ2023, определяемого по следующей формуле:\n\nККГ2023 =i(ViПРОМ x ЦiПРОМ x 0,1 x КИНФ),\n\nгде ViПРОM - выраженный в тысячах кубических метров совокупный объем реализации газа в месяце, непосредственно предшествующем месяцу налогового периода, на территории i-гo субъекта Российской Федерации потребителям (за исключением организаций, осуществляющих переработку попутного газа (в том числе на основе договора об оказании такой организации услуг по переработке попутного газа), организаций, являющихся налогоплательщиками, указанными в абзаце одиннадцатом настоящего пункта, или входящих с такими налогоплательщиками в одну группу компаний и осуществляющих перепродажу приобретенного газа, организаций, входящих с налогоплательщиком в одну группу компаний, в части объемов газа, приобретаемых ими для использования на собственные нужды либо для переработки с получением сухого отбензиненного газа, организаций, газ которым поставляется из объемов природного газа, причитающихся Российской Федерации в соответствии с условиями Соглашения о разработке Пильтун-Астохского и Лунского месторождений нефти и газа на условиях раздела продукции в счет регулярных платежей за добычу полезных ископаемых (роялти), для реализации природного газа потребителям, организаций, осуществляющих производство сжиженного природного газа, в части объемов газа, приобретаемых исключительно для производства сжиженного природного газа, организаций, выручка от реализации тепловой и (или) электрической энергии (мощности) которых за календарный год, предшествующий году налогового периода, составляет не менее 75 процентов общей выручки, определенной за соответствующий календарный год, организаций, выручка от реализации тепловой и (или) электрической энергии (мощности) которых за календарный год, предшествующий году налогового периода, составляет менее 75 процентов общей выручки, определенной за соответствующий календарный год, в части определяемых в порядке, утверждаемом федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, по согласованию с федеральным органом исполнительной власти, осуществляющим функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, и Министерством финансов Российской Федерации, объемов газа, необходимых им для производства и реализации тепловой и (или) электрической энергии (мощности) по регулируемым ценам (тарифам), населения и организаций, осуществляющих определяемый на основании содержащейся в едином государственном реестре юридических лиц информа\n\nции в качестве основного или дополнительного вид экономической деятельности по производству электроэнергии тепловыми электростанциями, производству, передаче и распределению пара и горячей воды тепловыми электростанциями и (или) котельными в соответствии с критериями и перечнем, которые устанавливаются Правительством Российской Федерации, и организаций, осуществляющих перепродажу приобретенного газа в части объемов, реализуемых ими потребителям, указанным в настоящем абзаце) налогоплательщиком и (или) организациями, входящими с налогоплательщиком в одну группу компаний; (В редакции  Федерального закона от 26.02.2024 № 37-ФЗ)\n\nЦiПРОМ - утвержденный в порядке, установленном Правительством Российской Федерации в соответствии с Федеральным законом от 31 марта 1999 года № 69-ФЗ \"О газоснабжении в Российской Федерации\", предельный минимальный уровень цен на газ для потребителей (кроме населения) в i-ом субъекте Российской Федерации по состоянию на 30 ноября 2023 года, выраженный в рублях за тысячу кубических метров, без учета налога на добавленную стоимость. В случае, если предельный минимальный уровень оптовых цен на газ по состоянию на 30 ноября 2023 года не утвержден для субъекта Российской Федерации, в целях настоящего пункта применяется минимальная из оптовых цен на газ, реализуемый потребителям (за исключением населения) данного субъекта Российской Федерации, утвержденная по состоянию на 30 ноября 2023 года, а в случае ее отсутствия - средневзвешенное значение фактических цен реализации налогоплательщиком и (или) организациями, входящими с налогоплательщиком в одну группу компаний, газа потребителям (за исключением населения), не являющимся взаимозависимыми с ними лицами, в i-ом субъекте Российской Федерации за ноябрь 2023 года; (В редакции  Федерального закона от 26.02.2024 № 37-ФЗ)\n\nКИНФ - показатель, который принимается равным:\n\n1 - на период с 1 января по 31 июля 2024 года включительно;\n\n1,11 - на период с 1 августа 2024 года по 31 июля 2025 года включительно;\n\n1,2 - на период с 1 августа 2025 года по 31 июля 2026 года включительно;\n\n1,25 - на период начиная с 1 августа 2026 года.\n\nВ целях настоящего пункта группой компаний признается совокупность организаций, связанных между собой посредством участия в их капитале и (или) осуществления контроля, в отношении которой составляется консолидированная финансовая отчетность в соответствии с требованиями законодательства Российской Федерации о бухгалтерском учете либо требованиями фондовых бирж, в том числе иностранных фондовых бирж, при принятии решения о допуске к торгам ценных бумаг любой из указанных организаций или такая отчетность составлялась бы, если бы ценные бумаги любой из указанных организаций были допущены к торгам на фондовой бирже, в том числе иностранной фондовой бирже. Материнской компанией группы компаний признается участник группы компаний, который прямо и (или) косвенно участвует в остальных участниках этой группы или иным способом осуществляет контроль над ними и доля участия (наличие контроля) которого является достаточной для того, чтобы финансовая отчетность других участников подлежала включению в консолидированную финансовую отчетность такого участника группы компаний либо подлежала включению в такую консолидированную финансовую отчетность, если бы ценные бумаги такого участника были допущены к торгам на фондовой бирже, в том числе иностранной фондовой бирже (далее в настоящей статье - материнская компания). Лицо, финансовая отчетность по которому не учитывается при составлении консолидированной финансовой отчетности группы компаний исключительно в силу размера или несущественности данных о таком лице, признается в целях настоящего пункта участником такой группы компаний. (В редакции  Федерального закона от 26.02.2024 № 37-ФЗ)\n\nМатеринская компания определяет из состава участников такой группы компаний организацию, осуществляющую добычу газа горючего природного на основании лицензии на пользование недрами, выданной такой организации в соответствии с законодательством Российской Федерации о недрах, которая исчисляет налог с учетом особенностей, предусмотренных настоящим пунктом.\n\nДля других организаций - участников группы компаний, осуществляющих добычу газа горючего природного на основании лицензий на пользование недрами, выданных таким организациям в соответствии с законодательством Российской Федерации о недрах, величина показателя ККГ2023 принимается равной 0.\n\nМатеринская компания до 20 января 2024 года представляет в налоговый орган по месту своего нахождения уведомление в произвольной форме, содержащее следующую информацию:\n\nоб участниках группы компаний, осуществляющих реализацию газа потребителям;\n\nоб участниках группы компаний, осуществляющих добычу газа горючего природного на основании лицензий на пользование недрами, выданных таким организациям в соответствии с законодательством Российской Федерации о недрах;\n\nоб организации - участнике группы компаний, которая будет исчислять налог с учетом особенностей, предусмотренных настоящим пунктом.\n\nВ случае изменения информации, содержащейся в представленном уведомлении, материнская компания обязана представить в налоговый орган по месту своего нахождения уточненное уведомление не позднее 20-го числа месяца, следующего за месяцем, в котором произошло указанное изменение.\n\nНачиная с 1 января 2024 года организации - участники группы компаний, осуществляющие реализацию газа потребителям (за исключением организаций, объемы реализации газа которым не учитываются при определении показателя ViПРОM в соответствии с настоящим пунктом), обязаны не позднее 20-го числа месяца налогового периода представлять организации, исчисляющей налог с учетом особенностей, предусмотренных настоящим пунктом, информацию о показателях ViПРОМ и ЦiПРОМ в разрезе субъектов Российской Федерации исходя из объемов реализации соответствующей организацией газа в месяце, предшествующем месяцу налогового периода. (В редакции  Федерального закона от 26.02.2024 № 37-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n19. Сумма налога, исчисленная налогоплательщиком, указанным в абзаце пятнадцатом настоящего пункта, за налоговые периоды, дата начала которых приходится на период начиная с 1 августа 2024 года, при добыче газа горючего природного по совокупности всех участков недр, лицензия на пользование которыми выдана такому налогоплательщику в соответствии с законодательством Российской Федерации о недрах, увеличивается на величину ККГ2024, определяемую по следующей формуле:\n\nККГ2024 =i((ViПРОМ x ЦiПРОМ x 1,1 + ViНАС x ЦiНАС + ViТЭ x ЦiПРОМ) x КО x КИНД),\n\nгде ViПРОМ, ЦiПРОМ - показатели, определяемые в соответствии с пунктом 18 настоящей статьи;\n\nViНАС - выраженный в тысячах кубических метров совокупный объем реализации газа в месяце, непосредственно предшествующем месяцу налогового периода, населению на территории i-го субъекта Российской Федерации налогоплательщиком и (или) организациями, входящими с налогоплательщиком в одну группу компаний;\n\nЦiНАС - утвержденная в порядке, установленном Правительством Российской Федерации в соответствии с Федеральным законом от 31 марта 1999 года № 69-ФЗ \"О газоснабжении в Российской Федерации\", оптовая цена на газ, предназначенный для последующей реализации населению, в i-ом субъекте Российской Федерации по состоянию на 30 ноября 2023 года, выраженная в рублях за тысячу кубических метров, без учета налога на добавленную стоимость, а в случае ее отсутствия - средневзвешенное значение фактических цен реализации налогоплательщиком и (или) организациями, входящими с налогоплательщиком в одну группу компаний, газа населению в i-ом субъекте Российской Федерации за июль 2024 года; (В редакции  Федерального закона от 26.02.2024 № 37-ФЗ)\n\nViTЭ - выраженный в тысячах кубических метров совокупный объем реализации газа в месяце, непосредственно предшествующем месяцу налогового периода, организациям, выручка от реализации тепловой и (или) электрической энергии (мощности) которых за календарный год, предшествующий году налогового периода, составляет не менее 75 процентов общей выручки, определенной за соответствующий календарный год, организациям, выручка от реализации тепловой и (или) электрической энергии (мощности) которых за календарный год, предшествующий году налогового периода, составляет менее 75 процентов общей выручки, определенной за соответствующий календарный год, в части определяемых в порядке, предусмотренном пунктом 18 настоящей статьи, объемов газа, необходимых им для производства и реализации тепловой и (или) электрической энергии (мощности) по регулируемым ценам (тарифам), и организациям, осуществляющим определяемый на основании содержащейся в едином государственном реестре юридических лиц информации в качестве основного или дополнительного вид экономической деятельности по производству электроэнергии тепловыми электростанциями, производству, передаче и распределению пара и горячей воды тепловыми электростанциями и (или) котельными в соответствии с критериями и перечнем, которые устанавливаются Правительством Российской Федерации, на территории i-го субъекта Российской Федерации налогоплательщиком и (или) организациями, входящими с налогоплательщиком в одну группу компаний; (В редакции  Федерального закона от 26.02.2024 № 37-ФЗ)\n\nКО - показатель, который принимается равным:\n\n0,01 - на период с 1 августа 2024 года по 31 июля 2025 года включительно;\n\n0,02 - на период начиная с 1 августа 2025 года;\n\nКИНД - показатель, который принимается равным:\n\n1 - на период с 1 августа 2024 года по 31 июля 2025 года включительно;\n\n1,08 - на период с 1 августа 2025 года по 31 июля 2026 года включительно;\n\n1,12 - на период начиная с 1 августа 2026 года.\n\nДля целей настоящего пункта понятия \"группа компаний\" и \"материнская компания\" используются в значении, предусмотренном пунктом 18 настоящей статьи.\n\nМатеринская компания определяет из состава участников группы компаний организацию, осуществляющую добычу газа горючего природного на основании лицензии на пользование недрами, выданной такой организации в соответствии с законодательством Российской Федерации о недрах, которая исчисляет налог с учетом особенностей, предусмотренных настоящим пунктом.\n\nВеличина показателя ККГ2024 принимается равной 0 для других организаций - участников группы компаний, осуществляющих добычу газа горючего природного на основании лицензий на пользование недрами, выданных таким организациям в соответствии с законодательством Российской Федерации о недрах.\n\nМатеринская компания представляет в налоговый орган по месту своего нахождения уведомление, содержащее информацию, указанную в пункте 18 настоящей статьи, не позднее 20 августа 2024 года. В случае, если указанное уведомление ранее представлено материнской компанией в соответствии с пунктом 18 настоящей статьи, повторное представление указанного уведомления не требуется.\n\nВ случае изменения информации, содержащейся в представленном уведомлении, материнская компания обязана представить в налоговый орган по месту своего нахождения уточненное уведомление не позднее 20-го числа месяца, следующего за месяцем, в котором произошло указанное изменение.\n\nНачиная с 1 августа 2024 года организации - участники группы компаний, осуществляющие реализацию газа потребителям, обязаны не позднее 20-го числа месяца налогового периода представлять организации, исчисляющей налог с учетом особенностей, предусмотренных настоящим пунктом, информацию о показателях ViПРОМ, ЦiПРОМ, ViНАС, ЦiНАС, ViТЭ в разрезе субъектов Российской Федерации исходя из объемов реализации соответствующей организацией газа в месяце, предшествующем месяцу налогового периода.\n\nПоложения настоящего пункта не применяются в отношении группы компаний, материнской компанией которой является организация - собственник Единой системы газоснабжения.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nУказанное в абзаце первом настоящего пункта изменение рассчитывается как разность между значением коэффициента КАБДТ, предусмотренного пунктом 11 статьи 3425 настоящего Кодекса, определяемым для соответствующего налогового периода с применением указанных в пункте 27 статьи 200 настоящего Кодекса показателей ДАБ и ДДТ, рассчитываемых с учетом коэффициента КВР, равного 1, и фактическим значением коэффициента КАБДТ, применяемым при расчете налога для соответствующего налогового периода.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nКДРМ = 0,1 х (ЦЗ / 1000 - 61 000) х VДРМ x Р,\n\nгде ЦЗ - показатель, определяемый для налогового периода в порядке, установленном пунктом 1 статьи 34210 настоящего Кодекса;\n\nVДРМ - количество драгоценного металла (золота), содержащегося в полезном ископаемом, указанном в подпункте 13 пункта 2 статьи 337 настоящего Кодекса (за исключением полезного ископаемого, при добыче которого налогообложение производится по налоговой ставке, установленной подпунктом 1 пункта 1 статьи 342 настоящего Кодекса), добытом на участке недр, указанном в абзаце первом настоящего пункта, выраженное в килограммах и округленное с точностью до третьего знака после запятой в соответствии с действующим порядком округления;\n\nР - среднее значение за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, определяемое налогоплательщиком самостоятельно как среднеарифметическое значение курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, за все дни в календарном месяце.\n\nРассчитанное значение показателя КДРМ округляется до целого значения в соответствии с действующим порядком округления.\n\n(Дополнение пунктом - Федеральный закон от 22.04.2024 № 96-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 343. Порядок исчисления и уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a2db4f05af22887327de98393b64dd547cd8a5f7efc748ea9fe92dfd46c95c2"},{"code_id":"NK_RF_2","article_number":"343.1","version_date":"2000-07-31","article_text":"1. Налогоплательщики по своему выбору могут уменьшить сумму налога, исчисленную за налоговый период при добыче угля на участке недр, на сумму экономически обоснованных и документально подтвержденных расходов, осуществленных (понесенных) налогоплательщиком в налоговом периоде и связанных с обеспечением безопасных условий и охраны труда при добыче угля на данном участке недр (налоговый вычет), в порядке, установленном настоящей статьей, либо учесть указанные расходы при исчислении налоговой базы по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса.\n\nПорядок признания расходов, указанных в настоящем пункте, должен быть отражен в учетной политике для целей налогообложения. Изменение указанного порядка допускается не чаще одного раза в пять лет.\n\n2. Предельная величина налогового вычета, применяемого в соответствии с настоящей статьей, рассчитывается налогоплательщиком самостоятельно как произведение суммы налога, исчисленного при добыче угля на каждом участке недр за налоговый период, и коэффициента Кт, определяемого в порядке, установленном настоящей статьей.\n\n3. Коэффициент Кт определяется для каждого участка недр в соответствии с порядком, устанавливаемым Правительством Российской Федерации, с учетом степени метанообильности участка недр, на котором осуществляется добыча угля, а также с учетом склонности угля к самовозгоранию в пласте на участке недр, на котором осуществляется добыча угля. Значение коэффициента Кт, рассчитанное в соответствии с настоящей статьей для каждого участка недр, устанавливается в принятой налогоплательщиком учетной политике для целей налогообложения. Значение коэффициента Кт не может превышать 0,3.\n\n4. В случае, если фактическая сумма расходов, осуществленных (понесенных) налогоплательщиком в налоговом периоде и связанных с обеспечением безопасных условий и охраны труда при добыче угля, превышает предельную сумму налогового вычета, определенную в соответствии с пунктом 2 настоящей статьи, сумма такого превышения учитывается при определении налогового вычета в течение 36 налоговых периодов после налогового периода, в котором такие расходы были осуществлены (понесены) налогоплательщиком.\n\n5. В налоговый вычет включаются следующие виды расходов, осуществленных (понесенных) налогоплательщиком и связанных с обеспечением безопасных условий и охраны труда при добыче угля (по перечню, устанавливаемому Правительством Российской Федерации):\n\n1) материальные расходы налогоплательщика, определяемые в порядке, предусмотренном главой 25 настоящего Кодекса;\n\n2) расходы налогоплательщика на приобретение и (или) создание амортизируемого имущества;\n\n3) расходы, осуществленные (понесенные) налогоплательщиком в случаях достройки, дооборудования, реконструкции, модернизации, технического перевооружения объектов основных средств.\n\n6. Виды расходов, связанных с обеспечением безопасных условий и охраны труда при добыче угля, учитываемых при определении налогового вычета в соответствии с настоящей статьей, устанавливаются в учетной политике для целей налогообложения.\n\n7. Налогоплательщики, у которых отсутствует исчисленная за налоговый период сумма налога, могут учитывать расходы, предусмотренные пунктом 5 настоящей статьи, при определении налогового вычета в порядке, установленном настоящей статьей, начиная с того налогового периода, когда у них возникает обязанность по исчислению налога.\n\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 425-ФЗ)","article_title":"Статья 343.1. Порядок уменьшения суммы налога, исчисленного при добыче угля, на расходы, связанные с обеспечением безопасных условий и охраны труда","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"471fe7e275890cc25ef4fe22cb18cccc534148ceab034dc28026c5d9eb2388ea"},{"code_id":"NK_RF_2","article_number":"343.2","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.11.2017 № 335-ФЗ; от 03.08.2018 № 301-ФЗ)\n\n1. Налогоплательщик имеет право уменьшить общую сумму налога, исчисленную в соответствии со статьей 343 настоящего Кодекса при добыче нефти обезвоженной, обессоленной и стабилизированной, на установленные настоящей статьей налоговые вычеты.\n\n>Сумма налогового вычета, указанная в абзаце первом настоящего пункта, увеличивается на величину показателя НВ. Величина показателя НВ определяется налогоплательщиком для каждого налогового периода самостоятельно и не может превышать 1167 миллионов рублей в налоговых периодах, дата начала которых приходится на период с 1 июля по 31 декабря 2024 года включительно, 583 миллиона рублей в налоговых периодах, дата начала которых приходится на период с 1 января по 31 декабря 2025 года включительно, 434 миллиона рублей в налоговых периодах, дата начала которых приходится на период с 1 января по 31 декабря 2026 года включительно. Общая сумма показателей НВ, определенных налогоплательщиком за все налоговые периоды, не может превышать 16 600 миллионов рублей.\n\nНалоговый вычет, исчисленный в соответствии с настоящим пунктом, применяется с 1 января 2018 года по 31 декабря 2027 года включительно.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nНалоговый вычет применяется при добыче нефти обезвоженной, обессоленной и стабилизированной на участках недр, которые одновременно расположены в границах Сургутского и Ханты-Мансийского районов Ханты-Мансийского автономного округа - Югры, лицензии на пользование которыми выданы до 1 января 2018 года и начальные извлекаемые запасы нефти каждого из которых составляют 1 000 миллионов тонн и более по состоянию на 1 января 2018 года.\n\nСумма налогового вычета определяется в совокупности по всем таким участкам недр в следующем порядке:\n\n3 830 миллионов рублей - в случае, если средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США, за баррель (Ц), определенный для налогового периода в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса, оказался выше базовой цены на нефть, определенной в порядке, установленном пунктом 9 настоящей статьи, для года налогового периода; (В редакции  Федерального закона от 27.04.2023 № 136-ФЗ)\n\n0 рублей - в случае, если средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США, за баррель (Ц), определенный для налогового периода в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса, оказался ниже базовой цены на нефть или равным базовой цене на нефть, определенной в порядке, установленном пунктом 9 настоящей статьи, для года налогового периода. (В редакции  Федерального закона от 27.04.2023 № 136-ФЗ)\n\nДля целей настоящего пункта значение базовой цены на нефть округляется до второго знака после запятой в соответствии с действующим порядком округления.\n\nНалоговый вычет применяется при условии заключения налогоплательщиком, владеющим лицензиями на пользование участками недр, указанными в настоящем пункте, инвестиционного соглашения о стимулировании добычи нефти на указанных участках недр (далее в настоящем пункте - соглашение о добыче) с Министерством финансов Российской Федерации и федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере изучения, использования, воспроизводства и охраны природных ресурсов.\n\nСоглашение о добыче должно содержать следующие существенные условия:\n\nпредмет соглашения о добыче - номера лицензий на пользование участками недр и географические координаты участков недр, на которых добыта нефть, в отношении которой будет применяться налоговый вычет (далее в настоящем пункте - участки недр, являющиеся предметом соглашения о добыче), предельный размер налогового вычета в налоговом периоде по каждому участку недр, являющемуся предметом соглашения о добыче, но не более 3 830 миллионов рублей за налоговый период в совокупности по всем участкам недр, являющимся предметом соглашения о добыче;\n\nпланируемый объем добычи нефти обезвоженной, обессоленной и стабилизированной в тоннах в год в совокупности по всем участкам недр, являющимся предметом соглашения о добыче, на период с 1 января 2021 года по 31 декабря 2032 года включительно в условиях отсутствия налогового вычета;\n\nидентификационный номер налогоплательщика, полное и сокращенное наименования организации-налогоплательщика, владеющего лицензиями на пользование участками недр, являющимися предметом соглашения о добыче.\n\nНалогоплательщик вправе заключить соглашение о добыче до 1 июля 2021 года. С 1 июля 2021 года заключение соглашений о добыче не допускается.\n\nОснованием для отказа в заключении соглашения о добыче является наличие одного из следующих обстоятельств:\n\nв соглашении о добыче указана недостоверная информация;\n\nучастки недр, являющиеся предметом соглашения о добыче, не соответствуют условиям, установленным настоящим пунктом;\n\nпредельный размер налогового вычета за налоговый период в совокупности по всем участкам недр, являющимся предметом соглашения о добыче, превышает 3 830 миллионов рублей.\n\nФорма соглашения о добыче, порядок заключения (расторжения) соглашения о добыче, порядок контроля за исполнением соглашения о добыче устанавливаются Правительством Российской Федерации.\n\nВ целях настоящего пункта временным интервалом признается период с 31 декабря 2020 года до истечения трех следующих подряд календарных лет, шести следующих подряд календарных лет, девяти следующих подряд календарных лет или двенадцати следующих подряд календарных лет.\n\nЕсли сумма налоговых вычетов за все налоговые периоды, дата начала которых приходится на соответствующий временной интервал, превысила условную сумму дополнительных доходов бюджета, определенную для такого временного интервала в порядке, установленном настоящим пунктом, сумма налоговых вычетов в части такого превышения (далее в настоящем пункте - сумма превышения) подлежит уплате в бюджет в срок до 31 марта года, непосредственно следующего за последним годом соответствующего временного интервала.\n\nУсловная сумма дополнительных доходов бюджета определяется как разница между условными доходами бюджета в условиях применения налогового вычета и условными доходами бюджета в условиях отсутствия налогового вычета.\n\nУсловные доходы бюджета в условиях применения налогового вычета рассчитываются как сумма следующих произведений:\n\nпроизведения объема добытой нефти обезвоженной, обессоленной и стабилизированной в тоннах за все налоговые периоды, дата начала которых приходится на соответствующий временной интервал, в совокупности по всем участкам недр, являющимся предметом соглашения о добыче (VПМ_ФАКТ), и средневзвешенной по объемам добытой нефти обезвоженной, обессоленной и стабилизированной в налоговом периоде на каждом участке недр, являющемся предметом соглашения о добыче, ставки налога, определенной для соответствующего временного интервала (ТПМ_ФАКТ);\n\nпроизведения величины VПМ_ФАКТ и средневзвешенной по объемам добытой нефти обезвоженной, обессоленной и стабилизированной в налоговом периоде на каждом участке недр, являющемся предметом соглашения о добыче, ставки вывозной таможенной пошлины на нефть, выраженной в рублях за тонну (DПМ_ФАКТ).\n\nУсловные доходы бюджета в условиях отсутствия налогового вычета рассчитываются как сумма следующих произведений:\n\nпроизведения планируемого в условиях отсутствия соглашения о добыче объема добычи нефти обезвоженной, обессоленной и стабилизированной в тоннах в совокупности по всем участкам недр, являющимся предметом соглашения о добыче, в соответствующем временном интервале, определенного на основе данных, содержащихся в соглашении о добыче (VПМ_ПЛАН), и величины ТПМ_ФАКТ;\n\nпроизведения величины VПМ_ПЛАН и величины DПМ_ФAKT.\n\nНалоговый вычет не применяется начиная с налогового периода, в котором сумма налоговых вычетов, предоставленных на основе соглашения о добыче (с учетом налоговых вычетов, относящихся к суммам превышения), впервые оказалась более 459 600 миллионов рублей (далее в настоящем пункте - пороговая величина вычета). При этом, если по итогам двенадцати следующих подряд календарных лет начиная с 31 декабря 2020 года сумма налоговых вычетов (с учетом налоговых вычетов, относящихся к суммам превышения) за все налоговые периоды, дата начала которых приходится на такой временной интервал, оказалась менее суммы условных дополнительных доходов бюджета, рассчитанных для такого временного интервала, и ранее налогоплательщиком осуществлялась уплата в бюджет сумм превышения, для целей настоящего абзаца пороговая величина вычета увеличивается на суммы превышения, уплаченные в бюджет.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 340-ФЗ)\n\nНалоговый вычет (НВВЗ) подлежит применению в следующие сроки:\n\nдля участков недр, расположенных полностью или частично в Охотском море, - с 1 января 2021 года;\n\nдля иных участков недр, степень выработанности запасов нефти которых больше или равна 0,8, - с 1 января 2027 года. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nДля целей настоящего пункта:\n\nстепень выработанности запасов нефти участка недр определяется на 1 января года, предшествующего году налогового периода, в порядке, установленном подпунктом 1 пункта 5 статьи 33343 настоящего Кодекса;\n\nналоговый вычет (НВВЗ) определяется при условии применения в течение всего налогового периода в отношении участка недр налога на дополнительный доход от добычи углеводородного сырья.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\nв размере фактически оплаченных налогоплательщиком расходов, указанных в настоящем пункте, но не более 1 000 миллиона рублей в случае, если средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США, за баррель (Ц), определенный в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса, оказался выше базовой цены на нефть, определенной в порядке, установленном пунктом 9 настоящей статьи, для года налогового периода; (В редакции  Федерального закона от 27.04.2023 № 136-ФЗ)\n\n0 рублей в ином случае.\n\nДля целей настоящего пункта при определении суммы налогового вычета учитываются фактически оплаченные в период с 1 января 2021 года по последнее число налогового периода (включительно), в котором применяется налоговый вычет, суммы расходов, связанные с соблюдением обязательных требований, установленных Федеральным законом от 10 января 2002 года № 7-ФЗ \"Об охране окружающей среды\" и Федеральным законом от 21 июля 1997 года № 116-ФЗ \"О промышленной безопасности опасных производственных объектов\", и при условии, что указанные суммы расходов также связаны с добычей сверхвязкой нефти, добываемой на участках недр, содержащих нефть вязкостью 10 000 мПа·с и более (в пластовых условиях).\n\nВ целях настоящего пункта оплатой расходов (товаров, работ, услуг, имущественных прав) признается также прекращение встречного обязательства налогоплательщиком - приобретателем указанных расходов (товаров, работ, услуг, имущественных прав) перед продавцом, которое связано с поставкой этих товаров (выполнением работ, оказанием услуг, передачей имущественных прав), а также перечисление авансовых платежей в счет предстоящих поставок товаров (выполнения работ, оказания услуг, передачи имущественных прав).\n\nВ целях настоящего пункта перечень видов расходов, связанных с соблюдением обязательных требований, установленных Федеральным законом от 10 января 2002 года № 7-ФЗ \"Об охране окружающей среды\" и Федеральным законом от 21 июля 1997 года № 116-ФЗ \"О промышленной безопасности опасных производственных объектов\", утверждается Правительством Российской Федерации. (В редакции Федерального закона от 02.07.2021 № 309-ФЗ)\n\nСуммы фактически оплаченных расходов, указанные в настоящем пункте, не учтенные при определении суммы налогового вычета в налоговом периоде, могут быть учтены при определении налогового вычета в последующем налоговом периоде в пределах периода применения налогоплательщиком налогового вычета.\n\nСуммы фактически оплаченных расходов, указанные в настоящем пункте, учтенные при определении суммы налогового вычета в налоговом периоде, не подлежат повторному включению в состав налогового вычета в иных налоговых периодах, а также на иных участках недр.\n\nНалоговый вычет, предусмотренный настоящим пунктом, применяется с 1 января 2021 года до налогового периода, в котором сумма налоговых вычетов, предусмотренных настоящим пунктом, впервые оказалась более 36 000 миллионов рублей.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\nв размере 1 000 миллиона рублей в случае, если средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США, за баррель (Ц), определенный в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса, оказался выше базовой цены на нефть, определенной в порядке, установленном пунктом 9 настоящей статьи, для года налогового периода; (В редакции  Федерального закона от 27.04.2023 № 136-ФЗ)\n\n0 рублей в ином случае.\n\nНалоговой вычет, предусмотренный настоящим пунктом, предоставляется при условии заключения налогоплательщиком, владеющим лицензиями на право пользования недрами участков недр, указанных в настоящем пункте, соглашения об объеме добычи нефти и объеме инвестиций на указанных участках недр (далее в настоящем пункте - соглашение об объеме добычи) с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, согласованного с Министерством финансов Российской Федерации.\n\nСоглашение об объеме добычи должно включать следующие существенные условия:\n\nпредмет соглашения об объеме добычи - номера лицензий на пользование недрами и координаты участков недр, в отношении которых будет применяться налоговый вычет в соответствии с настоящим пунктом;\n\nпланируемый объем добычи нефти обезвоженной, обессоленной и стабилизированной в тоннах в год по всем участкам недр, являющимся предметом соглашения об объеме добычи, на период с 1 января 2021 года по 31 декабря 2023 года включительно;\n\nпланируемый объем инвестиций в год по всем участкам недр, являющимся предметом соглашения об объеме добычи, на период с 1 января 2021 года по 31 декабря 2023 года включительно;\n\nидентификационный номер налогоплательщика, полное и сокращенное наименования организации-налогоплательщика, владеющего лицензиями на пользование участками недр, являющимися предметом соглашения об объеме добычи.\n\nФорма соглашения об объеме добычи, порядок заключения соглашения об объеме добычи устанавливаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\nЕсли по итогам любого из календарных годов, приходящихся на период с 2021 по 2023 год включительно, фактический объем добычи нефти обезвоженной, обессоленной и стабилизированной в тоннах по всем участкам недр, являющимся предметом соглашения об объеме добычи, и (или) фактический объем инвестиций по всем таким участкам недр оказался менее соответствующих планируемых величин, указанных в соглашении об объеме добычи, сумма налоговых вычетов, примененных налогоплательщиком в соответствии с настоящим пунктом в налоговых периодах, дата начала которых приходится на такой календарный год, подлежит уплате в бюджет в срок до 31 марта года, непосредственно следующего за годом, в отношении которого подводится итог.\n\nНалоговый вычет, предусмотренный настоящим пунктом, применяется с 1 января 2021 года до налогового периода, в котором сумма налоговых вычетов, предусмотренных настоящим пунктом, впервые оказалась более 36 000 миллионов рублей.\n\nВ целях настоящего пункта под объемом инвестиций на участке недр понимаются фактические расходы на участке недр на приобретение, сооружение, изготовление, доставку амортизируемого имущества, доведение его до состояния, пригодного для использования, учитываемые при определении налоговой базы по соответствующему участку недр в соответствии с главой 254 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 15.10.2020 № 342-ФЗ)\n\nНалоговый вычет, предусмотренный настоящим пунктом, применяется в налоговых периодах, начало которых приходится на период с 1 июля 2022 года по 31 декабря 2024 года включительно.\n\nПеречень организаций, реализующих (в том числе через прямое участие в дочернем хозяйственном обществе, непосредственно реализующем проект) по состоянию на 1 января 2021 года в Иркутской области проекты по созданию новых производственных мощностей по переработке этана и (или) сжиженных углеводородных газов в товары, являющиеся продукцией нефтехимии, а также порядок и критерии включения организаций в указанный перечень утверждаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса. В данном перечне в обязательном порядке указываются полное и сокращенное наименования организации, реализующей по состоянию на 1 янв\n\nаря 2021 года в Иркутской области проект по созданию новых производственных мощностей по переработке этана и (или) сжиженных углеводородных газов в товары, являющиеся продукцией нефтехимии, место нахождения такой организации в Иркутской области и (или) ее обособленных подразделений, расположенных в Иркутской области, идентификационный номер налогоплательщика.\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, в срок до 31 января 2022 года направляет в налоговые органы перечень организаций, реализующих по состоянию на 1 января 2021 года в Иркутской области проекты по созданию новых производственных мощностей по переработке этана и (или) сжиженных углеводородных газов в товары, являющиеся продукцией нефтехимии.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ) (В редакции Федерального закона от 14.07.2022 № 323-ФЗ)\n\nНалоговый вычет применяется при добыче нефти обезвоженной, обессоленной и стабилизированной на участках недр, которые расположены полностью или частично в границах Ханты-Мансийского района Ханты-Мансийского автономного округа - Югры, лицензии на пользование которыми выданы до 1 января 2018 года и начальные извлекаемые запасы нефти на каждом из которых составляют не менее 450 миллионов тонн и не более 470 миллионов тонн по состоянию на 1 января 2018 года.\n\nСумма налогового вычета определяется в совокупности по всем таким участкам недр в следующем порядке:\n\n833 миллиона рублей - в случае, если средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США, за баррель (Ц), определенный для налогового периода в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса, оказался выше базовой цены на нефть, определенной в порядке, установленном пунктом 9 настоящей статьи, для года налогового периода; (В редакции  Федерального закона от 27.04.2023 № 136-ФЗ)\n\n0 рублей - в случае, если средний за налоговый период уровень цен нефти сорта \"Юралс\", выраженный в долларах США, за баррель (Ц), определенный для налогового периода в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса, оказался ниже базовой цены на нефть или равным базовой цене на нефть, определенной в порядке, установленном пунктом 9 настоящей статьи, для года налогового периода. (В редакции  Федерального закона от 27.04.2023 № 136-ФЗ)\n\nДля целей настоящего пункта значение базовой цены на нефть округляется до второго знака после запятой в соответствии с действующим порядком округления.\n\nНалоговый вычет применяется при условии заключения налогоплательщиком, владеющим лицензиями на пользование участками недр, указанными в настоящем пункте, инвестиционного соглашения о стимулировании добычи нефти на указанных участках недр (далее в настоящем пункте - соглашение о добыче) в порядке, установленном пунктом 33 настоящей статьи, с учетом следующих особенностей:\n\nпредельный размер налогового вычета в налоговом периоде по каждому участку недр, являющемуся предметом соглашения о добыче, указанный в соглашении о добыче, не может превышать 833 миллиона рублей за налоговый период в совокупности по всем участкам недр, являющимся предметом соглашения о добыче;\n\nпланируемый объем добычи нефти обезвоженной, обессоленной и стабилизированной в тоннах в год в совокупности по всем участкам недр, являющимся предметом соглашения о добыче, указывается в соглашении о добыче на период с 1 января 2022 года по 31 декабря 2033 года включительно в условиях отсутствия налогового вычета;\n\nналогоплательщики вправе заключить соглашение о добыче до 1 июля 2022 года. С 1 июля 2022 года заключение соглашений о добыче не допускается;\n\nоснованием для отказа в заключении соглашения о добыче помимо оснований, указанных в пункте 33 настоящей статьи, является указание в соглашении о добыче предельного размера налогового вычета за налоговый период в совокупности по всем участкам недр, являющимся предметом соглашения о добыче, превышающего 833 миллиона рублей.\n\nВ целях настоящего пункта временным интервалом признается период с 31 декабря 2021 года до истечения трех следующих подряд календарных лет, шести следующих подряд календарных лет, девяти следующих подряд календарных лет или двенадцати следующих подряд календарных лет.\n\nЕсли сумма налоговых вычетов за все налоговые периоды, дата начала которых приходится на соответствующий временной интервал, превысила условную сумму дополнительных доходов бюджета, определенную для такого временного интервала в порядке, установленном пунктом 33 настоящей статьи, сумма налоговых вычетов в части такого превышения (далее в настоящем пункте - сумма превышения) подлежит уплате в бюджет в срок до 31 марта года, непосредственно следующего за последним годом соответствующего временного интервала.\n\nНалоговый вычет не применяется начиная с налогового периода, в котором сумма налоговых вычетов, предоставленных на основе соглашения о добыче (с учетом налоговых вычетов, относящихся к суммам превышения), впервые оказалась более 99 960 миллионов рублей (далее в настоящем пункте - пороговая величина вычета). При этом, если по итогам двенадцати следующих подряд календарных лет начиная с 31 декабря 2021 года сумма налоговых вычетов (с учетом налоговых вычетов, относящихся к суммам превышения) за все налоговые периоды, дата начала которых приходится на такой временной интервал, оказалась менее суммы условных дополнительных доходов бюджета, рассчитанных для такого временного интервала, и ранее налогоплательщиком осуществлялась уплата в бюджет сумм превышения, для целей настоящего абзаца пороговая величина вычета увеличивается на суммы превышения, уплаченные в бюджет.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\nСумма налогового вычета, предусмотренного настоящим пунктом, принимается равной нулю, если средний за налоговый период уровень цен нефти сорта \"Юралс\", определенный в порядке, установленном пунктом 3 статьи 342 настоящего Кодекса (Ц):\n\nоказался ниже базовой цены на нефть или равным базовой цене на нефть, определенной в соответствии с пунктом 9 настоящей статьи, для года налогового периода;\n\nоказался равным или выше базовой цены на нефть, определенной в соответствии с пунктом 9 настоящей статьи, для года налогового периода, увеличенной на 27,55 доллара США за баррель.\n\nПеречень организаций, участвующих в реализации проектов по строительству транспортной инфраструктуры, указанной в настоящем пункте (в том числе в случае, если налогоплательщик и лицо, непосредственно реализующее проект, являются организациями, в которых непосредственно и (или) косвенно участвуют собственники объектов Единой системы газоснабжения и суммарная доля такого участия составляет более 50 процентов), а также порядок и критерии включения организаций в данный перечень утверждаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса.\n\nФедеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере топливно-энергетического комплекса, в срок до 20 мая 2023 года направляет в налоговые органы перечень организаций, реализующих проекты (участвующих в реализации проектов) по строительству транспортной инфраструктуры, указанной в настоящем пункте.\n\n(Дополнение пунктом - Федеральный закон от 23.02.2023 № 36-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.11.2011 № 338-ФЗ)","article_title":"Статья 343.2. Порядок уменьшения суммы налога, исчисленной при добыче нефти обезвоженной, обессоленной и стабилизированной, на сумму налогового вычета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"167d2f4f4fc02f723c24a466948d7a0eceb5fde17bc919d4c79ce84b6e32c609"},{"code_id":"NK_RF_2","article_number":"343.3","version_date":"2000-07-31","article_text":"1. Налогоплательщик в налоговые периоды с 1 января 2018 года по 31 декабря 2020 года вправе уменьшить общую сумму налога, исчисленную при добыче газа горючего природного из всех видов месторождений углеводородного сырья, добытого на участке недр, расположенном полностью или частично в Черном море, на величину налогового вычета, определяемого и применяемого в порядке, установленном настоящей статьей (далее в настоящей статье - налоговый вычет).\n\n2. Налоговый вычет применяется в налоговом периоде при одновременном выполнении следующих условий в отношении участка недр, расположенного полностью или частично в Черном море, на котором осуществляется добыча газа горючего природного из всех видов месторождений углеводородного сырья:\n\nв отношении такого участка недр не применяется коэффициент Кас, установленный пунктом 11 статьи 3424 настоящего Кодекса;\n\nместорождение углеводородного сырья участка недр, на котором осуществляется добыча газа горючего природного из всех видов месторождений углеводородного сырья, не относится к новым морским месторождениям углеводородного сырья.\n\n3. Налоговый вычет вправе применять налогоплательщики-организации, государственная регистрация которых осуществлена на территории Республики Крым или города федерального значения Севастополя в период до 1 января 2017 года.\n\n4. Налоговый вычет определяется как величина фактически оплаченных налогоплательщиком в период с 1 января 2018 года по последнее число налогового периода (включительно), в котором применяется налоговый вычет, сумм расходов на приобретение, сооружение, изготовление, доставку объектов основных средств, отвечающих условиям, установленным пунктом 5 настоящей статьи, и доведение их до состояния, в котором они пригодны для использования.\n\nНалоговый вычет не может превышать величину, равную произведению коэффициента 0,9 и общей суммы налога, которую он уменьшает.\n\nСуммы фактически оплаченных расходов, указанных в абзаце первом настоящего пункта, не учтенные при налогообложении в налоговом периоде, могут быть учтены при определении налогового вычета в любом последующем налоговом периоде, указанном в пункте 1 настоящей статьи.\n\nСуммы фактически оплаченных расходов, указанных в абзаце первом настоящего пункта, учтенные при налогообложении в налоговом периоде, не подлежат повторному включению в состав налогового вычета в иных налоговых периодах, а также на иных участках недр.\n\nКлассификация имущества в качестве объектов основных средств осуществляется на основании положений пункта 1 статьи 257 настоящего Кодекса.\n\nВ целях настоящей статьи оплатой (частичной оплатой) товаров (работ, услуг) и имущественных прав признается прекращение (частичное прекращение) встречного обязательства налогоплательщиком - приобретателем указанных товаров (работ, услуг) и имущественных прав перед продавцом, которое непосредственно связано с поставкой этих товаров (выполнением работ, оказанием услуг) и передачей имущественных прав.\n\n5. Налоговый вычет предоставляется при условии, что объекты основных средств, указанные в настоящей статье, включены в инвестиционную программу развития газотранспортной системы Республики Крым и города федерального значения Севастополя, утвержденную уполномоченными исполнительными органами государственной власти Республики Крым и города федерального значения Севастополя.\n\n6. В целях подтверждения выполнения условий, установленных настоящей статьей, налогоплательщик одновременно с налоговой декларацией по налогу представляет в налоговый орган документы, подтверждающие фактическую оплату учтенных в соответствующем налоговом периоде при определении налогового вычета сумм расходов, указанных в пункте 4 настоящей статьи, а также документы, подтверждающие включение объектов основных средств в инвестиционную программу, указанную в пункте 5 настоящей статьи.\n\n(Дополнение статьей - Федеральный закон от 30.09.2017 № 286-ФЗ)","article_title":"Статья 343.3. Порядок уменьшения суммы налога, исчисленной при добыче газа горючего природного из всех видов месторождений углеводородного сырья, добытого на участке недр, расположенном полностью или частично в Черном море","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eb323fb5280eba1ce76e218b39529715f1af388d16394f06e53bc9e6f72c0844"},{"code_id":"NK_RF_2","article_number":"343.4","version_date":"2000-07-31","article_text":"1. Налогоплательщик имеет право уменьшить общую сумму налога, исчисленную в соответствии с настоящим Кодексом при добыче газового конденсата из всех видов месторождений углеводородного сырья, на сумму налогового вычета в порядке, установленном настоящей статьей, при выполнении одновременно следующих условий:\n\n1) добытый налогоплательщиком газовый конденсат направлен им и (или) иной российской организацией, обладающей правом владения и (или) пользования и (или) распоряжения в отношении этого газового конденсата, на переработку на технологическом оборудовании, принадлежащем российской организации;\n\n2) из добытого налогоплательщиком газового конденсата на технологическом оборудовании, принадлежащем российской организации, в процессе его переработки получена широкая фракция легких углеводородов;\n\n3) факт получения широкой фракции легких углеводородов из добытого налогоплательщиком газового конденсата документально подтвержден в порядке, установленном настоящей статьей.\n\n2. В целях подтверждения выполнения условий, предусмотренных пунктом 1 настоящей статьи, налогоплательщик представляет в налоговый орган вместе с декларацией по налогу следующие документы:\n\n1) в случае получения широкой фракции легких углеводородов при переработке добытого газового конденсата на технологическом оборудовании, принадлежащем российской организации, - копии первичных учетных документов, подтверждающих факт направления добытого газового конденсата на переработку, его количество, а также подтверждающих оприходование (постановку на бухгалтерский учет) готовой продукции - широкой фракции легких углеводородов, полученной в текущем налоговом периоде из добытого газового конденсата;\n\n2) в случае передачи добытого газового конденсата на переработку в соответствии с договором, предусматривающим оказание российской организацией услуг налогоплательщику по переработке добытого газового конденсата с получением широкой фракции легких углеводородов, - копию договора налогоплательщика с указанной организацией, копии первичных учетных документов, подтверждающих факт направления добытого газового конденсата указанной организации на переработку, а также подтверждающих оприходование (постановку на бухгалтерский учет) готовой продукции - широкой фракции легких углеводородов, полученной в текущем налоговом периоде из добытого газового конденсата;\n\n3) в случае реализации добытого газового конденсата без переработки, если налогоплательщику известно, что такой газовый конденсат в дальнейшем направляется иными организациями на переработку с получением широкой фракции легких углеводородов, - копию договора купли-продажи добытого газового конденсата, копии первичных учетных документов (в том числе первичных учетных документов третьих лиц, если такие лица признают доходы (расходы) от реализации этого газового конденсата без переработки или перерабатывают его (направляют его на переработку), подтверждающих факт направления такого газового конденсата на переработку (в том числе третьими лицами), его количество, а также первичных учетных документов, подтверждающих факт получения из такого газового конденсата широкой фракции легких углеводородов (в том числе третьими лицами) в виде готовой продукции, копии первичных учетных документов, подтверждающих оприходование (постановку на бухгалтерский учет) готовой продукции - широкой фракции легких углеводородов, полученной в текущем налоговом периоде из добытого газового конденсата.\n\n3. Сумма налогового вычета определяется налогоплательщиком самостоятельно по итогам каждого налогового периода по следующей формуле:\n\nВгк = Кшфлу х Мгк х В,\n\nгде Кшфлу - коэффициент извлечения широкой фракции легких углеводородов при переработке газового конденсата, в том числе добытого налогоплательщиком, определяемый за истекший налоговый период организацией, осуществляющей такую переработку, как отношение количества полученной за истекший налоговый период широкой фракции легких углеводородов к общему количеству переработанного в истекшем налоговом периоде газового конденсата. Значение коэффициента округляется до четвертого знака после запятой в соответствии с действующим порядком округления. Значение коэффициента доводится этой организацией до недропользователей, имеющих право на налоговый вычет в соответствии с настоящей статьей, официальным письмом, подписанным руководителем или лицом, временно исполняющим обязанности руководителя и назначенным в установленном порядке. В случае, установленном подпунктом 1 пункта 2 настоящей статьи, значение коэффициента определяется налогоплательщиком самостоятельно;\n\nМгк - количество добытого налогоплательщиком газового кон\n\nденсата, переработанного на технологическом оборудовании по его переработке для получения широкой фракции легких углеводородов (в том числе третьими лицами), определенное налогоплательщиком самостоятельно, выраженное в тоннах и округленное до четвертого знака после запятой в соответствии с действующим порядком округления;\n\nВ - ставка налогового вычета в рублях на 1 тонну широкой фракции легких углеводородов, полученной из газового конденсата, добытого налогоплательщиком, рассчитываемая по следующей формуле:\n\nВ = 147 + (n - 1) х 147,\n\nгде n - порядковый номер налогового периода, отсчитываемый последовательно с 1 января 2018 года, учитывая, что порядковый номер налогового периода, начинающегося 1 января 2018 года, равен 1.\n\nНачиная с тридцать шестого налогового периода (n = 36), отсчитываемого в порядке, установленном настоящим пунктом, значение ставки налогового вычета (В) принимается равной 5 280.\n\n4. Рассчитанная в порядке, определенном настоящей статьей, сумма налогового вычета при добыче газового конденсата (Вгк) округляется до второго знака после запятой в соответствии с действующим порядком округления.\n\n5. Для целей настоящей статьи к широкой фракции легких углеводородов также относится пропан-бутан технический, если в отношении его не выполняются следующие условия:\n\n1) пропан-бутан технический получен при переработке газового конденсата на технологическом оборудовании, впервые введенном в эксплуатацию до 1 января 2018 года;\n\n2) пропан-бутан технический получен (выделен) из широкой фракции легких углеводородов, ранее извлеченной при переработке газового конденсата.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 301-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 335-ФЗ)","article_title":"Статья 343.4. Порядок уменьшения суммы налога, исчисленного при добыче газового конденсата из всех видов месторождений углеводородного сырья, на сумму налогового вычета в связи с получением при переработке газового конденсата широкой фракции легких углеводородов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad3642633c9ee4deaf22b497bc86e4a8acb4f0ab7cef791cc85de62a4c35ecfb"},{"code_id":"NK_RF_2","article_number":"343.5","version_date":"2000-07-31","article_text":"1. Налогоплательщик вправе уменьшить общую сумму налога, исчисленную при добыче нефти обезвоженной, обессоленной и стабилизированной на участках недр, отвечающих требованиям, установленным пунктом 2 настоящей статьи, на сумму налогового вычета, определяемого и применяемого в порядке, установленном настоящей статьей (далее в настоящей статье - налоговый вычет).\n\nНалоговый вычет применяется с 1-го числа налогового периода, в котором вступила в силу настоящая статья, до истечения 120 налоговых периодов с начала применения налогового вычета.\n\n2. В целях применения налогового вычета в отношении общей суммы налога, исчисленной за налоговый период при добыче нефти обезвоженной, обессоленной и стабилизированной на участке недр, такой участок недр в течение всего налогового периода должен отвечать одновременно следующим требованиям:\n\n1) участок недр расположен полностью или частично севернее 67 градуса северной широты и южнее 69 градуса северной широты полностью в границах Красноярского края;\n\n2) при добыче нефти обезвоженной, обессоленной и стабилизированной на участке недр применяются налоговая ставка, установленная подпунктом 9 пункта 2 статьи 342 настоящего Кодекса, и соответствующие коэффициенты КД, КЗ, ККАН, определенные в установленном настоящей главой порядке, равные 1, либо налоговая ставка, установленная подпунктом 91 пункта 2 статьи 342 настоящего Кодекса (за исключением нефти обезвоженной, обессоленной и стабилизированной, добытой на участках недр, соответствующих требованиям, установленным подпунктом 5 пункта 1 статьи 33345 настоящего Кодекса);\n\n3) права пользования участком недр предоставлены организации, в которой прямо или косвенно участвует другая организация и доля такого участия составляет не менее 50 процентов, при этом Российская Федерация имеет право прямо или косвенно распоряжаться более чем 50 процентами общего количества голосов, приходящихся на голосующие акции (доли), составляющие уставный капитал указанной другой организации. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n3. Налоговый вычет вправе применять:\n\n1) организации, которым права пользования соответствующими участками недр предоставлены до 1 января 2019 года;\n\n2) организации, которым начиная с 1 января 2019 года права пользования участками недр перешли от организаций, указанных в подпункте 1 настоящего пункта, по основаниям и в порядке, которые установлены законодательством Российской Федерации о недрах.\n\nК расходам, указанным в абзаце первом настоящего пункта, относятся расходы налогоплательщика, а также лиц, которым предоставлены лицензии на пользование участками недр, указанными в подпункте 5 пункта 1 статьи 33345 настоящего Кодекса, при условии передачи такими лицами налогоплательщику копий документов, подтверждающих суммы указанных расходов, их оплату и соответствие установленным настоящей статьей требованиям. Расходы лиц, которым предоставлены лицензии на пользование участками недр, указанными в подпункте 5 пункта 1 статьи 33345 настоящего Кодекса, учитываются при определении налогового вычета одним налогоплательщиком.\n\nК расходам на приобретение, сооружение, изготовление, доставку объектов основных средств, соответствующих требованиям, установленным пунктом 6 настоящей статьи, и доведение указанных объектов основных средств до состояния, в котором они пригодны для использования, в целях настоящей статьи относятся также:\n\nрасходы на достройку, дооборудование, реконструкцию, модернизацию, техническое перевооружение, частичную ликвидацию указанных объектов. При этом указанные понятия используются в значении, указанном в статье 257 настоящего Кодекса;\n\nрасходы, связанные с договорами технологического присоединения, договорами возмещения затрат, договорами инвестирования и иными аналогичными договорами, заключенными исключительно в отношении объектов основных средств, указанных в пункте 6 настоящей статьи, с организациями, осуществляющими создание и эксплуатацию указанных объектов.\n\nПри этом предельная сумма налогового вычета и порядок определения фактически оплаченных сумм расходов, указанных в настоящем пункте, определяются с учетом порядка и требований, которые установлены настоящей статьей.\n\nЕсли иное не предусмотрено настоящей статьей, суммы фактически оплаченных расходов, указанных в пункте 4 настоящей статьи, не учтенные при определении суммы налогового вычета в налоговом периоде, могут быть учтены при определении налогового вычета в последующем налоговом периоде в пределах периода, указанного в пункте 1 настоящей статьи. (В редакции  Федерального закона от 29.11.2024 № 416-ФЗ)\n\nСуммы фактически оплаченных расходов, указанных в пункте 4 настоящей статьи, учтенные при определении суммы налогового вычета в налоговом периоде, не подлежат повторному включению в состав налогового вычета в иных налоговых периодах, а также на иных участках недр.\n\nКлассификация имущества в качестве объектов основных средств осуществляется на основании положений пункта 1 статьи 257 настоящего Кодекса.\n\nВ целях настоящей статьи:\n\nк расходам на приобретение, сооружение, изготовление, доставку объектов основных средств и доведение указанных объектов основных средств до состояния, в котором они пригодны для использования, а также на приобретение имущественных прав на такие объекты основных средств приравниваются авансовые платежи, выданные (перечисленные) поставщикам (подрядчикам) по договорам на приобретение, сооружение, изготовление, доставку объектов основных средств и доведение указанных объектов основных средств до состояния, в котором они пригодны для использования, а также на приобретение имущественных прав на такие объекты основных средств;\n\nфактической оплатой сумм расходов признается прекращение (частичное прекращение) встречного обязательства приобретателем товаров (работ, услуг) и имущественных прав перед продавцом, которое непосредственно связано с поставкой этих товаров (выполнением работ, оказанием услуг) и передачей имущественных прав, а также перечисление авансовых платежей в счет предстоящих поставок товаров (выполнения работ, оказания услуг, передачи имущественных прав);\n\nпонятие \"деятельность по освоению участка недр\" используется в значении, указанном в пункте 3 статьи 33343 настоящего Кодекса.\n\nУказанные в настоящем пункте объекты основных средств должны быть введены в эксплуатацию до истечения периода применения налогового вычета.\n\nВ случае применения налогоплательщиком налогового вычета за налоговый период в порядке, указанном в абзаце первом пункта 12 настоящей статьи, документы, подтверждающие фактическую оплату расходов, указанных в пункте 4 настоящей статьи, в сумме не менее величины соответствующего превышения размера примененного налогового вычета над суммой фактически оплаченных в период с 1 января 2020 года по последнее число налогового периода (включительно) расходов, представляются налогоплательщиком в налоговый орган не позднее 25-го числа месяца, следующего за месяцем, в котором истекает срок, установленный абзацем первым пункта 12 настоящей статьи. (Дополнение абзацем - Федеральный закон от 29.11.2024 № 416-ФЗ)\n\nВ случае, если сумма фактически оплаченных расходов на приобретение, сооружение, изготовление, доставку объекта основных средств, указанного в пункте 6 настоящей статьи, и доведение его до состояния, в котором он пригоден для использования, оказалась выше первоначальной стоимости такого основного средства, определенной в порядке и с применением методов, которые установлены главой 143 настоящего Кодекса, сумма налогового вычета в части такого превышения принимается равной 0 для всех налоговых периодов, в которых налогоплательщиком были учтены соответствующие расходы при определении налогового вычета. При этом сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих сумм пеней, начисляемых со дня, следующего за днем уплаты налога за соответствующий налоговый период.\n\nВ целях настоящей статьи понятие \"рыночная цена\" используется в значении, указанном в статье 1053 настоящего Кодекса.\n\nРасходы, учтенные для целей выполнения условий, установленных абзацем первым настоящего пункта, в одном налоговом периоде, не подлежат повторному учету для целей выполнения этих условий или включению в состав налогового вычета в порядке, указанном в пункте 5 настоящей статьи, в иных налоговых периодах, а также на иных участках недр.\n\nВ случае, если при применении налогового вычета за налоговый период в соответствии с абзацем первым настоящего пункта налогоплательщиком не представлены в срок, установленный абзацем вторым пункта 9 настоящей статьи, документы, подтверждающие фактическую оплату расходов, указанных в пункте 4 настоящей статьи, в сумме не менее величины соответствующего превышения размера примененного налогового вычета над суммой фактически оплаченных в период с 1 января 2020 года по последнее число налогового периода (включительно) расходов, сумма налога, не уплаченного в бюджет в результате применения налогового вычета, увеличенного на величину указанного превышения, подлежит восстановлению и уплате в бюджет с уплатой соответствующих пеней, начисляемых со дня, следующего за днем уплаты налога за соответствующий налоговый период.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2024 № 416-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 18.03.2020 № 65-ФЗ)","article_title":"Статья 343.5. Порядок уменьшения суммы налога, исчисленной при добыче нефти обезвоженной, обессоленной и стабилизированной, на сумму налогового вычета, связанного с созданием объектов внешней инфраструктуры","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbb043017281b5e91f680353ebbf30b8e90c6836cd5ac17241b355c07876b635"},{"code_id":"NK_RF_2","article_number":"343.6","version_date":"2000-07-31","article_text":"В целях настоящей статьи под новым участком недр понимается участок недр, расположенный полностью в границах Арктической зоны Российской Федерации, на котором степень выработанности запасов конкретного полезного ископаемого меньше значения или равна значению 0,001 в соответствии с данными государственного баланса запасов полезных ископаемых по состоянию на 1 января 2021 года либо запасы такого полезного ископаемого отсутствуют в государственном балансе запасов полезных ископаемых по состоянию на указанную дату.\n\nВ целях настоящей статьи степень выработанности запасов полезного ископаемого рассчитывается налогоплательщиком самостоятельно на основании данных государственного баланса запасов полезных ископаемых на 1 января 2021 года как частное от деления суммы накопленной добычи конкретного полезного ископаемого (включая потери при добыче) на участке недр на начальные извлекаемые запасы такого полезного ископаемого на участке недр. Рассчитанное в порядке, установленном настоящим пунктом, значение степени выработанности запасов полезного ископаемого округляется до третьего знака после запятой в соответствии с действующим порядком округления.\n\nНалоговый вычет применяется с 1 января 2021 года по 31 декабря 2032 года включительно.\n\nПри этом при определении суммы налогового вычета учитываются указанные в абзаце первом настоящего пункта расходы, понесенные в отношении введенных в эксплуатацию объектов основных средств, а также в отношении исполненных договоров, указанных в абзаце первом настоящего пункта.\n\nСумма налогового вычета не может превышать 50 процентов суммы налога, подлежащей уплате в налоговом периоде, в котором применяется налоговый вычет.\n\nКлассификация имущества в качестве объектов основных средств осуществляется на основании положений пункта 1 статьи 257 настоящего Кодекса.\n\nУказанные в настоя\n\nщем пункте объекты основных средств должны быть введены в эксплуатацию не ранее 1 января 2021 года.\n\nВ отношении указанных в настоящем пункте объектов основных средств не применен или не будет применен налоговый вычет для организации, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, предусмотренный статьей 2518 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nСуммы фактически оплаченных расходов, указанных в пункте 2 настоящей статьи, учтенные при определении суммы налогового вычета в налоговом периоде, не подлежат повторному включению в состав налогового вычета в иных налоговых периодах, а также при добыче полезных ископаемых на других участках недр или добыче иных полезных ископаемых на данном участке недр.\n\n(Дополнение статьей - Федеральный закон от 13.07.2020 № 195-ФЗ)","article_title":"Статья 343.6. Порядок уменьшения суммы налога, исчисленной при добыче отдельных видов полезных ископаемых резидентами Арктической зоны Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34d575cf0635d4c73adc464a5fd5ea4f94a0426ad7b0f65bdf1c68b47425ea85"},{"code_id":"NK_RF_2","article_number":"343.7","version_date":"2000-07-31","article_text":"1. Налогоплательщик в налоговых периодах, начало которых приходится на период с 1 августа 2022 года по 31 декабря 2040 года включительно, вправе уменьшить сумму налога, исчисленную при добыче многокомпонентной комплексной руды, содержащей молибден и медь, на участках недр, расположенных полностью или частично на территории Республики Хакасия, на сумму налогового вычета, определяемого и применяемого в порядке, установленном настоящей статьей (далее в настоящей статье - налоговый вычет).\n\n2. Сумма налогового вычета за налоговый период определяется в совокупности по указанным в пункте 1 настоящей статьи участкам недр как величина фактически оплаченных в период с 1 августа 2022 года по последнее число (включительно) налогового периода, в котором применяется налоговый вычет, сумм расходов на приобретение, сооружение, изготовление, доставку объектов основных средств, соответствующих требованиям, установленным пунктом 4 настоящей статьи, и доведение таких объектов до состояния, в котором они пригодны для использования, и сумм расходов в виде процентов по кредитам, определяемых с учетом особенностей, предусмотренных статьей 269 настоящего Кодекса, в случае, если соответствующие кредитные средства были привлечены для финансирования расходов, указанных в настоящем пункте.\n\nПри этом при определении суммы налогового вычета учитываются указанные в настоящем пункте расходы, понесенные в отношении объектов основных средств, введенных в эксплуатацию после даты, указанной в пункте 4 настоящей статьи.\n\nВ случае, если в сделках, учитываемых при определении расходов, указанных в настоящем пункте, применялись цены, не признаваемые рыночными, такие расходы учитываются при определении налогового вычета в размере, определенном с использованием цен указанных сделок, принимаемых для целей налогообложения в порядке и с применением методов, установленных главой 143 настоящего Кодекса. В целях настоящей статьи рыночная цена определяется с учетом положений статьи 1053 настоящего Кодекса.\n\nСумма налогового вычета, определенная в соответствии с настоящим пунктом, округляется до целого значения в соответствии с действующим порядком округления.\n\n3. Размер налогового вычета в налоговых периодах, начало которых приходится на период с 1 августа 2027 года, не может превышать величину, определяемую для соответствующего налогового периода как разница между суммой налога, исчисленной с применением рентного коэффициента КРЕНТА, равного 3,5, и суммой налога, исчисленной с применением рентного коэффициента КРЕНТА, равного 1.\n\n4. В целях применения налогового вычета объекты основных средств, указанные в пункте 2 настоящей статьи, должны относиться к горнодобывающему оборудованию и горной технике, используемым в деятельности по добыче полезных ископаемых, указанных в пункте 1 настоящей статьи, и включенным в перечень, утверждаемый федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по согласованию с Министерством финансов Российской Федерации.\n\nКлассификация имущества в качестве объектов основных средств осуществляется на основании положений пункта 1 статьи 257 настоящего Кодекса.\n\nУказанные в настоящем пункте объекты основных средств должны быть введены в эксплуатацию не ранее 1 августа 2022 года.\n\n5. Суммы фактически оплаченных расходов, указанных в пункте 2 настоящей статьи, не учтенные при определении суммы налогового вычета в налоговом периоде, могут быть учтены при определении налогового вычета в последующих налоговых периодах.\n\nСуммы фактически оплаченных расходов, указанных в пункте 2 настоящей статьи, учтенные при определении суммы налогового вычета в налоговом периоде, не подлежат повторному включению в состав налогового вычета в иных налоговых периодах, а также при добыче полезных ископаемых на других участках недр и (или) добыче иных полезных ископаемых на данном участке недр.\n\n(Дополнение статьей - Федеральный закон от 14.07.2022 № 323-ФЗ)","article_title":"Статья 343.7. Порядок уменьшения суммы налога, исчисленной при добыче многокомпонентной комплексной руды, содержащей молибден и медь, на участках недр, расположенных полностью или частично на территории Республики Хакасия, на сумму налогового вычета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca254bb133cab8156694e847179e9fa7f7065d92867309d02ca7b44dd1932ba0"},{"code_id":"NK_RF_2","article_number":"343.8","version_date":"2000-07-31","article_text":"1. Налогоплательщик в налоговых периодах, начало которых приходится на период с 1 января 2023 года по 31 декабря 2026 года включительно, вправе уменьшить сумму налога, исчисленную при добыче железной руды (за исключением окисленных железистых кварцитов) на участках недр, расположенных полностью или частично в границах Качканарского и Нижнетуринского городских округов Свердловской области, на сумму налогового вычета, определяемого и применяемого в порядке, установленном настоящей статьей (далее в настоящей статье - налоговый вычет).\n\n2. Сумма налогового вычета за налоговый период определяется в совокупности по указанным в пункте 1 настоящей статьи участкам недр как величина фактически оплаченных налогоплательщиком в данном налоговом периоде и предыдущих налоговых периодах, но не ранее 1 января 2022 года сумм расходов на приобретение, сооружение, изготовление, доставку объектов основных средств, соответствующих требованиям, установленным пунктом 4 настоящей статьи, и доведение таких объектов до состояния, в котором они пригодны для использования, умноженных на коэффициент 0,33.\n\nК расходам на приобретение, сооружение, изготовление, доставку объектов основных средств, соответствующих требованиям, установленным пунктом 4 настоящей статьи, и доведение таких объектов до состояния, в котором они пригодны для использования, в целях настоящей статьи относятся также расходы на достройку, дооборудование, реконструкцию, модернизацию, техническое перевооружение, частичную ликвидацию указанных объектов. При этом данные понятия используются в значении, указанном в статье 257 настоящего Кодекса.\n\nВ случае, если в сделках, учитываемых при определении расходов, указанных в настоящем пункте, применялись цены, не признаваемые рыночными, эти расходы учитываются при определении налогового вычета в размере, определенном с использованием цен указанных сделок, принимаемых для целей налогообложения в порядке и с применением методов, установленных главой 143 настоящего Кодекса. В целях настоящей статьи рыночная цена определяется с учетом положений статьи 1053 настоящего Кодекса.\n\nСумма налогового вычета, определенная в соответствии с настоящим пунктом, округляется до целого значения в соответствии с действующим порядком округления.\n\n3. Налоговый вычет не применяется начиная с налогового периода, в котором определенная нарастающим итогом сумма налоговых вычетов, предусмотренных пунктом 2 настоящей статьи, впервые оказалась более 10 000 миллионов рублей.\n\n4. В целях применения налогового вычета объекты основных средств, указанные в пункте 2 настоящей статьи, должны относиться к объектам размещения отходов горнодобывающего и связанных с ним перерабатывающих производств, образованных в процессе переработки железной руды (за исключением окисленных железистых кварцитов), добытой на участках недр, указанных в пункте 1 настоящей статьи.\n\nКлассификация имущества в качестве объектов основных средств осуществляется на основании положений пункта 1 статьи 257 настоящего Кодекса.\n\n5. Суммы фактически оплаченных расходов, указанных в пункте 2 настоящей статьи, не учтенные при определении суммы налогового вычета в налоговом периоде, могут быть учтены при определении налогового вычета в последующих налоговых периодах.\n\nСуммы фактически оплаченных расходов, указанных в пункте 2 настоящей статьи, учтенные при определении суммы налогового вычета в налоговом периоде, не подлежат повторному включению в состав налогового вычета в иных налоговых периодах, а также при добыче полезных ископаемых на других участках недр и (или) добыче иных полезных ископаемых на данном участке недр.\n\n(Дополнение статьей - Федеральный закон от 14.07.2022 № 323-ФЗ)","article_title":"Статья 343.8. Порядок уменьшения суммы налога, исчисленной при добыче железной руды (за исключением окисленных железистых кварцитов), на сумму налогового вычета, связанного с созданием объектов размещения отходов горнодобывающих производств","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6d91df269bc8d540de7fc9e5e9996fb6da34abd66e1f991291e5cf74aa332443"},{"code_id":"NK_RF_2","article_number":"343.9","version_date":"2000-07-31","article_text":"1. Налогоплательщики, отвечающие требованиям пункта 2 настоящей статьи, в налоговых периодах, начало которых приходится на период с 1 января 2023 года по 31 декабря 2032 года включительно, вправе уменьшить сумму налога, исчисленную при добыче кондиционных руд олова на участках недр, расположенных полностью или частично на территории Дальневосточного федерального округа, на сумму налогового вычета, определяемого и применяемого в порядке, установленном настоящей статьей (далее в настоящей статье - налоговый вычет).\n\n2. В целях применения налогового вычета налогоплательщик в течение всего налогового периода должен отвечать одновременно требованиям подпунктов 1 и 2 или подпунктов 1 и 3 настоящего пункта:\n\n1) налогоплательщик не является резидентом особой экономической зоны любого типа, участником регионального инвестиционного проекта, стороной соглашения о защите и поощрении капиталовложений, участником специального инвестиционного контракта;\n\n2) налогоплательщик является взаимозависимым лицом с организацией, признаваемой пользователем недр и осуществляющей деятельность по добыче кондиционных руд олова на участках недр, расположенных полностью или частично на территории Дальневосточного федерального округа, степень выработанности запасов которых, определенная в соответствии с подпунктом 1 пункта 11 статьи 3428 настоящего Кодекса, по состоянию на 1 января 2022 года составляет менее 1 процента;\n\n3) налогоплательщик осуществляет деятельность по добыче кондиционных руд олова на участках недр, расположенных полностью или частично на территории Дальневосточного федерального округа, степень выработанности запасов которых, определенная в соответствии с подпунктом 1 пункта 11 статьи 3428 настоящего Кодекса, по состоянию на 1 января 2022 года составляет менее 20 процентов.\n\n3. Если иное не установлено пунктом 4 настоящей статьи, сумма налогового вычета за налоговый период определяется по участку недр как величина фактически оплаченных в период с 1 января 2023 года по последнее число (включительно) налогового периода, в котором применяется налоговый вычет, сумм расходов на приобретение, сооружение, изготовление, доставку объектов основных средств, соответствующих требованиям, установленным пунктом 5 настоящей статьи, и доведение таких объектов до состояния, в котором они пригодны для использования, включая расходы на разработку проектной и сметной документации, при условии что такие расходы ранее не учитывались при определении сумм налогового вычета.\n\nК расходам, предусмотренным настоящим пунктом, относятся также расходы организации, осуществляющей деятельность по добыче кондиционных руд олова и указанной в подпункте 2 пункта 2 настоящей статьи, в случае передачи такой организацией налогоплательщику - взаимозависимому лицу копий документов, подтверждающих суммы указанных расходов, их оплату и соответствие объектов основных средств требованиям, установленным пунктом 5 настоящей статьи.\n\nРасходы организации, осуществляющей деятельность по добыче кондиционных руд олова и указанной в подпункте 2 пункта 2 настоящей статьи, по каждому объекту основных средств учитываются при определении налогового вычета такой организацией или ее взаимозависимым лицом единожды.\n\nВ случае, если в сделках, учитываемых при определении расходов, указанных в настоящем пункте, применялись цены, не признаваемые рыночными, такие расходы учитываются при определении налогового вычета в размере, определенном с использованием цен указанных сделок, принимаемых для целей налогообложения в порядке и с применением методов, установленных главой 143 настоящего Кодекса. В целях настоящей статьи рыночная цена определяется с учетом положений статьи 1053 настоящего Кодекса.\n\nСумма налогового вычета, определенная в соответствии с настоящим пунктом, округляется до целого значения в соответствии с действующим порядком округления.\n\n4. Размер налогового вычета в налоговых периодах, начало которых приходится на период с 1 января 2028 года, не может превышать величину, определяемую для соответствующего налогового периода как разница между суммой налога, исчисленной с применением рентного коэффициента КРЕНТА, равного 3,5, и суммой налога, исчисленной с применением рентного коэффициента КРЕНТА, равного 1.\n\n5. В целях применения налогового вычета объекты основных средств, указанные в пункте 3 настоящей статьи, должны относиться к горнодобывающему оборудованию и горной технике, объектам дорожной, транспортной, инженерной, энергетической инфраструктур, используемым для осуществления деятельности по добыче кондиционных руд олова на участках недр, указанных в подпункте 2 или 3 пункта 2 настоящей статьи, и (или) к производственным мощностям, используемым для дальнейшей переработки (обогащения, технологического передела) указанных полезных ископаемых.\n\nДля целей настоящей статьи перечень видов горнодобывающего оборудования, горной техники, производственных мощностей, используемых для дальнейшей переработки (обогащения, технологического передела) полезных ископаемых, расходы на приобретение (создание) которых учитываются при определении налогового вычета, утверждается федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере промышленного и оборонно-промышленного комплексов, по согласованию с Министерством финансов Российской Федерации.\n\nКлассификация имущества в качестве объектов основных средств осуществляется на основании положений пункта 1 статьи 257 настоящего Кодекса.\n\nУказанные в настоящем пункте объекты основных средств должны быть введены в эксплуатацию после 1 января 2023 года.\n\n6. Суммы фактически оплаченных расходов, указанных в пункте 3 настоящей статьи, не учтенные при определении суммы налогового вычета в налоговом периоде, могут быть учтены при определении налогового вычета в последующих налоговых периодах.\n\nСредняя за налоговый период цена на олово на мировых рынках ЦО, выраженная в долларах США за 1 килограмм, определяется в порядке, установленном федеральным органом исполнительной власти, осуществляющим функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы. Значение показателя ЦО округляется до первого знака после запятой в соответствии с действующим порядком округления. Показатель ЦО рассчитывается федеральным органом исполнительной власти, осуществляющим функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, и подлежит размещению на официальном сайте указанного федерального органа исполнительной власти в информационно-телекоммуникационной сети \"Интернет\" до 10-го числа календарного месяца, следующего за истекшим налоговым периодом.\n\nВ случае, если средняя за налоговый период цена на олово на мировых рынках ЦО не размещена (своевременно не размещена) на официальном сайте федерального органа исполнительной власти, осуществляющего функции по принятию нормативных правовых актов, контролю и надзору за соблюдением законодательства в сфере конкуренции на товарных рынках, защиты конкуренции на рынке финансовых услуг, деятельности субъектов естественных монополий и рекламы, указанный показатель рассчитывается налогоплательщиком самостоятельно в порядке, установленном указанным федеральным органом исполнительной власти.\n\n(Дополнение статьей - Федеральный закон от 28.12.2022 № 566-ФЗ)","article_title":"Статья 343.9. Порядок уменьшения суммы налога, исчисленной при добыче кондиционных руд олова на участках недр, расположенных полностью или частично на территории Дальневосточного федерального округа, на сумму налогового вычета","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bbc3b58a73eb605487cd94a367a8a9ff002015f798f5f6293bfc0edd2440aab"},{"code_id":"NK_RF_2","article_number":"344","version_date":"2000-07-31","article_text":"Сумма налога, подлежащая уплате по итогу налогового периода, уплачивается не позднее 28-го числа месяца, следующего за истекшим налоговым периодом. (В редакции Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 344. Сроки уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00ea2c4db5bbda71d82a53778671c0549874076067113efc254c2a1f1a2d9378"},{"code_id":"NK_RF_2","article_number":"345","version_date":"2000-07-31","article_text":"Налоговая декларация представляется налогоплательщиком в налоговые органы по месту нахождения (месту жительства) налогоплательщика. (Дополнение абзацем - Федеральный закон от 29.05.2002 № 57-ФЗ)","article_title":"Статья 345. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9cafc466d821c5cb3fca27ed4486e144a8686dcd414800e8a36cc18575fcfd51"},{"code_id":"NK_RF_2","article_number":"345.1","version_date":"2000-07-31","article_text":"1. Федеральный орган исполнительной власти, осуществляющий в установленном порядке ведение государственного баланса запасов полезных ископаемых, направляет в налоговые органы данные государственного баланса запасов полезных ископаемых на 1-е число каждого календарного года, включающие в том числе следующие сведения:\n\n1) наименование пользователя недр, идентификационный номер налогоплательщика и код прич\n\nины постановки на учет;\n\n2) реквизиты лицензии на право пользования недрами;\n\n3) сведения по каждому виду углеводородного сырья, указанному в подпункте 3 пункта 2 статьи 337 настоящего Кодекса, в том числе:\n\nсведения о накопленной добыче (включая потери при добыче) и начальных извлекаемых запасах, утвержденных в установленном порядке, с учетом прироста и списания запасов (за исключением списания запасов добытых полезных ископаемых и потерь при добыче) всех категорий по каждому конкретному участку недр, а также по каждой конкретной залежи углеводородного сырья, указанной в подпунктах 2 - 4 пункта 1 статьи 3422 настоящего Кодекса;\n\nпоказатели проницаемости и эффективной нефтенасыщенной толщины пласта по залежи углеводородного сырья;\n\nнаименование продуктивных отложений, к которым отнесена залежь углеводородного сырья;\n\nсведения о накопленной добыче каждого вида углеводородного сырья на новом морском месторождении углеводородного сырья (включая потери при добыче) и его начальных запасах (для нефти - начальных извлекаемых запасах), утвержденных в установленном порядке, с учетом прироста и списания запасов полезного ископаемого (за исключением списания запасов добытого полезного ископаемого и потерь при добыче) всех категорий по каждому месторождению (залежи) углеводородного сырья;\n\nсведения о месторождениях, предусмотренные пунктом 6 статьи 338 настоящего Кодекса;\n\nсведения о минимальной глубине залегания залежи углеводородного сырья;\n\n4) сведения о добыче антрацита, угля коксующегося, угля бурого и угля, за исключением антрацита, угля коксующегося и угля бурого, и фактических потерях при добыче (в разрезе пластов);\n\n5) сведения о добыче руд, содержащих черные, цветные, редкие и драгоценные металлы, о долях содержания металлов в руде, а также потерях металлов при добыче соответствующих руд;\n\n6) сведения о добыче (включая потери при добыче) полезных ископаемых, не указанных в подпунктах 3 - 5 настоящего пункта, о накопленной добыче (включая потери при добыче) и начальных извлекаемых запасах, утвержденных в установленном порядке, с учетом прироста и списания запасов (за исключением списания запасов добытых полезных ископаемых и потерь при добыче) всех категорий по каждому конкретному участку недр.\n\n(Пункт в редакции Федерального закона от 29.11.2021 № 382-ФЗ)\n\n2. Данные представляются после выпуска государственного баланса запасов полезных ископаемых на 1-е число каждого календарного года, но не позднее 1-го числа следующего календарного года.\n\n(Дополнение статьей - Федеральный закон от 28.12.2010 № 425-ФЗ)","article_title":"Статья 345.1. Порядок представления сведений органами управления государственным фондом недр, а также органами, осуществляющими контроль и надзор в сфере природопользования","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9536f2a105b44e0c628bbc83dc2fe9b6458ff49249ca37d851752d0994a4c8a8"},{"code_id":"NK_RF_2","article_number":"346","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 06.06.2003 № 65-ФЗ)\n\nРАЗДЕЛ VIII1. СПЕЦИАЛЬНЫЕ НАЛОГОВЫЕ РЕЖИМЫ\n\n(Дополнение разделом - Федеральный закон от 29.12.2001 № 187-ФЗ)\n\nГЛАВА 261. СИСТЕМА НАЛОГООБЛОЖЕНИЯ ДЛЯ СЕЛЬСКОХОЗЯЙСТВЕННЫХ ТОВАРОПРОИЗВОДИТЕЛЕЙ (ЕДИНЫЙ СЕЛЬСКОХОЗЯЙСТВЕННЫЙ НАЛОГ)\n\n(Глава в редакции Федерального закона от 11.11.2003 № 147-ФЗ)","article_title":"Статья 346. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ecee7ed8188df65dce41e4408f3cb8b3b23baf80b2d3ddcdd0c30e7740051aa"},{"code_id":"NK_RF_2","article_number":"346.1","version_date":"2000-07-31","article_text":"Организации, являющиеся налогоплательщиками единого сельскохозяйственного налога, не признаются налогоплательщиками налога на добавленную стоимость (за исключением налога на добавленную стоимость, подлежащего уплате в соответствии с настоящим Кодексом при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией (включая суммы налога, подлежащие уплате при завершении действия таможенной процедуры свободной таможенной зоны на территории Особой экономической зоны в Калининградской области), а также налога на добавленную стоимость, уплачиваемого в соответствии со статьями 161 и 1741 настоящего Кодекса).\n\nИные налоги, сборы и страховые взносы уплачиваются организациями, перешедшими на уплату единого сельскохозяйственного налога, в соответствии с законодательством Российской Федерации о налогах и сборах.\n\nИндивидуальные предприниматели, являющиеся налогоплательщиками единого сельскохозяйственного налога, освобождаются от обязанности по уплате налога на доходы физических лиц (в отношении доходов, полученных от предпринимательской деятельности, за исключением налога, уплачиваемого с доходов в виде дивидендов, а также с доходов, облагаемых по налоговым ставкам, предусмотренным пунктами 2 и 5 статьи 224 настоящего Кодекса), налога на имущество физических лиц (в отношении имущества, используемого для осуществления предпринимательской деятельности (в части имущества, используемого при производстве сельскохозяйственной продукции, первичной и последующей (промышленной) переработке и реализации этой продукции, а также при оказании услуг сельскохозяйственными товаропроизводителями).\n\nИндивидуальные предприниматели, являющиеся налогоплательщиками единого сельскохозяйственного налога, не признаются налогоплательщиками налога на добавленную стоимость (за исключением налога на добавленную стоимость, подлежащего уплате в соответствии с настоящим Кодексом при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией (включая суммы налога, подлежащие уплате при завершении действия таможенной процедуры свободной таможенной зоны на территории Особой экономической зоны в Калининградской области), а также налога на добавленную стоимость, уплачиваемого в соответствии со статьями 161 и 1741 настоящего Кодекса).\n\nИные налоги, сборы и страховые взносы уплачиваются индивидуальными предпринимателями, перешедшими на уплату единого сельскохозяйственного налога, в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)","article_title":"Статья 346.1. Общие условия применения системы налогообложения для сельскохозяйственных товаропроизводителей (единого сельскохозяйственного налога)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cafa900f4b06f036d4ebdb725eb3ecbedfaa6d2eb1c8098a666f6ebe226f58fe"},{"code_id":"NK_RF_2","article_number":"346.10","version_date":"2000-07-31","article_text":"1) организации - по месту своего нахождения;\n\n2) индивидуальные предприниматели - по месту своего жительства.\n\n1) по итогам налогового периода не позднее 25 марта года, следующего за истекшим налоговым периодом, за исключением случая, предусмотренного подпунктом 2 настоящего пункта; (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2) не позднее 25-го числа месяца, следующего за месяцем, в котором согласно уведомлению, представленному налогоплательщиком в налоговый орган в соответствии с пунктом 9 статьи 3463 настоящего Кодекса, им прекращена предпринимательская деятельность в качестве сельскохозяйственного товаропроизводителя, признаваемого таковым в соответствии с настоящей главой.\n\n(Пункт в редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\n(Статья в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\nГЛАВА 262. УПРОЩЕННАЯ СИСТЕМА НАЛОГООБЛОЖЕНИЯ\n\n(Дополнение главой - Федеральный закон от 24.07.2002 № 104-ФЗ)","article_title":"Статья 346.10. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1a96919bcf12c04f5596259ad72e29b5197fccc889e7de77b783fb91a7016bb"},{"code_id":"NK_RF_2","article_number":"346.11","version_date":"2000-07-31","article_text":"Переход к упрощенной системе налогообложения или возврат к иным режимам налогообложения осуществляется организациями и индивидуальными предпринимателями добровольно в порядке, предусмотренном настоящей главой. (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nИные налоги, сборы и страховые взносы уплачиваются организациями, применяющими упрощенную систему налогообложения, в соответствии с законодательством о налогах и сборах. (В редакции федеральных законов от 21.07.2005 № 101-ФЗ; от 30.11.2016 № 401-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nИные налоги, сборы и страховые взносы уплачиваются индивидуальными предпринимателями, применяющими упрощенную систему налогообложения, в соответствии с законодательством о налогах и сборах. (В редакции федеральных законов от 21.07.2005 № 101-ФЗ; от 30.11.2016 № 401-ФЗ)","article_title":"Статья 346.11. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77a3c04654c5491a9e743506615a470f751bdae140efd40b04c510707be6bebd"},{"code_id":"NK_RF_2","article_number":"346.12","version_date":"2000-07-31","article_text":"1. Налогоплательщиками признаются организации и индивидуальные предприниматели, перешедшие на упрощенную систему налогообложения и применяющие ее в порядке, установленном настоящей главой.\n\nУказанная в абзаце первом настоящего пункта величина предельного размера доходов организации, ограничивающая право организации перейти на упрощенную систему налогообложения, подлежит индексации на коэффициент-дефлятор, установленный на календарный год, предшествующий календарному году перехода организации на применение упрощенной системы налогообложения. (Дополнение абзацем - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции  федеральных законов от 25.06.2012 № 94-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nУказанные в пунктах 4 и 41 статьи 34613 настоящего Кодекса величины доходов налогоплательщика, а также указанная в подпункте 16 пункта 3 настоящей статьи величина остаточной стоимости основных средств подлежит индексации на коэффициент-дефлятор, установленный на календарный год отчетного (налогового) периода, в котором налогоплательщиком получены соответствующие доходы. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nУстановленное абзацем первым настоящего пункта ограничение по доходам не применяется в отношении организаций, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\", подающих уведомление о переходе на упрощенную систему налогообложения с 1 января 2015 года. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\n1) организации, имеющие филиалы; (В редакции Федерального закона от 06.04.2015 № 84-ФЗ)\n\n3) страховщики;\n\n4) негосударственные пенсионные фонды;\n\n5) инвестиционные фонды;\n\n6) профессиональные участники рынка ценных бумаг, за исключением инвестиционных советников, не являющихся кредитными организациями и не совмещающих деятельность по инвестиционному консультированию с иной профессиональной деятельностью на рынке ценных бумаг; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ);\n\n7) ломбарды;\n\n8) организации и индивидуальные предприниматели, производящие подакцизные товары (за исключением подакцизного винограда, вина, игристого вина, включая российское шампанское, виноматериалов, виноградного сусла, произведенных из винограда собственного производства, указанных в подпункте 23 пункта 1 статьи 181 настоящего Кодекса сахаросодержащих напитков), а также осуществляющие добычу и реализацию полезных ископаемых, за исключением общераспространенных полезных ископаемых; (В редакции  федеральных законов от 29.11.2021 № 382-ФЗ, от 21.11.2022 № 443-ФЗ)\n\n9) организации, осуществляющие деятельность по организации и проведению азартных игр; (В редакции Федерального закона от 23.07.2013 № 198-ФЗ)\n\n10) нотариусы, занимающиеся частной практикой, адвокаты, учредившие адвокатские кабинеты, а также иные формы адвокатских образований; (В редакции федеральных законов от 21.07.2005 № 101-ФЗ; от 27.07.2006 № 137-ФЗ)\n\n11) организации, являющиеся участниками соглашений о разделе продукции; (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n12) (Подпункт утратил силу - Федеральный закон от 07.07.2003 № 117-ФЗ)\n\n13) организации и индивидуальные предприниматели, перешедшие на систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) в соответствии с главой 261 настоящего Кодекса; (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\n14) организации, в которых доля участия других организаций составляет более 25 процентов. Данное ограничение не распространяется:\n\nна организации, уставный капитал которых полностью состоит из вкладов общественных организаций инвалидов, если среднесписочная численность инвалидов среди их работников составляет не менее 50 процентов, а их доля в фонде оплаты труда - не менее 25 процентов;\n\nна некоммерческие организации, в том числе организации потребительской кооперации, осуществляющие свою деятельность в соответствии с Законом Российской Федерации от 19 июня 1992 года № 3085-I \"О потребительской кооперации (потребительских обществах, их союзах) в Российской Федерации\", а также на хозяйственные общества, единственными учредителями которых являются потребительские общества и их союзы, осуществляющие свою деятельность в соответствии с указанным Законом;\n\nна учрежденные в соответствии с Федеральным законом от 23 августа 1996 года № 127-ФЗ \"О науке и государственной научно-технической политике\" бюджетными и автономными научными учреждениями хозяйственные общества и хозяйственные партнерства, деятельность которых заключается в практическом применении (внедрении) результатов интеллектуальной деятельности (программ для электронных вычислительных машин, баз данных, изобретений, полезных моделей, промышленных образцов, селекционных достижений,\n\nтопологий интегральных микросхем, секретов производства (ноу-хау), исключительные права на которые принадлежат указанным научным учреждениям (в том числе совместно с другими лицами); (В редакции Федерального закона от 02.04.2014 № 52-ФЗ)\n\nна учрежденные в соответствии с Федеральным законом от 29 декабря 2012 года № 273-ФЗ \"Об образовании в Российской Федерации\" образовательными организациями высшего образования, являющимися бюджетными и автономными учреждениями, хозяйственные общества и хозяйственные партнерства, деятельность которых заключается в практическом применении (внедрении) результатов интеллектуальной деятельности (программ для электронных вычислительных машин, баз данных, изобретений, полезных моделей, промышленных образцов, селекционных достижений, топологий интегральных микросхем, секретов производства (ноу-хау), исключительные права на которые принадлежат указанным образовательным организациям (в том числе совместно с другими лицами); (В редакции Федерального закона от 02.04.2014 № 52-ФЗ)\n\n(Подпункт в редакции Федерального закона от 27.11.2010 № 310-ФЗ)\n\n15) организации и индивидуальные предприниматели, средняя численность работников которых за налоговый (отчетный) период, определяемая в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным в области статистики, превышает 130 человек. (В редакции  федеральных законов от 29.06.2004 № 58-ФЗ, от 31.07.2020 № 266-ФЗ, от 23.11.2020 № 373-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nПоложения настоящего подпункта не применяются в отношении организаций потребительской кооперации, осуществляющих свою деятельность в соответствии с Законом Российской Федерации от 19 июня 1992 года № 3085-I \"О потребительской кооперации (потребительских обществах, их союзах) в Российской Федерации\", а также в отношении хозяйственных обществ, единственными учредителями которых являются потребительские общества и их союзы, осуществляющие свою деятельность в соответствии с указанным Законом; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n16) организации, у которых остаточная стоимость основных средств, определяемая в соответствии с законодательством Российской Федерации о бухгалтерском учете, превышает 200 млн. рублей. В целях настоящего подпункта учитываются основные средства, которые подлежат амортизации и признаются амортизируемым имуществом в соответствии с главой 25 настоящего Кодекса. (В редакции  федеральных законов от 21.07.2005 № 101-ФЗ, от 25.06.2012 № 94-ФЗ, от 03.07.2016 № 243-ФЗ, от 12.07.2024 № 176-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nВ целях настоящего подпункта не учитывается стоимость российского высокотехнологичного оборудования, перечень которого утверждается Правительством Российской Федерации; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Подпункт в редакции Федерального закона от 31.12.2002 № 191-ФЗ)\n\n17) казенные и бюджетные учреждения; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n18) иностранные организации; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n19) организации и индивидуальные предприниматели, не уведомившие о переходе на упрощенную систему налогообложения в сроки, установленные пунктами 1 и 2 статьи 34613 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\n20) микрофинансовые организации; (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 301-ФЗ)\n\n21) частные агентства занятости, осуществляющие деятельность по предоставлению труда работников (персонала); (Дополнение подпунктом - Федеральный закон от 05.05.2014 № 116-ФЗ)\n\n22) организации и индивидуальные предприниматели, осуществляющие производство ювелирных и других изделий из драгоценных металлов и (или) оптовую (розничную) торговлю ювелирными и другими изделиями из драгоценных металлов. (В редакции  Федерального закона от 23.03.2024 № 49-ФЗ)\n\nПоложения настоящего подпункта не применяются в отношении организаций и индивидуальных предпринимателей, осуществляющих производство ювелирных и других изделий из серебра и (или) оптовую (розничную) торговлю ювелирными и другими изделиями из серебра; (Дополнение абзацем - Федеральный закон от 23.03.2024 № 49-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 09.03.2022 № 47-ФЗ)\n\n23) организации и индивидуальные предприниматели, осуществляющие майнинг цифровой валюты. (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)","article_title":"Статья 346.12. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"843e4aa5b782481fcb96d56a79d340885e390ba9e079e57f2e681663fde0fc49"},{"code_id":"NK_RF_2","article_number":"346.13","version_date":"2000-07-31","article_text":"1. Организации и индивидуальные предприниматели, изъявившие желание перейти на упрощенную систему налогообложения со следующего календарного года, уведомляют об этом налоговый орган по месту нахождения организации или месту жительства индивидуального предпринимателя не позднее 31 декабря календарного года, предшествующего календарному году, начиная с которого они переходят на упрощенную систему налогообложения.\n\nВ уведомлении указывается выбранный объект налогообложения. Организации указывают в уведомлении также остаточную стоимость основных средств и размер доходов по состоянию на 1 октября года, предшествующего календарному году, начиная с которого они переходят на упрощенную систему налогообложения.\n\nНалогоплательщики - организации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\", в уведомлении о переходе на упрощенную систему налогообложения с 1 января 2015 года остаточную стоимость основных средств и размер доходов по состоянию на 1 октября 2014 года не указывают. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\n(Пункт в редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\nОрганизации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\", изъявившие желание перейти на упрощенную систему налогообложения с 1 января 2015 года, вправе уведомить об этом налоговый орган не позднее 1 февраля 2015 года. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\nОрганизации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\" с учетом части 4 статьи 121 Федерального конституционного закона от 21 марта 2014 года № 6-ФКЗ \"О принятии в Российскую Федерацию Республики Крым и образовании в составе Российской Федерации новых субъектов - Республики Крым и города федерального значения Севастополя\", вправе уведомить об этом налоговый орган не позднее 1 апреля 2015 года. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Пункт в редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\nВ случае, если налогоплательщик применяет одновременно упрощенную систему налогообложения и патентную систему налогообложения, при определении величины доходов, указанной в абзаце первом настоящего пункта, учитываются доходы по обоим указанным специальным налоговым режимам. (Дополнение абзацем - Федеральный закон от 25.06.2012 № 94-ФЗ) (В редакции Федерального закона от 31.07.2020 № 266-ФЗ)\n\nПри этом суммы налогов, подлежащих уплате при использовании иного режима налогообложения, исчисляются и уплачиваются в порядке, предусмотренном законодательством о налогах и сборах для вновь созданных организаций или вновь зарегистрированных индивидуальных предпринимателей. Указанные в настоящем абзаце налогоплательщики не уплачивают пени и штрафы за несвоевременную уплату ежемесячных платежей в течение того месяца, в котором эти налогоплательщики перешли на иной режим налогообложения. (В редакции  федеральных законов от 31.12.2002 № 191-ФЗ, от 21.07.2005 № 101-ФЗ, от 31.07.2020 № 266-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 21.07.2005 № 101-ФЗ) (Утратил силу  - Федеральный закон от 12.07.2024 № 176-ФЗ)","article_title":"Статья 346.13. Порядок и условия начала и прекращения применения упрощенной системы налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"52529c820e4006a86bdc114a20a2bda5535a6191c8059050ce94649b28aa8819"},{"code_id":"NK_RF_2","article_number":"346.14","version_date":"2000-07-31","article_text":"1. Объектом налогообложения признаются:\n\nдоходы, уменьшенные на величину расходов.","article_title":"Статья 346.14. Объекты налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cbd4ffe1edbacf8dc6b66ed4656d1ec4e307fb6b45d3252f8b8884ccb60f3de"},{"code_id":"NK_RF_2","article_number":"346.15","version_date":"2000-07-31","article_text":"11. При определении объекта налогообложения не учитываются:\n\n1) доходы, указанные в статье 251 настоящего Кодекса;\n\n2) доходы организации, облагаемые налогом на прибыль организаций по налоговым ставкам, предусмотренным пунктами 16, 3 и 4 статьи 284 настоящего Кодекса, в порядке, установленном главой 25 настоящего Кодекса; (В редакции Федерального закона от 24.11.2014 № 376-ФЗ)\n\n3) доходы индивидуального предпринимателя, облагаемые налогом на доходы физических лиц в виде дивидендов, а также доходы индивидуального предпринимателя, облагаемые налогом на доходы физических лиц по налоговым ставкам, предусмотренным пунктами 2 и 5 статьи 224 настоящего Кодекса, в порядке, установленном главой 23 настоящего Кодекса; (В редакции  Федерального закона от 25.02.2022 № 18-ФЗ)\n\n4) доходы, полученные товариществами собственников недвижимости, в том числе товариществами собственников жилья, управляющими организациями, жилищными или иными специализированными потребительскими кооперативами в оплату оказанных собственникам (пользователям) недвижимости коммунальных услуг, в случае оказания таких услуг указанными организациями, заключившими договоры ресурсоснабжения (договоры на оказание услуг по обращению с твердыми коммунальными отходами) с ресурсоснабжающими организациями (региональными операторами по обращению с твердыми коммунальными отходами) в соответствии с требованиями, установленными законодательством Российской Федерации; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n5) доходы в виде сумм возмещения в связи с изъятием земельных участков для государственных и муниципальных нужд собственникам этих земельных участков, землепользователям, землевладельцам и арендаторам этих земельных участков, а также правообладателям расположенных на этих земельных участках объектов недвижимости. (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 22.07.2008 № 155-ФЗ)","article_title":"Статья 346.15. Порядок определения доходов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4d6192cb19f095ced1643221afe92742f0535f13ee982b75fdbbb0ca6ab7ead"},{"code_id":"NK_RF_2","article_number":"346.16","version_date":"2000-07-31","article_text":"1. При определении объекта налогообложения налогоплательщик уменьшает полученные доходы на следующие расходы:\n\n1) расходы на приобретение, сооружение и изготовление основных средств, а также на достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств (с учетом положений пунктов 3 и 4 настоящей статьи); (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n2) расходы на приобретение нематериальных активов, а также создание нематериальных активов самим налогоплательщиком (с учетом положений пунктов 3 и 4 настоящей статьи); (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n21) расходы на приобретение исключительных прав на изобретения, полезные модели, промышленные образцы, программы для электронных вычислительных машин, базы данных, топологии интегральных микросхем, секреты производства (ноу-хау), а также прав на использование указанных результатов интеллектуальной деятельности на основании лицензионного договора; (Дополнение подпунктом - Федеральный закон от 19.07.2007 № 195-ФЗ)\n\n22) расходы на патентование и (или) оплату правовых услуг по получению правовой охраны результатов интеллектуальной деятельности, включая средства индивидуализации; (Дополнение подпунктом - Федеральный закон от 19.07.2007 № 195-ФЗ)\n\n23) расходы на научные исследования и (или) опытно-конструкторские разработки, признаваемые таковыми в соответствии со статьей 262 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 19.07.2007 № 195-ФЗ) (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\n3) расходы на ремонт основных средств (в том числе арендованных);\n\n4) арендные (в том числе лизинговые) платежи за арендуемое (в том числе принятое в лизинг) имущество; (В редакции Федерального закона от 31.12.2002 № 191-ФЗ)\n\n5) материальные расходы;\n\n6) расходы на оплату труда, выплату пособий по временной нетрудоспособности в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 31.12.2002 № 190-ФЗ)\n\n7) расходы на все виды обязательного страхования работников, имущества и ответственности, включая страховые взносы на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний, производимые в соответствии с законодательством Российской Федерации; (В редакции федеральных законов от 17.05.2007 № 85-ФЗ; от 22.07.2008 № 155-ФЗ; от 24.07.2009 № 213-ФЗ)\n\n8) суммы налога на добавленную стоимость по оплаченным товарам (работам, услугам), приобретенным налогоплательщиком и подлежащим включению в состав расходов в соответствии с настоящей статьей и статьей 34617 настоящего Кодекса; (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n9) проценты, уплачиваемые за предоставление в пользование денежных средств (кредитов, займов), а также расходы, связанные с оплатой услуг, оказываемых кредитными организациями, в том числе связанные с продажей иностранной валюты при взыскании задолженности  за счет имущества налогоплательщика в порядке, предусмотренном статьей 46 настоящего Кодекса; (В редакции  федеральных законов от 27.07.2006 № 137-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n10) расходы на обеспечение пожарной безопасности налогоплательщика в соответствии с законодательством Российской Федерации, расходы на услуги по охране имущества, обслуживанию охранно-пожарной сигнализации, расходы на приобретение услуг пожарной охраны и иных услуг охранной деятельности;\n\n11) суммы таможенных платежей, уплаченные при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, и не подлежащие возврату налогоплательщику в соответствии с таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле; (В редакции федеральных законов от 31.12.2002 № 191-ФЗ; от 27.11.2010 № 306\n\n12) расходы на содержание служебного транспорта, а также расходы на компенсацию за использование для служебных поездок личных легковых автомобилей и мотоциклов в пределах норм, установленных Правительством Российской Федерации;\n\n13) расходы на командировки, в частности на:\n\nпроезд работника к месту командировки и обратно к месту постоянной работы;\n\nнаем жилого помещения. По этой статье расходов подлежат возмещению также расходы работника на оплату дополнительных услуг, оказываемых в гостиницах (за исключением расходов на обслуживание в барах и ресторанах, расходов на обслуживание в номере, расходов за пользование рекреационно-оздоровительными объектами);\n\nсуточные или полевое довольствие; (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\nоформление и выдачу виз, паспортов, ваучеров, приглашений и иных аналогичных документов;\n\nконсульские, аэродромные сборы, сборы за право въезда, прохода, транзита автомобильного и иного транспорта, за пользование морскими каналами, другими подобными сооружениями и иные аналогичные платежи и сборы;\n\n14) плату государственному и (или) частному нотариусу за нотариальное оформление документов. При этом такие расходы принимаются в пределах тарифов, утвержденных в установленном порядке;\n\n15) расходы на бухгалтерские, аудиторские и юридические услуги; (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n16) расходы на публикацию бухгалтерской (финансовой) отчетности, а также на публикацию и иное раскрытие другой информации, если законодательством Российской Федерации на налогоплательщика возложена обязанность осуществлять их публикацию (раскрытие); (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n17) расходы на канцелярские товары;\n\n18) расходы на почтовые, телефонные, телеграфные и другие подобные услуги, расходы на оплату услуг связи;\n\n19) расходы, связанные с приобретением права на использование программ для ЭВМ и баз данных по договорам с правообладателем (по лицензионным соглашениям). К указанным расходам относятся также расходы на обновление программ для ЭВМ и баз данных;\n\n20) расходы на рекламу производимых (приобретенных) и (или) реализуемых товаров (работ, услуг), товарного знака и знака обслуживания;\n\n21) расходы на подготовку и освоение новых производств, цехов и агрегатов;\n\n22) суммы налогов и сборов, уплаченные в соответствии с законодательством о налогах и сборах, за исключением налога, уплаченного в соответствии с настоящей главой, налога на добавленную стоимость, уплаченного в бюджет в соответствии с пунктом 5 статьи 173 настоящего Кодекса, а также суммы туристического налога; (Дополнение подпунктом - Федеральный закон от 31.12.2002 № 191-ФЗ) (В редакции  федеральных законов от 06.04.2015 № 84-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n23) расходы по оплате стоимости товаров, приобретенных для дальнейшей реализации (уменьшенные на величину расходов, указанных в подпункте 8 настоящего пункта), а также расходы, связанные с приобретением и реализацией указанных товаров, в том числе расходы по хранению, обслуживанию и транспортировке товаров; (Дополнение подпунктом - Федеральный закон от 31.12.2002 № 191-ФЗ) (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n231) расходы в виде стоимости имущества (включая денежные средства), предназначенного для использования в целях предупреждения и предотвращения распространения, а также диагностики и лечения новой коронавирусной инфекции, безвозмездно переданного медицинским организациям, являющимся некоммерческими организациями, органам государственной власти и управления и (или) органам местного самоуправления, государственным и муниципальным учреждениям, государственным и муниципальным унитарным предприятиям; (Дополнение подпунктом - Федеральный закон от 08.06.2020 № 172-ФЗ)\n\n24) расходы на выплату комиссионных, агентских вознаграждений и вознаграждений по договорам поручения; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n25) расходы на оказание услуг по гарантийному ремонту и обслуживанию; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n26) расходы на подтверждение соответствия продукции или иных объектов, процессов производства, эксплуатации, хранения, перевозки, реализации и утилизации, выполнения работ или оказания услуг требованиям технических регламентов, положениям стандартов или условиям договоров; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n27) расходы на проведение (в случаях, установленных законодательством Российской Федерации) обязательной оценки в целях контроля за правильностью уплаты налогов в случае возникновения спора об исчислении налоговой базы; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n28) плата за предоставление информации о зарегистрированных правах; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n29) расходы на оплату услуг специализированных организаций по изготовлению документов кадастрового и технического учета (инвентаризации) объектов недвижимости (в том числе правоустанавливающих документов на земельные участки и документов о межевании земельных участков); (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n30) расходы на оплату услуг специализированных организаций по проведению экспертизы, обследований, выдаче заключений и предоставлению иных документов, наличие которых обязательно для получения лицензии (разрешения) на осуществление конкретного вида деятельности; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n31) судебные расходы и арбитражные сборы; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n32) периодические (текущие) платежи за пользование правами на результаты интеллектуальной деятельности и правами на средства индивидуализации (в частности, правами, возникающими из патентов на изобретения, полезные модели, промышленные образцы); (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции Федерального закона от 23.11.2015 № 322-ФЗ)\n\n321) вступительные, членские и целевые взносы, уплачиваемые в соответствии с Федеральным законом от 1 декабря 2007 года № 315-ФЗ \"О саморегулируемых организациях\"; (Дополнение подпунктом - Федеральный закон от 28.12.2010 № 395-ФЗ)\n\n33) расходы на проведение независимой оценки квалификации на соответствие требованиям к квалификации, подготовку и переподготовку кадров, состоящих в штате налогоплательщика, на договорной основе в порядке, предусмотренном пунктом 3 статьи 264 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции Федерального закона от 03.07.2016 № 251-ФЗ)\n\n34) (Дополнение подпунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (Утратил силу - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\n35) расходы на обслуживание контрольно-кассовой техники; (Дополнение подпунктом - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\n36) расходы по вывозу твердых бытовых отходов; (Дополнение подпунктом - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\n37) сумму платы в счет возмещения вреда, причиняемого автомобильным дорогам общего пользования федерального значения транспортными средствами, имеющими разрешенную максимальную массу свыше 12 тонн, зарегистрированными в реестре транспортных средств системы взимания платы.\n\nФактически уплаченная в течение налогового периода сумма платы, указанной в абзаце первом настоящего подпункта, учитывается налогоплательщиками в расходах при исчислении налога за налоговый период в размере превышения фактически уплаченной суммы платы над суммой транспортного налога, исчисленной за налоговый период в соответствии с главой 28 настоящего Кодекса в отношении транспортных средств, имеющих разрешенную максимальную массу свыше 12 тонн, зарегистрированных в реестре транспортных средств системы взимания платы.\n\nПри исчислении авансовых платежей по налогу за отчетные периоды налогоплательщики учитывают в расходах фактически уплаченную сумму платы за отчетный период, уменьшенную на сумму авансовых платежей по транспортному налогу, исчисленную за отчетный период в соответствии с главой 28 настоящего Кодекса в отношении транспортных средств, имеющих разрешенную максимальную массу свыше 12 тонн, зарегистрированных в реестре транспортных средств системы взимания платы;\n\n(Дополнение подпунктом - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\n38) обязательные отчисления (взносы) застройщиков в компенсационный фонд, формируемый в соответствии с Федеральным законом от 29 июля 2017 года № 218-ФЗ \"О публично-правовой компании \"Фонд развития территорий\" и о внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 342-ФЗ) (В редакции  Федерального закона от 28.06.2022 № 211-ФЗ)\n\n39) расходы на дезинфекцию помещений и приобретение приборов, лабораторного оборудования, спецодежды и других средств индивидуальной и коллективной защиты для выполнения санитарно-эпидемиологических и гигиенических требований органов государственной власти и органов местного самоуправления, их должностных лиц в связи с распространением новой коронавирусной инфекции; (Дополнение подпунктом - Федеральный закон от 22.04.2020 № 121-ФЗ)\n\n40) расходы на обеспечение мер по технике безопасности, предусмотренных нормативными правовыми актами Российской Федерации, и расходы, связанные с содержанием помещений и инвентаря здравпунктов, находящихся непосредственно на территории организации; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n41) расходы на приобретение медицинских изделий для диагностики (лечения) новой короновирусной инфекции по перечню, утверждаемому Правительством Российской Федерации, а также на сооружение, изготовление, доставку и доведение указанных медицинских изделий до состояния, в котором они пригодны для использования; (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n42) выплаты работнику в виде безотчетных сумм, право на выплаты которых установлено актом Президента Российской Федерации и (или) актом Правительства Российской Федерации, в целях возмещения его дополнительных расходов, связанных с командированием на территории, нуждающиеся в обеспечении жизнедеятельности населения и восстановлении объектов инфраструктуры, в размерах, определенных локальными нормативными актами работодателя, но не более 700 рублей за каждый день нахождения в такой командировке; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n43) расходы в виде безвозмездно переданных денежных средств и (или) иного имущества, указанных в пункте 93 статьи 217 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n44) расходы в виде стоимости имущества (за исключением денежных средств), работ, услуг, безвозмездно переданных являющимся казенными учреждениями воинским частям и организациям Вооруженных Сил Российской Федерации, войск национальной гвардии Российской Федерации, органов федеральной службы безопасности, при условии, что данные имущество, работы, услуги переданы в целях их использования указанными воинскими частями и организациями в ходе специальной военной операции. Факт получения указанными воинской частью или организацией данного имущества (результатов выполненных работ, оказанных услуг) и цели его (их) использования подтверждаются документом, подписанным командиром (руководителем) указанных воинской части или организации либо уполномоченным им лицом. (Дополнение подпунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\n2. Расходы, указанные в пункте 1 настоящей статьи, принимаются при условии их соответствия критериям, указанным в пункте 1 статьи 252 настоящего Кодекса.\n\nРасходы, указанные в подпунктах 5, 6, 7, 9 - 21, 38 пункта 1 настоящей статьи, принимаются в порядке, предусмотренном для исчисления налога на прибыль организаций статьями 254, 255, 263, 264, 265 и 269 настоящего Кодекса. (В редакции федеральных законов от 31.12.2002 № 191-ФЗ; от 21.07.2005 № 101-ФЗ; от 17.05.2007 № 85-ФЗ; от 27.11.2017 № 342-ФЗ)\n\n1) в отношении расходов на приобретение (сооружение, изготовление) основных средств в период применения упрощенной системы налогообложения, а также расходов на достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств, произведенных в указанном периоде, - с момента ввода этих основных средств в эксплуатацию; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n2) в отношении приобретенных (созданных самим налогоплательщиком) нематериальных активов в период применения упрощенной системы налогообложения - с момента принятия этих нематериальных активов на бухгалтерский учет; (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\n3) в отношении приобретенных (сооруженных, изготовленных) основных средств, а также приобретенных (созданных самим налогоплательщиком) нематериальных активов до перехода на упрощенную систему налогообложения стоимость основных средств и нематериальных активов включается в расходы в следующем порядке:\n\nв отношении основных средств и нематериальных активов со сроком полезного использования до трех лет включительно - в течение первого календарного года применения упрощенной системы налогообложения; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nв отношении основных средств и нематериальных активов со сроком полезного использования от трех до 15 лет включительно в течение первого календарного года применения упрощенной системы налогообложения - 50 процентов стоимости, второго календарного года - 30 процентов стоимости и третьего календарного года - 20 процентов стоимости; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nв отношении основных средств и нематериальных активов со сроком полезного использования свыше 15 лет - в течение первых 10 лет применения упрощенной системы налогообложения равными долями стоимости основных средств. (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nПри этом в течение налогового периода расходы принимаются за отчетные периоды равными долями.\n\nВ случае, если налогоплательщик применяет упрощенную систему налогообложения с момента постановки на учет в налоговых органах, стоимость основных средств и нематериальных активов принимается по первоначальной стоимости этого имущества, определяемой в порядке, установленном законодательством о бухгалтерском учете.\n\nВ случае, если налогоплательщик перешел на упрощенную систему налогообложения с иных режимов налогообложения, стоимость основных средств и нематериальных активов учитывается в порядке, установленном пунктами 21 и 4 статьи 34625 настоящего Кодекса.\n\nОпределение сроков полезного использования основных средств осуществляется на основании утверждаемой Правительством Российской Федерации в соответствии со статьей 258 настоящего Кодекса классификации основных средств, включаемых в амортизационные группы. Сроки полезного использования основных средств, которые не указаны в данной классификации, устанавливаются налогоплательщиком в соответствии с техническими условиями или рекомендациями организаций-изготовителей.\n\nАбзац. (Утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nОпределение сроков полезного использования нематериальных активов осуществляется в соответствии с пунктом 2 статьи 258 настоящего Кодекса.\n\nВ случае реализации (передачи) приобретенных (сооруженных, изготовленных, созданных самим налогоплательщиком) основных средств и нематериальных активов до истечения трех лет с момента учета расходов на их приобретение (сооружение, изготовление, достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение, а также создание самим налогоплательщиком) в составе расходов в соответствии с настоящей главой (в отношении основных средств и нематериальных активов со сроком полезного использования свыше 15 лет - до истечения 10 лет с момента их приобретения (сооружения, изготовления, создания самим налогоплательщиком) налогоплательщик обязан пересчитать налоговую базу за весь период пользования такими основными средствами и нематериальными активами с момента их учета в составе расходов на приобретение (сооружение, изготовление, достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение, а также создание самим налогоплательщиком) до даты реализации (передачи) с учетом положений главы 25 настоящего Кодекса и уплатить дополнительную сумму налога и пени. (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n(Пункт в редакции Федерального закона от 21.07.2005 № 101-ФЗ)","article_title":"Статья 346.16. Порядок определения расходов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7db59102d18f146a90df3fb6a46e77e0121c05216dd19cfb9d246599643369f"},{"code_id":"NK_RF_2","article_number":"346.17","version_date":"2000-07-31","article_text":"При использовании покупателем в расчетах за приобретенные им товары (работы, услуги), имущественные права векселя датой получения доходов у налогоплательщика признается дата оплаты векселя (день поступления денежных средств от векселедателя либо иного обязанного по указанному векселю лица) или день передачи налогоплательщиком указанного векселя по индоссаменту третьему лицу.\n\nВ случае возврата налогоплательщиком сумм, ранее полученных в счет предварительной оплаты поставки товаров, выполнения работ, оказания услуг, передачи имущественных прав, на сумму возврата уменьшаются доходы того налогового (отчетного) периода, в котором произведен возврат. (Дополнение абзацем - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\nСуммы выплат, полученные на содействие самозанятости безработных граждан и стимулирование создания безработными гражданами, открывшими собственное дело, дополнительных рабочих мест для трудоустройства безработных граждан за счет средств бюджетов бюджетной системы Российской Федерации в соответствии с программами, утверждаемыми соответствующими органами государственной власти, учитываются в составе доходов в течение трех налоговых периодов с одновременным отражением соответствующих сумм в составе расходов в пределах фактически осуществленных расходов каждого налогового периода, предусмотренных условиями получения указанных сумм выплат. (Дополнение абзацем - Федеральный закон от 05.04.2010 № 41-ФЗ)\n\nВ случае нарушения условий получения выплат, предусмотренных абзацем четвертым настоящего пункта, суммы полученных выплат в полном объеме отражаются в составе доходов налогового периода, в котором допущено нарушение. Если по окончании третьего налогового периода сумма полученных выплат, указанных в абзаце четвертом настоящего пункта, превышает сумму расходов, учтенных в соответствии с настоящим пунктом, оставшиеся неучтенные суммы в полном объеме отражаются в составе доходов этого налогового периода.\n\n(Дополнение абзацем - Федеральный закон от 05.04.2010 № 41-ФЗ)\n\nСредства финансовой поддержки в виде субсидий, полученные в соответствии с Федеральным законом \"О развитии малого и среднего предпринимательства в Российской Федерации\", отражаются в составе доходов пропорционально расходам, фактически осуществленным за счет этого источника, но не более двух налоговых периодов с даты получения. Если по окончании второго налогового периода сумма полученных средств финансовой поддержки, указанных в настоящем пункте, превысит сумму признанных расходов, фактически осуществленных за счет этого источника, разница между указанными суммами в полном объеме отражается в составе доходов этого налогового периода. (Дополнение абзацем - Федеральный закон от 07.03.2011 № 23-ФЗ)\n\nПорядок признания доходов, предусмотренный абзацами четвертым - шестым настоящего пункта, применяется налогоплательщиками, применяющими в качестве объекта налогообложения доходы, уменьшенные на величину расходов, а также налогоплательщиками, применяющими в качестве объекта налогообложения доходы, при условии ведения ими учета сумм выплат (средств), указанных в абзацах четвертом - шестом настоящего пункта. (Дополнение абзацем - Федеральный закон от 07.03.2011 № 23-ФЗ)\n\nСредства финансовой поддержки, полученные за счет средств бюджетов бюджетной системы Российской Федерации по сертификату на привлечение трудовых ресурсов в субъекты Российской Федерации, включенные в перечень субъектов Российской Федерации, привлечение трудовых ресурсов в которые является приоритетным, в соответствии с Законом Российской Федерации от 19 апреля 1991 года № 1032-I \"О занятости населения в Российской Федерации\", учитываются в составе доходов в течение трех налоговых периодов с одновременным отражением соответствующих сумм в составе расходов в пределах фактически осуществленных расходов каждого налогового периода, предусмотренных условиями получения указанных средств финансовой поддержки. (Дополнение абзацем - Федеральный закон от 29.12.2014 № 465-ФЗ)\n\nВ случае нарушения условий получения средств финансовой поддержки, предусмотренных абзацем восьмым настоящего пункта, сумма полученной финансовой поддержки в полном объеме отражается в составе доходов налогового периода, в котором допущено нарушение. Если по окончании третьего налогового периода сумма полученных средств финансовой поддержки, указанных в абзаце восьмом настоящего пункта, превышает сумму расходов, учтенных в соответствии с настоящим пунктом, оставшиеся неучтенные суммы в полном объеме отражаются в составе доходов этого налогового периода. (Дополнение абзацем - Федеральный закон от 29.12.2014 № 465-ФЗ)\n\nПоложения абзаца шестого настоящего пункта применяются как при расходовании средств субсидий после их получения, так и в целях возмещения расходов налогоплательщика, произведенных в налоговом периоде до получения средств субсидий в этом же налоговом периоде. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n1) материальные расходы (в том числе расходы по приобретению сырья и материалов), а также расходы на оплату труда - в момент погашения задолженности путем списания денежных средств с расчетного счета, счета цифрового рубля налогоплательщика, выплаты из кассы, а при ином способе погашения задолженности - в момент такого погашения. Аналогичный порядок применяется в отношении оплаты процентов за пользование заемными средствами (включая банковские кредиты) и при оплате услуг третьих лиц. (В редакции  федеральных законов от 17.05.2007 № 85-ФЗ, от 22.07.2008 № 155-ФЗ, от 29.09.2019 № 325-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nТоварищества собственников недвижимости, в том числе товарищества собственников жилья, управляющие организации, жилищные или иные специализированные потребительские кооперативы, заключившие договоры ресурсоснабжения (договоры на оказание услуг по обращению с твердыми коммунальными отходами) с ресурсоснабжающими организациями (региональными операторами по обращению с твердыми коммунальными отходами) в соответствии с требованиями, установленными законодательством Российской Федерации, не учитывают при исчислении налога в составе материальных расходов средства, перечисленные в оплату коммунальных услуг, в случае, если такие средства получены указанными организациями от собственников (пользователей) недвижимости в оплату оказанных им коммунальных услуг и не учитывались при определении объекта налогообложения в соответствии с подпунктом 4 пункта 11 статьи 34615 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n2) расходы по оплате стоимости товаров, приобретенных для дальнейшей реализации, - по мере реализации указанных товаров. Налогоплательщик вправе для целей налогообложения использовать один из следующих методов оценки покупных товаров:\n\nпо стоимости первых по времени приобретения (ФИФО);\n\nабзац; (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nпо средней стоимости;\n\nпо стоимости единицы товара.\n\nРасходы, непосредственно связанные с реализацией указанных товаров, в том числе расходы по хранению, обслуживанию и транспортировке, учитываются в составе расходов после их фактической оплаты. (В редакции  Федерального закона от 29.11.2024 № 418-ФЗ)\n\nСтоимость цифровой валюты определяется исходя из цены приобретения в порядке, предусмотренном абзацем вторым пункта 3 статьи 2823 настоящего Кодекса, но не выше дохода, полученного от ее реализации. При получении цифровой валюты налогоплательщиком без несения соответствующих расходов на ее приобретение стоимость такой цифровой валюты определяется в размере дохода исходя из рыночной котировки такой цифровой валюты на дату ее получения. При этом убытки, полученные от реализации цифровой валюты, не учитываются; (Дополнение абзацем - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n21) налогоплательщики - организации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\", перешедшие на упрощенную систему налогообложения с объектом налогообложения в виде доходов, уменьшенных на величину расходов, предусмотренную настоящей главой, вправе учитывать расходы по оплате стоимости товаров, приобретенных ими для дальнейшей реализации в период осуществления деятельности до даты внесения указанных сведений, после проведения инвентаризации, осуществляемой в порядке, действовавшем до 1 января 2015 года, при определении налоговой базы по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, по мере реализации указанных товаров в соответствии с подпунктом 2 настоящего пункта. При этом такие расходы могут быть учтены при определении налоговой базы по налогу, подлежащему уплате в связи с применением упрощенной системы налогообложения, только в случае, если они не были учтены при исчислении налога, подлежащего уплате при осуществлении предпринимательской деятельности до даты внесения сведений о таких налогоплательщиках в единый государственный реестр юридических лиц на основании Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\" и статьи 1202 части третьей Гражданского кодекса Российской Федерации; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\n3) расходы на уплату налогов, сборов и страховых взносов - в размере, фактически уплаченном налогоплательщиком при самостоятельном исполнении обязанности по уплате налогов, сборов и страховых взносов либо при погашении задолженности перед иным лицом, возникшей вследствие уплаты этим лицом в соответствии с настоящим Кодексом за налогоплательщика сумм налогов, сборов и страховых взносов. При наличии задолженности по уплате налогов, сборов и страховых взносов расходы на ее погашение учитываются в составе расходов в пределах фактически погашенной задолженности в те отчетные (налоговые) периоды, когда налогоплательщик погашает указанную задолженность либо задолженность перед иным лицом, возникшую вследствие уплаты этим лицом в соответствии с настоящим Кодексом за налогоплательщика сумм налогов, сборов и страховых взносов, если иное не предусмотрено настоящим подпунктом. (В редакции Федерального закона  от 08.08.2024 № 259-ФЗ)\n\nИндивидуальные предприниматели, выбравшие в качестве объекта налогообложения доходы, уменьшенные на величину расходов, учитывают в составе расходов сумму страховых взносов на обязательное пенсионное страхование и на обязательное медицинское страхование, подлежащую уплате в данном налоговом периоде в соответствии со статьей 430 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nСтраховые взносы, указанные в абзаце втором настоящего подпункта, считаются подлежащими уплате в данном налоговом периоде в том числе в случае, если срок уплаты таких страховых взносов приходится в соответствии с пунктом 7 статьи 61 настоящего Кодекса на первый рабочий день следующего года.  (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nСуммы страховых взносов, определяемые в соответствии со статьей 430 настоящего Кодекса, уплаченные после 31 декабря 2024 года за расчетные периоды, предшествующие 2025 году, учитываются в расходах при определении за налоговые (отчетные) периоды 2025 - 2027 годов налоговой базы по налогу, подлежащему уплате в связи с применением упрощенной системы налогообложения; (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Подпункт в редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n4) расходы на приобретение (сооружение, изготовление) основных средств, достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств, а также расходы на приобретение (создание самим налогоплательщиком) нематериальных активов, учитываемые в порядке, предусмотренном пунктом 3 статьи 34616 настоящего Кодекса, отражаются в последнее число отчетного (налогового) периода в размере уплаченных сумм. При этом указанные расходы учитываются только по основным средствам и нематериальным активам, используемым при осуществлении предпринимательской деятельности; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n5) при выдаче налогоплательщиком продавцу в оплату приобретаемых товаров (работ, услуг) и (или) имущественных прав векселя расходы по приобретению указанных товаров (работ, услуг) и (или) имущественных прав учитываются после оплаты указанного векселя. При передаче налогоплательщиком продавцу в оплату приобретаемых товаров (работ, услуг) и (или) имущественных прав векселя, выданного третьим лицом, расходы по приобретению указанных товаров (работ, услуг) и (или) имущественных прав учитываются на дату передачи указанного векселя за приобретаемые товары (работы, услуги) и (или) имущественные права. Указанные в настоящем подпункте расходы учитываются исходя из цены договора, но не более суммы долгового обязательства, указанной в векселе.\n\n(Статья в редакции Федерального закона от 21.07.2005 № 101-ФЗ)","article_title":"Статья 346.17. Порядок признания доходов и расходов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"148537482edbb1fe35d69b336721c96286f37e6d18cf5cee4fc045282bebbd78"},{"code_id":"NK_RF_2","article_number":"346.18","version_date":"2000-07-31","article_text":"1. В случае, если объектом налогообложения являются доходы организации или индивидуального предпринимателя, налоговой базой признается денежное выражение доходов организации или индивидуального предпринимателя.\n\n2. В случае, если объектом налогообложения являются доходы организации или индивидуального предпринимателя, уменьшенные на величину расходов, налоговой базой признается денежное выражение доходов, уменьшенных на величину расходов.\n\nЕсли по итогам отчетного (налогового) периода сумма расходов превышает сумму доходов, то применительно к этому отчетному (налоговому) периоду налоговая база принимается равной нулю. (Дополнение абзацем - Федеральный закон от 31.07.2020 № 266-ФЗ)\n\nСумма минимального налога исчисляется за налоговый период в размере 1 процента налоговой базы, которой являются доходы, определяемые в соответствии со статьей 34615 настоящего Кодекса. (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\nМинимальный налог уплачивается в случае, если за налоговый период сумма исчисленного в общем порядке налога меньше суммы исчисленного минимального налога. (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\nНалогоплательщик имеет право в следующие налоговые периоды включить сумму разницы между суммой уплаченного минимального налога и суммой налога, исчисленной в общем порядке, в расходы при исчислении налоговой базы, в том числе увеличить сумму убытков, которые могут быть перенесены на будущее в соответствии с положениями пункта 7 настоящей статьи.\n\nНалогоплательщик вправе осуществлять перенос убытка на будущие налоговые периоды в течение 10 лет, следующих за тем налоговым периодом, в котором получен этот убыток.\n\nНалогоплательщик вправе перенести на текущий налоговый период сумму полученного в предыдущем налоговом периоде убытка.\n\nУбыток, не перенесенный на следующий год, может быть перенесен целиком или частично на любой год из последующих девяти лет.\n\nЕсли налогоплательщик получил убытки более чем в одном налоговом периоде, перенос таких убытков на будущие налоговые периоды производится в той очередности, в которой они получены.\n\nВ случае прекращения налогоплательщиком деятельности по причине реорганизации налогоплательщик-правопреемник вправе уменьшать налоговую базу в порядке и на условиях, которые предусмотрены настоящим пунктом, на сумму убытков, полученных реорганизуемыми организациями до момента реорганизации.\n\nНалогоплательщик обязан хранить документы, подтверждающие объем понесенного убытка и сумму, на которую была уменьшена налоговая база по каждому налоговому периоду, в течение всего срока использования права на уменьшение налоговой базы на сумму убытка.\n\nУбыток, полученный налогоплательщиком при применении иных режимов налогообложения, не принимается при переходе на упрощенную систему налогообложения.\n\nУбыток, полученный налогоплательщиком при применении упрощенной системы налогообложения, не принимается при переходе на иные режимы налогообложения.\n\n(Пункт в редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\nДоходы и расходы по видам деятельности, в отношении которых применяется патентная система налогообложения в соответствии с главой 265 настоящего Кодекса (с учетом положений, установленных настоящей главой), не учитываются при исчислении налоговой базы по налогу, уплачиваемому при применении упрощенной системы налогообложения. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)","article_title":"Статья 346.18. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"413979ef1d09c06c7b55957b89481afd8841793709415e838590c57f2fe37661"},{"code_id":"NK_RF_2","article_number":"346.19","version_date":"2000-07-31","article_text":"1. Налоговым периодом признается календарный год.\n\n2. Отчетными периодами признаются первый квартал, полугодие и девять месяцев календарного года.","article_title":"Статья 346.19. Налоговый период. Отчетный период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ec400542d1e5a2a9e6c12d64c9e6918490ae54734f9fef918646c95233f8bf2"},{"code_id":"NK_RF_2","article_number":"346.2","version_date":"2000-07-31","article_text":"1. Налогоплательщиками единого сельскохозяйственного налога (далее в настоящей главе - налогоплательщики) признаются организации и индивидуальные предприниматели, являющиеся сельскохозяйственными товаропроизводителями и перешедшие на уплату единого сельскохозяйственного налога в порядке, установленном настоящей главой.\n\n2. В целях настоящей главы сельскохозяйственными товаропроизводителями признаются:\n\n1) организации и индивидуальные предприниматели, производящие сельскохозяйственную продукцию, осуществляющие ее первичную и последующую (промышленную) переработку (в том числе на арендованных основных средствах) и реализующие эту продукцию, при условии, что в общем доходе от реализации товаров (работ, услуг) таких организаций и индивидуальных предпринимателей доля дохода от реализации произведенной ими сельскохозяйственной продукции, включая продукцию ее первичной переработки, произведенную ими из сельскохозяйственного сырья собственного производства, а также от оказания сельскохозяйственным товаропроизводителям услуг, указанных в подпункте 2 настоящего пункта, составляет не менее 70 процентов;\n\n2) организации и индивидуальные предприниматели, оказывающие услуги сельскохозяйственным товаропроизводителям, признаваемым таковыми в целях настоящей главы, которые относятся в соответствии с Общероссийским классификатором видов экономической деятельности к вспомогательной деятельности в области производства сельскохозяйственных культур и послеуборочной обработки сельскохозяйственной продукции, в том числе:\n\nуслуги в области растениеводства в части подготовки полей, посева сельскохозяйственных культур, возделывания и выращивания сельскохозяйственных культур, опрыскивания сельскохозяйственных культур, обрезки фруктовых деревьев и виноградной лозы, пересаживания риса, рассаживания свеклы, уборки урожая, обработки семян до посева (посадки);\n\nуслуги в области животноводства в части обследования состояния стада, перегонки скота, выпаса скота, выбраковки сельскохозяйственной птицы, содержания сельскохозяйственных животных и ухода за ними.\n\nВ общем доходе от реализации товаров (работ, услуг) организаций и индивидуальных предпринимателей, осуществляющих деятельность по оказанию услуг сельскохозяйственным товаропроизводителям, доля дохода от реализации перечисленных в настоящем подпункте услуг должна составлять не менее 70 процентов;\n\n3) сельскохозяйственные потребительские кооперативы (перерабатывающие, сбытовые (торговые), снабженческие, растениеводческие, животноводческие), признаваемые таковыми в соответствии с Федеральным законом от 8 декабря 1995 года № 193-ФЗ \"О сельскохозяйственной кооперации\", у которых доля доходов от реализации сельскохозяйственной продукции собственного производства членов данных кооперативов, включая продукцию первичной переработки, произведенную данными кооперативами из сельскохозяйственного сырья собственного производства членов этих кооперативов, а также от выполненных работ (услуг) для членов данных кооперативов составляет в общем доходе от реализации товаров (работ, услуг) не менее 70 процентов; (В редакции Федерального закона от 29.09.2019 № 321-ФЗ)\n\n4) для налоговых периодов 2024 - 2026 годов - соответствующие по итогам 2023 года условиям, установленным подпунктом 1 настоящего пункта, организации и индивидуальные предприниматели, которые пострадали в результате действий вооруженных формирований и (или) террористических актов и (или) осуществление хозяйственной деятельности которых невозможно в результате действий вооруженных формирований и (или) террористических актов. Отнесение организации, индивидуального предпринимателя к пострадавшим в результате действий вооруженных формирований и (или) террористических актов, подтверждение невозможности осуществления организацией, индивидуальным предпринимателем хозяйственной деятельности в результате действий вооруженных формирований и (или) террористических актов осуществляются по месту нахождения организации, месту жительства индивидуального предпринимателя и месту осуществления ими предпринимательской деятельности в соответствующем субъекте Российской Федерации в порядке, установленном высшим исполнительным органом этого субъекта Российской Федерации. (Дополнение подпунктом - Федеральный закон от 27.10.2025 № 384-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.06.2016 № 216-ФЗ)\n\n21. В целях настоящей главы сельскохозяйственными товаропроизводителями также признаются:\n\n1) градо- и поселкообразующие российские рыбохозяйственные организации, численность работающих в которых с учетом совместно проживающих с ними членов семей составляет не менее половины численности населения соответствующего населенного пункта и которые удовлетворяют условиям, установленным абзацами третьим и четвертым подпункта 2 настоящего пункта;\n\n11) сельскохозяйственные производственные кооперативы (включая рыболовецкие артели (колхозы), которые удовлетворяют условиям, установленным абзацами третьим и четвертым подпункта 2 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 07.05.2013 № 94-ФЗ)\n\n2) рыбохозяйственные организации и индивидуальные предприниматели при соблюдении ими следующих условий:\n\nесли средняя численность работников, определяемая в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным в области статистики, не превышает за налоговый период 300 человек;\n\nесли в общем доходе от реализации товаров (работ, услуг) доля дохода от реализации их уловов водных биологических ресурсов и (или) произведенной собственными силами из них рыбной и иной продукции из водных биологических ресурсов составляет за налоговый период не менее 70 процентов;\n\nесли они осуществляют рыболовство на судах рыбопромыслового флота, принадлежащих им на праве собственности, или используют их на основании договоров фрахтования (бербоут-чартера и тайм-чартера).\n\n(Дополнение пунктом - Федеральный закон от 30.12.2008 № 314-ФЗ)\n\n1) сельскохозяйственные товаропроизводители (за исключением сельскохозяйственных товаропроизводителей, указанных в подпунктах 2 - 4 настоящего пункта), если по итогам работы за календарный год, предшествующий календарному году, в котором организация или индивидуальный предприниматель подает уведомление о переходе на уплату единого сельскохозяйственного налога, в общем доходе от реализации товаров (работ, услуг) доля дохода от реализации произведенной ими сельскохозяйственной продукции, включая продукцию первичной переработки, произведенную ими из сельскохозяйственного сырья собственного производства, и (или) от оказания услуг, указанных в подпункте 2 пункта 2 настоящей статьи, составляет не менее 70 процентов; (В редакции федеральных законов от 25.06.2012 № 94-ФЗ; от 23.06.2016 № 216-ФЗ)\n\n2) сельскохозяйственные товаропроизводители - сельскохозяйственные потребительские кооперативы, если по итогам работы за календарный год, предшествующий календарному году, в котором они подают уведомление о переходе на уплату единого сельскохозяйственного налога, в общем доходе от реализации товаров (работ, услуг) доля доходов от реализации сельскохозяйственной продукции собственного производства членов сельскохозяйственных потребительских кооперативов, включая продукцию первичной переработки, произведенную данными кооперативами из сельскохозяйственного сырья собственного производства членов данных кооперативов, а также от выполненных работ (услуг) для членов данных кооперативов составляет не менее 70 процентов; (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\n3) сельскохозяйственные товаропроизводители - рыбохозяйственные организации, являющиеся градо- и поселкообразующими российскими рыбохозяйственными организациями, если они удовлетворяют следующим условиям:\n\nесли в общем доходе от реализации товаров (работ, услуг) за календарный год, предшествующий календарному году, в котором эти организации подают уведомление о переходе на уплату единого сельскохозяйственного налога, доля дохода от реализации их уловов водных биологических ресурсов и (или) произведенной из них собственными силами рыбной и иной продукции из водных биологических ресурсов составляет не менее 70 процентов; (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\nесли они осуществляют рыболовство на судах рыбопромыслового флота, принадлежащих им на праве собственности, или используют их на основании договоров фрахтования (бербоут-чартера и тайм-чартера);\n\n4) сельскохозяйственные товаропроизводители - рыбохозяйственные организации (за исключением организаций, указанных в подпункте 3 настоящего пункта) и индивидуальные предприниматели с начала следующего календарного года, если они удовлетворяют следующим условиям:\n\nесли средняя численность работников, определяемая в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным в области статистики, за каждый из двух календарных лет, предшествующих календарному году, в котором организация или индивидуальный предприниматель подают уведомление о переходе на уплату единого сельскохозяйственного налога, не превышает 300 человек; (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\nесли в общем доходе от реализации товаров (работ, услуг) за календарный год, предшествующий календарному году, в котором подается уведомление о переходе на уплату единого сельскохозяйственного н\n\nалога, доля дохода от реализации их уловов водных биологических ресурсов и (или) произведенной из них собственными силами рыбной и иной продукции из водных биологических ресурсов составляет не менее 70 процентов; (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\n5) вновь созданные в текущем году организации (за исключением организаций, указанных в подпунктах 6 и 7 настоящего пункта) с начала следующего календарного года, если в общем объеме доходов от реализации товаров (работ, услуг) по итогам последнего отчетного периода в текущем календарном году, определяемого в связи с применением иного налогового режима, доля дохода от реализации произведенной этими организациями сельскохозяйственной продукции, включая продукцию первичной переработки, произведенную ими из сельскохозяйственного сырья собственного производства, составляет не менее 70 процентов;\n\n6) вновь созданные в текущем календарном году сельскохозяйственные потребительские кооперативы с начала следующего календарного года, если в общем объеме доходов от реализации товаров (работ, услуг) за последний отчетный период в текущем календарном году, определяемый в связи с применением иного налогового режима, доля доходов от реализации сельскохозяйственной продукции собственного производства членов сельскохозяйственных потребительских кооперативов, включая продукцию первичной переработки, произведенную данными кооперативами из сельскохозяйственного сырья собственного производства членов данных кооперативов, а также от выполненных работ (услуг) для членов данных кооперативов составляет не менее 70 процентов;\n\n7) вновь созданные в текущем календарном году рыбохозяйственные организации или вновь зарегистрированные индивидуальные предприниматели вправе подать уведомление о переходе на уплату единого сельскохозяйственного налога с начала следующего календарного года при соблюдении ими следующих условий: (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\nесли по итогам последнего отчетного периода в текущем календарном году средняя численность работников, определяемая в порядке, устанавливаемом федеральным органом исполнительной власти, уполномоченным в области статистики, не превышает 300 человек (данная норма не распространяется на градо- и поселкообразующие российские рыбохозяйственные организации);\n\nесли в общем объеме доходов от реализации товаров (работ, услуг) за последний отчетный период в текущем календарном году, определяемый в связи с применением иного налогового режима, доля дохода от реализации выловленных ими рыбы и (или) объектов водных биологических ресурсов, включая продукцию их первичной переработки, произведенную собственными силами из выловленных ими рыбы и (или) объектов водных биологических ресурсов, составляет не менее 70 процентов;\n\nесли они осуществляют рыболовство на судах рыбопромыслового флота, принадлежащих им на праве собственности, или используют их на основании договоров фрахтования (бербоут-чартера и тайм-чартера);\n\n8) вновь зарегистрированные в текущем календарном году индивидуальные предприниматели (за исключением индивидуальных предпринимателей, указанных в подпункте 7 настоящего пункта) с начала следующего календарного года, если за период до 1 октября текущего года в общем доходе от реализации товаров (работ, услуг) в связи с осуществлением предпринимательской деятельности таких индивидуальных предпринимателей доля дохода от реализации произведенной ими сельскохозяйственной продукции, включая продукцию первичной переработки, произведенную ими из сельскохозяйственного сырья собственного производства, составляет не менее 70 процентов.\n\nВ целях настоящего пункта доходы от реализации определяются в порядке, предусмотренном статьями 248 и 249 настоящего Кодекса, доходы, указанные в статье 251 настоящего Кодекса, не учитываются.\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 314-ФЗ)\n\n1) (Подпункт утратил силу - Федеральный закон от 22.07.2008 № 155-ФЗ)\n\n2) организации и индивидуальные предприниматели, производящие подакцизные товары, за исключением подакцизного винограда, вина, игристого вина, включая российское шампанское, виноматериалов, виноградного сусла, произведенных из винограда собственного производства, доля которого составляет не менее 70 процентов, а также сахаросодержащих напитков, указанных в подпункте 23 пункта 1 статьи 181 настоящего Кодекса; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n3) организации, осуществляющие деятельность по организации и проведению азартных игр; (В редакции Федерального закона от 23.07.2013 № 198-ФЗ)\n\n4) казенные, бюджетные и автономные учреждения; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n5) организации и индивидуальные предприниматели, осуществляющие майнинг цифровой валюты. (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n(Статья в редакции Федерального закона от 03.11.2006 № 177-ФЗ)","article_title":"Статья 346.2. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1bb8792077df871dc862db6703b9e55602f3f0c6aad6cc69e20f6cf36d7b526"},{"code_id":"NK_RF_2","article_number":"346.20","version_date":"2000-07-31","article_text":"Законами субъектов Российской Федерации могут быть установлены налоговые ставки в пределах от 1 до 6 процентов в зависимости от категорий налогоплательщиков.\n\n(Пункт в редакции Федерального закона от 31.07.2020 № 266-ФЗ)\n\nЗаконами субъектов Российской Федерации могут быть установлены налоговые ставки в пределах от 5 до 15 процентов в зависимости от категорий налогоплательщиков.\n\n(Пункт в редакции Федерального закона от 31.07.2020 № 266-ФЗ)\n\nВ отношении периодов 2015 - 2016 годов налоговая ставка может быть уменьшена до 0 процентов.\n\nВ отношении периодов 2017 - 2021 годов налоговая ставка может быть уменьшена до 3 процентов в случае, если объектом налогообложения являются доходы, уменьшенные на величину расходов. При этом налоговые ставки могут устанавливаться в зависимости от категорий налогоплательщиков и видов предпринимательской деятельности. (В редакции Федерального закона от 13.07.2015 № 232-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nНалоговые ставки, установленные в соответствии с настоящим пунктом законами Республики Крым и города федерального значения Севастополя, не могут быть повышены в течение периодов, указанных в настоящем пункте, начиная с налогового периода, с которого применяется пониженная налоговая ставка. (В редакции  федеральных законов от 31.07.2020 № 266-ФЗ, от 12.07.2024 № 176-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\nНалогоплательщики, указанные в абзаце первом настоящего пункта, вправе применять налоговую ставку в размере 0 процентов со дня их государственной регистрации в качестве индивидуальных предпринимателей непрерывно в течение двух налоговых периодов. В период действия налоговой ставки в размере 0 процентов, установленной в соответствии с настоящим пунктом, индивидуальные предприниматели, указанные в абзаце первом настоящего пункта, выбравшие объект налогообложения в виде доходов, уменьшенных на величину расходов, не уплачивают минимальный налог, предусмотренный пунктом 6 статьи 34618 настоящего Кодекса. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nВиды предпринимательской деятельности в производственной, социальной и научной сферах, в отношении которых устанавливается налоговая ставка в размере 0 процентов, устанавливаются субъектами Российской Федерации на основании Общероссийского классификатора видов экономической деятельности. (В редакции Федерального закона от 03.07.2016 № 248-ФЗ)\n\nПо итогам налогового периода доля доходов от реализации товаров (работ, услуг) при осуществлении видов предпринимательской деятельности, в отношении которых применялась налоговая ставка в размере 0 процентов, в общем объеме доходов от реализации товаров (работ, услуг) должна быть не менее 70 процентов.\n\nЗаконами субъектов Российской Федерации могут быть установлены ограничения на применение налогоплательщиками, указанными в абзаце первом настоящего пункта, налоговой ставки в размере 0 процентов, в том числе в виде:\n\nограничения средней численности работников;\n\nограничения предельного размера доходов от реализации, определяемых в соответствии со статьей 249 настоящего Кодекса, получаемых индивидуальным предпринимателем при осуществлении вида предпринимательской деятельности, в отношении которого применяется налоговая ставка в размере 0 процентов. При этом предусмотренный пунктом 4 статьи 34613 настоящего Кодекса предельный размер дохода в целях применения упрощенной системы налогообложения может быть уменьшен законом субъекта Российской Федерации не более чем в 10 раз.\n\nВ случае нарушения ограничений на применение налоговой ставки в размере 0 процентов, установленных настоящей главой и законом субъекта Российской Федерации, индивидуальный предприниматель считается утратившим право на ее применение и обязан уплатить налог по налоговым ставкам, предусмотренным пунктом 1, 2 или 3 настоящей статьи, за налоговый период, в котором нарушены указанные ограничения.\n\nВиды предпринимательской деятельности в сфере бытовых услуг населению, в отношении которых устанавливается налоговая ставка в размере 0 процентов, устанавливаются субъектами Российской Федерации на основании кодов видов деятельности в соответствии с Общероссийским классификатором видов экономической деятельности и (или) кодов услуг в соответствии с Общероссийским классификатором продукции по видам экономической деятельности, относящихся к бытовым услугам, определяемых Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 248-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2014 № 477-ФЗ)","article_title":"Статья 346.20. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5ccdaad65116ade202ba8a17c68812428851a2832f3463f0ed4ec4daab27146"},{"code_id":"NK_RF_2","article_number":"346.21","version_date":"2000-07-31","article_text":"Абзац: (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 31.07.2020 № 266-ФЗ)\n\nВ случае изменения места нахождения организации (места жительства индивидуального предпринимателя) в течение налогового периода налог (авансовые платежи по налогу) исчисляется, если иное не установлено настоящим пунктом, по налоговой ставке, установленной законом субъекта Российской Федерации по новому месту нахождения организации (месту жительства индивидуального предпринимателя). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ) (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nВ случае, если для налогового периода из трех последовательных налоговых периодов начиная с налогового периода, в котором было изменено место нахождения организации (место жительства индивидуального предпринимателя), законом субъекта Российской Федерации по новому месту нахождения организации (месту жительства индивидуального предпринимателя) установлена налоговая ставка в размере меньшем, чем налоговая ставка, установленная законом субъекта Российской Федерации, на территории которого такая организация (такой индивидуальный предприниматель) применяла упрощенную систему налогообложения до изменения места нахождения организации (места жительства индивидуального предпринимателя), для указанного налогового периода налог (авансовые платежи по налогу) исчисляется по налоговой ставке, установленной для соответствующего налогового периода законом субъекта Российской Федерации, на территории которого такая организация (такой индивидуальный предприниматель) применяла упрощенную систему налогообложения до изменения места нахождения организации (места жительства индивидуального предпринимателя). (Дополнение абзацем - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nАбзац: (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 31.07.2020 № 266-ФЗ)\n\n1) страховых взносов на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний, уплаченных (в пределах исчисленных сумм) в данном налоговом (отчетном) периоде в соответствии с законодательством Российской Федерации, если иное не установлено настоящим пунктом; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) расходов по выплате в соответствии с законодательством Российской Федерации пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\", в части, не покрытой страховыми выплатами, произведенными работникам страховыми организациями, имеющими лицензии, выданные в соответствии с законодательством Российской Федерации, на осуществление соответствующего вида деятельности, по договорам с работодателями в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\";\n\n3) платежей (взносов) по договорам добровольного личного страхования, заключенным со страховыми организациями, имеющими лицензии, выданные в соответствии с законодательством Российской Федерации, на осуществление соответствующего вида деятельности, в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\". Указанные платежи (взносы) уменьшают сумму налога (авансовых платежей по налогу), если сумма страховой выплаты по таким договорам не превышает определяемого в соответствии с законодательством Российской Федерации размера пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\".\n\nПри этом налогоплательщики (за исключением налогоплательщиков, указанных в абзаце шестом настоящего пункта) вправе уменьшить сумму налога (авансовых платежей по налогу) на сумму указанных в настоящем пункте расходов не более чем на 50 процентов. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nИндивидуальные предприниматели, не производящие выплаты и иные вознаграждения физическим лицам, производят указанное уменьшение налога (авансового платежа по налогу) без установленного в абзаце пятом настоящего пункта ограничения. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nИндивидуальные предприниматели, выбравшие в качестве объекта налогообложения доходы, уменьшают сумму налога (авансовых платежей по налогу), исчисленную за налоговый (отчетный) период, на сумму страховых взносов на обязательное пенсионное страхование и на обязательное медицинское страхование, подлежащую уплате в данном налоговом периоде в соответствии со статьей 430 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nСтраховые взносы, указанные в абзаце седьмом настоящего пункта, считаются подлежащими уплате в данном налоговом периоде в том числе в случае, если срок уплаты таких страховых взносов приходится в соответствии с пунктом 7 статьи 61 настоящего Кодекса на первый рабочий день следующего года. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nСуммы страховых взносов, определяемые в соответствии со статьей 430 настоящего Кодекса, уплаченные после 31 декабря 2022 года за расчетные периоды, предшествующие 2023 году, уменьшают исчисленную за налоговые (отчетные) периоды 2023 - 2025 годов сумму налога (авансовых платежей по налогу). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\nНалогоплательщики, указанные в абзаце первом настоящего пункта, которые выбрали в качестве объекта налогообложения доходы, производят данное уменьшение налога (авансового платежа по налогу) в дополнение к суммам уменьшения, установленным пунктами 31 и 8 настоящей статьи.\n\nВ целях настоящего пункта в расходы на приобретение контрольно-кассовой техники включаются затраты на покупку контрольно-кассовой техники, фискального накопителя, необходимого программного обеспечения, выполнение сопутствующих работ и оказание услуг (услуг по настройке контрольно-кассовой техники и прочих услуг).\n\nУменьшение суммы налога в соответствии с настоящим пунктом производится за налоговый период 2024 или 2025 года по выбору налогоплательщика.\n\nВ случае, если при исчислении суммы налога за налоговый период сумма расходов на приобретение одного экземпляра контрольно-кассовой техники с учетом ограничения, установленного абзацем первым настоящего пункта, превысила сумму этого налога, на сумму указанного превышения может быть уменьшена сумма исчисленного налога за последующий налоговый период.\n\nРасходы на приобретение контрольно-кассовой техники не учитываются при исчислении налога, если они были учтены налогоплательщиками в составе расходов при применении упрощенной системы налогообложения с объектом налогообложения в виде доходов, уменьшенных на величину расходов, и (или) при исчислении налогов, уплачиваемых в связи с применением иных режимов налогообложения.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nАбзац: (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 31.07.2020 № 266-ФЗ)\n\nорганизациями - не позднее 28 марта года, следующего за истекшим налоговым периодом;\n\nиндивидуальными предпринимателями - не позднее 28 апреля года, следующего за истекшим налоговым периодом;\n\nналогоплательщиками, которыми согласно уведомлению, представленному в налоговый орган в соответствии с пунктом 8 статьи 34613 настоящего Кодекса, прекращена предпринимательская деятельность, в отношении которой этим налогоплательщиком применялась упрощенная система налогообложения, - не позднее 28-го числа месяца, следующего за месяцем прекращения деятельности;\n\nналогоплательщиками, утратившими право применять упрощенную систему налогообложения на основании пункта 4 статьи 34613 настоящего Кодекса, - не позднее 28-го числа месяца, следующего за кварталом, в котором утрачено данное право.\n\nАвансовые платежи по налогу уплачиваются не позднее 28-го числа месяца, следующего за истекшим отчетным периодом.\n\n(Пункт в редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nПоложения настоящего пункта не применяются в случае непредставления налогоплательщиком в отношении объекта осуществления предпринимательской деятельности, по которому уплачен торговый сбор, уведомления о постановке на учет в качестве плательщика торгового сбора.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)","article_title":"Статья 346.21. Порядок исчисления и уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c5589a7bb401bd526fc355d038698c6a2530560994ff7edc1314ecbd00b203e"},{"code_id":"NK_RF_2","article_number":"346.22","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 25.06.2012 № 94-ФЗ)","article_title":"Статья 346.22. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35a1286dd892cae1a19a0fef55ae369f0705ca4ded54f17e6a65c335790a1a26"},{"code_id":"NK_RF_2","article_number":"346.23","version_date":"2000-07-31","article_text":"1. По итогам налогового периода налогоплательщики представляют налоговую деклар\n\nацию в налоговый орган по месту нахождения организации или месту жительства индивидуального предпринимателя в следующие сроки:\n\n1) организации - не позднее 25 марта года, следующего за истекшим налоговым периодом (за исключением случаев, предусмотренных пунктами 2 и 3 настоящей статьи); (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2) индивидуальные предприниматели - не позднее 25 апреля года, следующего за истекшим налоговым периодом (за исключением случаев, предусмотренных пунктами 2 и 3 настоящей статьи). (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n2. Налогоплательщик представляет налоговую декларацию не позднее 25-го числа месяца, следующего за месяцем, в котором согласно уведомлению, представленному им в налоговый орган в соответствии с пунктом 8 статьи 34613 настоящего Кодекса, прекращена предпринимательская деятельность, в отношении которой этим налогоплательщиком применялась упрощенная система налогообложения.\n\n3. Налогоплательщик представляет налоговую декларацию не позднее 25-го числа месяца, следующего за кварталом, в котором на основании пункта 4 статьи 34613 настоящего Кодекса он утратил право применять упрощенную систему налогообложения.\n\n(Статья в редакции Федерального закона от 25.06.2012 № 94-ФЗ)","article_title":"Статья 346.23. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dacbe32000e7f50a9bbdc6eecd6fc8e91cb4f041a1ea9309548013fcc845a5b5"},{"code_id":"NK_RF_2","article_number":"346.24","version_date":"2000-07-31","article_text":"Налогоплательщики обязаны вести учет доходов и расходов для целей исчисления налоговой базы по налогу в книге учета доходов и расходов организаций и индивидуальных предпринимателей, применяющих упрощенную систему налогообложения, форма и порядок заполнения которой утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Статья в редакции Федерального закона от 21.07.2005 № 101-ФЗ)","article_title":"Статья 346.24. Налоговый учет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f4735fb9030bacd0724a54aa4374facc16e3a1ed3ec2b469b0f68c517c619fe"},{"code_id":"NK_RF_2","article_number":"346.25","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n1) на дату перехода на упрощенную систему налогообложения в налоговую базу включаются суммы денежных средств, полученные до перехода на упрощенную систему налогообложения в оплату по договорам, исполнение которых налогоплательщик осуществляет после перехода на упрощенную систему налогообложения; (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 21.07.2005 № 101-ФЗ)\n\n3) не включаются в налоговую базу денежные средства, полученные после перехода на упрощенную систему налогообложения, если по правилам налогового учета по методу начислений указанные суммы были включены в доходы при исчислении налоговой базы по налогу на прибыль организаций; (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n4) расходы, осуществленные организацией после перехода на упрощенную систему налогообложения, признаются расходами, вычитаемыми из налоговой базы, на дату их осуществления, если оплата таких расходов была осуществлена до перехода на упрощенную систему налогообложения, либо на дату оплаты, если оплата была осуществлена после перехода организации на упрощенную систему налогообложения; (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n5) не вычитаются из налоговой базы денежные средства, уплаченные после перехода на упрощенную систему налогообложения в оплату расходов организации, если до перехода на упрощенную систему налогообложения такие расходы были учтены при исчислении налоговой базы по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса. (В редакции Федерального закона от 21.07.2005 № 101-ФЗ)\n\n1) признаются в составе доходов доходы в сумме выручки от реализации товаров (выполнения работ, оказания услуг, передачи имущественных прав) в период применения упрощенной системы налогообложения, оплата (частичная оплата) которых не произведена до даты перехода на исчисление налоговой базы по налогу на прибыль по методу начисления;\n\n2) признаются в составе расходов расходы на приобретение в период применения упрощенной системы налогообложения товаров (работ, услуг, имущественных прав), которые не были оплачены (частично оплачены) налогоплательщиком до даты перехода на исчисление налоговой базы по налогу на прибыль по методу начисления, если иное не предусмотрено главой 25 настоящего Кодекса.\n\nУказанные в подпунктах 1 и 2 настоящего пункта доходы и расходы признаются доходами (расходами) месяца перехода на исчисление налоговой базы по налогу на прибыль организаций с использованием метода начислений.\n\n(Пункт в редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nПри переходе налогоплательщика с объекта налогообложения в виде доходов на объект налогообложения в виде доходов, уменьшенных на величину расходов, на дату такого перехода остаточная стоимость основных средств, приобретенных в период применения упрощенной системы налогообложения с объектом налогообложения в виде доходов, не определяется.\n\nПри переходе на упрощенную систему налогообложения с объектом налогообложения в виде доходов, уменьшенных на величину расходов, организации, применяющей систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) в соответствии с главой 261 настоящего Кодекса, в налоговом учете на дату указанного перехода отражается остаточная стоимость приобретенных (сооруженных, изготовленных) основных средств и приобретенных (созданных самой организацией) нематериальных активов, определяемая исходя из их остаточной стоимости на дату перехода на уплату единого сельскохозяйственного налога, уменьшенной на сумму расходов, определяемых в порядке, предусмотренном подпунктом 2 пункта 4 статьи 3465 настоящего Кодекса, за период применения главы 261 настоящего Кодекса.\n\nАбзац. (Утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 21.07.2005 № 101-ФЗ) (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\nРасходы, непосредственно связанные с реализацией указанных товаров, в том числе расходы по хранению, обслуживанию и транспортировке, при применении упрощенной системы налогообложения учитываются в том отчетном (налоговом) периоде, в котором была произведена их фактическая оплата после перехода на упрощенную систему налогообложения.\n\n(Дополнение пунктом - Федеральный закон от 01.04.2020 № 102-ФЗ)","article_title":"Статья 346.25. Особенности исчисления налоговой базы при переходе на упрощенную систему налогообложения с иных режимов налогообложения и при переходе с упрощенной системы налогообложения на иные режимы налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b648ec7dc93e1f5ca0bb692c3dfefbcbcc6691c2fa926308832e5e980bb6452a"},{"code_id":"NK_RF_2","article_number":"34625.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 21.07.2005 № 101-ФЗ) (Утратила силу - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\nГЛАВА 263. (Статьи 34626 - 34633)\n\n(Дополнение главой - Федеральный закон от 24.07.2002 № 104-ФЗ) (Утратила силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nГЛАВА 264. СИСТЕМА НАЛОГООБЛОЖЕНИЯ ПРИ ВЫПОЛНЕНИИ СОГЛАШЕНИЙ О РАЗДЕЛЕ ПРОДУКЦИИ\n\n(Дополнение главой - Федеральный закон от 06.06.2003 № 65-ФЗ)","article_title":"Статья 34625.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33292efee0345b8e4f1ec2aff21782dc3083771eb65fed777594a4913370e1bb"},{"code_id":"NK_RF_2","article_number":"346.3","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n1. Организации и индивидуальные предприниматели, изъявившие желание перейти на уплату единого сельскохозяйственного налога со следующего календарного года, уведомляют об этом налоговый орган по месту нахождения организации или месту жительства индивидуального предпринимателя не позднее 31 декабря календарного года, предшествующего календарному году, начиная с которого они переходят на уплату единого сельскохозяйственного налога.\n\nВ уведомлении указываются данные о доле дохода от реализации произведенной ими сельскохозяйственной продукции (от оказания услуг сельскохозяйственным товаропроизводителям, указанных в подпункте 2 пункта 2 статьи 3462 настоящего Кодекса), включая продукцию первичной переработки, произведенную ими из сельскохозяйственного сырья собственного производства, или данные о доле доходов от реализации сельскохозяйственной продукции собственного производства членов сельскохозяйственных потребительских кооперативов, включая продукцию первичной переработки, произведенную этими кооперативами из сельскохозяйственного сырья собственного производства членов этих кооперативов, а также от выполненных работ (оказанных услуг) для членов этих кооперативов в общем доходе от реализации товаров (выполнения работ, оказания услуг), полученном ими по итогам календарного года, предшествующего году, в котором подается уведомление о переходе на уплату единого сельскохозяйственного налога. (В редакции Федерального закона от 23.06.2016 № 216-ФЗ)\n\nНалогоплательщики - организации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\", изъявившие желание перейти на уплату единого сельскохозяйственного налога с 1 января 2015 года или с 1 января 2016 года, в уведомлении о переходе на уплату единого сельскохозяйственного налога данные о доле дохода от реализации произведенной ими сельскохозяйственной продукции (от оказания услуг сельскохозяйственным товаропроизводителям, указанных в подпункте 2 пункта 2 статьи 3462 настоящего Кодекса), включая продукцию первичной переработки, произведенную ими из сельскохозяйственного сырья собственного производства, или данные о доле доходов от реализации сельскохозяйственной продукции собственного производства членов сельскохозяйственных потребительских кооперативов, включая продукцию первичной переработки, произведенную этими кооперативами из сельскохозяйственного сырья собственного производства членов этих кооперативов, а также от выполнения работ (оказания услуг) для членов этих кооперативов в общем доходе от реализации товаров (выполнения работ, оказания услуг), полученном ими за 2013 и 2014 годы соответственно, не указывают. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ) (В редакции Федерального закона от 23.06.2016 № 216-ФЗ)\n\n(Пункт в редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\nОрганизации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\", изъявившие желание перейти на уплату единого сельскохозяйственного налога с 1 января 2015 года, вправе уведомить об этом налоговый орган не позднее 1 февраля 2015 года. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\nОрганизации, сведения о которых внесены в единый государственный реестр юридических лиц на основании статьи 19 Федерального закона от 30 ноября 1994 года № 52-ФЗ \"О введении в действие части первой Гражданского кодекса Российской Федерации\" с учетом части 4 статьи 121 Федерального конституционного закона от 21 марта 2014 года № 6-ФКЗ \"О принятии в Российскую Федерацию Республики Крым и образовании в составе Российской Федерации новых субъектов - Республики Крым и города федерального значения Севастополя\", вправе уведомить об этом налоговый орган не позднее 1 апреля 2015 года. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 379-ФЗ)\n\nНалогоплательщики не вправе до окончания налогового периода перейти на иной режим налогообложения, если иное не установлено настоящей статьей.\n\n(Пункт в редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\nПри этом ограничения по объему дохода от реализации произведенной налогоплательщиком сельскохозяйственной продукции (от оказания услуг сельскохозяйственным товаропроизводителям, указанных в подпункте 2 пункта 2 статьи 3462 настоящего Кодекса), в том числе от реализации сельскохозяйственной продукции собственного производства членов сельскохозяйственных потребительских кооперативов, включая продукцию первичной переработки, произведенную налогоплательщиком из сельскохозяйственного сырья собственного производства, в том числе продукцию первичной переработки, произведенную сельскохозяйственным потребительским кооперативом из сельскохозяйственного сырья собственного производства членов данного кооператива, а также от выполненных работ (услуг) для членов данных кооперативов определяются исходя из всех осуществляемых им видов деятельности. (В редакции федеральных законов от 17.05.2007 № 85-ФЗ; от 23.06.2016 № 216-ФЗ)\n\nНалогоплательщик, утративший право на применение единого сельскохозяйственного налога, в течение одного месяца после истечения налогового периода, в котором допущено нарушение указанного в абзаце первом настоящего пункта ограничения и (или) несоответствие требованиям, установленным пунктами 2, 21, 5 и 6 статьи 3462 настоящего Кодекса, должен за весь налоговый период произвести перерасчет налоговых обязательств по налогу на добавленную стоимость, налогу на прибыль организаций, налогу на доходы физических лиц, налогу на имущество организаций, налогу на имущество физических лиц в порядке, предусмотренном законодательством Российской Федерации о налогах и сборах для вновь созданных организаций или вновь зарегистрированных индивидуальных предпринимателей. Указанный в настоящем абзаце налогоплательщик уплачивает пени за несвоевременную уплату указанных налогов и авансовых платежей по ним в следующем порядке: (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 30.12.2008 № 314-ФЗ; от 24.07.2009 № 213-ФЗ; от 02.06.2010 № 115-ФЗ)\n\nв случае, если налогоплательщик по итогам налогового периода нарушил требования, установленные пунктами 2 и 21 статьи 3462 настоящего Кодекса, и не произвел в установленном абзацем третьим настоящего пункта порядке перерасчет подлежащих уплате сумм налогов, то пени начисляются за каждый календарный день просрочки исполнения обязанности по уплате соответствующего налога начиная со следующего дня после установленного абзацем третьим настоящего пункта срока перерасчета подлежащих уплате сумм налогов; (Дополнение абзацем - Федеральный закон от 02.06.2010 № 115-ФЗ)\n\nв случае, если организация или индивидуальный предприниматель нарушили требования, установленные пунктами 5 и 6 статьи 3462 настоящего Кодекса для перехода на уплату единого сельскохозяйственного налога, и необоснованно применяли данный налог, то пени начисляются за каждый календарный день просрочки исполнения обязанности по уплате налога (авансового платежа по налогу), который должен был уплачиваться в соответствии с общим режимом налогообложения, начиная со дня, следующего за установленным законодательством о налогах и сборах днем уплаты соответствующего налога (авансового платежа по налогу) в налоговом периоде, в котором необоснованно применялся единый сельскохозяйственный налог. (Дополнение абзацем - Федеральный закон от 02.06.2010 № 115-ФЗ)\n\n(Пункт в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n1) если у вновь созданной организации или вновь зарегистрированного индивидуального предпринимателя, перешедших на уплату единого сельскохозяйственного налога в порядке, установленном пунктом 2 настоящей статьи, в первом налоговом периоде отсутствовали доходы, учитываемые при определении налоговой базы;\n\n2) если в текущем налоговом периоде налогоплательщиком не было допущено нарушения ограничений и (или) несоответствия требованиям, установленным пунктами 2, 21, 5 и 6 статьи 3462 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 25.06.2012 № 94-ФЗ)","article_title":"Статья 346.3. Порядок и условия начала и прекращения применения единого сельскохозяйственного налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96aba1d7aa6e23fe75bf1e6757f2294db5223813595034f77731c6ad0d927803"},{"code_id":"NK_RF_2","article_number":"346.34","version_date":"2000-07-31","article_text":"В целях настоящей главы используются следующие основные понятия:\n\nинвестор - юридическое лицо или создаваемое на основе договора о совместной деятельности и не имеющее статуса юридического лица объединение юридических лиц, осуществляющее вложение собственных заемных или привлеченных средств (имущества и (или) имущественных прав) в поиск, разведку и добычу минерального сырья и являющееся пользователем недр на условиях соглашения о разделе продукции (далее в настоящей главе - соглашение);\n\nпродукция - полезное ископаемое, добытое из недр на территории Российской Федерации, а также на континентальном шельфе Российской Федерации и (или) в пределах исключительной экономической зоны Российской Федерации, на участке недр, предоставленном инвестору, и первое по своему качеству соответствующее национальному стандарту, региональному стандарту, международному стандарту, а в случае отсутствия указанных стандартов для отдельного добытого полезного ископаемого - стандарту организации. Не может быть признана полезным ископаемым продукция, полученная при дальнейшей переработке (обогащении, технологическом переделе) полезного ископаемого и являющаяся продукцией обрабатывающей промышленности; (В редакции Федерального закона от 19.07.2011 № 248-ФЗ)\n\nпроизведенная продукция - количество продукции горнодобывающей промышленности и продукции разработки карьеров, содержащееся в фактически добытом (извлеченном) из недр (отходов, потерь) минеральном сырье (породе, жидкости и иной смеси), первой по своему качеству соответствующей национальному стандарту, региональному стандарту, международному стандарту, а в случае отсутствия указанных стандартов для отдельного добытого полезного ископаемого - стандарту организации, добытой инвестором в ходе выполнения работ по соглашению и уменьшенной на количество технологических потерь в пределах установленных нормативов. При выполнении соглашений, в которых применяется порядок раздела продукции, установленный пунктом 2 статьи 8 Федерального закона \"О соглашениях о разделе продукции\", доля государства в общем объеме произведенной продукции составляет не менее 32 процентов общего количества произведенной продукции; (В редакции Федерального закона от 19.07.2011 № 248-ФЗ)\n\nраздел продукции - раздел между государством и инвестором произведенной продукции в натуральном и (или) стоимостном выражении в соответствии с Федеральным законом \"О соглашениях о разделе продукции\";\n\nприбыльная продукция - произведенная за отчетный (налоговый) период при выполнении соглашения продукция за вычетом части продукции, стоимостный эквивалент которой используется для уплаты налога на добычу полезных ископаемых, и компенсационной продукции;\n\nкомпенсационная продукция - часть произведенной при выполнении соглашения продукции, которая не должна превышать 75 процентов общего количества произведенной продукции, а при добыче на континентальном шельфе Российской Федерации - 90 процентов общего количества произведенной продукции, передаваемой в собственность инвестора для возмещения понесенных им расходов (возмещаемые расходы), состав которых устанавливается соглашением в соответствии с настоящей главой;\n\nпункт раздела - место коммерческого учета продукции, в котором государство передает инвестору часть произведенной продукции, причитающуюся ему по условиям соглашения. При добыче нефти место коммерческого учета продукции определяется в случае транспортировки ее трубопроводным транспортом как место, в которое нефть по трубопроводу поступает на контрольно-измерительную станцию и в котором осуществляется измерение ее количества и определение качества, подсчет в качестве произведенной продукции и передача в систему магистрального трубопровода. В случае транспортировки нефти иным транспортом, чем трубопроводный, место коммерческого учета продукции определяется соглашением как место, в которое нефть поступает на контрольно-измерительную станцию и в котором осуществляется измерение ее количества и определение качества;\n\nцена продукции - определяемая в соответствии с условиями соглашения стоимость продукции, если иное не установлено настоящей главой;\n\nцена нефти - цена реализации нефти, которая указана сторонами сделки, но не ниже среднего за отчетный период уровня цен нефти сорта \"Юралс\", определяемого как деленная на количество дней торгов в соответствующем налоговом периоде сумма средних арифметических цен покупки и продажи нефти при поставках в морские порты Российской Федерации, расположенные в Северо-Западном федеральном округе и Южном федеральном округе, которая увеличивается на стоимость транспортировки нефти морским транспортом за пределы территории Российской Федерации до мировых рынков нефтяного сырья (средиземноморского и роттердамского), рассчитываемую в соответствии с абзацем вторым пункта 3 статьи 342 настоящего Кодекса. Средние за истекший месяц уровни цен нефти сорта \"Юралс\" ежемесячно в срок не позднее 15-го числа следующего месяца доводятся через официальные источники информации в порядке, установленном Правительством Российской Федерации. При отсутствии указанной информации в официальных источниках информации средний за истекший отчетный период уровень цен нефти сорта \"Юралс\" определяется налогоплательщиком самостоятельно. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 346.34. Основные понятия, используемые в настоящей главе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d0a1f3b8bbcc6a35ca6ac97ae0f65f2768eebfe6ced2b9241c94f2f147693a5"},{"code_id":"NK_RF_2","article_number":"346.35","version_date":"2000-07-31","article_text":"1. Настоящая глава устанавливает специальный налоговый режим, применяемый при выполнении соглашений, которые заключены в соответствии с Федеральным законом \"О соглашениях о разделе продукции\" и отвечают следующим условиям:\n\n1) соглашения заключены после проведения аукциона на предоставление права пользования недрами на иных условиях, чем раздел продукции, в порядке и на условиях, которые определены пунктом 4 статьи 2 Федерального закона \"О соглашениях о разделе продукции\", и признания аукциона несостоявшимся;\n\n2) при выполнении соглашений, в которых применяется порядок раздела продукции, установленный пунктом 2 статьи 8 Федерального закона \"О соглашениях о разделе продукции\", доля государства в общем объеме произведенной продукции составляет не менее 32 процентов общего количества произведенной продукции;\n\n3) соглашения предусматривают увеличение доли государства в прибыльной продукции в случае улучшения показателей инвестиционной эффективности для инвестора при выполнении соглашения. Показатели инвестиционной эффективности устанавливаются в соответствии с условиями соглашения.\n\n2. Налогоплательщик, использующий право на применение специального налогового режима при выполнении соглашений, представляет в налоговые органы соответствующие уведомления в письменном виде и следующие документы:\n\nсоглашение о разделе продукции;\n\nрешение об утверждении результатов аукциона на предоставление права пользования участком недр на иных условиях, чем раздел продукции, в соответствии с Законом Российской Федерации \"О недрах\" и о признании аукциона несостоявшимся в связи с отсутствием участников.\n\n3. В целях настоящей главы цена продукции (цена нефти) применяется для определения объема компенсационной продукции, передаваемой инвестору, для раздела прибыльной продукции в стоимостном выражении, для определения прибыли, подлежащей налогообложению, а также для компенсации расходов инвестора на уплату налогов и сборов в случаях, предусмотренных настоящей главой.\n\n4. Установленный настоящей главой специальный налоговый режим применяется в течение всего срока действия соглашения.\n\n5. Установленный настоящей главой специальный налоговый режим применяется в отношении налогоплательщиков и плательщиков сборов, указанных в статье 34636 настоящего Кодекса.\n\n6. Установленный настоящей главой специальный налоговый режим предусматривает замену уплаты совокупности налогов и сборов, установленных законодательством Российской Федерации о налогах и сборах, разделом произведенной продукции в соответствии с условиями соглашения, за исключением налогов и сборов, уплата которых предусмотрена настоящей главой.\n\n7. При выполнении соглашения, предусматривающего условия раздела произведенной продукции в соответствии с пунктом 1 статьи 8 Федерального закона \"О соглашениях о разделе продукции\", инвестор уплачивает следующие налоги и сборы:\n\nналог на добавленную стоимость;\n\nналог на прибыль организаций;\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nналог на добычу полезных ископаемых;\n\nплатежи за пользование природными ресурсами;\n\nплату за негативное воздействие на окружающую среду;\n\nводный налог; (В редакции Федерального закона от 31.12.2005 № 205-ФЗ)\n\nгосударственную пошлину;\n\nтаможенные сборы;\n\nземельный налог;\n\nакциз, за исключением акциза на подакцизное минеральное сырье, предусмотренное подпунктом 1 пункта 2 статьи 181 настоящего Кодекса.\n\nИнвестор освобождается от уплаты региональных и местных налогов и сборов в соответствии с настоящей главой по решению соответствующего законодательного (представительного) органа государственной власти или представительного органа местного самоуправления.\n\nСуммы уплаченных инвестором налога на добавленную стоимость, платежей за пользование природными ресурсами, водного налога, го\n\nсударственной пошлины, таможенных сборов, земельного налога, акциза, а также суммы платы за негативное воздействие на окружающую среду подлежат возмещению в соответствии с положениями настоящей главы. (В редакции федеральных законов от 31.12.2005 № 205-ФЗ; от 24.07.2009 № 213-ФЗ)\n\nИнвестор не уплачивает налог на имущество организаций в отношении основных средств, нематериальных активов, запасов и затрат, которые находятся на балансе налогоплательщика и используются исключительно для осуществления деятельности, предусмотренной соглашениями. В случае, если указанное имущество используется инвестором не для целей, связанных с выполнением работ по соглашению, оно облагается налогом на имущество организаций в общеустановленном порядке.\n\nПеречень документов, при предоставлении которых в налоговые органы осуществляется освобождение от уплаты указанного налога, определяется Правительством Российской Федерации.\n\nИнвестор не уплачивает транспортный налог в отношении принадлежащих ему транспортных средств (за исключением легковых автомобилей), используемых исключительно для целей соглашения.\n\nПеречень документов, при предоставлении которых в налоговые органы осуществляется освобождение от уплаты указанного налога, определяется Правительством Российской Федерации.\n\nПри использовании транспортных средств не для целей соглашения уплата транспортного налога осуществляется в общеустановленном порядке.\n\n8. При выполнении соглашения, предусматривающего условия раздела произведенной продукции в соответствии с пунктом 2 статьи 8 Федерального закона \"О соглашениях о разделе продукции\", инвестор уплачивает следующие налоги и сборы:\n\nабзац; (Утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\nгосударственную пошлину;\n\nтаможенные сборы;\n\nналог на добавленную стоимость;\n\nплату за негативное воздействие на окружающую среду.\n\nИнвестор освобождается от уплаты региональных и местных налогов и сборов в соответствии с настоящей главой по решению соответствующего законодательного (представительного) органа государственной власти или представительного органа местного самоуправления.\n\nПеречень документов, при предоставлении которых в таможенные органы осуществляется освобождение от уплаты указанного налога, определяется Правительством Российской Федерации.","article_title":"Статья 346.35. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e1c76aa29a59dafc0956350c3b937cf7fa978105f7d5bd0844131ab526d0527"},{"code_id":"NK_RF_2","article_number":"346.36","version_date":"2000-07-31","article_text":"1. Налогоплательщиками и плательщиками сборов, уплачиваемых при применении специального налогового режима, установленного настоящей главой, признаются организации, являющиеся инвесторами соглашения в соответствии с Федеральным законом \"О соглашениях о разделе продукции\" (далее в настоящей главе - налогоплательщики).\n\n2. Налогоплательщик вправе поручить исполнение своих обязанностей, связанных с применением специального налогового режима, установленного настоящей главой, при выполнении соглашений, оператору с его согласия. Оператор осуществляет в соответствии с настоящим Кодексом предоставленные ему налогоплательщиком полномочия на основании нотариально удостоверенной доверенности, выдаваемой в порядке, установленном гражданским законодательством Российской Федерации, в качестве уполномоченного представителя налогоплательщика.","article_title":"Статья 346.36. Налогоплательщики и плательщики сборов при выполнении соглашений. Уполномоченные представители налогоплательщиков и плательщиков сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7a9673bd5e56200cb5e989f50f26756295c28bb345360440c790895b5d09e8d9"},{"code_id":"NK_RF_2","article_number":"346.37","version_date":"2000-07-31","article_text":"1. Положения настоящей статьи применяются при выполнении соглашений, которые предусматривают условия раздела произведенной продукции в соответствии с пунктом 1 статьи 8 Федерального закона \"О соглашениях о разделе продукции\".\n\n2. Налогоплательщики определяют сумму налога на добычу полезных ископаемых, подлежащую уплате, в соответствии с главой 26 настоящего Кодекса с учетом особенностей, установленных настоящей статьей.\n\n3. Налоговая база при добыче нефти и газового конденсата из нефтегазоконденсатных месторождений определяется как количество добытых полезных ископаемых в натуральном выражении в соответствии со статьей 339 настоящего Кодекса.\n\n4. Налоговая база определяется отдельно по каждому соглашению.\n\n5. Налоговая ставка при добыче нефти и газового конденсата из нефтегазоконденсатных месторождений составляет 340 рублей за одну тонну. При этом указанная налоговая ставка применяется с коэффициентом, характеризующим динамику мировых цен на нефть, - Кц.\n\nДанный коэффициент ежемесячно определяется налогоплательщиком самостоятельно по формуле:\n\nКц = (Ц - 8) х Р / 252,\n\nгде Ц - средний за налоговый период уровень цен нефти сорта \"Юралс\" в долларах США за один баррель; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nР - среднее значение за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации.\n\nСреднее значение за налоговый период курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, определяется налогоплательщиком самостоятельно как среднеарифметическое значение курса доллара США к рублю Российской Федерации, устанавливаемого Центральным банком Российской Федерации, за все календарные дни в соответствующем налоговом периоде. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nСредний за истекший налоговый период уровень цен нефти сорта \"Юралс\" определяется как деленная на количество дней торгов в соответствующем налоговом периоде сумма средних арифметических цен покупки и продажи нефти при поставках в морские порты Российской Федерации, расположенные в Северо-Западном федеральном округе и Южном федеральном округе, которая увеличивается на стоимость транспортировки нефти морским транспортом за пределы территории Российской Федерации до мировых рынков нефтяного сырья (средиземноморского и роттердамского), рассчитываемую в соответствии с абзацем вторым пункта 3 статьи 342 настоящего Кодекса. (В редакции  федеральных законов от 27.11.2023 № 539-ФЗ, от 29.10.2024 № 362-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 23.02.2023 № 36-ФЗ) (Утратил силу  - Федеральный закон от 29.10.2024 № 362-ФЗ)\n\nСредние за истекший месяц уровни цен нефти сорта \"Юралс\" ежемесячно в срок не позднее 15-го числа следующего месяца доводятся через официальные источники информации в порядке, установленном Правительством Российской Федерации. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nПри отсутствии указанной информации в официальных источниках информации средний за истекший налоговый период уровень цен нефти сорта \"Юралс\" определяется налогоплательщиком самостоятельно. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nРассчитанный в порядке, определенном настоящей статьей, коэффициент (Кц) округляется до четвертого знака в соответствии с действующим порядком округления.\n\nСумма налога на добычу полезных ископаемых при добыче нефти и газового конденсата из нефтегазоконденсатных месторождений исчисляется как произведение соответствующей налоговой ставки, исчисленной с учетом коэффициента (Кц), и величины налоговой базы, определяемой в соответствии с настоящей статьей.\n\n6. При выполнении соглашений налоговые ставки, установленные статьей 342 настоящего Кодекса, при добыче полезных ископаемых, за исключением нефти и газового конденсата, применяются с коэффициентом 0,5.\n\n7. Налоговая ставка, установленная пунктом 5 настоящей статьи, применяется при добыче нефти и газового конденсата из нефтегазоконденсатных месторождений с коэффициентом 0,5 до достижения предельного уровня коммерческой добычи нефти и газового конденсата, который может быть установлен соглашением.\n\nВ случае, если соглашением установлен предельный уровень коммерческой добычи нефти и газового конденсата, при достижении такого предельного уровня налоговая ставка применяется с коэффициентом 1, который не изменяется в течение всего срока действия соглашения.","article_title":"Статья 346.37. Особенности определения налоговой базы, исчисления и уплаты налога на добычу полезных ископаемых при выполнении соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a87695a6b470cd5b0dded8de5ab5ce4a90036868cbb6d5fccc1e8f88b87f1062"},{"code_id":"NK_RF_2","article_number":"346.38","version_date":"2000-07-31","article_text":"1. Положения настоящей статьи применяются при выполнении соглашений, которые предусматривают порядок раздела продукции, установленный пунктом 1 статьи 8 Федерального закона \"О соглашениях о разделе продукции\".\n\n2. Налогоплательщики определяют сумму налога на прибыль организаций (далее в настоящей статье - налог), подлежащую уплате, в соответствии с главой 25 настоящего Кодекса с учетом особенностей, установленных настоящей статьей.\n\n3. Объектом налогообложения признается прибыль, полученная налогоплательщиком в связи с выполнением соглашения.\n\nВ целях настоящей статьи прибылью налогоплательщика признается его доход от выполнения соглашения, уменьшенный на величину расходов, определяемых в соответствии с настоящей статьей.\n\nВ случае, если стороной соглашения является объединение организаций, не имеющее статуса юридического лица, доход, полученный каждой организацией, являющейся участником указанного объединения, определяется пропорционально доле соответствующего участника в общем доходе такого объединения за отчетный (налоговый) период.\n\n4. Доходом налогоплательщика от выполнения соглашения признаются стоимость прибыльной продукции, принадлежащей инвестору в соответствии с условиями соглашения, а также внереализационные доходы, определяемые в соответствии со статьей 250 настоящего Кодекса.\n\nСтоимость прибыльной продукции определяется как произведение объема прибыльной продукции и цены произведенной продукции, устанавливаемой соглашением, за исключением цены продукции (цены нефти), определяемой в соответствии с настоящей главой.\n\n5. Расходами налогоплательщика признаются обоснованные и документально подтвержденные расходы, произведенные (понесенные) налогоплательщиком при выполнении соглашения.\n\nСостав расходов, размер и порядок их признания определяются в соответствии с главой 25 настоящего Кодекса с учетом особенностей, установленных настоящей статьей.\n\nОбоснованными расходами для целей настоящей главы признаются расходы, произведенные (понесенные) налогоплательщиком в соответствии с программой работ и сметой расходов, утвержденными управляющим комитетом, в порядке, предусмотренном соглашением, а также внереализационные расходы, непосредственно связанные с выполнением соглашения.\n\n6. В целях настоящей главы расходы налогоплательщика подразделяются на:\n\n1) расходы, возмещаемые за счет компенсационной продукции (возмещаемые расходы);\n\n2) расходы, уменьшающие налоговую базу по налогу.\n\n7. Возмещаемыми расходами признаются расходы, произведенные (понесенные) налогоплательщиком в отчетном (налоговом) периоде в целях выполнения работ по соглашению в соответствии с программой работ и сметой расходов. Не признаются возмещаемыми:\n\n1) произведенные (понесенные) до вступления соглашения в силу:\n\nрасходы на приобретение пакета геологической информации для участия в аукционе;\n\nрасходы на оплату сбора за участие в аукционе на право пользования участком недр на условиях соглашения;\n\n2) произведенные (понесенные) с даты вступления соглашения в силу:\n\nразовые платежи за пользование недрами при наступлении определенных событий, оговоренных в соглашении;\n\nналог на добычу полезных ископаемых;\n\nплатежи (проценты) по полученным кредитным и заемным средствам, а также комиссионные выплаты по ним и другие расходы, связанные с получением и использованием заемных средств для финансирования деятельности по соглашению;\n\nрасходы, предусмотренные подпунктом 6 пункта 2 статьи 262 настоящего Кодекса; (В редакции Федерального закона от 07.06.2011 № 132-ФЗ)\n\nрасходы, предусмотренные подпунктами 10 и 13 пункта 1 и подпунктом 5 пункта 2 статьи 265 настоящего Кодекса.\n\n8. Возмещаемые расходы, состав которых предусмотрен соглашением в соответствии с настоящей статьей, утверждаются управляющим комитетом в порядке, установленном соглашением.\n\nВ целях настоящей статьи сумма возмещаемых расходов определяется по каждому отчетному (налоговому) периоду и подлежит возмещению налогоплательщику за счет компенсационной продукции в порядке, установленном пунктом 10 настоящей статьи.\n\n9. В состав возмещаемых расходов включаются:\n\n1) расходы, произведенные (понесенные) налогоплательщиком до вступления соглашения в силу. Расходы, произведенные (понесенные) до вступления соглашения в силу, признаются возмещаемыми, если соглашение заключено по ранее не разрабатываемым месторождениям полезных ископаемых и эти расходы не были ранее признаны недропользователем участка недр для целей исчисления налога в соответствии с главой 25 настоящего Кодекса. Указанные расходы должны быть отражены в смете расходов, представляемой одновременно со сметой расходов на первый год работ по соглашению, и возмещаются в порядке и размере, которые предусмотрены настоящей статьей. В целях применения настоящей статьи амортизация по данному виду амортизируемого имущества не начисляется. В случае, если расходы относятся в соответствии со статьей 256 настоящего Кодекса к амортизируемому имуществу, их возмещение производится в следующем порядке:\n\nесли указанные расходы произведены (понесены) налогоплательщиком - российской организацией, они подлежат возмещению в размере, не превышающем остаточную стоимость амортизируемого имущества, определяемую в соответствии со статьей 257 настоящего Кодекса;\n\nесли указанные расходы произведены (понесены) налогоплательщиком - иностранной организацией, они подлежат возмещению в размере, не превышающем уровень рыночных цен;\n\n2) расходы, произведенные (понесенные) налогоплательщиком с даты вступления соглашения в силу и в течение всего срока его действия. При этом в отношении указанных расходов устанавливаются следующие особенности:\n\nрасходы на освоение природных ресурсов, указанные в пункте 1 статьи 261 настоящего Кодекса, а также аналогичные расходы по сопряженным участкам недр, если это предусмотрено соглашением, включаются в состав расходов равномерно в течение 12 месяцев;\n\nрасходы на приобретение, сооружение, изготовление, доставку амортизируемого имущества (основных средств и нематериальных активов) и доведение его до состояния, в котором оно пригодно для использования, включаются в состав возмещаемых расходов в сумме фактически понесенных затрат при условии их включения в программу работ и смету расходов и с учетом ограничений, установленных соглашением. Начисление амортизации в порядке, установленном настоящим Кодексом, по таким расходам не производится;\n\nрасходы, произведенные (понесенные) в форме отчислений в ликвидационный фонд для финансирования ликвидационных работ, учитываются в целях налогообложения в размере и порядке, которые установлены соглашением. Порядок формирования и использования ликвидационного фонда устанавливается Правительством Российской Федерации;\n\nрасходы, связанные с содержанием и эксплуатацией имущества, которое было передано государством в безвозмездное пользование налогоплательщику в соответствии со статьей 11 Федерального закона \"О соглашениях о разделе продукции\", учитываются в целях налогообложения в размере фактически произведенных (понесенных) расходов;\n\nуправленческие расходы, связанные с выполнением соглашения, в состав которых включаются расходы на оплату аренды офисов налогоплательщика, в том числе расположенных за пределами Российской Федерации, расходы на их содержание, информационные и консультационные услуги, представительские расходы, расходы на рекламу и другие управленческие расходы по условиям соглашения возмещаются в размере норматива управленческих расходов, установленного соглашением, но не более 2 процентов общей суммы расходов, возмещаемых налогоплательщику в отчетном (налоговом) периоде. Превышение суммы управленческих расходов над нормативом, установленным настоящим пунктом, учитывается при исчислении налоговой базы инвестора по налогу.\n\n10. В целях настоящей главы возмещаемые расходы подлежат возмещению налогоплательщику в размере, не превышающем установленного соглашением предельного уровня компенсационной продукции, который не может быть выше размера, определяемого в соответствии со статьей 34634 настоящего Кодекса.\n\nКомпенсационная продукция за отчетный (налоговый) период рассчитывается путем деления подлежащей возмещению суммы расходов налогоплательщика на цену продукции, определяемую в соответствии с условиями соглашения, или на цену нефти, определяемую в соответствии с настоящей главой.\n\nЕсли размер возмещаемых расходов не достигает предельного уровня компенсационной продукции в отчетном (налоговом) периоде, налогоплательщику в указанном периоде возмещается вся сумма возмещаемых расходов. Если размер возмещаемых расходов\n\nпревышает предельный уровень компенсационной продукции в отчетном (налоговом) периоде, возмещение расходов производится в размере указанного предельного уровня. Невозмещенные в отчетном (налоговом) периоде возмещаемые расходы подлежат включению в состав возмещаемых расходов следующего отчетного (налогового) периода.\n\nРасходы капитального характера принимаются к возмещению при условии соблюдения требования об использовании доли товаров российского происхождения при проведении работ по соглашению, установленного пунктом 2 статьи 7 Федерального закона \"О соглашениях о разделе продукции\". Несоблюдение указанного требования является основанием для отказа в возмещении соответствующих затрат инвестора. При этом на приобретаемое оборудование и иное имущество распространяется порядок амортизации имущества, установленный статьями 256 - 259 настоящего Кодекса.\n\n11. Расходы, уменьшающие налоговую базу по налогу, включают в себя расходы, учитываемые в целях налогообложения в соответствии с главой 25 настоящего Кодекса и не включенные в состав возмещаемых расходов, определяемых в соответствии с положениями настоящей статьи. В указанные в настоящем пункте расходы не включаются суммы налога на добычу полезных ископаемых.\n\n12. В целях настоящей главы применяется следующий порядок признания доходов и расходов:\n\n1) для дохода, полученного налогоплательщиком в виде части прибыльной продукции, датой получения дохода признается последнее число отчетного (налогового) периода, в котором был осуществлен раздел прибыльной продукции; (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n2) по иным видам доходов и расходов применяется порядок признания доходов и расходов, установленный главой 25 настоящего Кодекса.\n\n13. Налоговой базой для целей настоящей статьи признается денежное выражение подлежащей налогообложению прибыли, определяемой в соответствии с пунктом 3 настоящей статьи.\n\nНалоговая база определяется по каждому соглашению раздельно.\n\n14. В случае, если налоговая база, исчисленная в соответствии с положениями настоящей статьи, является для соответствующего налогового периода отрицательной величиной, она для этого налогового периода признается равной нулю. Налогоплательщик имеет право уменьшить налоговую базу на величину полученной отрицательной величины в последующие налоговые периоды в течение 10 лет, следующих за тем налоговым периодом, в котором получена отрицательная величина, но не более срока действия соглашения.\n\n15. Размер налоговой ставки определяется в соответствии с пунктом 1 статьи 284 настоящего Кодекса.\n\nНалоговая ставка, действующая на дату вступления соглашения в силу, применяется в течение всего срока действия этого соглашения.\n\n16. Налогоплательщики исчисляют налоговую базу по итогам каждого отчетного (налогового) периода на основе данных налогового учета. Налоговый учет осуществляется в соответствии с главой 25 настоящего Кодекса.\n\nПорядок ведения налогового учета устанавливается налогоплательщиком в учетной политике для целей налогообложения, утверждаемой в установленном порядке.\n\n17. Налоговый и отчетный периоды по налогу устанавливаются в соответствии со статьей 285 настоящего Кодекса.\n\n18. Порядок исчисления налога (авансовых платежей) и сроки уплаты определяются в соответствии с главой 25 настоящего Кодекса.\n\nАбзац. (Утратил силу - Федеральный закон от 24.11.2008 № 205-ФЗ)\n\n19. Особенности исчисления и уплаты налога налогоплательщиком, имеющим обособленные подразделения, определяются статьей 288 настоящего Кодекса. При этом уплата сумм налога (авансовых платежей), которые подлежат зачислению в доходную часть бюджетов субъектов Российской Федерации и местных бюджетов, производится налогоплательщиком по местонахождению участка недр, представляемого в пользование по соглашению.\n\n20. В целях настоящей статьи налогоплательщик обязан вести раздельный учет доходов и расходов по операциям, возникающим при выполнении соглашения.\n\nПри отсутствии раздельного учета применяется порядок налогообложения прибыли, установленный главой 25 настоящего Кодекса, без учета особенностей, установленных настоящей статьей.\n\n21. Доходы и расходы налогоплательщика по другим видам деятельности, не связанным с выполнением соглашения, в том числе доходы в виде вознаграждения за выполнение функций оператора и (или) за реализацию продукции, принадлежащей государству по условиям соглашения, подлежат налогообложению в порядке, установленном главой 25 настоящего Кодекса.\n\nПрибыль, полученная инвестором от реализации компенсационной продукции, подлежит налогообложению в порядке, установленном главой 25 настоящего Кодекса, и определяется как выручка от реализации компенсационной продукции (определяемая в соответствии со статьей 249 настоящего Кодекса), уменьшенная на величину расходов, связанных с реализацией указанной продукции (определяемых в соответствии со статьей 253 настоящего Кодекса) и не учтенных в стоимости компенсационной продукции, уменьшенная на стоимость компенсационной продукции, определяемой в соответствии с пунктом 10 настоящей статьи.\n\nВ случае, если от реализации компенсационной продукции налогоплательщиком понесен убыток, он принимается в целях налогообложения в порядке и на условиях, которые установлены статьей 283 настоящего Кодекса.","article_title":"Статья 346.38. Особенности определения налоговой базы, исчисления и уплаты налога на прибыль организаций при выполнении соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58ff7245ade3291ea423efc24d0cb4ec25318fea366aca10a3f0ed9cc8755b8d"},{"code_id":"NK_RF_2","article_number":"346.39","version_date":"2000-07-31","article_text":"1. При выполнении соглашений налог на добавленную стоимость (далее в настоящей статье - налог) уплачивается в соответствии с главой 21 настоящего Кодекса с учетом особенностей, установленных настоящей статьей.\n\n2. При выполнении соглашений применяется налоговая ставка, действующая в соответствующем налоговом периоде в соответствии с главой 21 настоящего Кодекса.\n\nпередача на безвозмездной основе имущества, необходимого для выполнения работ по соглашению, между инвестором по соглашению и оператором соглашения в соответствии с программой работ и сметой расходов, которые утверждены в установленном соглашением порядке;\n\nпередача организацией, являющейся участником не имеющего статуса юридического лица объединения организаций, выступающего в качестве инвестора в соглашении, другим участникам такого объединения соответствующей доли произведенной продукции, полученной инвестором по условиям соглашения;\n\nпередача налогоплательщиком в собственность государства вновь созданного или приобретенного налогоплательщиком имущества, использованного для выполнения работ по соглашению и подлежащего передаче государству в соответствии с условиями соглашения.","article_title":"Статья 346.39. Особенности уплаты налога на добавленную стоимость при выполнении соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3b908997c2e77a80c617b1da7fc93b06ba16ad91b6ec1df6d6b7c151df3a2f0"},{"code_id":"NK_RF_2","article_number":"346.4","version_date":"2000-07-31","article_text":"Объектом налогообложения признаются доходы, уменьшенные на величину расходов.","article_title":"Статья 346.4. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6b91cd3cdc9a3fcfca855334a215524308d9193670325badb5b979937e954c6"},{"code_id":"NK_RF_2","article_number":"346.40","version_date":"2000-07-31","article_text":"Если участок недр, предоставляемый в пользование на условиях соглашения, расположен на континентальном шельфе Российской Федерации и (или) в пределах исключительной экономической зоны Российской Федерации, налогоплательщик представляет налоговые декларации по налогам, предусмотренным статьей 34635 настоящего Кодекса, в налоговые органы, в которых он состоит на учете, по его местонахождению. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют налоговые декларации (расчеты) в налоговый орган по месту учета в качестве крупнейших налогоплательщиков. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ)\n\nПо вновь введенным соглашениям в срок до начала работ налогоплательщик представляет в налоговые органы, указанные в пункте 1 настоящей статьи, утвержденные в порядке, установленном соглашением, программу работ и смету расходов по соглашению на текущий год.\n\nВ случае внесения изменений и (или) дополнений в программу работ и смету расходов налогоплательщик обязан представить указанные изменения и (или) дополнения в срок не позднее 10 дней с даты их утверждения в установленном соглашением порядке.","article_title":"Статья 346.40. Особенности представления налоговых деклараций при выполнении соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"685d36d628bcfddba2ce715101ae17c1df7b76e83ce687c4790c4445a3c5dd6a"},{"code_id":"NK_RF_2","article_number":"346.41","version_date":"2000-07-31","article_text":"1. Налогоплательщики подлежат постановке на учет в налоговом органе по местонахождению участка недр, предоставленного инвестору в пользование на условиях соглашения, за исключением случаев, предусмотренных пунктом 3 настоящей статьи.\n\n2. В случае, если в качестве инвестора по соглашению выступает объединение организаций, не имеющее статуса юридического лица, постановке на учет в налоговом органе по местонахождению участка недр, предоставляемого в пользование на условиях соглашения, подлежат все организации, входящие в состав указанного объединения, за исключением случаев, предусмотренных пунктом 3 настоящей статьи.\n\n3. Если участок недр, предоставляемый в пользование на условиях соглашения, расположен на континентальном шельфе Российской Федерации и (или) в пределах исключительной экономической зоны Российской Федерации, постановка налогоплательщика на учет производится в налоговом органе по его местонахождению.\n\nУказанное свидетельство должно содержать наименование соглашения, указание даты вступления соглашения в силу и срока его действия, наименование участка недр, предоставленного в пользование в соответствии с условиями соглашения, и указание его местонахождения, а также указание на то, что данный налогоплательщик является инвестором по соглашению или оператором соглашения и в отношении этого налогоплательщика применяется специальный налоговый режим, установленный настоящей главой.","article_title":"Статья 346.41. Особенности учета налогоплательщиков при выполнении соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3b9e58508757b4879987b115d5fa6071201ad53ec3a7ec187f1f7f7513ac9ab5"},{"code_id":"NK_RF_2","article_number":"346.42","version_date":"2000-07-31","article_text":"1. Выездной налоговой проверкой может быть охвачен любой период в течение срока действия соглашения с учетом положений статьи 87 настоящего Кодекса начиная с года вступления соглашения в силу.\n\n2. Для целей налогового контроля инвестор по соглашению или оператор соглашения обязан хранить первичные документы, связанные с исчислением и уплатой налогов, в течение всего срока действия соглашения.\n\n3. Выездная налоговая проверка инвестора по соглашению или оператора соглашения в связи с деятельностью по соглашению не может продолжаться более шести месяцев. При проведении выездных проверок организаций, имеющих филиалы и представительства, срок проведения проверки увеличивается на один месяц для проведения проверки каждого филиала и представительства.\n\nГЛАВА 265. ПАТЕНТНАЯ СИСТЕМА НАЛОГООБЛОЖЕНИЯ\n\n(Дополнение главой - Федеральный закон от 25.06.2012 № 94-ФЗ)","article_title":"Статья 346.42. Особенности проведения выездных налоговых проверок при выполнении соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"978be80b3b77d5767ced65307480a0567de3980e1aa83ea5750257cbb6eb5700"},{"code_id":"NK_RF_2","article_number":"346.43","version_date":"2000-07-31","article_text":"Патентная система налогообложения устанавливается в федеральной территории \"Сириус\" в соответствии с настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\nПатентная система налогообложения применяется индивидуальными предпринимателями наряду с иными режимами налогообложения, предусмотренными законодательством Российской Федерации о налогах и сборах.\n\n1) ремонт и пошив швейных, меховых и кожаных изделий, головных уборов и изделий из текстильной галантереи, ремонт, пошив и вязание трикотажных изделий по индивидуальному заказу населения; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n2) ремонт, чистка, окраска и пошив обуви;\n\n3) парикмахерские и косметические услуги;\n\n4) стирка, химическая чистка и крашение текстильных и меховых изделий; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n5) изготовление и ремонт металлической галантереи, ключей, номерных знаков, указателей улиц;\n\n6) ремонт электронной бытовой техники, бытовых приборов, часов, металлоизделий бытового и хозяйственного назначения, предметов и изделий из металла, изготовление готовых металлических изделий хозяйственного назначения по индивидуальному заказу населения; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n7) ремонт мебели и предметов домашнего обихода; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n8) услуги в области фотографии; (В редакции Федерального закона от 06.02.2020 № 8-ФЗ)\n\n9) ремонт, техническое обслуживание автотранспортных и мототранспортных средств, мотоциклов, машин и оборудования, мойка автотранспортных средств, полирование и предоставление аналогичных услуг; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n10) оказание автотранспортных услуг по перевозке грузов автомобильным транспортом индивидуальными предпринимателями, имеющими на праве собственности или ином праве (пользования, владения и (или) распоряжения) транспортные средства, предназначенные для оказания таких услуг; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n11) оказание автотранспортных услуг по перевозке пассажиров автомобильным транспортом индивидуальными предпринимателями, имеющими на праве собственности или ином праве (пользования, владения и (или) распоряжения) транспортные средства, предназначенные для оказания таких услуг; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n12) реконструкция или ремонт существующих жилых и нежилых зданий, а также спортивных сооружений; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n13) услуги по производству монтажных, электромонтажных, санитарно-технических и сварочных работ;\n\n14) услуги по остеклению балконов и лоджий, нарезке стекла и зеркал, художественной обработке стекла;\n\n15) услуги в сфере дошкольного образования и дополнительного образования детей и взрослых; (В редакции Федерального закона от 06.02.2020 № 8-ФЗ)\n\n16) услуги по присмотру и уходу за детьми и больными;\n\n17) сбор тары и пригодных для вторичного использования материалов; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n18) деятельность ветеринарная; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n19) сдача в аренду (наем) собственных или арендованных жилых помещений, а также сдача в аренду собственных или арендованных нежилых помещений (включая выставочные залы, складские помещения), земельных участков; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n20) изготовление изделий народных художественных промыслов;\n\n21) услуги по переработке продуктов сельского хозяйства, лесного хозяйства и рыболовства для приготовления продуктов питания для людей и корма для животных, а также производство различных продуктов промежуточного потребления, которые не являются пищевыми продуктами; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n22) производство и реставрация ковров и ковровых изделий;\n\n23) ремонт ювелирных изделий, бижутерии;\n\n24) чеканка и гравировка ювелирных изделий;\n\n25) деятельность в области звукозаписи и издания музыкальных произведений; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n26) услуги по уборке квартир и частных домов, деятельность домашних хозяйств с наемными работниками; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n27) деятельность, специализированная в области дизайна, услуги художественного оформления; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n28) проведение занятий по физической культуре и спорту;\n\n29) услуги носильщиков на железнодорожных вокзалах, автовокзалах, аэровокзалах, в аэропортах, морских, речных портах;\n\n30) услуги платных туалетов;\n\n31) услуги по приготовлению и поставке блюд для торжественных мероприятий или иных событий; (В редакции Федерального закона от 06.02.2020 № 8-ФЗ)\n\n32) оказание услуг по перевозке пассажиров водным транспортом;\n\n33) оказание услуг по перевозке грузов водным транспортом;\n\n34) услуги, связанные со сбытом\n\nсельскохозяйственной продукции (хранение, сортировка, сушка, мойка, расфасовка, упаковка и транспортировка);\n\n35) услуги, связанные с обслуживанием сельскохозяйственного производства (механизированные, агрохимические, мелиоративные, транспортные работы);\n\n36) деятельность по благоустройству ландшафта; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n37) охота, отлов и отстрел диких животных, в том числе предоставление услуг в этих областях, деятельность, связанная со спортивно-любительской охотой; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n38) занятие медицинской деятельностью или фармацевтической деятельностью лицом, имеющим лицензию на указанные виды деятельности, за исключением реализации лекарственных препаратов, подлежащих обязательной маркировке средствами идентификации, в том числе контрольными (идентификационными) знаками в соответствии с Федеральным законом от 12 апреля 2010 года № 61-ФЗ \"Об обращении лекарственных средств\"; (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n39) осуществление частной детективной деятельности лицом, имеющим лицензию;\n\n40) услуги по прокату;\n\n41) услуги экскурсионные туристические; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n42) организация обрядов (свадеб, юбилеев), в том числе музыкальное сопровождение; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n43) организация похорон и предоставление связанных с ними услуг; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n44) услуги уличных патрулей, охранников, сторожей и вахтеров;\n\n45) розничная торговля, осуществляемая через объекты стационарной торговой сети, имеющие торговые залы; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n46) розничная торговля, осуществляемая через объекты стационарной торговой сети, не имеющие торговых залов, а также через объекты нестационарной торговой сети;\n\n47) услуги общественного питания, оказываемые через объекты организации общественного питания; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n48) услуги общественного питания, оказываемые через объекты организации общественного питания, не имеющие зала обслуживания посетителей; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n49) оказание услуг по забою и транспортировке скота; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции Федерального закона от 06.02.2020 № 8-ФЗ)\n\n50) производство кожи и изделий из кожи; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n51) сбор и заготовка пищевых лесных ресурсов, недревесных лесных ресурсов и лекарственных растений; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n52) переработка и консервирование фруктов и овощей; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n53) производство молочной продукции; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n54) растениеводство, услуги в области растениеводства; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции Федерального закона от 06.02.2020 № 8-ФЗ)\n\n55) производство хлебобулочных и мучных кондитерских изделий; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n56) рыболовство и рыбоводство, рыболовство любительское и спортивное; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n57) лесоводство и прочая лесохозяйственная деятельность; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n58) деятельность по письменному и устному переводу; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n59) деятельность по уходу за престарелыми и инвалидами; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n60) сбор, обработка и утилизация отходов, а также обработка вторичного сырья; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n61) резка, обработка и отделка камня для памятников; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n62) разработка компьютерного программного обеспечения, в том числе системного программного обеспечения, приложений программного обеспечения, баз данных, web-страниц, включая их адаптацию и модификацию; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n63) ремонт компьютеров и коммуникационного оборудования; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n64) животноводство, услуги в области животноводства; (Дополнение подпунктом - Федеральный закон от 06.02.2020 № 8-ФЗ)\n\n65) деятельность стоянок для транспортных средств; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n66) помол зерна, производство муки и крупы из зерен пшеницы, ржи, овса, кукурузы или прочих хлебных злаков; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n67) услуги по уходу за домашними животными; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n68) изготовление и ремонт бондарной посуды и гончарных изделий по индивидуальному заказу населения; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n69) услуги по изготовлению валяной обуви; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n70) услуги по изготовлению сельскохозяйственного инвентаря из материала заказчика по индивидуальному заказу населения; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n71) граверные работы по металлу, стеклу, фарфору, дереву, керамике, кроме ювелирных изделий по индивидуальному заказу населения; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n72) изготовление и ремонт деревянных лодок по индивидуальному заказу населения; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n73) ремонт игрушек и подобных им изделий; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n74) ремонт спортивного и туристического оборудования; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n75) услуги по вспашке огородов по индивидуальному заказу населения; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n76) услуги по распиловке дров по индивидуальному заказу населения; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n77) сборка и ремонт очков; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n78) изготовление и печатание визитных карточек и пригласительных билетов на семейные торжества; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n79) переплетные, брошюровочные, окантовочные, картонажные работы; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n80) услуги по ремонту сифонов и автосифонов, в том числе зарядка газовых баллончиков для сифонов. (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n1) розничная торговля - предпринимательская деятельность, связанная с торговлей товарами (в том числе за наличный расчет, а также с использованием платежных карт) на основе договоров розничной купли-продажи. К данному виду предпринимательской деятельности не относится реализация подакцизных товаров, указанных в подпунктах 6 - 10 пункта 1 статьи 181 настоящего Кодекса, продуктов питания и напитков, в том числе алкогольных, как в упаковке и расфасовке изготовителя, так и без таких упаковки и расфасовки, в барах, ресторанах, кафе и других объектах организации общественного питания, газа, грузовых и специальных автомобилей, прицепов, полуприцепов, прицепов-роспусков, автобусов любых типов, товаров по образцам и каталогам вне стационарной торговой сети (в том числе в виде почтовых отправлений (посылочная торговля), а также через телемагазины, телефонную связь и компьютерные сети), передача лекарственных препаратов по льготным (бесплатным) рецептам, а также продукции собственного производства (изготовления). Реализация лекарственных препаратов, подлежащих обязательной маркировке средствами идентификации, в том числе контрольными (идентификационными) знаками в соответствии с Федеральным законом от 12 апреля 2010 года № 61-ФЗ \"Об обращении лекарственных средств\", обувных товаров и предметов одежды, принадлежностей к одежде и прочих изделий из натурального меха, подлежащих обязательной маркировке средствами идентификации, в том числе контрольными (идентификационными) знаками по перечню кодов Общероссийского классификатора продукции по видам экономической деятельности и (или) по перечню кодов товаров в соответствии с Товарной номенклатурой внешнеэкономической деятельности Евразийского экономического союза, определяемых Правительством Российской Федерации, для целей настоящей главы не относится к розничной торговле. Реализация через торговые автоматы товаров и (или) продукции общественного питания, изготовленной в этих торговых автоматах, относится в целях настоящей главы к розничной торговле; (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n2) стационарная торговая сеть, имеющая торговые залы, - торговая сеть, расположенная в предназначенных для ведения торговли зданиях и строениях (их частях), имеющих оснащенные специальным оборудованием обособленные помещения, предназначенные для ведения розничной торговли и обслуживания покупателей. К данной категории торговых объектов относятся магазины и павильоны;\n\n3) магазин - специально оборудованное здание (его часть), предназначенное для продажи товаров и оказания услуг покупателям и обеспеченное торговыми, подсобными, административно-бытовыми помещениями, а также помещениями для приема, хранения товаров и подготовки их к продаже;\n\n4) павильон - строение, имеющее торговый зал и рассчитанное на одно или несколько рабочих мест;\n\n5) площадь торгового зала - часть магазина, павильона, занятая оборудованием, предназначенным для выкладки, демонстрации товаров, проведения денежных расчетов и обслуживания покупателей, площадь контрольно-кассовых узлов и кассовых кабин, площадь рабочих мест обслуживающего персонала, а также площадь проходов для покупателей. К площади торгового зала относится также арендуемая часть площади торгового зала. Площадь подсобных, административно-бытовых помещений, а также помещений для приема, хранения товаров и подготовки их к продаже, в которых не производится обслуживание покупателей, не относится к площади торгового зала. Площадь торгового зала определяется на основании инвентаризационных и правоустанавливающих документов;\n\n6) площадь зала обслуживания посетителей - площадь специально оборудованных помещений (открытых площадок) объекта организации общественного питания, предназначенных для потребления готовой кулинарной продукции, кондитерских изделий и (или) покупных товаров, а также для проведения досуга, определяемая на основании инвентаризационных и правоустанавливающих документов;\n\n7) стационарная торговая сеть, не имеющая торговых залов, - торговая сеть, расположенная в предназначенных для ведения торговли зданиях, строениях и сооружениях (их частях), не имеющих обособленных и специально оснащенных для этих целей помещений, а также в зданиях, строениях и сооружениях (их частях), используемых для заключения договоров розничной купли-продажи, а также для проведения торгов. К данной категории торговых объектов относятся розничные рынки, ярмарки, киоски, палатки, торговые автоматы и другие аналогичные объекты; (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n8) киоск - строение, которое не имеет торгового зала и рассчитано на одно рабочее место продавца;\n\n9) палатка - сборно-разборная конструкция, оснащенная прилавком, не имеющая торгового зала;\n\n10) нестационарная торговая сеть - торговая сеть, функционирующая на принципах развозной и разносной торговли, а также объекты организации торговли, неотносимые к стационарной торговой сети;\n\n11) развозная торговля - розничная торговля, осуществляемая вне стационарной розничной сети с использованием специализированных или специально оборудованных для торговли транспортных средств, а также мобильного оборудования, применяемого только с транспортным средством. К данному виду торговли относится торговля с использованием автомобиля, автолавки, автомагазина, тонара, автоприцепа, передвижного торгового автомата;\n\n12) разносная торговля - розничная торговля, осуществляемая вне стационарной розничной сети путем непосредственного контакта продавца с покупателем в организациях, на транспорте, на дому или на улице. К данному виду торговли относится торговля с рук, лотка, из корзин и ручных тележек;\n\n13) услуги общественного питания - услуги по изготовлению кулинарной продукции и (или) кондитерских изделий, созданию условий для потребления и (или) реализации готовой кулинарной продукции, кондитерских изделий и (или) покупных товаров, а также по проведению досуга. К услугам общественного питания не относятся услуги по производству и реализации подакцизных товаров, указанных в подпункте 3 пункта 1 статьи 181 настоящего Кодекса;\n\n14) объект организации общественного питания, имеющий зал обслуживания посетителей, - здание (его часть) или строение, предназначенные для оказания услуг общественного питания и имеющие специально оборудованное помещение (открытую площадку) для потребления готовой кулинарной продукции, кондитерских изделий и (или) покупных товаров, а также для проведения досуга;\n\n15) объект организации общественного питания, не имеющий зала обслуживания посетителей, - объект организации общественного питания, не имеющий специально оборудованного помещения (открытой площадки) для потребления готовой кулинарной продукции, кондитерских изделий и (или) покупных товаров. К данной категории объектов организации общественного питания относятся киоски, палатки, магазины (отделы) кулинарии при ресторанах, барах, кафе, столовых, закусочных и другие аналогичные точки общественного питания;\n\n16) открытая площадка - специально оборудованное для общественного питания место, расположенное на земельном участке;\n\n17) ремонт, техническое обслуживание автотранспортных и мототранспортных средств, мотоциклов, машин и оборудования, мойка автотранспортных средств, полирование и предоставление аналогичных услуг - платные услуги, оказываемые физическим лицам и организациям по перечню услуг, предусмотренному Общероссийским классификатором видов экономической деятельности, и платные услуги по проведению технического осмотра автотранспортных средств на предмет их соответствия обязательным требованиям безопасности в целях допуска к участию в дорожном движении на территории Российской Федерации, а в случаях, предусмотренных международными договорами Российской Федерации, также за ее пределами. К данным услугам не относятся услуги по заправке автотранспортных средств, услуги по гарантийному ремонту и обслуживанию и услуги по хранению автотранспортных средств на платных и штрафных стоянках; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n18) стоянки для транспортных средств - площади, используемые в качестве мест для оказания платных услуг по предоставлению во временное владение (в пользование) мест для стоянки транспортных средств, а также по хранению транспортных средств (за исключением штрафных стоянок); (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n19) площадь стоянки для транспортных средств - общая площадь стоянки, определяемая на основании правоустанавливающих и инвентаризационных документов; (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n20) транспортные средства (в целях подпунктов 10 и 11 пункта 2 настоящей статьи) - автотранспортные средства, предназначенные для перевозки по дорогам грузов и пассажиров (автобусы любых типов, легковые и грузовые автомобили). К транспортным средствам не относятся прицепы, полуприцепы и прицепы-роспуски. (Дополнение подпунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n1) видов деятельности, осуществляемых в рамках договора простого товарищества (договора о совместной деятельности) или договора доверительного управления имуществом;\n\n2) деятельности по производству подакцизных товаров, за исключением сахаросодержащих напитков, указанных в подпункте 23 пункта 1 статьи 181 настоящего Кодекса, а также по добыче и реализации полезных ископаемых; (В редакции Федерального закона от 21.11.2022 № 443-ФЗ)\n\n3) розничной торговли, осуществляемой через объекты стационарной торговой сети с площадью торгового зала более 150 квадратных метров;\n\n4) услуг общественного питания, оказываемых через объекты организации общественного питания с площадью зала обслуживания посетителей более 150 квадратных метров;\n\n5) оптовой торговли, а также торговли, осуществляемой по договорам поставки;\n\n6) услуг по перевозке грузов и пассажиров индивидуальными предпринимателями, имеющими на праве собственности или ином праве (пользования, владения и (или) распоряжения) более 20 автотранспортных средств, предназначенных для оказания таких услуг;\n\n7) деятельности по совершению сделок с ценными бумагами и (или) производными финансовыми инструментами, а также по оказанию кредитных и иных финансовых услуг, за исключением услуг банковских платежных агентов (субагентов) по принятию от физических лиц наличных денежных средств и их внесению на банковские счета этих физических лиц и по выдаче физическим лицам наличных денежных средств с их банковских счетов, оказываемых банковскими платежными агентами (субагентами) этим физическим лицам при осуществлении ими розничной торговли через объекты стационарной торговой сети в сельских населенных пунктах, входящих в состав сельских поселений; (В редакции  Федерального закона от 23.11.2024 № 388-ФЗ)\n\n8) деятельности по производству ювелирных и других изделий из драгоценных металлов, а также оптовой либо розничной торговли ювелирными и другими изделиями из драгоценных металлов.\n\nПоложения настоящего подпункта не применяются в отношении деятельности по производству ювелирных и других изделий из серебра, а также оптовой либо розничной торговли ювелирными и другими изделиями из серебра; (Дополнение абзацем - Федеральный закон от 23.03.2024 № 49-ФЗ)\n\n(Дополнение под\n\nпунктом - Федеральный закон от 09.03.2022 № 47-ФЗ)\n\n9) осуществления майнинга цифровой валюты, а также сделок по реализации (приобретению) цифровой валюты. (Дополнение подпунктом - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n(Пункт в редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n1) в целях установления размеров потенциально возможного к получению индивидуальным предпринимателем годового дохода по видам деятельности, в отношении которых применяется патентная система налогообложения, дифференцировать виды предпринимательской деятельности, указанные в пункте 2 настоящей статьи, если такая дифференциация предусмотрена Общероссийским классификатором видов экономической деятельности и (или) Общероссийским классификатором продукции по видам экономической деятельности; (В редакции Федерального закона от 03.07.2016 № 248-ФЗ)\n\n11) в целях установления размеров потенциально возможного к получению индивидуальным предпринимателем годового дохода по видам деятельности, в отношении которых применяется патентная система налогообложения, дифференцировать территорию субъекта Российской Федерации по территориям действия патентов по муниципальным образованиям (группам муниципальных образований), за исключением патентов на осуществление видов предпринимательской деятельности, указанных в подпунктах 10, 11, 32, 33 и подпункте 46 (в части, касающейся развозной и разносной розничной торговли) пункта 2 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 21.07.2014 № 244-ФЗ)\n\n2) включать в перечень видов предпринимательской деятельности, в отношении которых может применяться патентная система налогообложения, виды деятельности, предусмотренные Общероссийским классификатором видов экономической деятельности и Общероссийским классификатором продукции по видам экономической деятельности, с учетом ограничений, предусмотренных пунктом 6 настоящей статьи; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n21) устанавливать следующие ограничения для применения патентной системы налогообложения:\n\nпо общей площади сдаваемых в аренду (наем) собственных или арендованных жилых помещений и (или) нежилых помещений (включая выставочные залы, складские помещения), земельных участков - по виду предпринимательской деятельности, указанному в подпункте 19 пункта 2 настоящей статьи; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\nпо общему количеству автотранспортных средств и судов водного транспорта - по видам предпринимательской деятельности, указанным в подпунктах 10, 11, 32 и 33 пункта 2 настоящей статьи;\n\nпо общему количеству объектов стационарной и нестационарной торговой сети и объектов организации общественного питания и (или) их общей площади - по видам предпринимательской деятельности, указанным в подпунктах 45 - 48 пункта 2 настоящей статьи;\n\nпо размеру площади торгового зала и (или) зала обслуживания посетителей объектов стационарной торговой сети и объектов организации общественного питания - по видам предпринимательской деятельности, указанным в подпунктах 45 и 47 пункта 2 настоящей статьи; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\nпо иным физическим показателям, характеризующим виды предпринимательской деятельности, в отношении которых может применяться патентная система налогообложения в соответствии с подпунктом 2 настоящего пункта; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n3) устанавливать размер потенциально возможного к получению индивидуальным предпринимателем годового дохода, в частности: (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\nна единицу средней численности наемных работников;\n\nна единицу автотранспортных средств, судов водного транспорта;\n\nна 1 тонну грузоподъемности транспортных средств, на одно пассажирское место - по видам предпринимательской деятельности, указанным в подпунктах 10, 11, 32 и 33 пункта 2 настоящей статьи;\n\nна 1 квадратный метр площади сдаваемого в аренду (наем) собственного или арендованного жилого помещения и (или) нежилого помещения (включая выставочные залы, складские помещения), земельного участка - по виду предпринимательской деятельности, указанному в подпункте 19 пункта 2 настоящей статьи; (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\nна один объект стационарной (нестационарной) торговой сети, объект организации общественного питания и (или) на 1 квадратный метр площади объекта стационарной (нестационарной) торговой сети, объекта организации общественного питания - по видам предпринимательской деятельности, указанным в подпунктах 45 - 48 пункта 2 настоящей статьи;\n\nв зависимости от территории действия патента с учетом положений подпункта 11 настоящего пункта;\n\nна 1 квадратный метр площади стоянки для транспортных средств - по виду предпринимательской деятельности, указанному в подпункте 65 пункта 2 настоящей статьи; (Дополнение абзацем - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n(Подпункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n4) (Подпункт утратил силу - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n5) в целях установления размера единого потенциально возможного к получению индивидуальным предпринимателем годового дохода объединять в одном патенте виды предпринимательской деятельности в области животноводства, в области растениеводства и (или) услуги, предоставляемые в указанных областях; (Дополнение подпунктом - Федеральный закон от 06.02.2020 № 8-ФЗ)\n\n6) предусматривать ежегодную индексацию размеров потенциально возможного к получению индивидуальным предпринимателем годового дохода по всем или отдельным видам предпринимательской деятельности, в отношении которых применяется патентная система налогообложения, на коэффициент-дефлятор, установленный на соответствующий календарный год. (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n10. Применение патентной системы налогообложения индивидуальными предпринимателями предусматривает их освобождение от обязанности по уплате:\n\n1) налога на доходы физических лиц (в части доходов, полученных при осуществлении видов предпринимательской деятельности, в отношении которых применяется патентная система налогообложения);\n\n2) налога на имущество физических лиц (в части имущества, используемого при осуществлении видов предпринимательской деятельности, в отношении которых применяется патентная система налогообложения, за исключением объектов налогообложения налогом на имущество физических лиц, включенных в перечень, определяемый в соответствии с пунктом 7 статьи 3782 настоящего Кодекса с учетом особенностей, предусмотренных абзацем вторым пункта 10 статьи 3782 настоящего Кодекса). (В редакции Федерального закона от 29.11.2014 № 382-ФЗ)\n\n11. Индивидуальные предприниматели, применяющие патентную систему налогообложения, не признаются налогоплательщиками налога на добавленную стоимость, за исключением налога на добавленную стоимость, подлежащего уплате в соответствии с настоящим Кодексом:\n\n1) при осуществлении видов предпринимательской деятельности, в отношении которых не применяется патентная система налогообложения;\n\n2) при ввозе товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, включая суммы налога, подлежащие уплате при завершении действия таможенной процедуры свободной таможенной зоны на территории Особой экономической зоны в Калининградской области; (В редакции Федерального закона от 30.03.2016 № 72-ФЗ)\n\n3) при осуществлении операций, облагаемых в соответствии со статьями 161 и 1741 настоящего Кодекса. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n12. Иные налоги индивидуальные предприниматели, применяющие патентную систему налогообложения, уплачивают в соответствии с законодательством о налогах и сборах, а также исполняют обязанности налоговых агентов, предусмотренные настоящим Кодексом.","article_title":"Статья 346.43. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0ebb788f4079845545518cc3968397a6c5950e135ecd534d84c0196ede6854c4"},{"code_id":"NK_RF_2","article_number":"346.44","version_date":"2000-07-31","article_text":"1. Налогоплательщиками признаются индивидуальные предприниматели, перешедшие на патентную систему налогообложения в порядке, установленном настоящей главой.\n\n2. Переход на патентную систему налогообложения или возврат к иным режимам налогообложения индивидуальными предпринимателями осуществляется добровольно в порядке, установленном настоящей главой.","article_title":"Статья 346.44. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03fc96773d04b180a25ae4605f2127b66ff1f9a9768a43cb4579225e5fd8ca4e"},{"code_id":"NK_RF_2","article_number":"346.45","version_date":"2000-07-31","article_text":"Форма патента и форма заявления на получение патента утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 21.07.2014 № 244-ФЗ)\n\nПатент действует на всей территории федеральной территории \"Сириус\". (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 02.12.2013 № 334-ФЗ)\n\nПатент действует на всей территории субъекта Российской Федерации, за исключением федеральной территории \"Сириус\", а также случаев, когда законом субъекта Российской Федерации определена территория действия патентов в соответствии с подпунктом 11 пункта 8 статьи 34643 настоящего Кодекса. В патенте должно содержаться указание на территорию его действия. (В редакции федеральных законов от 21.07.2014 № 244-ФЗ, от 11.06.2021 № 199-ФЗ)\n\nИндивидуальный предприниматель вправе получить несколько патентов. (В редакции Федерального закона от 21.07.2014 № 244-ФЗ)\n\nВ случае, если индивидуальный предприниматель планирует осуществлять предпринимательскую деятельность на основе патента на территории городов федерального значения Москвы, Санкт-Петербурга и Севастополя, заявление на получение патента подается в любой по выбору индивидуального предпринимателя территориальный налоговый орган соответствующего города федерального значения, в котором индивидуальный предприниматель планирует осуществлять предпринимательскую деятельность на основе патента, кроме случая, предусмотренного абзацем третьим настоящего пункта. (Дополнение абзацем - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\nВ случае, если физическое лицо планирует со дня его государственной регистрации в качестве индивидуального предпринимателя осуществлять предпринимательскую деятельность на основе патента в субъекте Российской Федерации либо федеральной территории \"Сириус\", на территории которых такое лицо состоит на учете в налоговом органе по месту жительства, заявление на получение патента подается одновременно с документами, представляемыми при государственной регистрации физического лица в качестве индивидуального предпринимателя. В этом случае действие патента, выданного индивидуальному предпринимателю, начинается со дня его государственной регистрации. (Дополнение абзацем - Федеральный закон от 02.12.2013 № 334-ФЗ) (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПри отправке заявления на получение патента по почте днем его представления считается дата отправки почтового отправления. При передаче заявления на получение патента по телекоммуникационным каналам связи днем его представления считается дата его отправки.\n\nПатент или уведомление об отказе в выдаче патента выдается индивидуальному предпринимателю под расписку или передается иным способом, свидетельствующим о дате его получения.\n\n(Пункт в редакции Федерального закона от 02.12.2013 № 334-ФЗ)\n\n1) несоответствие в заявлении на получение патента вида предпринимательской деятельности перечню видов предпринимательской деятельности, в отношении которых на территории субъекта Российской Федерации либо федеральной территории \"Сириус\" в соответствии со статьей 34643 настоящего Кодекса введена патентная система налогообложения; (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n2) указание срока действия патента, не соответствующего пункту 5 настоящей статьи;\n\n3) нарушение условия перехода на патентную систему налогообложения, установленного абзацем вторым пункта 8 настоящей статьи;\n\n4) наличие недоимки по налогу, подлежащему уплате в связи с применением патентной системы налогообложения; (В редакции Федерального закона от 02.12.2013 № 334-ФЗ)\n\n5) незаполнение обязательных полей в заявлении на получение патента. (Дополнение подпунктом - Федеральный закон от 21.07.2014 № 244-ФЗ)\n\n1) если за предшествующий календарный год или с начала календарного года доходы налогоплательщика от реализации, определяемые в соответствии со статьей 249 настоящего Кодекса, по всем видам предпринимательской деятельности, в отношении которых применяется патентная система налогообложения, превысили 60 млн. рублей; (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\n2) если в течение налогового периода налогоплательщиком было допущено несоответствие требованиям, установленным пунктами 5 и 6 статьи 34643 настоящего Кодекса; (В редакции Федерального закона от 06.02.2020 № 8-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n4) если в течение налогового периода налогоплательщиком, применяющим патентную систему налогообложения по видам предпринимательской деятельности, указанным в подпунктах 45 и 46 пункта 2 статьи 34643 настоящего Кодекса, была осуществлена реализация товаров, не относящихся к розничной торговле в соответствии с подпунктом 1 пункта 3 статьи 34643 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nВ случае, если налогоплательщик применяет в календарном году патентную систему налогообложения и упрощенную систему налогообложения, при определении величины доходов от реализации для целей соблюдения ограничения, установленного настоящим пунктом, учитываются доходы по обоим указанным специальным налоговым режимам. (В редакции  Федерального закона от 29.10.2024 № 362-ФЗ)\n\nСумма налога на доходы физических лиц, сумма налога, уплачиваемого при применении упрощенной системы налогообложения, сумма налога, уплачиваемого при применении системы налогообложения для сельскохозяйственных товаропроизводителей, подлежащие уплате за налоговый период, в котором индивидуальный предприниматель утратил право на применение патентной системы налогообложения в соответствии с пунктом 6 настоящей статьи, уменьшаются на сумму налога, уплаченного в связи с применением патентной системы налогообложения.\n\n(Пункт в редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nИндивидуальный предприниматель, утративший право на применение патентной системы налогообложения или прекративший предпринимательскую деятельность, в отношении которой применялась патентная система налогообложения, до истечения срока действия патента, вправе вновь перейти на патентную систему налогообложения по этому же виду предпринимательской деятельности не ранее чем со следующего календарного года.\n\nЗаявление об утрате права на применение патентной системы налогообложения подается в любой из налоговых органов, в которых индивидуальный предприниматель состоит на учете в качестве налогоплательщика, применяющего патентную систему налогообложения, по выбору этого индивидуального предпринимателя с указанием реквизитов всех имеющихся патентов с не истекшим на дату подачи указанного заявления сроком действия. Форма указанного заявления утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 02.12.2013 № 334-ФЗ) (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nПосле окончания периода прохождения мобилизованным лицом военной службы такое лицо в срок не позднее 15-го числа включительно третьего месяца, следующего за месяцем окончания периода частичной мобилизации, объявленной в соответствии с Указом, или увольнения мобилизованного лица с военной службы по основаниям, установленным Указом, вправе уведомить налоговый орган:\n\nо ведении в период его мобилизации предпринимательской деятельности, в отношении которой применялась патентная система налогообложения;\n\nо прекращении в период его мобилизации предпринимательской деятельности, в отношении которой применялась патентная система налогообложения, до истечения срока действия патента. В этом случае сумма налога пересчитывается в порядке, аналогичном порядку, установленному пунктом 1 статьи 34651 настоящего Кодекса;\n\nоб утрате права на применение в период его мобилизации патентной системы налогообложения.\n\nЕсли в течение указанного в абзаце втором настоящего пункта срока мобилизованное лицо не уведомило налоговый орган о ведении в период его мобилизации предпринимательской деятельности, в отношении которой применялась патентная система налогообложения, либо о прекращении такой деятельности в период его мобилизации до истечения срока действия патента, указанное лицо считается прекратившим предпринимательскую деятельность, в отношении которой применялась патентная система налогообложения, с даты начала его мобилизации. В этом случае сумма налога пересчитывается в порядке, аналогичном порядку, установленному пунктом 1 статьи 34651 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)","article_title":"Статья 346.45. Порядок и условия начала и прекращения применения патентной системы налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"733474bf2c937ceac1a839a5385c1edfd11c83d9ec9fe4c797829c23c7b0e7ce"},{"code_id":"NK_RF_2","article_number":"346.46","version_date":"2000-07-31","article_text":"1. Постановка на учет индивидуального предпринимателя в качестве налогоплательщика, применяющего патентную систему налогообложения, осуществляется налоговым органом, в который он обратился с заявлением на получение патента, на основании указанного заявления в течение пяти дней со дня его получения.\n\nВ случае, предусмотренном абзацем третьим пункта 2 статьи 34645 настоящего Кодекса, индивидуальный предприниматель подлежит постановке на учет в качестве налогоплательщика, применяющего патентную систему налогообложения, в налоговом органе по месту его жительства со дня государственной регистрации этого физического лица в качестве индивидуального предпринимателя. (Дополнение абзацем - Федеральный закон от 02.12.2013 № 334-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nДатой постановки индивидуального предпринимателя на учет в налоговом органе по основанию, предусмотренному настоящим пунктом, является дата начала действия патента.\n\nПодача индивидуальным предпринимателем заявления на получение патента в налоговый орган, в котором этот индивидуальный предприниматель состоит на учете в качестве налогоплательщика, применяющего патентную систему налогообложения, не влечет его повторную постановку на учет в этом налоговом органе в качестве налогоплательщика, применяющего патентную систему налогообложения. (Дополнение абзацем - Федеральный закон от 02.12.2013 № 334-ФЗ)\n\n2. Снятие с учета в налоговом органе индивидуального предпринимателя, применяющего патентную систему налогообложения, осуществляется в течение пяти дней со дня истечения срока действия патента, если иное не предусмотрено настоящей статьей.\n\nСнятие с учета в налоговом органе индивидуального предпринимателя, применяющего патентную систему налогообложения и имеющего одновременно несколько патентов, выданных указанным налоговым органом, осуществляется по истечении срока действия всех патентов. (Дополнение абзацем - Федеральный закон от 02.12.2013 № 334-ФЗ)\n\nДатой снятия с учета в налоговом органе индивидуального предпринимателя является дата перехода индивидуального предпринимателя на общий режим налогообложения (на упрощенную систему налогообложения, на систему налогообложения для сельскохозяйственных товаропроизводителей (в случае применения налогоплательщиком соответствующего специального налогового режима) или дата прекращения предпринимательской деятельности, в отношении которой применялась патентная система налогообложения. (В редакции федеральных законов от 27.11.2017 № 335-ФЗ, от 02.07.2021 № 305-ФЗ)","article_title":"Статья 346.46. Учет налогоплательщиков","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ca01108d7cd0ff2ae6b45edfb8ed2319d065ebf501892d1e2a123f77769e495"},{"code_id":"NK_RF_2","article_number":"346.47","version_date":"2000-07-31","article_text":"Объектом налогообложения признается потенциально возможный к получению годовой доход индивидуального предпринимателя по соответствующему виду предпринимательской деятельности, установленный законом субъекта Российской Федерации, если иное не предусмотрено настоящей статьей. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nВ федеральной территории \"Сириус\" объектом налогообложения признается потенциально возможный к получению годовой доход индивидуального предпринимателя по соответствующему виду предпринимательской деятельности, установленный законом Краснодарского края для города-курорта Сочи. (Дополнение частью - Федеральный закон от 11.06.2021 № 199-ФЗ)","article_title":"Статья 346.47. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63d583ac390543ef61e79cb0925370bbfcfe87a9092f499a7baf8c44586f1c1b"},{"code_id":"NK_RF_2","article_number":"346.48","version_date":"2000-07-31","article_text":"1. Налоговая база определяется как денежное выражение потенциально возможного к получению индивидуальным предпринимателем годового дохода по виду предпринимательской деятельности, в отношении которого применяется патентная система налогообложения в соответствии с настоящей главой, устанавливаемого на календарный год законом субъекта Российской Федерации.\n\nВ федеральной территории \"Сириус\" налоговая база определяется как денежное выражение потенциально возможного к получению индивидуальным предпринимателем годового дохода по виду предпринимательской деятельности, в отношении которого применяется патентная система налогообложения в соответствии с настоящей главой, устанавливаемого законом Краснодарского края для города-курорта Сочи. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\n2. Установленный на календарный год законом субъекта Российской Федерации размер потенциально возможного к получению индивидуальным предпринимателем годового дохода применяется в следующем календарном году (следующих календарных годах), если он не изменен законом субъекта Российской Федерации.","article_title":"Статья 346.48. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30721d860a9d2f39f85f2ccbefaf3ee32587bbf958652a9fe5312d8c4113086f"},{"code_id":"NK_RF_2","article_number":"346.5","version_date":"2000-07-31","article_text":"Абзац. (Утратил силу - Федеральный закон от 06.04.2015 № 84-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 06.04.2015 № 84-ФЗ)\n\nПри определении объекта налогообложения не учитываются: (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\nдоходы, указанные в статье 251 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 22.07.2008 № 155-ФЗ)\n\nдоходы организации, облагаемые налогом на прибыль организаций по налоговым ставкам, предусмотренным пунктами 16, 3 и 4 статьи 284 настоящего Кодекса, в порядке, установленном главой 25 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 22.07.2008 № 155-ФЗ) (В редакции Федерального закона от 24.11.2014 № 376-ФЗ)\n\nдоходы индивидуального предпринимателя в виде дивидендов, а также доходы индивидуального предпринимателя, облагаемые налогом на доходы физических лиц по налоговым ставкам, предусмотренным пунктами 2 и 5 статьи 224 настоящего Кодекса, в порядке, установленном главой 23 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 22.07.2008 № 155-ФЗ) (В редакции Федерального закона от 24.11.2014 № 366-ФЗ)\n\nдоходы в виде сумм возмещения в связи с изъятием земельных участков для государственных и муниципальных нужд собственникам этих земельных участков, землепользователям, землевладельцам и арендаторам этих земельных участков, а также правообладателям расположенных на этих земельных участках объектов недвижимости. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n1) расходы на приобретение, сооружение и изготовление основных средств, а также на достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств (с учетом положений пункта 4 и абзаца шестого подпункта 2 пункта 5 настоящей статьи); (В редакции федеральных законов от 13.03.2006 № 39-ФЗ; от 17.05.2007 № 85-ФЗ)\n\n2) расходы на приобретение нематериальных активов, создание нематериальных активов самим налогоплательщиком (с учетом положений пункта 4 и абзаца шестого подпункта 2 пункта 5 настоящей статьи); (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n3) расходы на ремонт основных средств (в том числе арендованных);\n\n4) арендные (в том числе лизинговые) платежи за арендуемое (в том числе принятое в лизинг) имущество;\n\n5) материальные расходы, включая расходы на приобретение семян, рассады, саженцев и другого посадочного материала, удобрений, кормов, лекарственных препаратов для ветеринарного применения, биопрепаратов и средств защиты растений; (В редакции федеральных законов от 13.03.2006 № 39-ФЗ; от 25.11.2013 № 317-ФЗ)\n\n6) расходы на оплату труда, выплату компенсаций, пос\n\nобий по временной нетрудоспособности в соответствии с законодательством Российской Федерации; (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\n61) расходы на обеспечение мер по технике безопасности, предусмотренных нормативными правовыми актами Российской Федерации, и расходы, связанные с содержанием помещений и инвентаря здравпунктов, находящихся непосредственно на территории организации; (Дополнение подпунктом - Федеральный закон от 22.07.2008 № 155-ФЗ)\n\n7) расходы на обязательное и добровольное страхование, которые включают страховые взносы по всем видам обязательного страхования, в том числе страховые взносы на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний, а также по следующим видам добровольного страхования: (В редакции Федерального закона от 24.07.2009 № 213-ФЗ)\n\nдобровольному страхованию средств транспорта (в том числе арендованного);\n\nдобровольному страхованию грузов;\n\nдобровольному страхованию основных средств производственного назначения (в том числе арендованных), нематериальных активов, объектов незавершенного капитального строительства (в том числе арендованных);\n\nдобровольному страхованию рисков, связанных с выполнением строительно-монтажных работ;\n\nдобровольному страхованию товарно-материальных запасов;\n\nдобровольному страхованию урожая сельскохозяйственных культур и животных;\n\nдобровольному страхованию иного имущества, используемого налогоплательщиком при осуществлении деятельности, направленной на получение дохода;\n\nдобровольному страхованию ответственности за причинение вреда, если такое страхование является условием осуществления налогоплательщиком деятельности в соответствии с международными обязательствами Российской Федерации или общепринятыми международными требованиями;\n\n(Подпункт в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n8) (Подпункт утратил силу - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\n9) суммы процентов, уплачиваемые за предоставление в пользование денежных средств (кредитов, займов), а также расходы, связанные с оплатой услуг, оказываемых кредитными организациями, в том числе связанные с продажей иностранной валюты при взыскании задолженности в порядке, предусмотренном статьей 46 настоящего Кодекса; (В редакции  федеральных законов от 27.07.2006 № 137-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n10) расходы на обеспечение пожарной безопасности в соответствии с законодательством Российской Федерации, расходы на услуги по охране имущества, обслуживанию охранно-пожарной сигнализации, расходы на приобретение услуг пожарной охраны и иных услуг охранной деятельности;\n\n11) суммы таможенных платежей, уплачиваемые при ввозе (вывозе) товаров на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, и не подлежащие возврату налогоплательщикам в соответствии с таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле; (В редакции федеральных законов от 27.11.2010 № 306-ФЗ; от 28.12.2010 № 395-ФЗ)\n\n12) расходы на содержание служебного транспорта, а также расходы на компенсацию за использование для служебных поездок личных легковых автомобилей и мотоциклов в пределах норм, установленных Правительством Российской Федерации;\n\n13) расходы на командировки, в частности на:\n\nпроезд работника к месту командировки и обратно к месту постоянной работы;\n\nнаем жилого помещения. По этой статье расходов подлежат возмещению также расходы работника на оплату дополнительных услуг, оказываемых в гостиницах (за исключением расходов на обслуживание в барах и ресторанах, расходов на обслуживание в номере, расходов за пользование рекреационно-оздоровительными объектами);\n\nсуточные или полевое довольствие; (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\nоформление и выдачу виз, паспортов, ваучеров, приглашений и иных аналогичных документов;\n\nконсульские, аэродромные сборы, сборы за право въезда, прохода, транзита автомобильного и иного транспорта, за пользование морскими каналами, другими подобными сооружениями и иные аналогичные платежи и сборы;\n\n14) плату нотариусу за нотариальное оформление документов. При этом такие расходы принимаются в пределах тарифов, утвержденных в установленном порядке;\n\n15) расходы на бухгалтерские, аудиторские и юридические услуги; (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n16) расходы на опубликование бухгалтерской (финансовой) отчетности, а также на опубликование и иное раскрытие другой информации, если законодательством Российской Федерации на налогоплательщика возложена обязанность осуществлять такое опубликование (раскрытие); (В редакции Федерального закона от 25.06.2012 № 94-ФЗ)\n\n17) расходы на канцелярские товары;\n\n18) расходы на почтовые, телефонные, телеграфные и другие подобные услуги, расходы на оплату услуг связи;\n\n19) расходы, связанные с приобретением права на использование программ для ЭВМ и баз данных по договорам с правообладателем (по лицензионным соглашениям). К указанным расходам относятся также расходы на обновление программ для ЭВМ и баз данных;\n\n20) расходы на рекламу производимых (приобретаемых) и (или) реализуемых товаров (работ, услуг), товарного знака и знака обслуживания;\n\n21) расходы на подготовку и освоение новых производств, цехов и агрегатов;\n\n22) расходы на питание работников, занятых на сельскохозяйственных работах;\n\n221) расходы на рацион питания экипажей морских и речных судов; (Дополнение подпунктом - Федеральный закон от 22.07.2008 № 155-ФЗ) (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n23) суммы налогов и сборов, уплаченные в соответствии с законодательством о налогах и сборах при самостоятельном исполнении обязанности по уплате налогов и сборов, за исключением единого сельскохозяйственного налога, уплаченного в соответствии с настоящей главой, налога на добавленную стоимость, уплаченного в бюджет в соответствии с пунктом 5 статьи 173 настоящего Кодекса, а также суммы туристического налога; (В редакции  федеральных законов от 06.04.2015 № 84-ФЗ, от 30.11.2016 № 401-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n231) суммы денежных средств, иного имущества, имущественных прав, переданные налогоплательщиком в счет погашения задолженности перед иным лицом, возникшей вследствие уплаты этим лицом в соответствии с настоящим Кодексом за налогоплательщика сумм налогов, сборов, страховых взносов, за исключением единого сельскохозяйственного налога, уплаченного в соответствии с настоящей главой, и налога на добавленную стоимость, уплаченного в бюджет в соответствии с пунктом 5 статьи 173 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n24) расходы на оплату стоимости товаров, приобретенных для дальнейшей реализации, в том числе расходы, связанные с приобретением и реализацией указанных товаров, включая расходы по хранению, обслуживанию и транспортировке;  (В редакции федеральных законов от 13.03.2006 № 39-ФЗ, от 29.09.2019 № 325-ФЗ)\n\n241) расходы в виде стоимости имущества (включая денежные средства), предназначенного для использования в целях предупреждения и предотвращения распространения, а также диагностики и лечения новой коронавирусной инфекции, безвозмездно переданного медицинским организациям, являющимся некоммерческими организациями, органам государственной власти и управления и (или) органам местного самоуправления, государственным и муниципальным учреждениям, государственным и муниципальным унитарным предприятиям; (Дополнение подпунктом - Федеральный закон от 08.06.2020 № 172-ФЗ)\n\n25) расходы на информационно-консультативные услуги;\n\n26) расходы на проведение независимой оценки квалификации на соответствие требованиям к квалификации, подготовку и переподготовку кадров, состоящих в штате налогоплательщика, на договорной основе в порядке, предусмотренном пунктом 3 статьи 264 настоящего Кодекса; (В редакции федеральных законов от 13.03.2006 № 39-ФЗ; от 03.07.2016 № 251-ФЗ)\n\n27) судебные расходы и арбитражные сборы;\n\n28) расходы в виде уплаченных на основании решения суда, вступившего в законную силу, штрафов, пеней и (или) иных санкций за нарушение договорных или долговых обязательств, а также расходы на возмещение причиненного ущерба; (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n29) расходы на обучение в профессиональных образовательных организациях и образовательных организациях высшего образования специалистов для налогоплательщиков. Указанные расходы учитываются для целей налогообложения при условии, что с обучающимися в указанных образовательных организациях физическими лицами заключены договоры (контракты) на обучение, предусматривающие их работу у налогоплательщика в течение не менее трех лет по специальности после окончания соответствующей образовательной организации; (Дополнение подпунктом - Федеральный закон от 29.06.2005 № 68-ФЗ) (В редакции Федерального закона от 27.11.2017 № 346-ФЗ)\n\n30) (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ) (Утратил силу - Федеральный закон от 25.06.2012 № 94-ФЗ)\n\n31) расходы на приобретение имущественных прав на земельные участки, включая расходы на приобретение права на заключение договора аренды земельных участков при условии заключения указанного договора аренды, в том числе:\n\nна земельные участки из земель сельскохозяйственного назначения;\n\nна земельные участки, которые находятся в государственной или муниципальной собственности и на которых расположены здания, строения, сооружения, используемые для сельскохозяйственного производства;\n\n(Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ) (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\n32) расходы на приобретение молодняка скота для последующего формирования основного стада, продуктивного скота, молодняка птицы и мальков рыбы; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n33) расходы на содержание вахтовых и временных поселков, связанных с сельскохозяйственным производством по пастбищному скотоводству; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n34) расходы на выплату комиссионных, агентских вознаграждений и вознаграждений по договорам поручения; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n35) расходы на сертификацию продукции; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n36) периодические (текущие) платежи за пользование правами на результаты интеллектуальной деятельности и правами на средства индивидуализации (в частности, правами, возникающими из патентов на изобретения, полезные модели, промышленные образцы); (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ) (В редакции Федерального закона от 23.11.2015 № 322-ФЗ)\n\n37) расходы на проведение (в случаях, установленных законодательством Российской Федерации) обязательной оценки в целях контроля за правильностью уплаты налогов в случае возникновения спора об исчислении налоговой базы, а также расходы на проведение оценки имущества при определении его рыночной стоимости в целях залога; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n38) плата за предоставление информации о зарегистрированных правах; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n39) расходы на оплату услуг специализированных организаций по изготовлению документов кадастрового и технического учета (инвентаризации) объектов недвижимости (в том числе правоустанавливающих документов на земельные участки и документов о межевании земельных участков); (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n40) расходы на оплату услуг специализированных организаций по проведению экспертизы, обследований, выдаче заключений и по предоставлению иных документов, наличие которых обязательно для получения лицензии (разрешения) на осуществление конкретного вида деятельности; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n41) расходы, связанные с участием в торгах (конкурсах, аукционах), проводимых при реализации заказов на поставку продукции, указанной в пункте 3 статьи 3462 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ) (В редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\n42) расходы в виде потерь от падежа и вынужденного убоя птицы и животных в пределах норм, утверждаемых Правительством Российской Федерации, за исключением случаев стихийных бедствий, пожаров, аварий, эпизоотий и других чрезвычайных ситуаций; (Дополнение подпунктом - Федеральный закон от 17.05.2007 № 85-ФЗ) (В редакции Федерального закона от 25.11.2009 № 275-ФЗ)\n\n43) суммы портовых сборов, расходы на услуги лоцмана и иные аналогичные расходы; (Дополнение подпунктом - Федеральный закон от 22.07.2008 № 155-ФЗ)\n\n44) расходы в виде потерь от стихийных бедствий, пожаров, аварий, эпизоотий и других чрезвычайных ситуаций, включая затраты, связанные с предотвращением и ликвидацией их последствий; (Дополнение подпунктом - Федеральный закон от 25.11.2009 № 275-ФЗ)\n\n45) сумму платы в счет возмещения вреда, причиняемого автомобильным дорогам общего пользования федерального значения транспортными средствами, имеющими разрешенную максимальную массу свыше 12 тонн, зарегистрированными в реестре транспортных средств системы взимания платы.\n\nФактически уплаченная в течение налогового периода сумма платы, указанной в абзаце первом настоящего подпункта, учитывается налогоплательщиками в расходах при исчислении налога за налоговый период в размере превышения фактически уплаченной суммы платы над суммой транспортного налога, исчисленной за налоговый период в соответствии с главой 28 настоящего Кодекса в отношении транспортных средств, имеющих разрешенную максимальную массу свыше 12 тонн, зарегистрированных в реестре транспортных средств системы взимания платы.\n\nПри исчислении авансовых платежей по налогу за отчетный период налогоплательщики учитывают в расходах фактически уплаченную сумму платы за отчетный период, уменьшенную на сумму авансовых платежей по транспортному налогу, исчисленную за первый и второй кварталы в соответствии с главой 28 настоящего Кодекса в отношении транспортных средств, имеющих разрешенную максимальную массу свыше 12 тонн, зарегистрированных в реестре транспортных средств системы взимания платы;\n\n(Дополнение подпунктом - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\n46) расходы на дезинфекцию помещений и приобретение приборов, лабораторного оборудования, спецодежды и других средств индивидуальной и коллективной защиты для выполнения санитарно-эпидемиологических и гигиенических требований органов государственной власти и органов местного самоуправления, их должностных лиц в связи с распространением новой коронавирусной инфекции; (Дополнение подпунктом - Федеральный закон от 22.04.2020 № 121-ФЗ)\n\n47) выплаты работникам в виде безотчетных сумм, право на выплаты которых установлено актом Президента Российской Федерации и (или) актом Правительства Российской Федерации, в целях возмещения их дополнительных расходов, связанных с командированием на территории, нуждающиеся в обеспечении жизнедеятельности населения и восстановлении объектов инфраструктуры, в размерах, определенных локальными нормативными актами работодателя, но не более 700 рублей за каждый день нахождения в такой командировке; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n48) расходы в виде безвозмездно переданных денежных средств и (или) иного имущества, указанных в пункте 93 статьи 217 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)\n\n49) расходы в виде стоимости имущества (за исключением денежных средств), работ, услуг, безвозмездно переданных являющимся казенными учреждениями воинским частям и организациям Вооруженных Сил Российской Федерации, войск национальной гвардии Российской Федерации, органов федеральной службы безопасности, при условии, что данные имущество, работы, услуги переданы в целях их использования указанными воинскими частями и организациями в ходе специальной военной операции. Факт получения указанными воинской частью или организацией данного имущества (результатов выполненных работ, оказанных услуг) и цели его (их) использования подтверждаются документом, подписанным командиром (руководителем) указанных воинской части или организации либо уполномоченным им лицом. (Дополнение подпунктом - Федеральный закон от 23.07.2025 № 227-ФЗ)\n\nРасходы, указанные в подпунктах 5, 6, 7, 9 - 21, 26 и 30 пункта 2 настоящей статьи, принимаются применительно к порядку, предусмотренному для исчисления налога на прибыль организаций в соответствии со статьями 254, 255, 263, 264, 265 и 269 настоящего Кодекса. (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n1) в отношении расходов на приобретение (сооружение, изготовление) в период применения единого сельскохозяйственного налога основных средств, а также расходов на достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств, произведенных в указанном периоде, - с момента ввода этих основных средств в эксплуатацию; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nв отношении приобретенных (созданных самим налогоплательщиком) в период применения единого сельскохозяйственного налога нематериальных активов - с момента принятия этих нематериальных активов на бухгалтерский учет;\n\n2) в отношении приобретенных (сооруженных, изготовленных) основных средств, а также приобретенных (созданных самим налогоплательщиком) нематериальных активов до перехода на уплату единого сельскохозяйственного налога стоимость основных средств и нематериальных активов включается в расходы в следующем порядке:\n\nв отношении основных средств и нематериальных активов со сроком полезного использования до трех лет включительно - в течение первого календарного года применения единого сельскохозяйственного налога; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nв отношении основных средств и нематериальных активов со сроком полезного использования от трех до 15 лет включительно: в течение первого календарного года применения единого сельскохозяйственного налога - 50 процентов стоимости, второго календарного года - 30 процентов стоимости и в течение третьего календарного года - 20 процентов стоимости; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nв отношении основных средств и нематериальных активов со сроком полезного использования свыше 15 лет - в течение первых 10 лет применения единого сельскохозяйственного налога равными долями от стоимости основных средств и нематериальных активов. (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nПри этом в течение налогового периода данные расходы принимаются равными долями.\n\nВ случае, если налогоплательщик перешел на уплату единого сельскохозяйственного налога с момента постановки на учет в налоговых органах, стоимость основных средств и нематериальных активов принимается по первоначальной стоимости этого имущества, определяемой в порядке, установленном законодательством Российской Федерации о бухгалтерском учете.\n\nВ случае, если налогоплательщик\n\nперешел на уплату единого сельскохозяйственного налога с иных режимов налогообложения, стоимость основных средств и нематериальных активов учитывается в порядке, установленном пунктами 61 и 9 статьи 3466 настоящего Кодекса.\n\nОпределение сроков полезного использования основных средств осуществляется на основании утверждаемой Правительством Российской Федерации в соответствии со статьей 258 настоящего Кодекса классификации основных средств, включаемых в амортизационные группы. Сроки полезного использования основных средств, которые не указаны в данной классификации, устанавливаются налогоплательщиком в соответствии с техническими условиями или рекомендациями организаций-изготовителей.\n\nАбзац. (Утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nОпределение сроков полезного использования нематериальных активов осуществляется в соответствии с пунктом 2 статьи 258 настоящего Кодекса.\n\nВ случае реализации (передачи) приобретенных (сооруженных, изготовленных, созданных самим налогоплательщиком) основных средств и нематериальных активов до истечения трех лет с момента учета расходов на их приобретение (сооружение, изготовление, достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение, а также создание самим налогоплательщиком) в составе расходов в соответствии с настоящей главой (в отношении основных средств и нематериальных активов со сроком полезного использования свыше 15 лет - до истечения 10 лет с момента их приобретения (сооружения, изготовления, создания самим налогоплательщиком) налогоплательщик обязан пересчитать налоговую базу за весь период пользования такими основными средствами и нематериальными активами с момента их учета в составе расходов на приобретение (сооружение, изготовление, достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение, а также создание самим налогоплательщиком) до даты реализации (передачи) с учетом положений главы 25 настоящего Кодекса и уплатить дополнительную сумму налога и пени. (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nВ состав основных средств и нематериальных активов в целях настоящей статьи включаются основные средства и нематериальные активы, которые признаются амортизируемым имуществом в соответствии с главой 25 настоящего Кодекса с учетом положений настоящей главы, а расходы на достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств определяются с учетом положений пункта 2 статьи 257 настоящего Кодекса. (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\n(Пункт в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\nСумма расходов на приобретение имущественных прав на земельные участки подлежит включению в состав расходов после фактической оплаты налогоплательщиком имущественных прав на земельные участки в размере уплаченных сумм и при наличии документально подтвержденного факта подачи документов на государственную регистрацию указанного права в случаях, установленных законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 22.07.2008 № 155-ФЗ)\n\nВ целях настоящего пункта под документальным подтверждением факта подачи документов на государственную регистрацию имущественных прав понимается расписка в получении органом, осуществляющим государственный кадастровый учет и государственную регистрацию прав на недвижимое имущество, документов на государственную регистрацию указанных прав. (Дополнение абзацем - Федеральный закон от 22.07.2008 № 155-ФЗ) (В редакции федеральных законов от 28.11.2009 № 283-ФЗ; от 30.11.2016 № 401-ФЗ)\n\nУказанные расходы отражаются в последний день отчетного (налогового) периода и учитываются только по земельным участкам, используемым при осуществлении предпринимательской деятельности. (Дополнение абзацем - Федеральный закон от 22.07.2008 № 155-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n1) в целях настоящей главы датой получения доходов признается день поступления средств на счета в банках, и (или) на счет цифрового рубля, и (или) в кассу, получения иного имущества (работ, услуг) и (или) имущественных прав, а также погашения задолженности иным способом (кассовый метод). (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПри использовании покупателем в расчетах за приобретенные им товары (работы, услуги) и (или) имущественные права векселя датой получения доходов у налогоплательщика признается дата оплаты векселя (день поступления денежных средств от векселедателя либо иного обязанного по указанному векселю лица) или день передачи налогоплательщиком указанного векселя по индоссаменту третьему лицу.\n\nСуммы выплат, полученные на содействие самозанятости безработных граждан и стимулирование создания безработными гражданами, открывшими собственное дело, дополнительных рабочих мест для трудоустройства безработных граждан за счет средств бюджетов бюджетной системы Российской Федерации в соответствии с программами, утверждаемыми соответствующими органами государственной власти, учитываются в составе доходов в течение трех налоговых периодов с одновременным отражением соответствующих сумм в составе расходов в пределах фактически осуществленных расходов каждого налогового периода, предусмотренных условиями получения указанных сумм выплат. (Дополнение абзацем - Федеральный закон от 05.04.2010 № 41-ФЗ)\n\nВ случае нарушения условий получения выплат, предусмотренных абзацем третьим настоящего подпункта, суммы полученных выплат в полном объеме отражаются в составе доходов налогового периода, в котором допущено нарушение. Если по окончании третьего налогового периода сумма полученных выплат, указанных в абзаце третьем настоящего подпункта, превышает сумму расходов, учтенных в соответствии с настоящим подпунктом, оставшиеся неучтенные суммы в полном объеме отражаются в составе доходов этого налогового периода. (Дополнение абзацем - Федеральный закон от 05.04.2010 № 41-ФЗ)\n\nСредства финансовой поддержки в виде субсидий, полученные в соответствии с Федеральным законом \"О развитии малого и среднего предпринимательства в Российской Федерации\", отражаются в составе доходов пропорционально расходам, фактически осуществленным за счет этого источника, но не более двух налоговых периодов с даты получения. Если по окончании второго налогового периода сумма полученных средств финансовой поддержки, указанных в настоящем пункте, превысит сумму признанных расходов, фактически осуществленных за счет этого источника, разница между указанными суммами в полном объеме отражается в составе доходов этого налогового периода. (Дополнение абзацем - Федеральный закон от 07.03.2011 № 23-ФЗ)\n\nВ случае возврата налогоплательщиком сумм, ранее полученных в счет предварительной оплаты поставки товаров, выполнения работ, оказания услуг, передачи имущественных прав, на сумму возврата уменьшаются доходы того налогового (отчетного) периода, в котором произведен возврат. (Дополнение абзацем - Федеральный закон от 25.06.2012 № 94-ФЗ) (В редакции Федерального закона от 29.12.2014 № 465-ФЗ)\n\nСредства финансовой поддержки, полученные за счет средств бюджетов бюджетной системы Российской Федерации по сертификату на привлечение трудовых ресурсов в субъекты Российской Федерации, включенные в перечень субъектов Российской Федерации, привлечение трудовых ресурсов в которые является приоритетным, в соответствии с Законом Российской Федерации от 19 апреля 1991 года № 1032-I \"О занятости населения в Российской Федерации\", учитываются в составе доходов в течение трех налоговых периодов с одновременным отражением соответствующих сумм в составе расходов в пределах фактически осуществленных расходов каждого налогового периода, предусмотренных условиями получения указанных средств финансовой поддержки. (Дополнение абзацем - Федеральный закон от 29.12.2014 № 465-ФЗ)\n\nВ случае нарушения условий получения средств финансовой поддержки, предусмотренных абзацем седьмым настоящего подпункта, сумма полученных средств финансовой поддержки в полном объеме отражается в составе доходов налогового периода, в котором допущено нарушение. Если по окончании третьего налогового периода сумма полученных средств указанной финансовой поддержки превышает сумму расходов, учтенных в соответствии с настоящим подпунктом, оставшиеся неучтенные суммы в полном объеме отражаются в составе доходов этого налогового периода. (Дополнение абзацем - Федеральный закон от 29.12.2014 № 465-ФЗ) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nПоложения абзаца пятого настоящего подпункта применяются как при расходовании средств субсидий после их получения, так и в целях возмещения расходов налогоплательщика, произведенных в налоговом периоде до получения средств субсидии в этом же налоговом периоде; (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n2) расходами налогоплательщика признаются затраты после их фактической оплаты. В целях настоящей главы оплатой товаров (работ, услуг) и (или) имущественных прав признается прекращение обязательства налогоплательщика - приобретателя указанных товаров (работ, услуг) и (или) имущественных прав перед продавцом, которое непосредственно связано с поставкой этих товаров (выполнением работ, оказанием услуг) и (или) передачей имущественных прав.\n\nПри этом расходы учитываются в составе расходов с учетом следующих особенностей:\n\nматериальные расходы, в том числе расходы на приобретение сырья и материалов (включая расходы на приобретение семян, рассады, саженцев и другого посадочного материала, удобрений, кормов, лекарственных препаратов для ветеринарного применения, биопрепаратов и средств защиты растений), а также расходы на оплату труда учитываются в составе расходов в момент погашения задолженности путем списания денежных средств с расчетного счета, счета цифрового рубля налогоплательщика, выплаты из кассы, а при ином способе погашения задолженности - в момент такого погашения. Аналогичный порядок применяется в отношении оплаты процентов за пользование заемными средствами (включая банковские кредиты) и при оплате услуг третьих лиц; (В редакции  федеральных законов от 25.11.2013 № 317-ФЗ, от 19.12.2023 № 610-ФЗ)\n\nрасходы по оплате стоимости товаров, приобретенных для дальнейшей реализации, в том числе расходы, связанные с приобретением и реализацией указанных товаров, включая расходы по хранению, обслуживанию и транспортировке, учитываются в составе расходов после их фактической оплаты;\n\nрасходы на уплату налогов, сборов и страховых взносов учитываются в составе расходов в размере, фактически уплаченном налогоплательщиком. При наличии задолженности по уплате налогов, сборов и страховых взносов расходы на ее погашение учитываются в составе расходов в пределах фактически погашенной задолженности в те отчетные (налоговые) периоды, когда налогоплательщик погашает указанную задолженность; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nрасходы на приобретение (сооружение, изготовление), достройку, дооборудование, реконструкцию, модернизацию и техническое перевооружение основных средств, а также расходы на приобретение (создание самим налогоплательщиком) нематериальных активов, учитываемые в порядке, предусмотренном пунктом 4 настоящей статьи, отражаются в последний день отчетного (налогового) периода в размере оплаченных сумм. При этом указанные расходы учитываются только по основным средствам и нематериальным активам, используемым при осуществлении предпринимательской деятельности; (В редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nпри выдаче налогоплательщиком продавцу в оплату приобретаемых товаров (работ, услуг) и (или) имущественных прав векселя расходы по приобретению указанных товаров (работ, услуг) и (или) имущественных прав учитываются после оплаты указанного векселя. При передаче налогоплательщиком продавцу в оплату приобретаемых товаров (работ, услуг) и (или) имущественных прав векселя, выданного третьим лицом, расходы по приобретению указанных товаров (работ, услуг) и (или) имущественных прав учитываются на дату передачи указанного векселя за приобретенные товары (выполненные работы, оказанные услуги) и (или) имущественные права. Указанные в настоящем подпункте расходы учитываются исходя из цены договора, но в размере, не превышающем суммы долгового обязательства, указанной в векселе;\n\nстоимость цифровой валюты определяется исходя из цены приобретения в порядке, предусмотренном абзацем вторым пункта 3 статьи 2823 настоящего Кодекса, но не выше дохода, полученного от ее реализации. При получении цифровой валюты налогоплательщиком без несения соответствующих расходов на ее приобретение стоимость такой цифровой валюты определяется в размере дохода исходя из рыночной котировки такой цифровой валюты на дату ее получения. При этом убытки, полученные от реализации цифровой валюты, не учитываются; (Дополнение абзацем - Федеральный закон от 29.11.2024 № 418-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\n(Пункт в редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\nИндивидуальные предприниматели ведут учет доходов и расходов для целей исчисления налоговой базы по единому сельскохозяйственному налогу в книге учета доходов и расходов индивидуальных предпринимателей, применяющих систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог), форма и порядок заполнения которой утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 13.03.2006 № 39-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)","article_title":"Статья 346.5. Порядок определения и признания доходов и расходов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6dd060d92d52c22f54694ad8b78ea7a05d621629783ec26f5089b76281e8ac3e"},{"code_id":"NK_RF_2","article_number":"346.50","version_date":"2000-07-31","article_text":"1. Налоговая ставка устанавливается в размере 6 процентов.\n\n2. Законами Республики Крым и города федерального значения Севастополя налоговая ставка может быть уменьшена на территориях соответствующих субъектов Российской Федерации для всех или отдельных категорий налогоплательщиков:\n\nв отношении периодов 2015 - 2016 годов - до 0 процентов;\n\nв отношении периодов 2017 - 2021 годов - до 4 процентов.\n\nНалоговые ставки, установленные в соответствии с настоящим пунктом законами Республики Крым и города федерального значения Севастополя, не могут быть повышены в течение периодов, указанных в настоящем пункте, начиная с календарного года, с которого применяется пониженная налоговая ставка.\n\nИндивидуальные предприниматели, указанные в абзаце первом настоящего пункта, вправе применять налоговую ставку в размере 0 процентов со дня их государственной регистрации в качестве индивидуального предпринимателя непрерывно не более двух налоговых периодов в пределах двух календарных лет.\n\nАбзац. (Утратил силу - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\nВ случае, если налогоплательщик осуществляет виды предпринимательской деятельности, в отношении которых применяется патентная система налогообложения с налоговой ставкой в размере 0 процентов, и иные виды предпринимательской деятельности, в отношении которых применяется патентная система налогообложения с налоговой ставкой в размере, установленном пунктом 1 настоящей статьи, или иной режим налогообложения, этот налогоплательщик обязан вести раздельный учет доходов.\n\nЗаконами субъектов Российской Федерации могут быть установлены ограничения на применение налогоплательщиками, указанными в абзаце первом настоящего пункта, налоговой ставки в размере 0 процентов, в том числе в виде:\n\nограничения средней численности работников;\n\nограничения предельного размера доходов от реализации, определяемых в соответствии со статьей 249 настоящего Кодекса, получаемых индивидуальным предпринимателем при осуществлении вида предпринимательской деятельности, в отношении которого применяется налоговая ставка в размере 0 процентов.\n\nВ случае нарушения ограничений на применение налоговой ставки в размере 0 процентов, установленных настоящей главой и законом субъекта Российской Федерации, индивидуальный предприниматель считается утратившим право на применение налоговой ставки в размере 0 процентов и обязан уплатить налог по налоговой ставке, предусмотренной пунктом 1 или 2 настоящей статьи, за налоговый период, в котором нарушены указанные ограничения.\n\nВиды предпринимательской деятельности в производственной, социальной и научной сферах, а также в сфере бытовых услуг населению, в отношении которых устанавливается налоговая ставка в размере 0 процентов, устанавливаются субъектами Российской Федерации на основании Общероссийского классификатора видов экономической деятельности, а также кодов услуг в соответствии с Общероссийским классификатором продукции по видам экономической деятельности, относящихся к бытовым услугам, определяемых Правительством Российской Федерации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 248-ФЗ) (В редакции Федерального закона от 23.11.2020 № 373-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2014 № 477-ФЗ)\n\n(Статья в редакции Федерального закона от 29.11.2014 № 379-ФЗ)","article_title":"Статья 346.50. Налоговая ставка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a52025775631f9c9acbb794bfa0689cd18345dc0a872ccdb94a7d40b2eb90d71"},{"code_id":"NK_RF_2","article_number":"346.51","version_date":"2000-07-31","article_text":"1. Налог исчисляется как соответствующая налоговой ставке процентная доля налоговой базы.\n\nВ случае получения индивидуальным предпринимателем патента на срок менее календарного года налог рассчитывается путем деления размера потенциально возможного к получению индивидуальным предпринимателем годового дохода на количество дней в этом календарном году и умножения полученного результата на налоговую ставку и количество дней срока, на который выдан патент. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВ случае прекращения предпринимательской деятельности, в отношении которой применяется патентная система налогообложения, до истечения срока действия патента сумма налога пересчитывается путем деления размера потенциально возможного к получению индивидуальным предпринимателем годового дохода на количество дней в этом календарном году и умножения полученного результата на налоговую ставку и количество дней, в течение которых индивидуальным предпринимателем применялась патентная система налогообложения. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n11. Налогоплательщики вправе уменьшить сумму налога на сумму расходов по приобретению контрольно-кассовой техники, включенной в реестр контрольно-кассовой техники, для использования при осуществлении расчетов в ходе предпринимательской деятельности, в отношении которой применяется патентная система налогообложения, в размере не более 18 000 рублей на каждый экземпляр контрольно-кассовой техники при условии регистрации указанной контрольно-кассовой техники в налоговых органах с 1 февраля 2017 года до 1 июля 2019 года, если иное не предусмотрено абзацем вторым настоящего пункта.\n\nИндивидуальные предприниматели, осуществляющие предпринимательскую деятельность, предусмотренную подпунктами 45 - 48 пункта 2 статьи 34643 настоящего Кодекса, и имеющие работников, с которыми заключены трудовые договоры на дату регистрации контрольно-кассовой техники, в отношении которой производится уменьшение суммы налога, вправе уменьшить сумму налога на сумму расходов, указанную в абзаце первом настоящего пункта, при условии регистрации соответствующей контрольно-кассовой техники с 1 февраля 2017 года до 1 июля 2018 года.\n\nВ целях настоящего пункта в расходы по приобретению контрольно-кассовой техники включаются затраты на покупку контрольно-кассовой техники, фискального накопителя, необходимого программного обеспечения, выполнение сопутствующих работ и оказание услуг (услуг по настройке контрольно-кассовой техники и прочих), в том числе затраты на приведение контрольно-кассовой техники в соответствие с требованиями, предъявляемыми Федеральным законом от 22 мая 2003 года № 54-ФЗ \"О применении контрольно-кассовой техники при осуществлении расчетов в Российской Федерации\". (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nУменьшение суммы налога в соответствии с абзацем первым настоящего пункта производится за налоговые периоды, которые начинаются в 2018 и 2019 годах и завершаются после регистрации индивидуальным предпринимателем соответствующей контрольно-кассовой техники.\n\nУменьшение суммы налога в соответствии с абзацем вторым настоящего пункта производится за налоговые периоды, которые начинаются в 2018 году и завершаются после регистрации индивидуальным предпринимателем соответствующей контрольно-кассовой техники.\n\nЕсли налогоплательщик получил в соответствующих периодах, указанных в абзацах четвертом и пятом настоящего пункта, несколько патентов и при исчислении налога по одному из них расходы по приобретению контрольно-кассовой техники с учетом ограничения, установленного абзацем первым настоящего пункта, превысили сумму этого налога, то он вправе уменьшить сумму налога, исчисленную по другому (другим) патенту, на сумму указанного превышения.\n\nНалогоплательщик направляет уведомление об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму расходов п\n\nо приобретению контрольно-кассовой техники в письменной или электронной форме с использованием усиленной квалифицированной электронной подписи по телекоммуникационным каналам связи в налоговый орган, в котором он состоит на учете в качестве налогоплательщика и в который уплачена (должна быть уплачена) сумма налога, подлежащая уменьшению.\n\nФорма, формат и порядок представления указанного уведомления утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nВ случае, если налоговый орган на основании имеющейся у него информации установит, что сведения, указанные в уведомлении об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, являются недостоверными или не соответствуют требованиям настоящего пункта, налоговый орган уведомляет об отказе в уменьшении суммы налога на расходы по приобретению контрольно-кассовой техники, в отношении которой установлены указанные недостоверность или несоответствие, в срок не позднее 20 дней со дня получения данного уведомления. В таком случае налогоплательщик должен уплатить налог в установленный срок без соответствующего уменьшения. Налогоплательщик вправе повторно представить уведомление об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, с исправленными сведениями. Если несоответствие сведений, указанных в настоящем абзаце, связано с указанием в уведомлении суммы уменьшения в размере большем, чем сумма, установленная абзацем первым настоящего пункта, налоговый орган отказывает в уменьшении суммы налога в соответствующей части.\n\nРасходы по приобретению контрольно-кассовой техники не учитываются при исчислении налога, если были учтены при исчислении налогов, уплачиваемых в связи с применением иных режимов налогообложения.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2017 № 349-ФЗ)\n\n12. Сумма налога, исчисленная за налоговый период, уменьшается на сумму:\n\n1) страховых взносов на обязательное пенсионное страхование, обязательное социальное страхование на случай временной нетрудоспособности и в связи с материнством, обязательное медицинское страхование, обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний, уплаченных (в пределах исчисленных сумм) в календарном году периода действия патента в соответствии с законодательством Российской Федерации (за исключением страховых взносов, установленных в соответствии со статьей 430 настоящего Кодекса), и страховых взносов на обязательное пенсионное страхование, обязательное медицинское страхование, подлежащих уплате в соответствии со статьей 430 настоящего Кодекса в календарном году периода действия патента; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) расходов по выплате в соответствии с законодательством Российской Федерации пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\", в части, не покрытой страховыми выплатами, произведенными работникам страховыми организациями, имеющими лицензии, выданные в соответствии с законодательством Российской Федерации, на осуществление соответствующего вида деятельности, по договорам с работодателями в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\";\n\n3) платежей (взносов) по договорам добровольного личного страхования, заключенным со страховыми организациями, имеющими лицензии, выданные в соответствии с законодательством Российской Федерации, на осуществление соответствующего вида деятельности, в пользу работников на случай их временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\". Указанные платежи (взносы) уменьшают сумму налога, если сумма страховой выплаты по таким договорам не превышает определяемого в соответствии с законодательством Российской Федерации размера пособия по временной нетрудоспособности (за исключением несчастных случаев на производстве и профессиональных заболеваний) за дни временной нетрудоспособности работника, которые оплачиваются за счет средств работодателя и число которых установлено Федеральным законом от 29 декабря 2006 года № 255-ФЗ \"Об обязательном социальном страховании на случай временной нетрудоспособности и в связи с материнством\".\n\nУказанные в настоящем пункте страховые платежи (взносы) и пособия уменьшают сумму налога, исчисленную за налоговый период, в случае их уплаты в пользу работников, занятых в тех сферах деятельности налогоплательщика, по которым уплачивается налог в связи с применением патентной системы налогообложения.\n\nПри этом налогоплательщики (за исключением налогоплательщиков, указанных в абзаце седьмом настоящего пункта) вправе уменьшить сумму налога на сумму указанных в настоящем пункте страховых платежей (взносов) и пособий, но не более чем на 50 процентов.\n\nНалогоплательщики, не производящие выплаты и иные вознаграждения физическим лицам, производят указанное уменьшение налога без установленного в абзаце шестом настоящего пункта ограничения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nЕсли налогоплательщик в календарном году получил несколько патентов и при исчислении налога по одному из них сумма страховых платежей (взносов) и пособий, указанных в настоящем пункте, превысила сумму этого налога с учетом ограничения, установленного абзацем шестым настоящего пункта, то он вправе уменьшить сумму налога, исчисленную по другому (другим) патенту, действующему в этом же календарном году, на сумму указанного превышения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалогоплательщик направляет уведомление об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму указанных в настоящем пункте страховых платежей (взносов) и пособий в письменной или электронной форме с использованием усиленной квалифицированной электронной подписи по телекоммуникационным каналам связи либо через личный кабинет налогоплательщика в налоговый орган по месту постановки на учет в качестве налогоплательщика, применяющего патентную систему налогообложения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nФорма, формат и порядок представления указанного уведомления утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nВ случае установления нарушений требований, установленных настоящим пунктом, налоговый орган уведомляет налогоплательщика через личный кабинет налогоплательщика (при отсутствии (прекращении) у налогоплательщика доступа к личному кабинету налогоплательщика - по почте заказным письмом) об отказе в уменьшении суммы налога в срок не позднее 20 дней со дня получения им уведомления об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму указанных в настоящем пункте страховых платежей (взносов) и пособий. В этом случае налогоплательщик должен уплатить налог в установленный пунктом 2 настоящей статьи срок без соответствующего уменьшения. Налогоплательщик вправе повторно представить уведомление об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму указанных в настоящем пункте страховых платежей (взносов) и пособий. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nЕсли в уведомлении об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму указанных в настоящем пункте страховых платежей (взносов) и пособий указана сумма страховых платежей (взносов) и пособий, уменьшающая сумму налога, уплачиваемого в связи с применением патентной системы налогообложения, в размере большем, чем сумма налога, подлежащая уменьшению в соответствии с настоящим пунктом, налоговый орган отказывает в уменьшении суммы налога в соответствующей части.\n\nЕсли по итогам календарного года, в котором применялась патентная система налогообложения и в котором произведено уменьшение суммы налога на основании уведомления об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму указанных в настоящем пункте страховых платежей (взносов) и пособий, будет установлено, что налог уменьшен в размере, превышающем размер исчисленных в этом календарном году страховых взносов, в случае:  (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nутраты силы государственной регистрации физического лица в качестве индивидуального предпринимателя; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nперехода в календарном году применения патентной системы налогообложения на применение специального налогового режима \"Налог на профессиональный доход\"; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nвозникновения оснований, указанных в пункте 7 статьи 430 настоящего Кодекса, (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nналоговым органом осуществляется перерасчет такого уменьшения, но не позднее двух лет со дня окончания срока действия патента, в отношении которого установлено такое превышение. В указанном случае налоговый орган уведомляет налогоплательщика через личный кабинет налогоплательщика о произведенном перерасчете (при отсутствии (прекращении) у налогоплательщика доступа к личному кабинету налогоплательщика - по почте заказным письмом). (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nУказанные в настоящем пункте страховые платежи (взносы) и пособия не учитываются при исчислении налогов, если они были учтены в целях налогообложения в соответствующем налоговом периоде, в том числе при исчислении налогов, уплачиваемых в связи с применением иных режимов налогообложения.\n\nСтраховые взносы, указанные в статье 430 настоящего Кодекса, считаются подлежащими уплате в календарном году, в котором применялась патентная система налогообложения, в том числе в случае, если срок уплаты таких страховых взносов приходится в соответствии с пунктом 7 статьи 61 настоящего Кодекса на первый рабочий день следующего года. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nСуммы страховых взносов, определяемые в соответствии со статьей 430 настоящего Кодекса, уплаченные после 31 декабря 2022 года за расчетные периоды, предшествующие 2023 году, уменьшают исчисленную за налоговые периоды 2023 - 2025 годов сумму налога. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 373-ФЗ)\n\n13. Налогоплательщики, местом жительства которых на дату регистрации контрольно-кассовой техники являлась территория Донецкой Народной Республики, Луганской Народной Республики, Запорожской области или Херсонской области, в дополнение к суммам уменьшения, установленным пунктом 12 настоящей статьи, вправе уменьшить сумму налога на сумму расходов на приобретение одного экземпляра контрольно-кассовой техники, включенной в реестр контрольно-кассовой техники, для использования при осуществлении расчетов в ходе предпринимательской деятельности, в отношении которой применяется патентная система налогообложения, в размере не более 28 000 рублей при условии регистрации такой контрольно-кассовой техники по адресу ее установки (применения), находящемуся на указанной территории, до 31 декабря 2025 года включительно.\n\nВ целях настоящего пункта в расходы на приобретение контрольно-кассовой техники включаются затраты на покупку контрольно-кассовой техники, фискального накопителя, необходимого программного обеспечения, выполнение сопутствующих работ и оказание услуг (услуг по настройке контрольно-кассовой техники и прочих услуг).\n\nУменьшение суммы налога в соответствии с абзацем первым настоящего пункта производится за налоговый период 2024 или 2025 года по выбору налогоплательщика. Если налогоплательщик получил в соответствующем налоговом периоде несколько патентов и при исчислении налога по одному из них расходы на приобретение контрольно-кассовой техники с учетом ограничения, установленного абзацем первым настоящего пункта, превысили сумму этого налога, то он вправе уменьшить сумму налога, исчисленную по другому патенту (другим патентам) в указанном налоговом периоде, на сумму указанного превышения.\n\nНалогоплательщик направляет уведомление об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму расходов на приобретение контрольно-кассовой техники в письменной или электронной форме с использованием усиленной квалифицированной электронной подписи по телекоммуникационным каналам связи либо через личный кабинет налогоплательщика в налоговый орган, в котором он состоит на учете в качестве налогоплательщика, применяющего патентную систему налогообложения.\n\nФорма, формат и порядок направления данного уведомления утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налоговый орган на основании имеющейся у него информации установит, что сведения, указанные в уведомлении об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму расходов на приобретение контрольно-кассовой техники, являются недостоверными или не соответствуют требованиям настоящего пункта, налоговый орган уведомляет об отказе в уменьшении суммы налога на расходы на приобретение контрольно-кассовой техники, в отношении которой установлены указанные недостоверность или несоответствие, в срок не позднее 20 дней со дня получения данного уведомления. В таком случае налогоплательщик должен уплатить налог в установленный срок без соответствующего уменьшения. Налогоплательщик вправе повторно представить уведомление об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму расходов на приобретение контрольно-кассовой техники с исправленными сведениями. Если несоответствие сведений, указанных в настоящем абзаце, связано с указанием в данном уведомлении суммы уменьшения в размере большем, чем сумма, установленная абзацем первым настоящего пункта, налоговый орган отказывает в уменьшении суммы налога в соответствующей части. Если по итогам календарного года, в котором применялась патентная система налогообложения и в котором произведено уменьшение суммы налога на основании уведомления об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму расходов на приобретение контрольно-кассовой техники, будет установлено, что налог уменьшен с нарушением требований, предусмотренных абзацами вторым и третьим настоящего пункта, налоговым органом осуществляется перерасчет такого уменьшения, но не позднее двух лет со дня представления уведомления об уменьшении суммы налога, уплачиваемого в связи с применением патентной системы налогообложения, на сумму расходов по приобретению контрольно-кассовой техники. В указанном случае налоговый орган уведомляет налогоплательщика через личный кабинет налогоплательщика о произведенном перерасчете (при отсутствии (прекращении) у налогоплательщика доступа к личному кабинету налогоплательщика налоговый орган уведомляет его по почте заказным письмом).\n\nРасходы на приобретение контрольно-кассовой техники не учитываются при исчислении налога, если они были учтены при исчислении налогов, уплачиваемых в связи с применением иных режимов налогообложения.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n1) если патент получен на срок до шести месяцев, - в размере полной суммы налога в срок не позднее срока окончания действия патента;\n\n2) если патент получен на срок от шести месяцев до календарного года:\n\nв размере одной трети суммы налога в срок не позднее девяноста календарных дней после начала действия патента;\n\nв размере двух третей суммы налога в срок не позднее срока окончания действия патента;\n\n3) если произведен перерасчет суммы налога в соответствии с абзацем третьим пункта 1 настоящей статьи, то сумма налога, подлежащая доплате, уплачивается не позднее 20 дней со дня снятия с учета налогоплательщика в налоговом органе в соответствии с пунктом 3 статьи 34646 настоящего Кодекса.\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.12.2014 № 477-ФЗ)","article_title":"Статья 346.51. Порядок исчисления налога, порядок и сроки уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5800c98fcf9b1513db29fab0797c442cb0fc078f71928e4beba7ba768d9d1aa0"},{"code_id":"NK_RF_2","article_number":"346.52","version_date":"2000-07-31","article_text":"Налоговая декларация по налогу, уплачиваемому в связи с применением патентной системы налогообложения, в налоговые органы не представляется.","article_title":"Статья 346.52. Налоговая декларация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"12f5f1bf532db687e4d19b8a7330100d72965559bfe1b74484759aa7d2be8f16"},{"code_id":"NK_RF_2","article_number":"346.53","version_date":"2000-07-31","article_text":"1) выплаты дохода, в том числе перечисления дохода на счета налогоплательщика в банках либо по его поручению на счета третьих лиц, - при получении дохода в денежной форме;\n\n2) передачи дохода в натуральной форме - при получении дохода в натуральной форме;\n\n3) получения иного имущества (работ, услуг) и (или) имущественных прав, а также погашения задолженности (оплаты) налогоплательщику иным способом.\n\nвекселю лица) или день передачи налогоплательщиком указанного векселя по индоссаменту третьему лицу.\n\nДоходы, полученные в натуральной форме, учитываются по рыночным ценам, определяемым с учетом положений статьи 1053 настоящего Кодекса.\n\nРАЗДЕЛ IX. РЕГИОНАЛЬНЫЕ НАЛОГИ И СБОРЫ\n\n(Дополнение разделом - Федеральный закон от 27.11.2001 № 148-ФЗ)\n\nГЛАВА 27. (Статьи 347 - 355)\n\n(Глава утратила силу  - Федеральный закон от 27.11.2001 № 148-ФЗ)\n\nГЛАВА 28. ТРАНСПОРТНЫЙ НАЛОГ\n\n(Дополнение главой - Федеральный закон от 24.07.2002 № 110-ФЗ)","article_title":"Статья 346.53. Налоговый учет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2972edd9904b43350063f4d31d881eff9dbcb0adbc3d9020bb423ed9b75fd59b"},{"code_id":"NK_RF_2","article_number":"346.6","version_date":"2000-07-31","article_text":"1. Налоговой базой признается денежное выражение доходов, уменьшенных на величину расходов.\n\n2. Доходы и расходы, выраженные в иностранной валюте, учитываются в совокупности с доходами и расходами, выраженными в рублях. При этом доходы и расходы, выраженные в иностранной валюте, пересчитываются в рубли по официальному курсу Центрального банка Российской Федерации, установленному соответственно на дату получения доходов и (или) дату осуществления расходов.\n\nНалогоплательщики вправе осуществлять перенос убытка на будущие налоговые периоды в течение 10 лет, следующих за тем налоговым периодом, в котором получен этот убыток.\n\nНалогоплательщики вправе перенести на текущий налоговый период сумму полученного в предыдущем налоговом периоде убытка.\n\nУбыток, не перенесенный на следующий год, может быть перенесен целиком или частично на любой год из последующих девяти лет.\n\nЕсли налогоплательщики получили убытки более чем в одном налоговом периоде, перенос таких убытков на будущие налоговые периоды производится в той очередности, в которой они получены.\n\nВ случае прекращения налогоплательщиками деятельности по причине реорганизации налогоплательщики-правопреемники вправе уменьшать налоговую базу в порядке и на условиях, которые предусмотрены настоящим пунктом, на сумму убытков, полученных реорганизуемыми организациями до момента реорганизации.\n\nНалогоплательщики обязаны хранить документы, подтверждающие размер полученного убытка и сумму, на которую была уменьшена налоговая база по каждому налоговому периоду, в течение всего срока использования права на уменьшение налоговой базы на сумму убытка.\n\nУбыток, полученный налогоплательщиками при применении иных режимов налогообложения, не принимается при переходе на уплату единого сельскохозяйственного налога.\n\nУбыток, полученный налогоплательщиками при уплате единого сельскохозяйственного налога, не принимается при переходе на иные режимы налогообложения.\n\n(Пункт в редакции Федерального закона от 22.07.2008 № 155-ФЗ)\n\n1) на дату перехода на уплату единого сельскохозяйственного налога в налоговую базу включаются суммы денежных средств, полученные до перехода на уплату единого сельскохозяйственного налога в оплату по договорам, исполнение которых налогоплательщики осуществляют после перехода на уплату единого сельскохозяйственного налога; (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n2) (Подпункт утратил силу - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n3) не включаются в налоговую базу денежные средства, полученные после перехода на уплату единого сельскохозяйственного налога, если по правилам налогового учета по методу начислений указанные суммы были включены в доходы при исчислении налоговой базы по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса; (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n4) расходы, осуществленные организацией после перехода на уплату единого сельскохозяйственного налога, признаются расходами, вычитаемыми из налоговой базы, на дату их осуществления, если оплата таких расходов была осуществлена до перехода на уплату единого сельскохозяйственного налога, либо на дату оплаты, если оплата таких расходов была осуществлена после перехода организации на уплату единого сельскохозяйственного налога; (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n5) не вычитаются из налоговой базы денежные средства, уплаченные после перехода на уплату единого сельскохозяйственного налога в оплату расходов организации, если до перехода на уплату единого сельскохозяйственного налога такие расходы были учтены при исчислении налоговой базы по налогу на прибыль организаций в соответствии с главой 25 настоящего Кодекса; (В редакции Федерального закона от 13.03.2006 № 39-ФЗ)\n\n6) материальные расходы и расходы на оплату труда, относящиеся к незавершенному производству на дату\n\nперехода на уплату единого сельскохозяйственного налога, оплаченные до перехода на уплату единого сельскохозяйственного налога, учитываются при определении налоговой базы по единому сельскохозяйственному налогу в отчетном (налоговом) периоде изготовления готовой продукции; (Дополнение подпунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n7) затраты на приобретение квот (долей) добычи (вылова) водных биологических ресурсов, фактически оплаченные до перехода на уплату единого сельскохозяйственного налога и не отнесенные на расходы при определении налоговой базы, включаются в налоговую базу на дату перехода на уплату единого сельскохозяйственного налога. (Дополнение подпунктом - Федеральный закон от 25.11.2009 № 275-ФЗ)\n\nПри переходе на уплату единого сельскохозяйственного налога организации, применяющей упрощенную систему налогообложения в соответствии с главой 262 настоящего Кодекса, в учете на дату такого перехода отражается остаточная стоимость приобретенных (сооруженных, изготовленных) основных средств и приобретенных (созданных самой организацией) нематериальных активов, определяемая в соответствии с пунктом 3 статьи 34625 настоящего Кодекса.\n\nАбзац. (Утратил силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 13.03.2006 № 39-ФЗ)\n\n1) признаются в составе доходов доходы в сумме выручки от реализации товаров (выполнения работ, оказания услуг, передачи имущественных прав) в период применения единого сельскохозяйственного налога, оплата (частичная оплата) которых не произведена до даты перехода на исчисление налоговой базы по налогу на прибыль по методу начисления;\n\n2) признаются в составе расходов расходы на приобретение в период применения единого сельскохозяйственного налога товаров (работ, услуг, имущественных прав), которые не были оплачены (частично оплачены) налогоплательщиком до даты перехода на исчисление налоговой базы по налогу на прибыль по методу начисления, если иное не предусмотрено главой 25 настоящего Кодекса.\n\n(Пункт в редакции Федерального закона от 17.05.2007 № 85-ФЗ)\n\nДоходы и расходы по видам деятельности, в отношении которых применяется патентная система налогообложения в соответствии с главой 265 настоящего Кодекса (с учетом положений, установленных настоящей главой), не учитываются при исчислении налоговой базы по единому сельскохозяйственному налогу. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 13.03.2006 № 39-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)","article_title":"Статья 346.6. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b369300ed11bd5689ac76b21815be1193c764083274520f7276dbf96cc0bdf8"},{"code_id":"NK_RF_2","article_number":"346.7","version_date":"2000-07-31","article_text":"1. Налоговым периодом признается календарный год.\n\n2. Отчетным периодом признается полугодие.","article_title":"Статья 346.7. Налоговый период. Отчетный период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8604847716fe4e8e39120c19d14ee395516b9201c6c504882626991e598eec43"},{"code_id":"NK_RF_2","article_number":"346.8","version_date":"2000-07-31","article_text":"1. Налоговая ставка устанавливается в размере 6 процентов.\n\n2. Законами субъектов Российской Федерации могут быть установлены дифференцированные налоговые ставки в пределах от 0 до 6 процентов для всех или отдельных категорий налогоплательщиков в зависимости:\n\nот видов производимой сельскохозяйственной продукции, а также работ и услуг, указанных в статье 3462 настоящего Кодекса;\n\nот размера доходов от реализации произведенной сельскохозяйственной продукции, включая продукцию ее первичной переработки, произведенную из сельскохозяйственного сырья собственного производства, а также от выполнения работ и оказания услуг, указанных в статье 3462 настоящего Кодекса;\n\nот места ведения предпринимательской деятельности;\n\nот средней численности работников.\n\n(Пункт в редакции Федерального закона от 07.03.2018 № 51-ФЗ)\n\n(Статья в редакции Федерального закона от 29.11.2014 № 379-ФЗ)","article_title":"Статья 346.8. Налоговая ставка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d6a19ef9126fe84b4af322be15967fffc1324172d66ceef93f8b5d76a75b7b1"},{"code_id":"NK_RF_2","article_number":"346.9","version_date":"2000-07-31","article_text":"1. Единый сельскохозяйственный налог исчисляется как соответствующая налоговой ставке процентная доля налоговой базы.\n\n2. Налогоплательщики по итогам отчетного периода исчисляют сумму авансового платежа по единому сельскохозяйственному налогу, исходя из налоговой ставки и фактически полученных доходов, уменьшенных на величину расходов, рассчитанных нарастающим итогом с начала налогового периода до окончания полугодия.\n\nАвансовые платежи по единому сельскохозяйственному налогу уплачиваются не позднее 28 календарных дней со дня окончания отчетного периода. (Дополнение абзацем - Федеральный закон от 03.06.2005 № 55-ФЗ) (В редакции  федеральных законов от 27.07.2006 № 137-ФЗ, от 28.12.2022 № 565-ФЗ)\n\n3. Уплаченные авансовые платежи по единому сельскохозяйственному налогу засчитываются в счет уплаты единого сельскохозяйственного налога по итогам налогового периода.","article_title":"Статья 346.9. Порядок исчисления и уплаты единого сельскохозяйственного налога. Зачисление сумм единого сельскохозяйственного налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"537eab4fa8a20d9459c0cd61204c7eafcbe50f9026082b14a8148d19896d6a9f"},{"code_id":"NK_RF_2","article_number":"356","version_date":"2000-07-31","article_text":"Транспортный налог (далее в настоящей главе - налог) устанавливается настоящим Кодексом и законами субъектов Российской Федерации о налоге, вводится в действие в соответствии с настоящим Кодексом законами субъектов Российской Федерации о налоге и обязателен к уплате на территории соответствующего субъекта Российской Федерации, если иное не предусмотрено статьей 3561 настоящего Кодекса. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nУстанавливая налог, законодательные органы субъектов Российской Федерации определяют налоговую ставку в пределах, установленных настоящей главой. В отношении налогоплательщиков-организаций законодательные органы субъектов Российской Федерации, устанавливая налог, определяют также порядок уплаты налога. (В редакции  федеральных законов от 04.10.2014 № 284-ФЗ, от 29.09.2019 № 325-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nПри установлении налога законами субъектов Российской Федерации могут также предусматриваться налоговые льготы, основания и порядок их применения. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)","article_title":"Статья 356. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"542a75037c246e1d569774fa43ff49a4a7a0605d5041cc47833f3b77439f3fde"},{"code_id":"NK_RF_2","article_number":"356.1","version_date":"2000-07-31","article_text":"1. Налог, обязательный к уплате в федеральной территории \"Сириус\", устанавливается настоящей главой.\n\n2. Налогообложение в федеральной территории \"Сириус\" производится по налоговым ставкам, установленным пунктом 1 статьи 361 настоящего Кодекса.\n\n3. От уплаты налога освобождаются следующие лица, на которых зарегистрированы транспортные средства, имеющие место нахождения в федеральной территории \"Сириус\":\n\n1) Герои Советского Союза, Герои Российской Федерации, Герои Социалистического Труда, полные кавалеры орденов Славы, Трудовой Славы, Герои Кубани, Герои труда Кубани, ветераны Великой Отечественной войны, ветераны боевых действий, физические лица, имеющие право на получение социальной поддержки в соответствии с Законом Российской Федерации от 15 мая 1991 года № 1244-I \"О социальной защите граждан, подвергшихся воздействию радиации вследствие катастрофы на Чернобыльской АЭС\", в соответствии с Федеральным законом от 26 ноября 1998 года № 175-ФЗ \"О социальной защите граждан Российской Федерации, подвергшихся воздействию радиации вследствие аварии в 1957 году на производственном объединении \"Маяк\" и сбросов радиоактивных отходов в реку Теча\" и в соответствии с Федеральным законом от 10 января 2002 года № 2-ФЗ \"О социальных гарантиях гражданам, подвергшимся радиационному воздействию вследствие ядерных испытаний на Семипалатинском полигоне\", физические лица, принимавшие непосредственное участие в составе подразделений особого риска в испытаниях ядерного и термоядерного оружия, ликвидации аварий ядерных установок на средствах вооружения и военных объектах, инвалиды I и II групп - в отношении автомобилей легковых с мощностью двигателя до 150 лошадиных сил включительно, моторных лодок с мощностью двигателя до 20 лошадиных сил включительно, мотоциклов и мотороллеров с мощностью двигателя до 35 лошадиных сил включительно;\n\n2) лица, имеющие трех и более несовершеннолетних детей, - в отношении автомобилей легковых с мощностью двигателя до 150 лошадиных сил включительно, автобусов с мощностью двигателя до 150 лошадиных сил включительно;\n\n3) один из родителей (законных представителей) ребенка-инвалида, имеющего заключение о наличии медицинских показаний для приобретения транспортного средства в соответствии с индивидуальной программой реабилитации или абилитации ребенка-инвалида, выдаваемой федеральными государственными учреждениями медико-социальной экспертизы, - в отношении автомобилей легковых с мощностью двигателя до 150 лошадиных сил включительно;\n\n4) организации и физические лица - в отношении автомобилей, оснащенных исключительно электрическими двигателями мощностью до 150 лошадиных сил включительно.\n\n(Дополнение пунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 11.06.2021 № 199-ФЗ)","article_title":"Статья 356.1. Особенности установления налога и налогообложения в федеральной территории \"Сириус\"","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7d5c6520e8feca7fab40875c7e873645132e122dcc44d6d8c6859f2c8cf35c77"},{"code_id":"NK_RF_2","article_number":"357","version_date":"2000-07-31","article_text":"Налогоплательщиками налога (далее в настоящей главе - налогоплательщики) признаются лица, на которых в соответствии с законодательством Российской Федерации зарегистрированы транспортные средства, признаваемые объектом налогообложения в соответствии со статьей 358 настоящего Кодекса. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nЧасть. (Утратила силу - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nНе признаются налогоплательщиками лица, являющиеся организаторами XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи в соответствии со статьей 3 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", а также лица, являющиеся маркетинговыми партнерами Международного олимпийского комитета в соответствии со статьей 31 указанного Федерального закона, в отношении транспортных средств, принадлежащих им на праве собственности и используемых исключительно в связи с организацией и (или) проведением XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи и развитием города Сочи как горноклиматического курорта. (Дополнение частью - Федеральный закон от 01.12.2007 № 310-ФЗ) (В редакции Федерального закона от 30.07.2010 № 242-ФЗ)\n\nНе признаются налогоплательщиками UEFA (Union of European Football Associations) и дочерние организации UEFA в период по 31 декабря 2021 года включительно, FIFA (Federation Internationale de Football Association) и дочерние организации FIFA, указанные в Федеральном законе \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\". (Дополнение частью - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции федеральных законов от 01.05.2019 № 101-ФЗ, от 20.04.2021 № 101-ФЗ)\n\nНе признаются налогоплательщиками конфедерации, национальные футбольные ассоциации (в том числе Российский футбольный союз), Организационный комитет \"Россия-2018\", дочерние организации Организационного комитета \"Россия-2018\", производители медиаинформации FIFA, поставщики товаров (работ, услуг) FIFA, определенные Федеральным законом \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\", в отношении транспортных средств, принадлежащих им на праве собственности и используемых только в целях осуществления мероприятий, предусмотренных указанным Федеральным законом, а также в период по 31 декабря 2021 года включительно Российский футбольный союз, локальная организационная структура, коммерческие партнеры UEFA, поставщики товаров (работ, услуг) UEFA и вещатели UEFA, определенные указанным Федеральным законом, в отношении транспортных средств, принадлежащих им на праве собственности и используемых только в целях осуществления мероприятий по подготовке и проведению в Российской Федерации чемпионата Европы по футболу UEFA 2020 года, предусмотренных указанным Федеральным законом. (Дополнение частью - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции федеральных законов от 01.05.2019 № 101-ФЗ, от 20.04.2021 № 101-ФЗ)\n\nНе признаются налогоплательщиками организации, зарегистрированные на территории Курильских островов, в течение периода использования такими организациями права на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций в соответствии со статьей 2463 настоящего Кодекса. В случае утраты организацией в соответствии с пунктом 3 статьи 2463 настоящего Кодекса такого права она признается налогоплательщиком с 1-го числа налогового периода, в котором утрачено такое право, и сумма налога (авансового платежа по налогу) подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих пеней, начисляемых со дня, следующего за установленным статьей 363 настоящего Кодекса днем уплаты налога (авансового платежа по налогу). (Дополнение частью - Федеральный закон от 09.03.2022 № 50-ФЗ)","article_title":"Статья 357. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6220a74e277e09d47315e3e9b91b46d70e4d6fd7e7f92ef058b69a12b2ac093d"},{"code_id":"NK_RF_2","article_number":"358","version_date":"2000-07-31","article_text":"1. Объектом налогообложения признаются автомобили, мотоциклы, мотороллеры, автобусы и другие самоходные машины и механизмы на пневматическом и гусеничном ходу, самолеты, вертолеты, теплоходы, яхты, парусные суда, катера, снегоходы, мотосани, моторные лодки, гидроциклы, несамоходные (буксируемые суда) и другие водные и воздушные транспортные средства (далее в настоящей главе - транспортные средства), зарегистрированные в установленном порядке в соответствии с законодательством Российской Федерации.\n\n2. Не являются объектом налогообложения:\n\n1) (Подпункт утратил силу - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\n2) автомобили легковые, специально оборудованные для использования инвалидами, а также автомобили легковые с мощностью двигателя до 100 лошадиных сил (до 73,55 кВт), полученные (приобретенные) через органы социальной защиты населения в установленном законом порядке;\n\n3) промысловые морские и речные суда;\n\n4) пассажирские и грузовые морские, речные и воздушные суда, находящиеся в собственности (на праве хозяйственного ведения или оперативного управления) организаций и индивидуальных предпринимателей, основным видом деятельности которых является осуществление пассажирских и (или) грузовых перевозок; (В редакции Федерального закона от 27.12.2009 № 368-ФЗ)\n\n5) тракторы, самоходные комбайны, самоходные машины для перевозки и внесения минеральных удобрений, специальные и специализированные автотранспортные средства, зарегистрированные на сельскохозяйственных товаропроизводителей и используемые при сельскохозяйственных работах для производства сельскохозяйственной продукции; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n6) транспортные средства, принадлежащие на праве оперативного управления федеральным органам исполнительной власти и федеральным государственным органам, в которых законодательством Российской Федерации предусмотрена военная и (или) приравненная к ней служба; (В редакции федеральных законов от 28.11.2009 № 283-ФЗ; от 04.06.2014 № 145-ФЗ)\n\n7) (Подпункт утратил силу - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n8) самолеты и вертолеты санитарной авиации и медицинской службы;\n\n9) суда, зарегистрированные в Российском международном реестре судов; (Дополнение подпунктом - Федеральный закон от 20.12.2005 № 168-ФЗ)\n\n10) морские стационарные и плавучие платформы, морские передвижные буровые установки и буровые суда; (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n11) суда, зарегистрированные в Российском открытом реестре судов лицами, получившими статус участника специального административного района в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\"; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n12) воздушные суда, зарегистрированные в Государственном реестре гражданских воздушных судов лицами, получившими статус участника специального административного района в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\"; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n13) весельные лодки, а также моторные лодки с двигателем мощностью не свыше 5 лошадиных сил, зарегистрированные в порядке, установленном до дня вступления в силу Федерального закона от 23 апреля 2012 года № 36-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации в части определения понятия маломерного судна\". (Дополнение подпунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)","article_title":"Статья 358. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd5162c4aeb8de759dee334d76331a49875126b92a56c340aafbfa8bf3087a41"},{"code_id":"NK_RF_2","article_number":"359","version_date":"2000-07-31","article_text":"1. Налоговая база определяется:\n\n1) в отношении транспортных средств, имеющих двигатели (за исключением транспортных средств, указанных в подпункте 11 настоящего пункта), - как мощность двигателя транспортного средства в лошадиных силах; (В редакции Федерального закона от 20.08.2004 № 108-ФЗ)\n\n11) в отношении воздушных транспортных средств, для которых определяется тяга реактивного двигателя, - как паспортная статическая тяга реактивного двигателя (суммарная паспортная статическая тяга всех реактивных двигателей) воздушного транспортного средства на взлетном режиме в земных условиях в килограммах силы; (Дополнение подпунктом - Федеральный закон от 20.08.2004 № 108-ФЗ)\n\n2) в отношении водных несамоходных (буксируемых) транспортных средств, для которых определяется валовая вместимость, - как валовая вместимость; (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n3) в отношении водных и воздушных транспортных средств, не указанных в подпунктах 1, 11 и 2 настоящего пункта, - как единица транспортного средства. (В редакции Федерального закона от 20.08.2004 № 108-ФЗ)\n\nВ отношении транспортных средств, указанных в подпункте 3 пункта 1 настоящей статьи, налоговая база определяется отдельно.","article_title":"Статья 359. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"571da1fd77c2c780447986cd7a55ee58197a92f19450b46e392e420db37470bd"},{"code_id":"NK_RF_2","article_number":"360","version_date":"2000-07-31","article_text":"1. Налоговым периодом признается календарный год.\n\n(Статья в редакции Федерального закона от 20.10.2005 № 131-ФЗ)","article_title":"Статья 360. Налоговый период. Отчетный период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d22da1749202c5aad468defc91d6decb088cbdfff00a7bb4b3a31694b34a0dd4"},{"code_id":"NK_RF_2","article_number":"361","version_date":"2000-07-31","article_text":"Автомобили легковые с мощностью двигателя (с каждой лошадиной силы):\n\nдо 100 л. с. (до 73,55 кВт) включительно\n\nсвыше 100 л. с. до 150 л. с. (свыше 73,55 кВт до 110,33 кВт) включительно\n\nсвыше 150 л. с. до 200 л. с. (свыше 110,33 кВт до 147,1 кВт) включительно\n\nсвыше 200 л. с. до 250 л. с. (свыше 147,1 кВт до 183,9 кВт) включительно\n\nсвыше 250 л. с. (свыше 183,9 кВт)\n\nМотоциклы и мотороллеры с мощностью двигателя (с каждой лошадиной силы):\n\nдо 20 л. с. (до 14,7 кВт) включительно\n\nсвыше 20 л. с. до 35 л. с. (свыше 14,7 кВт до 25,74 кВт) включительно\n\nсвыше 35 л. с. (свыше 25,74 кВт)\n\nАвтобусы с мощностью двигателя (с каждой лошадиной силы):\n\nдо 200 л. с. (до 147,1 кВт) включительно\n\nсвыше 200 л. с. (свыше 147,1 кВт)\n\nАвтомобили грузовые с мощностью двигателя(с каждой лошадиной силы):\n\nдо 100 л. с. (до 73,55 кВт) включительно\n\nсвыше 100 л. с. до 150 л. с. (свыше 73,55 кВт до 110,33 кВт) включительно\n\nсвыше 150 л. с. до 200 л. с. (свыше 110,33 кВт до 147,1 кВт) включительно\n\nсвыше 200 л. с. до 250 л. с. (свыше 147,1 кВт до 183,9 кВт) включительно\n\nсвыше 250 л. с. (свыше 183,9 кВт)\n\nДругие самоходные транспортные средства, машины и механизмы на пневматическом и гусеничном ходу (с каждой лошадиной силы)\n\nСнегоходы, мотосани с мощностью двигателя(с каждой лошадиной силы):\n\nдо 50 л. с. (до 36,77 кВт) включительно\n\nсвыше 50 л. с. (свыше 36,77 кВт)\n\nКатера, моторные лодки и другие водные транспортные средства с мощностью двигателя (с каждой лошадиной силы):\n\nдо 100 л. с. (до 73,55 кВт) включительно\n\nсвыше 100 л. с. (свыше 73,55 кВт)\n\nЯхты и другие парусно-моторные суда с мощностью двигателя (с каждой лошадиной силы):\n\nдо 100 л. с. (до 73,55 кВт) включительно\n\nсвыше 100 л. с. (свыше 73,55 кВт)\n\nГидроциклы с мощностью двигателя (с каждой лошадиной силы):\n\nдо 100 л. с. (до 73,55 кВт) включительно\n\nсвыше 100 л. с. (свыше 73,55 кВт)\n\nНесамоходные (буксируемые) суда, для которых определяется валовая вместимость (с каждой регистровой тонны или единицы валовой вместимости в случае, если валовая вместимость определена без указания размерности) (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nСамолеты, вертолеты и иные воздушные суда, имеющие двигатели (с каждой лошадиной силы)\n\nСамолеты, имеющие реактивные двигатели (с каждого килограмма силы тяги)\n\nДругие водные и воздушные транспортные средства, не имеющие двигателей (с единицы транспортного средства)\n\n(Пункт в редакции Федерального закона от 27.11.2010 № 307-ФЗ)\n\nУказанное ограничение размера уменьшения налоговых ставок законами субъектов Российской Федерации не применяется в отношении автомобилей легковых с мощностью двигателя (с каждой лошадиной силы) до 150 л. с. (до 110,33 кВт) включительно. (Дополнение абзацем - Федеральный закон от 27.11.2010 № 307-ФЗ)\n\nКоличество лет, прошедших с года выпуска транспортного средства, определяется по состоянию на 1 января текущего года в календарных годах с года, следующего за годом выпуска транспортного средства. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 282-ФЗ)","article_title":"Статья 361. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"42e3243ec697dbba553ed51b07d421006d1c33c4ea5c103c92174106049cd0a7"},{"code_id":"NK_RF_2","article_number":"361.1","version_date":"2000-07-31","article_text":"1. Освобождаются от налогообложения физические лица в отношении каждого транспортного средства, имеющего разрешенную максимальную массу свыше 12 тонн, зарегистрированного в реестре транспортных средств системы взимания платы (далее в настоящей главе - реестр), если сумма платы в счет возмещения вреда, причиняемого автомобильным дорогам общего пользования федерального значения транспортными средствами, имеющими разрешенную максимальную массу свыше 12 тонн (далее в настоящей главе - плата), уплаченная в налоговом периоде в отношении такого транспортного средства, превышает или равна сумме исчисленного налога за данный налоговый период.\n\n2. Если сумма исчисленного налога в отношении транспортного средства, имеющего разрешенную максимальную массу свыше 12 тонн, зарегистрированного в реестре, превышает сумму платы, уплаченную в отношении такого транспортного средства в данном налоговом периоде, налоговая льгота предоставляется в размере суммы платы путем уменьшения суммы налога на сумму платы.\n\nВ случае, если документы, подтверждающие право налогоплательщика на налоговую льготу, в налоговом органе отсутствуют, в том числе не представлены налогоплательщиком самостоятельно, налоговый орган по информации, указанной в заявлении налогоплательщика о предоставлении налоговой льготы, запрашивает сведения, подтверждающие право налогоплательщика на налоговую льготу, у органов и иных лиц, у которых имеются эти сведения. (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\nОрган или иное лицо, получившие запрос налогового органа о представлении сведений, подтверждающих право налогоплательщика на налоговую льготу, исполняет его в течение семи дней со дня получения или в тот же срок сообщает в налоговый орган о причинах неисполнения запроса. (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\nНалоговый орган в течение трех дней со дня получения указанного сообщения обязан проинформировать налогоплательщика о неполучении по запросу сведений, подтверждающих право этого налогоплательщика на налоговую льготу, и о необходимости представления налогоплательщиком подтверждающих документов в налоговый орган.\n\nЗаявление о предоставлении налоговой льготы рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса, предусмотренного настоящим пунктом, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения заявления о предоставлении налоговой льготы не более чем на 30 дней, уведомив об этом налогоплательщика. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПо результатам рассмотрения заявления о предоставлении налоговой льготы налоговый орган направляет налогоплательщику способом, указанным в этом заявлении, уведомление о предоставлении налоговой льготы либо сообщение об отказе от предоставления налоговой льготы. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nВ уведомлении о предоставлении налоговой льготы должны быть указаны основания предоставления налоговой льготы, объекты налогообложения и периоды, применительно к которым предоставляется налоговая льгота. В сообщении об отказе от предоставления налоговой льготы должны быть указаны основания отказа от предоставления налоговой льготы, объекты налогообложения, а также период, начиная с которого налоговая льгота не предоставляется. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nФормы заявлений налогоплательщиков - организаций и физических лиц о предоставлении налоговых льгот, порядок их заполнения, форматы представления таких заявлений в электронной форме, формы уведомления о предоставлении налоговой льготы, сообщения об отказе от предоставления налоговой льготы утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nВ случае, если налогоплательщик, имеющий право на налоговую льготу, не представил в налоговый орган заявление о предоставлении налоговой льготы или не сообщил об отказе от применения налоговой льготы, налоговая льгота предоставляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором у налогоплательщика возникло право на налоговую льготу. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции федеральных законов от 23.11.2020 № 374-ФЗ, от 02.07.2021 № 305-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.09.2017 № 286-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 03.07.2016 № 249-ФЗ)","article_title":"Статья 361.1. Налоговые льготы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b1e20d7d8baa0a57fc516ad2e1e16e5664741d9feea1cba68f7d914f691d8290"},{"code_id":"NK_RF_2","article_number":"362","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 20.10.2005 № 131-ФЗ)\n\n1. Сумма налога (сумма авансового платежа по налогу) исчисляется на основании сведений органов (организаций, должностных лиц), осуществляющих государственную регистрацию транспортных средств в соответствии с законодательством Российской Федерации, если иное не предусмотрено настоящей статьей.\n\nНалогоплательщики-организации исчисляют сумму налога (сумму авансового платежа по налогу) самостоятельно.\n\nСумма налога, подлежащая уплате налогоплательщиками - физическими лицами, исчисляется налоговыми органами.\n\n(Пункт в редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n2. Сумма налога, подлежащая уплате в бюджет по итогам налогового периода, исчисляется в отношении каждого транспортного средства как произведение соответствующей налоговой базы и налоговой ставки, если иное не предусмотрено настоящей статьей.\n\nСумма налога, подлежащая уплате в бюджет налогоплательщиками-организациями, определяется как разница между исчисленной суммой налога и суммами авансовых платежей по налогу, подлежащих уплате в течение налогового периода. (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\nИсчисление суммы налога производится с учетом повышающего коэффициента: (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ) (Утратил силу - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ) (Утратил силу - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ) (Утратил силу - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nабзац; (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ) (Утратил силу - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\n3 - в отношении легковых автомобилей средней стоимостью от 10 миллионов до 15 миллионов рублей включительно, с года выпуска которых прошло не более 10 лет; (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ)\n\n3 - в отношении легковых автомобилей средней стоимостью от 15 миллионов рублей, с года выпуска которых прошло не более 20 лет. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ)\n\nПри этом исчисление сроков, указанных в настоящем пункте, начинается с года выпуска соответствующего легкового автомобиля. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ)\n\nПорядок расчета средней стоимости легковых автомобилей для целей настоящей главы определяется федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере торговли. Перечень легковых автомобилей средней стоимостью от 10 миллионов рублей, подлежащий применению в очередном налоговом периоде, размещается не позднее 31 марта очередного налогового периода на официальном сайте указанного органа в информационно-телекоммуникационной сети \"Интернет\". (Дополнение абзацем - Федеральный закон от 23.07.2013 № 214-ФЗ) (В редакции федеральных законов от 28.11.2015 № 327-ФЗ, от 26.03.2022 № 67-ФЗ)\n\nСумма налога, исчисленная по итогам налогового периода налогоплательщиками-организациями в отношении каждого транспортного средства, имеющего разрешенную максимальную массу свыше 12 тонн, зарегистрированного в реестре, уменьшается на сумму платы, уплаченную в отношении такого транспортного средства в данном налоговом периоде. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\nВ случае, если при применении налогового вычета, предусмотренного настоящим пунктом, сумма налога, подлежащая уплате в бюджет, принимает отрицательное значение, сумма налога принимается равной нулю. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\nСведения из реестра представляются в налоговые органы ежегодно до 15 февраля в порядке, определяемом федеральным органом исполнительной власти в области транспорта по согласованию с федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\n(Пункт в редакции Федерального закона от 20.10.2005 № 131-ФЗ)\n\nЕсли регистрация транспортного средства произошла до 15-го числа соответствующего месяца включительно или снятие транспортного средства с регистрации (снятие с учета, исключение из государственного судового реестра и так далее) произошло после 15-го числа соответствующего месяца, за полный месяц принимается месяц регистрации (снятия с регистрации) транспортного средства. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 396-ФЗ)\n\nЕсли регистрация транспортного средства произошла после 15-го числа соответствующего месяца или снятие транспортного средства с регистрации (снятие с учета, исключение из государственного судового реестра и так далее) произошло до 15-го числа соответствующего месяца включительно, месяц регистрации (снятия с регистрации) транспортного средства не учитывается при определении коэффициента, указанного в настоящем пункте. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 396-ФЗ)\n\n31. В отношении объекта налогообложения, прекратившего свое существование в связи с его гибелью или уничтожением, исчисление налога прекращается с 1-го числа месяца гибели или уничтожения такого объекта на основании заявления о его гибели или уничтожении, представленного налогоплательщиком в налоговый орган по своему выбору. С указанным заявлением налогоплательщик вправе представить документы, подтверждающие факт гибели или уничтожения объекта налогообложения. Указанные заявление и документы могут быть представлены в налоговый орган налогоплательщиками - физическими лицами через многофункциональный центр предоставления государственных и муниципальных услуг.\n\nВ случае, если документы, подтверждающие факт гибели или уничтожения объекта налогообложения, в налоговом органе отсутствуют, в том числе не представлены налогоплательщиком самостоятельно, налоговый орган по информации, указанной в заявлении налогоплательщика о гибели или уничтожении объекта налогообложения, запрашивает сведения, подтверждающие факт гибели или уничтожения объекта налогообложения, у органов и иных лиц, у которых имеются эти сведения.\n\nОрган или иное лицо, получившие запрос налогового органа о представлении сведений, подтверждающих факт гибели или уничтожения объекта налогообложения, исполняет указанный запрос в течение семи дней со дня его получения или в тот же срок сообщает в налоговый орган о причинах неисполнения запроса.\n\nНалоговый орган в течение трех дней со дня получения указанного сообщения обязан проинформировать налогоплательщика о неполучении по запросу сведений, подтверждающих факт гибели или уничтожения объекта налогообложения, и о необходимости представления налогоплательщиком подтверждающих документов в налоговый орган.\n\nЗаявление о гибели или уничтожении объекта налогообложения рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса, предусмотренного настоящим пунктом, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого заявления не более чем на 30 дней, уведомив об этом налогоплательщика.\n\nПо результатам рассмотрения заявления о гибели или уничтожении объекта налогообложения налоговый орган направляет налогоплательщику способом, указанным в этом заявлении, уведомление о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения либо сообщение об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения.\n\nВ уведомлении о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения должны быть указаны основания прекращения исчисления налога, объекты налогообложения и период, начиная с которого исчисление налога прекращается. В сообщении об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения должны быть указаны основания отказа в прекращении исчисления налога и объекты налогообложения.\n\nФорма заявления о гибели или уничтожении объекта налогообложения, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о прекращении исчисления налога в связи с гибелью или уничтожением объекта налогообложения, сообщения об отсутствии основания для прекращения исчисления налога в связи с гибелью или уничтожением объекта налогообложения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик не представил в налоговый орган заявление о гибели или уничтожении объекта налогообложения, исчисление налога прекращается с 1-го числа месяца гибели или уничтожения такого объекта на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\n32. В отношении водных и воздушных транспортных средств, находящихся в общей долевой собственности, сумма налога (сумма авансового платежа по налогу) исчисляется для каждого из участников долевой собственности пропорционально его доле в праве собственности на такой объект налогообложения.\n\nВ отношении водных и воздушных транспортных средств, находящихся в общей совместной собственности, сумма налога (сумма авансового платежа по налогу) исчисляется для каждого из участников совместной собственности в равных долях.\n\nВ случае изменения в течение налогового (отчетного) периода доли налогоплательщика в праве общей собственности на водное или воздушное транспортное средство сумма налога (сумма авансового платежа по налогу) исчисляется с учетом коэффициента, определяемого в соответствии с пунктом 3 настоящей статьи. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n34. В отношении транспортного средства, право собственности на которое прекращено в связи с его принудительным изъятием по основаниям, предусмотренным федеральным законом, исчисление налога прекращается с 1-го числа месяца, в котором такое транспортное средство было принудительно изъято у его собственника, на основании заявления о прекращении исчисления налога в связи с принудительным изъятием транспортного средства, представленного налогоплательщиком в налоговый орган по своему выбору. С указанным заявлением налогоплательщик вправе пр\n\nедставить документы, подтверждающие принудительное изъятие транспортного средства. Указанные заявление и документы могут быть представлены в налоговый орган налогоплательщиками - физическими лицами через многофункциональный центр предоставления государственных и муниципальных услуг.\n\nВ случае, если документы, подтверждающие принудительное изъятие транспортного средства, в налоговом органе отсутствуют, в том числе не представлены налогоплательщиком самостоятельно, налоговый орган по информации, указанной в заявлении налогоплательщика о прекращении исчисления налога в связи с принудительным изъятием транспортного средства, запрашивает сведения, подтверждающие принудительное изъятие транспортного средства, у органов и иных лиц, у которых имеются эти сведения.\n\nОрган или иное лицо, получившие запрос налогового органа о представлении сведений, подтверждающих принудительное изъятие транспортного средства, исполняет указанный запрос в течение семи дней со дня его получения или в тот же срок сообщает в налоговый орган о причинах неисполнения запроса.\n\nНалоговый орган в течение трех дней со дня получения указанного сообщения обязан проинформировать налогоплательщика о неполучении по запросу сведений, подтверждающих принудительное изъятие транспортного средства, и о необходимости представления налогоплательщиком подтверждающих документов в налоговый орган.\n\nЗаявление о прекращении исчисления налога в связи с принудительным изъятием транспортного средства рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса, предусмотренного настоящим пунктом, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого заявления не более чем на 30 дней, уведомив об этом налогоплательщика.\n\nПо результатам рассмотрения заявления о прекращении исчисления налога в связи с принудительным изъятием транспортного средства налоговый орган направляет налогоплательщику способом, указанным в этом заявлении, уведомление о прекращении исчисления налога в связи с принудительным изъятием транспортного средства либо сообщение об отсутствии основания для прекращения исчисления налога в связи с принудительным изъятием транспортного средства.\n\nВ уведомлении о прекращении исчисления налога в связи с принудительным изъятием транспортного средства должны быть указаны основания прекращения исчисления налога, объекты налогообложения и период, начиная с которого исчисление налога прекращается. В сообщении об отсутствии основания для прекращения исчисления налога в связи с принудительным изъятием транспортного средства должны быть указаны основания отказа в прекращении исчисления налога и объекты налогообложения.\n\nФорма заявления о прекращении исчисления налога в связи с принудительным изъятием транспортного средства, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о прекращении исчисления налога в связи с принудительным изъятием транспортного средства, сообщения об отсутствии основания для прекращения исчисления налога в связи с принудительным изъятием транспортного средства утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n35. В отношении транспортного средства, находящегося в розыске в связи с его угоном (хищением), а также транспортного средства, находившегося в розыске в связи с его угоном (хищением), розыск которого прекращен, исчисление налога (авансового платежа по налогу) прекращается с 1-го числа месяца начала розыска соответствующего транспортного средства до месяца его возврата лицу, на которое оно зарегистрировано, на основании заявления о прекращении исчисления налога (авансового платежа по налогу) в отношении такого транспортного средства (далее в настоящем пункте - заявление), представленного налогоплательщиком в налоговый орган по своему выбору. Вместе с заявлением налогоплательщик вправе представить выданные уполномоченным органом документы, подтверждающие, что транспортное средство находится в розыске в течение определенного периода или транспортное средство, розыск которого прекращен, не возвращено лицу, на которое оно зарегистрировано. Заявление и указанные документы могут быть представлены в налоговый орган налогоплательщиками - физическими лицами через многофункциональный центр предоставления государственных и муниципальных услуг.\n\nВ случае, если документы, указанные в абзаце первом настоящего пункта, в налоговом органе отсутствуют, в том числе не представлены налогоплательщиком самостоятельно, налоговый орган по информации, указанной в заявлении, запрашивает сведения, подтверждающие, что транспортное средство находится в розыске в течение определенного периода или транспортное средство, розыск которого прекращен, не возвращено лицу, на которое оно зарегистрировано, у уполномоченного органа, у которого имеются эти сведения.\n\nУполномоченный орган, получивший запрос налогового органа о представлении сведений, подтверждающих, что транспортное средство находится в розыске в течение определенного периода или транспортное средство, розыск которого прекращен, не возвращено лицу, на которое оно зарегистрировано, исполняет указанный запрос в течение семи дней со дня его получения или в тот же срок сообщает в налоговый орган об отсутствии запрашиваемых сведений.\n\nНалоговый орган в течение трех дней со дня получения сообщения, указанного в абзаце третьем настоящего пункта, обязан проинформировать налогоплательщика о неполучении по запросу сведений, подтверждающих, что транспортное средство находится в розыске в течение определенного периода или транспортное средство, розыск которого прекращен, не возвращено лицу, на которое оно зарегистрировано, и о необходимости представления налогоплательщиком подтверждающих документов в налоговый орган.\n\nЗаявление рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса, предусмотренного настоящим пунктом, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения заявления не более чем на 30 дней, уведомив об этом налогоплательщика.\n\nПо результатам рассмотрения заявления налоговый орган направляет налогоплательщику способом, указанным в заявлении, уведомление о прекращении исчисления налога (авансового платежа по налогу) в отношении транспортного средства, находящегося в розыске, или транспортного средства, розыск которого прекращен, либо сообщение об отсутствии основания для прекращения исчисления налога (авансового платежа по налогу) в отношении транспортного средства, указанного в заявлении.\n\nВ уведомлении о прекращении исчисления налога (авансового платежа по налогу) в отношении транспортного средства, находящегося в розыске, или транспортного средства, розыск которого прекращен, должны быть указаны основания прекращения исчисления налога (авансового платежа по налогу), объекты налогообложения и период, в течение которого сумма налога (сумма авансового платежа по налогу) не исчисляется. В сообщении об отсутствии основания для прекращения исчисления налога (авансового платежа по налогу) в отношении транспортного средства, указанного в заявлении, должны быть указаны основания отказа в прекращении исчисления налога (авансового платежа по налогу) и объекты налогообложения.\n\nФорма заявления, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о прекращении исчисления налога (авансового платежа по налогу) в отношении транспортного средства, находящегося в розыске, или транспортного средства, розыск которого прекращен, сообщения об отсутствии основания для прекращения исчисления налога (авансового платежа по налогу) в отношении транспортного средства, указанного в заявлении, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик не представил в налоговый орган заявление, исчисление налога (авансового платежа по налогу) в отношении транспортного средства, находящегося в розыске, или транспортного средства, розыск которого прекращен и которое не возвращено лицу, на которое оно зарегистрировано, прекращается с 1-го числа месяца начала розыска соответствующего транспортного средства до месяца его возврата лицу, на которое оно зарегистрировано, на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nФорма, порядок ее заполнения, формат и порядок представления сведений, предусмотренных настоящим пунктом, в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСведения, предусмотренные настоящим пунктом, представляются также органом или иным лицом, уполномоченными федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере внутренних дел, в налоговый орган по его запросу в течение пяти дней со дня получения соответствующего запроса.\n\nСведения, предусмотренные настоящим пунктом, представляются в налоговые органы бесплатно.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае, если документы, подтверждающие наличие оснований, влекущих перерасчет суммы ранее исчисленного налога, в налоговом органе отсутствуют, в том числе не представлены налогоплательщиком - физическим лицом самостоятельно, налоговый орган по информации, указанной в заявлении о перерасчете суммы ранее исчисленного налога, запрашивает сведения, подтверждающие наличие оснований, влекущих перерасчет суммы ранее исчисленного налога, у органов и иных лиц, у которых имеются эти сведения.\n\nОрган или иное лицо, получившие запрос налогового органа о представлении сведений, подтверждающих наличие оснований, влекущих перерасчет суммы ранее исчисленного налога, исполняет указанный запрос в течение семи дней со дня его получения или в тот же срок сообщает в налоговый орган об отсутствии запрашиваемых сведений.\n\nНалоговый орган в течение трех дней со дня получения указанного сообщения обязан проинформировать налогоплательщика - физическое лицо о неполучении по запросу сведений, подтверждающих наличие оснований, влекущих перерасчет суммы ранее исчисленного налога, и о необходимости представления налогоплательщиком - физическим лицом подтверждающих документов в налоговый орган.\n\nЗаявление о перерасчете суммы ранее исчисленного налога рассматривается налоговым органом в течение 30 дней со дня его получения. В случае направления налоговым органом запроса, предусмотренного настоящим пунктом, руководитель (заместитель руководителя) налогового органа вправе продлить срок рассмотрения такого заявления не более чем на 30 дней, уведомив об этом налогоплательщика - физическое лицо.\n\nПо результатам рассмотрения заявления о перерасчете суммы ранее исчисленного налога налоговый орган направляет налогоплательщику - физическому лицу способом, указанным в таком заявлении, уведомление о перерасчете суммы ранее исчисленного налога либо сообщение об отказе в перерасчете суммы ранее исчисленного налога.\n\nВ уведомлении о перерасчете суммы ранее исчисленного налога должны быть указаны основания перерасчета суммы ранее исчисленного налога, объекты налогообложения и период, за который осуществлен перерасчет суммы ранее исчисленного налога. В сообщении об отказе в перерасчете суммы ранее исчисленного налога должны быть указаны основания отказа в перерасчете суммы ранее исчисленного налога и объекты налогообложения.\n\nВ случае, если по результатам рассмотрения налоговым органом заявления о перерасчете суммы ранее исчисленного налога сумма ранее исчисленного налога изменилась, налоговый орган вместе с уведомлением о перерасчете суммы ранее исчисленного налога направляет налогоплательщику налоговое уведомление, сформированное в связи с данным перерасчетом, если иное не предусмотрено настоящим Кодексом.\n\nФорма заявления о перерасчете суммы ранее исчисленного налога, порядок ее заполнения, формат представления такого заявления в электронной форме, формы уведомления о перерасчете суммы ранее исчисленного налога, сообщения об отказе в перерасчете суммы ранее исчисленного налога утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если налогоплательщик - физическое лицо не представил в налоговый орган заявление о перерасчете суммы ранее исчисленного налога, перерасчет суммы ранее исчисленного налога осуществляется на основании сведений, полученных налоговым органом в соответствии с настоящим Кодексом и другими федеральными законами, начиная с налогового периода, в котором возникло основание для данного перерасчета, если иное не предусмотрено настоящим Кодексом.\n\nВ случае, если заявление о перерасчете суммы ранее исчисленного налога представлено при наличии оснований, предусмотренных пунктами 31, 34, 35 настоящей статьи, пунктом 3 статьи 3611 настоящего Кодекса, рассмотрение такого заявления осуществляется в соответствии с настоящим пунктом без учета положений пунктов 31, 34, 35 настоящей статьи, пункта 3 статьи 3611 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 362. Порядок исчисления суммы налога и сумм авансовых платежей по налогу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e94fd5be7cad1779a961f0e891d988b5896a129bef138e906463bce2f960782"},{"code_id":"NK_RF_2","article_number":"363","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 20.10.2005 № 131-ФЗ)\n\nНалог подлежит уплате налогоплательщиками-организациями в срок не позднее 28 февраля года, следующего за истекшим налоговым периодом. Авансовые платежи по налогу подлежат уплате налогоплательщиками-организациями в срок не позднее 28-го числа месяца, следующего за истекшим отчетным периодом. (Дополнение абзацем - Федеральный закон от 20.10.2005 № 131-ФЗ) (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nНалог подлежит уплате налогоплательщиками - физическими лицами в срок не позднее 1 декабря года, следующего за истекшим налоговым периодом, если иное не предусмотрено настоящим пунктом. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ) (В редакции  федеральных законов от 02.12.2013 № 334-ФЗ, от 23.11.2015 № 320-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nНалог, исчисленный по результатам перерасчета суммы ранее исчисленного налога, подлежит уплате налогоплательщиками - физическими лицами в срок не позднее 28-го числа третьего месяца, следующего за месяцем, в котором сформировано налоговое уведомление в связи с данным перерасчетом. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nНалогоплательщики-организации в отношении транспортного средства, имеющего разрешенную максимальную массу свыше 12 тонн, зарегистрированного в реестре, исчисленные авансовые платежи по налогу не уплачивают. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 249-ФЗ)\n\nНаправление налогового уведомления допускается не более чем за три налоговых периода, предшествующих календарному году его направления. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ)\n\nНалогоплательщики, указанные в абзаце первом настоящего пункта, уплачивают налог не более чем за три налоговых периода, предшествующих календарному году направления налогового уведомления, указанного в абзаце втором настоящего пункта. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.11.2009 № 283-ФЗ) (Утратил силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n1) в течение десяти дней после составления налоговым органом сообщения об исчисленной сумме налога, подлежащей уплате соответствующим налогоплательщиком-организацией за истекш\n\nий налоговый период, но не позднее шести месяцев со дня истечения установленного срока уплаты налога за указанный налоговый период;\n\n2) не позднее двух месяцев со дня получения налоговым органом документов и (или) иной информации, влекущих исчисление (перерасчет) суммы налога, подлежащей уплате соответствующим налогоплательщиком-организацией за предыдущие налоговые периоды;\n\n3) не позднее трех месяцев со дня получения налоговым органом сведений, содержащихся в едином государственном реестре юридических лиц, о том, что соответствующая организация находится в процессе ликвидации, в отношении организации принято решение о предстоящем исключении из единого государственного реестра юридических лиц, а также решение о возбуждении производства по делу о банкротстве организации; (В редакции  федеральных законов от 02.07.2021 № 305-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n4) не позднее одного месяца со дня истечения установленного срока уплаты авансового платежа по налогу по истечении каждого отчетного периода, подлежащего уплате организацией, которой передано (направлено) сообщение об исчисленной сумме налога в соответствии с подпунктом 3 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n5) не позднее пяти дней со дня получения налоговым органом сведений, содержащихся в государственном реестре аккредитованных филиалов, представительств иностранных юридических лиц, о представлении налогоплательщиком - иностранной организацией заявления о прекращении действия аккредитации филиала, представительства указанной иностранной организации. (Дополнение подпунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nВ сообщении об исчисленной сумме налога должны быть указаны объект налогообложения, налоговая база, налоговый период, налоговая ставка, сумма исчисленного налога.\n\nСообщение об исчисленной сумме налога передается налоговым органом налогоплательщику-организации (ее обособленному подразделению) в электронной форме по телекоммуникационным каналам связи через оператора электронного документооборота или через личный кабинет налогоплательщика, а в случае невозможности передачи указанными способами сообщение об исчисленной сумме налога направляется по почте заказным письмом. В случае направления сообщения об исчисленной сумме налога по почте заказным письмом такое сообщение считается полученным по истечении шести дней с даты направления заказного письма. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nНалогоплательщик-организация вправе получить сообщение об исчисленной сумме налога в любом налоговом органе на основании заявления о выдаче сообщения об исчисленной сумме налога. Сообщение об исчисленной сумме налога передается (направляется) руководителю организации (ее представителю) в срок не позднее пяти дней со дня получения налоговым органом заявления о выдаче сообщения об исчисленной сумме налога. (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\nФорма заявления о выдаче сообщения об исчисленной сумме налога, порядок ее заполнения, формат представления такого заявления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 02.07.2021 № 305-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nФорма пояснений налогоплательщика-организации (ее обособленного подразделения) в связи с полученным сообщением об исчисленной сумме налога, порядок ее заполнения и формат представления таких пояснений в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nО результатах рассмотрения представленных налогоплательщиком-организацией (ее обособленным подразделением) пояснений и (или) документов налоговый орган информирует налогоплательщика-организацию (ее обособленное подразделение) в срок, указанный в абзаце первом настоящего пункта, а в случае, если по результатам рассмотрения налоговым органом представленных налогоплательщиком-организацией (ее обособленным подразделением) пояснений и (или) документов сумма налога, указанная в сообщении об исчисленной сумме налога, изменилась, налоговый орган передает (направляет) налогоплательщику-организации (ее обособленному подразделению) уточненное сообщение об исчисленной сумме налога в течение десяти дней после составления такого сообщения. (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 15.04.2019 № 63-ФЗ)","article_title":"Статья 363. Порядок и сроки уплаты налога и авансовых платежей по налогу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47a648d507df8ecf0f70b2f22a9b46a30c2581c8dd902760602e4dcf63a82414"},{"code_id":"NK_RF_2","article_number":"363.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 20.10.2005 № 131-ФЗ) (Утратила силу  - Федеральный закон от 15.04.2019 № 63-ФЗ)\n\nГЛАВА 29. НАЛОГ НА ИГОРНЫЙ БИЗНЕС\n\n(Дополнение главой - Федеральный закон от 27.12.2002 № 182-ФЗ)","article_title":"Статья 363.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7f5bf92a0e837032b799e8a886b31b2277ac4ff8361118325dd211ff171cfb1d"},{"code_id":"NK_RF_2","article_number":"364","version_date":"2000-07-31","article_text":"Для целей настоящей главы используются следующие понятия:\n\nигорный бизнес - предпринимательская деятельность по организации и проведению азартных игр, связанная с извлечением организациями доходов в виде выигрыша и (или) платы за проведение азартных игр; (В редакции Федерального закона от 23.07.2013 № 198-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nигровое поле - специальное место на игровом столе, оборудованное в соответствии с правилами азартной игры, где проводится азартная игра с любым количеством участников азартной игры и только с одним работником организатора азартной игры, участвующим в указанной игре; (В редакции Федерального закона от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 16.11.2011 № 319-ФЗ)","article_title":"Статья 364. Понятия, используемые в настоящей главе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"837151a5e0f81e68fca278d1dc298ffce1ca207165b9525e2627cb514f159ca0"},{"code_id":"NK_RF_2","article_number":"365","version_date":"2000-07-31","article_text":"Налогоплательщиками налога на игорный бизнес (далее в настоящей главе - налог) признаются организации, осуществляющие предпринимательскую деятельность в сфере игорного бизнеса. (В редакции Федерального закона от 16.11.2011 № 319-ФЗ)","article_title":"Статья 365. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1eb98f04a5a1daed136075f8777a2f455c136956b132ed89d9d75c28fb852ebc"},{"code_id":"NK_RF_2","article_number":"366","version_date":"2000-07-31","article_text":"1. Объектами налогообложения признаются:\n\n1) игровой стол;\n\n2) игровой автомат;\n\n3) процессинговый центр букмекерской конторы;\n\n4) процессинговый центр тотализатора;\n\n5) процессинговый центр интерактивных ставок тотализатора;\n\n6) процессинговый центр интерактивных ставок букмекерской конторы;\n\n7) пункт приема ставок тотализатора;\n\n8) пункт приема ставок букмекерской конторы.\n\n2. В целях настоящей главы каждый объект налогообложения, указанный в пункте 1 настоящей статьи, подлежит регистрации в налоговом органе по месту установки (месту нахождения) этого объекта налогообложения.\n\nРегистрация проводится налоговым органом на основании заявления налогоплательщика о регистрации объекта (объектов) налогообложения с выдачей свидетельства о регистрации объекта (объектов) налогообложения.\n\nЗаявление о регистрации объекта (объектов) налогообложения должно быть представлено в налоговый орган не позднее чем за пять дней до даты установки каждого объекта налогообложения (открытия пункта приема ставок букмекерской конторы или пункта приема ставок тотализатора, процессингового центра тотализатора или процессингового центра букмекерской конторы, процессингового центра интерактивных ставок тотализатора или процессингового центра интерактивных ставок букмекерской конторы).\n\nНалогоплательщики, не состоящие на учете в налоговых органах на территории того субъекта Российской Федерации, где устанавливается (открывается) объект налогообложения, указанный в пункте 1 настоящей статьи, обязаны встать на учет в налоговых органах по месту установки (месту нахождения) такого объекта налогообложения не позднее чем за пять дней до даты установки (открытия) каждого объекта налогообложения.\n\nВ случае установки (открытия) объекта налогообложения в федеральной территории \"Сириус\" налогоплательщики, не состоящие на учете в уполномоченном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, налоговом органе по месту установки (месту нахождения) такого объекта налогообложения, обязаны встать на учет в указанном налоговом органе не позднее чем за пять дней до даты установки (открытия) каждого объекта налогообложения. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\n3. Налогоплательщик также обязан зарегистрировать в налоговых органах по месту регистрации объекта (объектов) налогообложения любое изменение количества объектов налогообложения не позднее чем за пять дней до даты установки (открытия) или выбытия (закрытия) каждого объекта налогообложения.\n\n4. Объект налогообложения считается зарегистрированным с даты выдачи налоговым органом свидетельства о регистрации объекта (объектов) налогообложения.\n\nОбъект налогообложения считается выбывшим (закрытым) с даты внесения налоговым органом в ранее выданное свидетельство изменений, связанных с изменением количества объектов налогообложения.\n\n5. Заявление о регистрации объекта (объектов) налогообложения, заявление о регистрации изменений (уменьшений) количества объектов налогообложения могут быть представлены налогоплательщиком в налоговый орган лично или через его представителя, направлены в виде почтового отправления с описью вложения или переданы в электронной форме по телекоммуникационным каналам связи с применением усиленной квалифицированной электронной подписи в формате, утвержденном федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПри направлении заявлений по почте днем их представления в налоговый орган считается день отправки почтового отправления с описью вложения. При передаче заявлений по телекоммуникационным каналам связи днем их представления в налоговый орган считается день их отправки.\n\n6. Налоговые органы в течение пяти дней с даты получения от налогоплательщика заявления о регистрации объекта (объектов) налогообложения (об изменении количества объектов налогообложения) при условии его надлежащего оформления выдают свидетельство о регистрации объекта (объектов) налогообложения или вносят изменения, связанные с изменением количества объектов налогообложения, в ранее выданное свидетельство.\n\n7. Формы документов, указанных в настоящей статье, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Статья в редакции Федерального закона от 27.11.2017 № 354-ФЗ)","article_title":"Статья 366. Объекты налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31c304b0741e03ea76f27eaa76a173968ba3a135e664743718c149941d1f5008"},{"code_id":"NK_RF_2","article_number":"367","version_date":"2000-07-31","article_text":"По каждому из объектов налогообложения, указанных в статье 366 настоящего Кодекса, налоговая база определяется отдельно как общее количество соответствующих объектов налогообложения.","article_title":"Статья 367. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"154bae464404747f9ac9f27d8f7f1dac67d7c1f370de45cd9c2977c2a9a3dc81"},{"code_id":"NK_RF_2","article_number":"368","version_date":"2000-07-31","article_text":"Налоговым периодом признается календарный месяц.","article_title":"Статья 368. Налоговый период","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d99669584ec220fd8be7fcb5fa3ea6fde58698d0f44fceb8d40891bc4c678c2b"},{"code_id":"NK_RF_2","article_number":"369","version_date":"2000-07-31","article_text":"1) за один игровой стол - от 50 000 до 250 000 рублей;\n\n2) за один игровой автомат - от 3 000 до 15 000 рублей;\n\n3) за один процессинговый центр букмекерской конторы - от 50 000 до 250 000 рублей;\n\n4) за один процессинговый центр тотализатора - от 50 000 до 250 000 рублей;\n\n5) за один процессинговый центр интерактивных ставок тотализатора - от 2 500 000 до 3 000 000 рублей;\n\n6) за один процессинговый центр интерактивных ставок букмекерской конторы - от 9 500 000 до 10 000 000 рублей; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n7) за один пункт приема ставок тотализатора - от 10 000 до 14 000 рублей;\n\n8) за один пункт приема ставок букмекерской конторы - от 10 000 до 14 000 рублей.\n\n1) за один игровой стол - 50 000 рублей;\n\n2) за один игровой автомат - 3 000 рублей;\n\n3) за один процессинговый центр букмекерской конторы - 50 000 рублей;\n\n4) за один процессинговый центр тотализатора - 50 000 рублей;\n\n5) за один процессинговый центр интерактивных ставок тотализатора - 2 500 000 рублей;\n\n6) за один процессинговый центр интерактивных ставок букмекерской конторы - 9 500 000 рублей; (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\n7) за один пункт приема ставок тотализатора - 10 000 рублей;\n\n8) за один пункт приема ставок букмекерской конторы - 10 000 рублей.\n\n(Статья в редакции Федерального закона от 27.11.2017 № 354-ФЗ)","article_title":"Статья 369. Налоговые ставки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cb8edd8370384d6588cb8a59181ef2e250c3fdba6deb17e112a738278605958"},{"code_id":"NK_RF_2","article_number":"369.1","version_date":"2000-07-31","article_text":"Налогообложение в федеральной территории \"Сириус\" производится по налоговым ставкам, установленным пунктом 2 статьи 369 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 11.06.2021 № 199-ФЗ)","article_title":"Статья 369.1. Особенности налогообложения в федеральной территории \"Сириус\"","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"139acc3055ee39fbb2d47853d4b313e5f3ab0b1a5d99f2dcb0f7b155703e8be9"},{"code_id":"NK_RF_2","article_number":"370","version_date":"2000-07-31","article_text":"В случае, если один игровой стол имеет более одного игрового поля, ставка налога по указанному игровому столу увеличивается кратно количеству игровых полей.\n\nНалогоплательщики, в соответствии со статьей 83 настоящего Кодекса отнесенные к категории крупнейших, представляют налоговые декларации в налоговый орган по месту учета в качестве крупнейших налогоплательщиков. (Дополнение абзацем - Федеральный закон от 30.12.2006 № 268-ФЗ)\n\nПри выдаче свидетельства о регистрации объекта (объектов) налогообложения после 15-го числа текущего налогового периода сумма налога по этим объектам за указанный налоговый период исчисляется как произведение количества объектов налогообложения и одной второй ставки налога, установленной для этих объектов налогообложения.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 354-ФЗ)\n\nПри внесении налоговым органом в ранее выданное свидетельство изменений, связанных с изменением количества объектов налогообложения, после 15-го числа текущего налогового периода сумма налога исчисляется как произведение общего количества соответствующих объектов налогообложения (включая выбывший (закрытый) объект налогообложения) и ставки налога, установленной для этих объектов налогообложения.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 354-ФЗ)","article_title":"Статья 370. Порядок исчисления налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9b0a754d711b0211bf25e8fe6cb64db3d21b35bfda71cb4992e08c857f28765"},{"code_id":"NK_RF_2","article_number":"371","version_date":"2000-07-31","article_text":"Налог, подлежащий уплате по итогам налогового периода, уплачивается налогоплательщиком в бюджет по месту регистрации в налоговом органе объектов налогообложения, указанных в пункте 1 статьи 366 настоящего Кодекса, не позднее 28-го числа месяца, следующего за истекшим налоговым периодом. (В редакции  федеральных законов от 30.06.2004 № 60-ФЗ, от 27.07.2010 № 229-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nГЛАВА 30. НАЛОГ НА ИМУЩЕСТВО ОРГАНИЗАЦИЙ\n\n(Дополнение главой - Федеральный закон от 11.11.2003 № 139-ФЗ)","article_title":"Статья 371. Порядок и сроки уплаты налога","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5ae236085337991bc5d3d1e564822973cf6c618e1c2f44f0a73f227b3a99885f"},{"code_id":"NK_RF_2","article_number":"372","version_date":"2000-07-31","article_text":"При установлении налога законами субъектов Российской Федерации могут также определяться особенности определения налоговой базы отдельных объектов недвижимого имущества в соответствии с настоящей главой, предусматриваться налоговые льготы, осн\n\nования и порядок их применения налогоплательщиками. (В редакции федеральных законов от 02.11.2013 № 307-ФЗ, от 02.07.2021 № 305-ФЗ)","article_title":"Статья 372. Общие положения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93e98478f525281d7758934c48f953673546574fc94d2577cd6b80697fe085de"},{"code_id":"NK_RF_2","article_number":"372.1","version_date":"2000-07-31","article_text":"1. Налог, обязательный к уплате в федеральной территории \"Сириус\", устанавливается настоящей главой.\n\nВ отношении объектов недвижимого имущества (за исключением объектов недвижимого имущества, используемых в деятельности по организации и проведению азартных игр), построенных в соответствии с Программой строительства олимпийских объектов и развития города Сочи как горноклиматического курорта, утвержденной Правительством Российской Федерации, налоговые ставки для организаций, обладавших правом на проведение чемпионата мира FIA \"Формула-1\", в том числе правом на популяризацию мероприятия и правом называть мероприятие российского этапа указанного чемпионата \"Чемпионат мира FIA \"Формула-1\", устанавливаются в 2022 году в размере 0,7 процента, в 2023 году - 1,5 процента, в 2024 году - 2 процентов. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n1) некоммерческие образовательные организации - в отношении объектов недвижимого имущества, находящихся в собственности указанных организаций и построенных в соответствии с Программой строительства олимпийских объектов и развития города Сочи как горноклиматического курорта, утвержденной Правительством Российской Федерации;\n\n2) организации, обладающие по состоянию на 1 января 2022 года правом на проведение чемпионата мира FIA \"Формула-1\", в том числе правом на популяризацию мероприятия и правом называть мероприятие российского этапа указанного чемпионата \"Чемпионат мира FIA \"Формула-1\", - в отношении объектов недвижимого имущества, построенных в соответствии с Программой строительства олимпийских объектов и развития города Сочи как горноклиматического курорта, утвержденной Правительством Российской Федерации. Налоговая льгота не применяется в отношении объектов недвижимого имущества, используемых в деятельности по организации и проведению азартных игр; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n3) органы публичной власти федеральной территории \"Сириус\", унитарные предприятия, казенные, бюджетные и автономные учреждения, иные организации, созданные органами публичной власти федеральной территории \"Сириус\" в целях обеспечения реализации их полномочий;\n\n4) образовательные организации и организации, основным видом экономической деятельности которых в течение всего налогового периода является деятельность спортивных объектов, - в отношении объектов недвижимого имущества, введенных в эксплуатацию начиная с 1 января 2022 года, площадью свыше 15 000 квадратных метров. Основной вид экономической деятельности определяется по содержащемуся в едином государственном реестре юридических лиц коду основного вида экономической деятельности, соответствующему классу 93.11 \"Деятельность спортивных объектов\" Общероссийского классификатора видов экономической деятельности. Освобождение в соответствии с настоящим подпунктом не применяется в отношении объектов недвижимого имущества, используемых в деятельности по организации и проведению азартных игр. (Дополнение подпунктом - Федеральный закон от 29.05.2023 № 200-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.11.2021 № 382-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 11.06.2021 № 199-ФЗ)","article_title":"Статья 372.1. Особенности установления налога и налогообложения в федеральной территории \"Сириус\"","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1b9dfd76313468f92ec53d05415561877cfb42a743f00b9da5e20aba639b0b4d"},{"code_id":"NK_RF_2","article_number":"373","version_date":"2000-07-31","article_text":"Не признаются налогоплательщиками конфедерации, национальные футбольные ассоциации (в том числе Российский футбольный союз), Организационный комитет \"Россия-2018\", дочерние организации Организационного комитета \"Россия-2018\", производители медиаинформации FIFA, поставщики товаров (работ, услуг) FIFA, определенные Федеральным законом \"О подготовке и проведении в Российской Федерации чемпионата мира по футболу FIFA 2018 года, Кубка конфедераций FIFA 2017 года, чемпионата Европы по футболу UEFA 2020 года и внесении изменений в отдельные законодательные акты Российской Федерации\", в отношении имущества, используемого ими только в целях осуществления мероприятий, предусмотренных указанным Федеральным законом, а также в период по 31 декабря 2021 года включительно Российский футбольный союз, локальная организационная структура, коммерческие партнеры UEFA, поставщики товаров (работ, услуг) UEFA и вещатели UEFA, определенные указанным Федеральным законом, в отношении имущества, используемого ими только в целях осуществления мероприятий по подготовке и проведению в Российской Федерации чемпионата Европы по футболу UEFA 2020 года, предусмотренных указанным Федеральным законом. (В редакции Федерального закона от 20.04.2021 № 101-ФЗ)\n\nНе признаются налогоплательщиками организации, зарегистрированные на территории Курильских островов, в течение периода использования такими организациями права на освобождение от исполнения обязанностей налогоплательщика налога на прибыль организаций в соответствии со статьей 2463 настоящего Кодекса. В случае утраты организацией в соответствии с пунктом 3 статьи 2463 настоящего Кодекса такого права она признается налогоплательщиком с 1-го числа налогового периода, в котором утрачено такое право, и сумма налога (авансового платежа по налогу) подлежит восстановлению и уплате в бюджет в установленном порядке с уплатой соответствующих пеней, начисляемых со дня, следующего за установленным статьей 383 настоящего Кодекса днем уплаты налога (авансового платежа по налогу). (Дополнение абзацем - Федеральный закон от 09.03.2022 № 50-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 07.06.2013 № 108-ФЗ) (В редакции Федерального закона от 01.05.2019 № 101-ФЗ)","article_title":"Статья 373. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"965b42970242d7aefb3d8445bd60a7713b8c0376efa83706b95c38557c704e8d"},{"code_id":"NK_RF_2","article_number":"374","version_date":"2000-07-31","article_text":"1. Объектами налогообложения признаются:\n\n1) недвижимое имущество (в том числе имущество, переданное во временное владение, в пользование, распоряжение, доверительное управление, внесенное в совместную деятельность или полученное по концессионному соглашению), учитываемое на балансе организации в качестве объектов основных средств в порядке, установленном для ведения бухгалтерского учета, в случае, если налоговая база в отношении такого имущества определяется в соответствии с пунктом 1 статьи 375 настоящего Кодекса, если иное не предусмотрено статьями 378 и 3781 настоящего Кодекса.\n\nВ целях настоящей главы иностранные организации, осуществляющие деятельность в Российской Федерации через постоянные представительства, ведут учет объектов налогообложения в порядке, установленном в Российской Федерации для ведения бухгалтерского учета;\n\n2) недвижимое имущество, находящееся на территории Российской Федерации и принадлежащее организациям на праве собственности или праве хозяйственного ведения, а также полученное по концессионному соглашению, в случае, если налоговая база в отношении такого имущества определяется в соответствии с пунктом 2 статьи 375 настоящего Кодекса, если иное не предусмотрено статьями 378 и 3781 настоящего Кодекса.\n\n(Пункт в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n1) земельные участки и иные объекты природопользования (водные объекты и другие природные ресурсы);\n\n2) имущество, принадлежащее на праве оперативного управления федеральным органам исполнительной власти и федеральным государственным органам, в которых законодательством Российской Федерации предусмотрена военная и (или) приравненная к ней служба, используемое этими органами для нужд обороны, гражданской обороны, обеспечения безопасности и охраны правопорядка в Российской Федерации; (В редакции федеральных законов от 28.11.2009 № 283-ФЗ; от 04.06.2014 № 145-ФЗ)\n\n3) объекты, признаваемые объектами культурного наследия (памятниками истории и культуры) народов Российской Федерации федерального значения в установленном законодательством Российской Федерации порядке; (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n4) ядерные установки, используемые для научных целей, пункты хранения ядерных материалов и радиоактивных веществ и хранилища радиоактивных отходов; (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n5) ледоколы, суда с ядерными энергетическими установками и суда атомно-технологического обслуживания; (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n6) космические объекты; (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n7) суда, зарегистрированные в Российском международном реестре судов; (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 202-ФЗ)\n\n8) (Дополнение подпунктом - Федеральный закон от 29.11.2012 № 202-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n9) суда, зарегистрированные в Российском открытом реестре судов лицами, получившими статус участника специального административного района в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\"; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n10) воздушные суда, зарегистрированные в Государственном реестре гражданских воздушных судов лицами, получившими статус участника специального административного района в соответствии с Федеральным законом от 3 августа 2018 года № 291-ФЗ \"О специальных административных районах на территориях Калининградской области и Приморского края\"; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 324-ФЗ)\n\n11) имущество международной холдинговой компании, расположенное за пределами территории Российской Федерации и используемое в связи с ее участием в реализации проектов по геологическому изучению, разведке, добыче полезных ископаемых и выполнением иных работ, предусмотренных указанными проектами, при условии, что такие проекты осуществляются в соответствии с соглашениями о разделе продукции, концессионными соглашениями, лицензионными соглашениями или иными соглашениями (контрактами) на условиях риска; (Дополнение подпунктом - Федеральный закон от 26.03.2022 № 66-ФЗ) (В редакции  Федерального закона от 19.12.2023 № 595-ФЗ)\n\n12) имущество, закрепленное на праве оперативного управления за учреждениями, находящимися в ведении федерального органа исполнительной власти, основными задачами которого являются материально-техническое обеспечение деятельности и социально-бытовое обслуживание Президента Российской Федерации, оказывающими государственные услуги и выполняющими работы по санаторно-курортному лечению и организованному отдыху. (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 443-ФЗ)","article_title":"Статья 374. Объект налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"90eb0e0720cc46c232b494e6aa8a6b6b2b7b783d10aa697376692835c91df0e3"},{"code_id":"NK_RF_2","article_number":"375","version_date":"2000-07-31","article_text":"1. Налоговая база определяется как среднегодовая стоимость имущества, признаваемого объектом налогообложения, если иное не предусмотрено настоящей статьей.\n\nНалоговая база в отношении отдельных объектов недвижимого имущества, указанных в абзаце первом настоящего пункта, за налоговый период 2023 года определяется как их кадастровая стоимость, внесенная в Единый государственный реестр недвижимости и подлежащая применению с 1 января 2022 года с учетом особенностей, предусмотренных статьей 3782 настоящего Кодекса, в случае, если кадастровая стоимость таких объектов недвижимого имущества, внесенная в Единый государственный реестр недвижимости и подлежащая применению с 1 января 2023 года, превышает кадастровую стоимость таких объектов недвижимого имущества, внесенную в Единый государственный реестр недвижимости и подлежащую применению с 1 января 2022 года, за исключением случаев, если кадастровая стоимость соответствующих объектов недвижимого имущества увеличилась вследствие изменения их характеристик. (Дополнение абзацем - Федеральный закон от 26.03.2022 № 67-ФЗ)\n\nВ случае, если для отдельных объектов основных средств начисление амортизации не предусмотрено, стоимость указанных объектов для целей налогообложения определяется как разница между их первоначальной стоимостью и величиной износа, исчисляемой по установленным нормам амортизационных отчислений для целей бухгалтерского учета в конце каждого налогового (отчетного) периода.\n\n(Статья в редакции Федерального закона от 02.11.2013 № 307-ФЗ)","article_title":"Статья 375. Налоговая база","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53999aa13fe68677760038ce9629e8ba1a65dc7ebb133fb3f4321995b065e0d3"},{"code_id":"NK_RF_2","article_number":"376","version_date":"2000-07-31","article_text":"Среднегодовая стоимость имущества, признаваемого объектом налогообложения, за налоговый период определяется как частное от деления суммы, полученной в результате сложения величин остаточной стоимости имущества (без учета имущества, налоговая база в отношении которого определяется как его кадастровая стоимость) на 1-е число каждого месяца налогового периода и последнее число налогового периода, на количество месяцев в налоговом периоде, увеличенное на единицу.\n\n(Пункт в редакции Федерального закона от 02.11.2013 № 307-ФЗ)\n\nПоложение настоящего пункта не применяется в отношении законченных капитальных вложений, учтенных в балансовой стоимости указанных объектов до 1 января 2010 года.\n\n(Дополнение пунктом - Федеральн\n\nый закон от 27.11.2010 № 308-ФЗ)","article_title":"Статья 376. Порядок определения налоговой базы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fe3b83992e86c894d176453328e17cd67487ca3dea956625f133eb7ee81ad20"},{"code_id":"NK_RF_2","article_number":"377","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 28.11.2011 № 336-ФЗ)","article_title":"Статья 377. Особенности определения налоговой базы в рамках договора простого товарищества (договора о совместной деятельности), договора инвестиционного товарищества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf8d6752101af6628e84e2bd3dd2e1cae709fdfffc601946df8412edf94d2070"},{"code_id":"NK_RF_2","article_number":"378","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.11.2021 № 382-ФЗ)","article_title":"Статья 378. Особенности налогообложения имущества, переданного в доверительное управление, а также имущества, переданного в аренду","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1e314d02ac1d6f96813ed7eb0dbb5497649b04508d3244434bdfa2d489c67db6"},{"code_id":"NK_RF_2","article_number":"378.1","version_date":"2000-07-31","article_text":"Имущество, переданное концессионеру и (или) созданное им в соответствии с концессионным соглашением, подлежит налогообложению у концессионера.\n\n(Дополнение статьей - Федеральный закон от 30.06.2008 № 108-ФЗ)","article_title":"Статья 378.1. Особенности налогообложения имущества при исполнении концессионных соглашений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"761a7044bc1cbbbaa0b821b54b63f88d9c332bed464099b404b094ad15ab84c9"},{"code_id":"NK_RF_2","article_number":"378.2","version_date":"2000-07-31","article_text":"1) административно-деловые центры и торговые центры (комплексы) и помещения в них;\n\n2) нежилые помещения, назначение, разрешенное использование или наименование которых в соответствии со сведениями, содержащимися в Едином государственном реестре недвижимости, или документами технического учета (инвентаризации) объектов недвижимости предусматривает размещение офисов, торговых объектов, объектов общественного питания и бытового обслуживания либо которые фактически используются для размещения офисов, торговых объектов, объектов общественного питания и бытового обслуживания; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n3) объекты недвижимого имущества иностранных организаций, не осуществляющих деятельности в Российской Федерации через постоянные представительства, а также объекты недвижимого имущества иностранных организаций, не относящиеся к деятельности данных организаций в Российской Федерации через постоянные представительства;\n\n4) жилые помещения, жилые строения, многоквартирные дома, наемные дома, садовые дома, гаражи, машино-места, объекты незавершенного строительства, а также  хозяйственные строения или сооружения, расположенные на земельных участках, предоставленных для ведения личного подсобного хозяйства, огородничества, садоводства или индивидуального жилищного строительства. (Дополнение подпунктом - Федеральный закон от 04.10.2014 № 284-ФЗ) (В редакции  федеральных законов от 28.11.2019 № 379-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nПосле принятия закона, указанного в настоящем пункте, переход к определению налоговой базы в отношении объектов недвижимого имущества, указанных в подпунктах 1, 2 и 4 пункта 1 настоящей статьи, как их среднегодовой стоимости не допускается, за исключением случаев, предусмотренных подпунктами 2 и 22 пункта 12 настоящей статьи. (В редакции федеральных законов от 04.10.2014 № 284-ФЗ, от 23.11.2020 № 374-ФЗ)\n\n1) здание (строение, сооружение) расположено на земельном участке, один из видов разрешенного использования которого предусматривает размещение офисных зданий делового, административного и коммерческого назначения;\n\n2) здание (строение, сооружение) предназначено для использования или фактически используется в целях делового, административного или коммерческого назначения. При этом:\n\nздание (строение, сооружение) признается предназначенным для использования в целях делового, административного или коммерческого назначения, если назначение, разрешенное использование или наименование помещений общей площадью не менее 20 процентов общей площади этого здания (строения, сооружения) в соответствии со сведениями, содержащимися в Едином государственном реестре недвижимости, или документами технического учета (инвентаризации) таких объектов недвижимости предусматривает размещение офисов и сопутствующей офисной инфраструктуры (включая централизованные приемные помещения, комнаты для проведения встреч, офисное оборудование, парковки); (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nфактическим использованием здания (строения, сооружения) в целях делового, административного или коммерческого назначения признается использование не менее 20 процентов его общей площади для размещения офисов и сопутствующей офисной инфраструктуры (включая централизованные приемные помещения, комнаты для проведения встреч, офисное оборудование, парковки).\n\n1) здание (строение, сооружение) расположено на земельном участке, один из видов разрешенного использования которого предусматривает размещение торговых объектов, объектов общественного питания и (или) бытового обслуживания;\n\n2) здание (строение, сооружение) предназначено для использования или фактически используется в целях размещения торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания. При этом:\n\nздание (строение, сооружение) признается предназначенным для использования в целях размещения торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания, если назначение, разрешенное использование или наименование помещений общей площадью не менее 20 процентов общей площади этого здания (строения, сооружения) в соответствии со сведениями, содержащимися в Едином государственном реестре недвижимости, или документами технического учета (инвентаризации) таких объектов недвижимости предусматривает размещение торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nфактическим использованием здания (строения, сооружения) в целях размещения торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания признается использование не менее 20 процентов его общей площади для размещения торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания.\n\nВ целях настоящего пункта:\n\nздание (строение, сооружение) признается предназначенным для использования одновременно как в целях делового, административного или коммерческого назначения, так и в целях размещения торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания, если назначение, разрешенное использование или наименование помещений общей площадью не менее 20 процентов общей площади этого здания (строения, сооружения) в соответствии со сведениями, содержащимися в Едином государственном реестре недвижимости, или документами технического учета (инвентаризации) таких объектов недвижимости предусматривает размещение офисов и сопутствующей офисной инфраструктуры (включая централизованные приемные помещения, комнаты для проведения встреч, офисное оборудование, парковки), торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\nфактическим использованием здания (строения, сооружения) одновременно как в целях делового, административного или коммерческого назначения, так и в целях размещения торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания признается использование не менее 20 процентов общей площади этого здания (строения, сооружения) для размещения офисов и сопутствующей офисной инфраструктуры (включая централизованные приемные помещения, комнаты для проведения встреч, офисное оборудование, парковки), торговых объектов, объектов общественного питания и (или) объектов бытового обслуживания.\n\n(Дополнение пунктом - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\n1) определяет на этот налоговый период перечень объектов недвижимого имущества, указанных в подпунктах 1 и 2 пункта 1 настоящей статьи, в отношении которых налоговая база определяется как кадастровая стоимость (далее в настоящей статье - перечень);\n\n2) направляет перечень в электронной форме в налоговый орган по субъекту Российской Федерации; (В редакции Федерального закона от 04.11.2014 № 347-ФЗ)\n\n3) размещает перечень на своем официальном сайте или на официальном сайте субъекта Российской Федерации в информационно-телекоммуникационной сети \"Интернет\".\n\nВ случае, если объект недвижимого имущества образован в результате раздела объекта недвижимого имущества или иного соответствующего законодательству Российской Федерации действия с объектами недвижимого имущества, включенными в перечень по состоянию на 1 января года налогового периода, указанный вновь образованный объект недвижимого имущества при условии соответствия его критериям, предусмотренным настоящей статьей, до включения его в перечень подлежит налогообложению по кадастровой стоимости, определенной на день внесения в Единый государственный реестр недвижимости сведений, являющихся основанием для определения кадастровой стоимости такого объекта. (Дополнение абзацем - Федеральный закон от 02.04.2014 № 52-ФЗ) (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n12. Исчисление суммы налога и сумм авансовых платежей по налогу в отношении имущества, в отношении которого налоговая база определяется как его кадастровая стоимость, осуществляется в порядке, предусмотренном статьей 382 настоящего Кодекса, с учетом следующих особенностей:\n\n1) сумма авансового платежа по налогу исчисляется по истечении отчетного периода как одна четвертая кадастровой стоимости объекта недвижимого имущества, умноженная на соответствующую налоговую ставку; (В редакции Федерального закона от 15.04.2019 № 63-ФЗ)\n\n2) в случае, если кадастровая стоимость объекта недвижимого имущества, указанного в подпункте 1 или 2 пункта 1 настоящей статьи, была определена в соответствии с законодательством Российской Федерации в течение налогового (отчетного) периода и (или) указанный объект недвижимого имущества не включен в перечень по состоянию на 1 января года налогового периода, определение налоговой базы и исчисление суммы налога (суммы авансового платежа по налогу) по текущему налоговому периоду в отношении данного объекта недвижимого имущества осуществляются в порядке, предусмотренном настоящей главой, без учета положений настоящей статьи; (В редакции Федерального закона от 30.11.2016 № 401-ФЗ)\n\n21) в случае, если кадастровая стоимость объекта недвижимого имущества, указанного в подпункте 3 или 4 пункта 1 настоящей статьи, была определена в соответствии с законодательством Российской Федерации в течение налогового (отчетного) периода, определение налоговой базы и исчисление суммы налога (суммы авансового платежа по налогу) по текущему налоговому периоду в отношении данного объекта недвижимого имущества осуществляются исходя из кадастровой стоимости, определенной на день внесения в Единый государственный реестр недвижимости сведений, являющихся основанием для определения кадастровой стоимости такого объекта; (Дополнение подпунктом - Федеральный закон от 30.09.2017 № 286-ФЗ)\n\n22) в случае, если кадастровая стоимость объектов недвижимого имущества, указанных в подпунктах 1, 2 и 4 пункта 1 настоящей статьи, не определена, определение налоговой базы и исчисление суммы налога (суммы авансового платежа по налогу) по текущему налоговому периоду в отношении данных объектов недвижимого имущества осуществляются в порядке, предусмотренном настоящей главой без учета положений настоящей статьи; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\n3) (Подпункт утратил силу - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n4) в отношении объекта недвижимого имущества, находящегося в общей долевой собственности, сумма налога (сумма авансового платежа по налогу) исчисляется для каждого из участников долевой собственности пропорционально его доле в праве общей собственности на такой объект недвижимого имущества. В случае изменения в течение налогового периода доли налогоплательщика в праве общей собственности на объект недвижимого имущества сумма налога (сумма авансового платежа по налогу) исчисляется с учетом коэффициента, определяемого в соответствии с пунктом 5 статьи 382 настоящего Кодекса. (Дополнение подпунктом - Федеральный закон от 0\n\nнной свободной экономической зоны, в течение десяти лет с месяца, следующего за месяцем принятия на учет указанного имущества. В случае расторжения договора об условиях деятельности в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области в одностороннем порядке (в свободной экономической зоне на прилегающих территориях - по соглашению сторон или по решению суда) в соответствии с Федеральным законом от 24 июня 2023 года № 266-ФЗ \"О свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях\" сумма налога подлежит исчислению и уплате в бюджет. Исчисление налога производится без учета применения налоговой льготы, предусмотренной настоящим пунктом, за весь период реализации инвестиционного проекта в свободной экономической зоне на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области, Херсонской области и на прилегающих территориях. Исчисленная сумма налога подлежит уплате по истечении отчетного или налогового периода, в котором был расторгнут указанный договор, не позднее сроков, установленных для уплаты авансовых платежей по налогу за отчетный период или налога за налоговый период. (Дополнение пунктом - Федеральный закон от 24.06.2023 № 268-ФЗ) (В редакции  Федерального закона от 22.06.2024 № 148-ФЗ)","article_title":"Статья 378.2. Особенности определения налоговой базы, исчисления и уплаты налога в отношении отдельных объектов недвижимого имущества","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30921a7087dc7a7c9396441578c9cbe7df699e56ea45c993b78aa23ba08981f6"},{"code_id":"NK_RF_2","article_number":"381.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 30.11.2016 № 401-ФЗ)","article_title":"Статья 381.1. Порядок применения налоговых льгот","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bbcf4796d291101d2a4c238ad62ba00c765d914712311f4ee8435fc97f802cb"}]$law7v028$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
